-- Azerbaijani content fixes from the 2026-11-25 content review (owner approved: 12 critical + 253 medium findings,
-- plus "qorşok (uşaq tualeti)" explanation). Azerbaijani cells only; translations follow in a separate migration.
-- Each cell is updated only if it still equals the reviewed value; any mismatch rolls the whole migration back.
-- Applied with run-sql.py on anacan-gcp-candidate.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '300s';
DO $$ BEGIN
  IF (SELECT count(*) FROM _anacan_gcp_migration.guarded_relations WHERE schema_name = 'public' AND table_name IN ('baby_daily_info', 'development_tips', 'epds_questions', 'exercise_daily_tips', 'exercises', 'faqs', 'first_aid_steps', 'flow_insights', 'mental_health_resources', 'mommy_daily_messages', 'mommy_day_notifications', 'play_activities', 'pregnancy_daily_content', 'pregnancy_day_notifications', 'safety_items', 'scheduled_notifications', 'teething_care_tips', 'vaccines', 'weekly_tips')) <> 19 THEN
    RAISE EXCEPTION 'CONTENT_FIX_GUARD_MISSING'; END IF;
END $$;
CREATE TEMP TABLE _fix (n int, tbl text, rid uuid, col text, kind text, old_v text, new_v text) ON COMMIT DROP;
INSERT INTO _fix VALUES
(1, 'baby_daily_info', '0d9fa9e8-940a-4ec4-b501-2f30433e0030', 'info', 'text', $q$Körpənin doğulduğu andan dərhal sonra həkim tərəfindən sağlamlıq yoxlamaları aparılır. Eyni zamanda həkim, doğuşdan sonrakı dəqiqələr ərzində körpənin ilk peyvəndi olan Hepatit B peyvəndini onun ayağına vurur. Əgər səndə Hepatit B daşıyıcılığı varsa, körpənə peyvəndlə birlikdə immunoqlobulin əlavəsi də edilir. Bunlardan başqa, ilk 1 ay ərzində Hepatit B xaricində körpənə edilən başqa bir peyvənd yoxdur. Bundan sonra isə körpən xəstəxanadan çıxmadan bir pediatr tərəfindən ətraflı sağlamlıq müayinəsindən keçirilir. Həmçinin, xəstəxananın təyin etdiyi tibb bacısı körpənə ilk günlərdə necə qulluq edəcəyini və nələrə diqqət etməli olduğunu izah edən təlimat verir. Verilən bütün bu məlumatlar körpənə necə baxacağın barədə sənə olduqca vacib ipucları qazandırır.$q$, $q$Körpənin doğulduğu andan dərhal sonra həkim tərəfindən sağlamlıq yoxlamaları aparılır. Eyni zamanda həkim, doğuşdan sonrakı dəqiqələr ərzində körpənin ilk peyvəndi olan Hepatit B peyvəndini onun ayağına vurur. Əgər səndə Hepatit B daşıyıcılığı varsa, körpənə peyvəndlə birlikdə immunoqlobulin əlavəsi də edilir. Bundan başqa, ilk günlərdə Hepatit B ilə yanaşı vərəm (BCG) peyvəndi də vurulur. Bundan sonra isə körpən xəstəxanadan çıxmadan bir pediatr tərəfindən ətraflı sağlamlıq müayinəsindən keçirilir. Həmçinin, xəstəxananın təyin etdiyi tibb bacısı körpənə ilk günlərdə necə qulluq edəcəyini və nələrə diqqət etməli olduğunu izah edən təlimat verir. Verilən bütün bu məlumatlar körpənə necə baxacağın barədə sənə olduqca vacib ipucları qazandırır.$q$),
(2, 'baby_daily_info', '79a8c317-465e-48a5-8158-982eb6d5f890', 'info', 'text', $q$Uşaqlığın, doğuşdan sonra hələ də hamiləlikdən əvvəlki normal ölçüsünə görə xeyli böyükdür. İndi uşaqlığını adətən göbək səviyyəsində və ya bir az yuxarıda hiss edə bilərsən. Təxminən 1 ay ərzində uşaqlığın tamamilə əvvəlki ölçülərinə qayıdacaq. Doğuş zamanı təxminən 1500 qram olan uşaqlıq kütləsi, hər gün bir az daha kiçilərək hamiləlikdən əvvəlki dövrdə olduğu kimi yenidən 60 qrama düşür. Zaman-zaman, xüsusilə də əmizdirmə zamanı, oksitosin hormonunun təsiri ilə uşaqlıq nahiyəsində yığılmalarla bağlı ağrılar ola bilər. Doğuşu izləyən ilk günlərdə şiddəti bir qədər çox olan bu sancılar gün keçdikcə yüngülləşməyə başlayır. Bu yığılmaların normal olduğu, hətta uşaqlığın daxili təbəqəsinin təmizlənməsinə kömək etdiyi düşünülür.$q$, $q$Uşaqlığın, doğuşdan sonra hələ də hamiləlikdən əvvəlki normal ölçüsünə görə xeyli böyükdür. Doğuşdan dərhal sonra göbək səviyyəsində olan uşaqlığın artıq kiçik çanağa enib. Təxminən 1 ay ərzində uşaqlığın tamamilə əvvəlki ölçülərinə qayıdacaq. Doğuş zamanı təxminən 1500 qram olan uşaqlıq kütləsi, hər gün bir az daha kiçilərək hamiləlikdən əvvəlki dövrdə olduğu kimi yenidən 60 qrama düşür. Zaman-zaman, xüsusilə də əmizdirmə zamanı, oksitosin hormonunun təsiri ilə uşaqlıq nahiyəsində yığılmalarla bağlı ağrılar ola bilər. Doğuşu izləyən ilk günlərdə şiddəti bir qədər çox olan bu sancılar gün keçdikcə yüngülləşməyə başlayır. Bu yığılmaların normal olduğu, hətta uşaqlığın daxili təbəqəsinin təmizlənməsinə kömək etdiyi düşünülür.$q$),
(3, 'baby_daily_info', '418e11ce-7ef6-4382-bb9b-0ee9fe10e295', 'info', 'text', $q$Körpənlə birlikdə 1 ayı daha geridə qoyursan! Körpənin peyvənd təqviminin 1-ci ayında, ilk dozası doğumdan dərhal sonra vurulan Hepatit B peyvəndinin ikinci dozası tətbiq olunur. Peyvəndin vurulduğu ayaqda qızartı və şişkinlik yarana bilər. Bu halda narahat olmamalısan. Həmçinin, körpəndə qısa müddətli hərarət yüksəlməsi və peyvənd sonrası huzursuzluq müşahidə edə bilərsən. Bu təsirlər tez-tez rast gəlinən və zərərsiz yan təsirlərdir. Xüsusilə huzursuzluq əlaməti peyvənd olunan körpələrin demək olar ki, hamısında görülə bilər. Peyvənddən sonra hərarət adətən 38 dərəcəni keçmir. Həkiminin məsləhəti ilə qısa müddətdə düşməyən hərarət üçün şərbət və ya şam istifadə edə bilərsən. Nadir hallarda rast gəlinsə də, əgər körpəndə qeyri-adi əlamətlər olduğunu düşünürsənsə, həkiminlə əlaqə saxlamağı unutma.$q$, $q$Körpənlə birlikdə 1 ayı daha geridə qoyursan! İlk dozası doğumdan dərhal sonra vurulan Hepatit B peyvəndinin növbəti dozaları Azərbaycanın milli peyvənd təqviminə əsasən 2-ci aydan etibarən kombinə peyvəndin tərkibində vurulur; dəqiq tarixləri həkimindən öyrən. Peyvəndin vurulduğu ayaqda qızartı və şişkinlik yarana bilər. Bu halda narahat olmamalısan. Həmçinin, körpəndə qısa müddətli hərarət yüksəlməsi və peyvənd sonrası huzursuzluq müşahidə edə bilərsən. Bu təsirlər tez-tez rast gəlinən və zərərsiz yan təsirlərdir. Xüsusilə huzursuzluq əlaməti peyvənd olunan körpələrin demək olar ki, hamısında görülə bilər. Peyvənddən sonra hərarət adətən 38 dərəcəni keçmir. Həkiminin məsləhəti ilə qısa müddətdə düşməyən hərarət üçün şərbət və ya şam istifadə edə bilərsən. Nadir hallarda rast gəlinsə də, əgər körpəndə qeyri-adi əlamətlər olduğunu düşünürsənsə, həkiminlə əlaqə saxlamağı unutma.$q$),
(4, 'baby_daily_info', '82ca4410-dc4b-42c9-8de1-8024396fe373', 'info', 'text', $q$Körpənin yatış pozisiyasını tənzimləyərkən qusma və boğulma təhlükəsinə qarşı diqqətli olmalısan. Körpəni başı yana çevrilmiş halda üzü üstə, arxası üstə və ya yan yatırtmaqda bir problem yoxdur. Lakin uzun müddət eyni vəziyyətdə yatması, hələ yumşaq olan kəllə sümüyündə forma dəyişikliyinə səbəb ola bilər. Buna görə də yuxu zamanı körpənin pozisiyasını ara-sıra dəyişdirməlisən. Körpəni yan tərəfə yatırdanda arxasını kiçik bir yastıqla dəstəkləyib tarazlıq yaratmağın lazım ola bilər. Yuxuda boğulma riskinə qarşı həkiminin məsləhəti ilə meylli yataqları seçmək yaxşı fikir ola bilər. Həmçinin düz baş yastığından istifadə edərək, körpənin başının arxa hissəsinin düzləşməsinin qarşısını ala və yuvarlaq formasını qoruya bilərsən.$q$, $q$Körpənin yatış pozisiyasını tənzimləyərkən qusma və boğulma təhlükəsinə qarşı diqqətli olmalısan. Körpəni hər yuxuda yalnız arxası üstə yatırt; üzüstə və yan yatırtmaq təhlükəlidir. Lakin uzun müddət eyni vəziyyətdə yatması, hələ yumşaq olan kəllə sümüyündə forma dəyişikliyinə səbəb ola bilər. Buna görə də hər yuxuda başının istiqamətini növbə ilə sağa və sola çevirməlisən. Yuxuda boğulma riskinə qarşı yastıq, dəstək yastığı və meylli yataq istifadə etmə; körpəni düz və bərk döşəkdə yatırt. Həmçinin oyaq olanda nəzarət altında qarınüstə vaxt keçirməsinə şərait yaradaraq, körpənin başının arxa hissəsinin düzləşməsinin qarşısını ala və yuvarlaq formasını qoruya bilərsən.$q$),
(5, 'baby_daily_info', '8b7bb2b5-f77d-4347-879b-67f02bacb220', 'info', 'text', $q$Südünün qidalılığını və miqdarını artıran ən vacib amil qəbul etdiyin suyun miqdarıdır. Südünün azalmaması və davamlılığını təmin etmək üçün gündə ən azı 2-3 litr maye qəbul etməli və hər əmizdirmədən sonra itirdiyin mayeni bərpa etməlisən. Həmçinin kifayət qədər su içmək hamiləlikdə aldığın kiloları sürətlə vermək üçün çox təsirli üsuldur. Vücudunun ehtiyac duyduğu bütün qida maddələrini kifayət qədər qəbul etməyin həm süd miqdarını artıracaq, həm də artıq çəkidən azad olmağına kömək edəcək. Gündəlik zülal ehtiyacını ödəyərkən həm bitki, həm də heyvan mənşəli zülal qaynaqlarından istifadə edə bilərsən. Lakin körpənin qaz problemlərini sıx yaşadığı bir dövrdə olduğu üçün qəbul etdiyin qidaların tərkibinə diqqət etməyində fayda var. Həmçinin unutma ki, körpəni nə qədər çox əmizdirsən, südünün miqdarı o qədər artacaq və davamlılığı təmin olunacaq.$q$, $q$Südünün miqdarını artıran ən vacib amil körpəni tez-tez və tələbə görə əmizdirməkdir; susadıqca su içmək kifayətdir. Bədəninin maye ehtiyacını ödəmək üçün əmizdirmə zamanı yanında su saxlamağın faydalıdır. Həmçinin kifayət qədər su içmək hamiləlikdə aldığın kiloları sürətlə vermək üçün çox təsirli üsuldur. Vücudunun ehtiyac duyduğu bütün qida maddələrini kifayət qədər qəbul etməyin həm süd miqdarını artıracaq, həm də artıq çəkidən azad olmağına kömək edəcək. Gündəlik zülal ehtiyacını ödəyərkən həm bitki, həm də heyvan mənşəli zülal qaynaqlarından istifadə edə bilərsən. Lakin körpənin qaz problemlərini sıx yaşadığı bir dövrdə olduğu üçün qəbul etdiyin qidaların tərkibinə diqqət etməyində fayda var. Həmçinin unutma ki, körpəni nə qədər çox əmizdirsən, südünün miqdarı o qədər artacaq və davamlılığı təmin olunacaq.$q$),
(6, 'baby_daily_info', 'a098a0a5-9cf9-4830-b539-70c7b71e29f4', 'info', 'text', $q$Körpəndə qaz problemlərinin yaranmasının bir çox fərqli səbəbi ola bilər. Bu səbəbləri bilməyin qaz sancıları ilə mübarizədə sənə çox kömək edəcək. Qaz sancılarının ən bilinən səbəbləri gərəyindən artıq tez-tez və nizamsız qidalanmadır. Bağırsaq florası hələ formalaşma mərhələsində olan körpən üçün qidalanma rejimi qurmağın, bağırsaqlarda olan bakteriyaların ən uyğun şərtlərdə işləməsini təmin edər. Bu da körpənin qaz sancılarını daha yüngül keçirməsinə kömək edəcək. Körpələrin mədəsində ilk 6 ay yalnız südü həzm edən fermentlər ifraz olunur. Bu səbəblə sadəcə ana südü və ya ana südünə ən yaxın tərkibdə olan süni qidalardan istifadə etməlisən. Süd və süd tərkibli qidalardan başqa verilən şəkərli su, bəhməz, bal və mürəbbə kimi qidalar körpənin həzm sistemini əlavə yormaqdan başqa bir işə yaramayacaq. Həmçinin istifadə olunan bəzi dərmanların da qaz sancılarını artırıcı təsiri ola biləcəyindən, həkiminin məsləhəti olmadan dərman istifadəsindən çəkinməlisən.$q$, $q$Körpəndə qaz problemlərinin yaranmasının bir çox fərqli səbəbi ola bilər. Bu səbəbləri bilməyin qaz sancıları ilə mübarizədə sənə çox kömək edəcək. Qaz sancılarının ən bilinən səbəbləri gərəyindən artıq tez-tez və nizamsız qidalanmadır. Bağırsaq florası hələ formalaşma mərhələsində olan körpən üçün qidalanma rejimi qurmağın, bağırsaqlarda olan bakteriyaların ən uyğun şərtlərdə işləməsini təmin edər. Bu da körpənin qaz sancılarını daha yüngül keçirməsinə kömək edəcək. Körpələrin mədəsində ilk 6 ay yalnız südü həzm edən fermentlər ifraz olunur. Bu səbəblə sadəcə ana südü və ya ana südünə ən yaxın tərkibdə olan süni qidalardan istifadə etməlisən. Süd və süd tərkibli qidalardan başqa şəkərli su, bəhməz və mürəbbə kimi qidalar verilməməlidir; bal isə 1 yaşa qədər botulizm riskinə görə qəti qadağandır. Həmçinin istifadə olunan bəzi dərmanların da qaz sancılarını artırıcı təsiri ola biləcəyindən, həkiminin məsləhəti olmadan dərman istifadəsindən çəkinməlisən.$q$),
(7, 'baby_daily_info', '37fe650b-ff02-444b-9514-314d6f5df25d', 'info', 'text', $q$Körpəndə qaz sancısının qarşısını almaq və ya bu ağrıları yüngülləşdirmək üçün bəzi üsullar mövcuddur. Körpəni mümkün qədər ana südü ilə qidalandırmağın, həzm sistemi üçün ən uyğun qida olduğu üçün rahat bir həzm prosesi yaradır. Bu sayədə körpənin bağırsaqlarında minimum miqdarda qaz yığılır və qazı parçalayan bakteriyalar daha yaxşı işləyə bilir. Əmizdirmə aralığını ən azı 2 saat olaraq tənzimləməlisən. Bu, həm südünün tərkibinin yağlanmasını təmin edərək körpənin inkişafını dəstəkləyir, həm də qəbul edilən südün daha rahat həzm olunmasına kömək edir. Körpəni həddindən artıq isti və ya soyuq mühitlərdə saxlamamağa, dar paltarları üst-üstə geyindirməməyə çalışmalısan. Bu hallar körpənin həzm və qan dövranı funksiyalarına mənfi təsir edərək bağırsaqlarda qaz yığılmasına səbəb ola bilər. Həmçinin, hər qidalanmadan sonra körpənin qazını çıxararaq mədəsində hava qalmadığından əmin olmalısan.$q$, $q$Körpəndə qaz sancısının qarşısını almaq və ya bu ağrıları yüngülləşdirmək üçün bəzi üsullar mövcuddur. Körpəni mümkün qədər ana südü ilə qidalandırmağın, həzm sistemi üçün ən uyğun qida olduğu üçün rahat bir həzm prosesi yaradır. Bu sayədə körpənin bağırsaqlarında minimum miqdarda qaz yığılır və qazı parçalayan bakteriyalar daha yaxşı işləyə bilir. Körpəni aclıq siqnallarına görə, istədikcə əmizdir; sabit aralıq qoymaq lazım deyil. Bir döşü tam boşaltmasına imkan vermək isə həm südün yağlı son hissəsini almasını təmin edərək körpənin inkişafını dəstəkləyir, həm də qəbul edilən südün daha rahat həzm olunmasına kömək edir. Körpəni həddindən artıq isti və ya soyuq mühitlərdə saxlamamağa, dar paltarları üst-üstə geyindirməməyə çalışmalısan. Bu hallar körpənin həzm və qan dövranı funksiyalarına mənfi təsir edərək bağırsaqlarda qaz yığılmasına səbəb ola bilər. Həmçinin, hər qidalanmadan sonra körpənin qazını çıxararaq mədəsində hava qalmadığından əmin olmalısan.$q$),
(8, 'baby_daily_info', '4db7b0e8-8a13-4223-9f1c-396106b58bfc', 'info', 'text', $q$Körpənin qidalanmasında edəcəyin bir neçə dəyişiklik onun reflüksünün qarşısını alacaq və gələcəkdə problem yaşama riskini minimuma endirəcək. Bunlardan ən vacibi qidalanma tezliyi və rejimidir. Körpəni qidalandırarkən onun mümkün qədər dik vəziyyətdə olmasını təmin etməlisən. Daha tez-tez, amma az miqdarda qidalanma proqramı qurmağın körpənin reflüksünü azaldır və həzm prosesinin rahat keçməsini təmin edir. Yemək aralarında və qidalanmadan sonra körpəni tullamaq və ya yuvarlamaq kimi sarsıdıcı hərəkətlərdən çəkinməli, əksinə, hər qidalanmadan sonra onu təxminən 20 dəqiqə dik tutmalısan. Həmçinin, körpənin altını dəyişərkən bezinin çox sıx olmamasına diqqət etməlisən. Bezin çox sıx bağlanması körpənin qarnındakı təzyiqi artıraraq qusmalara səbəb ola bilər. Körpən yatarkən baş hissəsini biraz hündürdə tutmaq üçün nazik bir yastıqdan istifadə etməyin qaz çıxışını rahatladır və mümkün boğulmaların qarşısını alır. Körpənin siqaret tüstüsü ilə nəfəs alması digər zərərli təsirləri ilə yanaşı reflüksə də səbəb olduğu üçün, çəkinməli olduğun bir digər vacib məsələdir.$q$, $q$Körpənin qidalanmasında edəcəyin bir neçə dəyişiklik onun reflüksünün qarşısını alacaq və gələcəkdə problem yaşama riskini minimuma endirəcək. Bunlardan ən vacibi qidalanma tezliyi və rejimidir. Körpəni qidalandırarkən onun mümkün qədər dik vəziyyətdə olmasını təmin etməlisən. Daha tez-tez, amma az miqdarda qidalanma proqramı qurmağın körpənin reflüksünü azaldır və həzm prosesinin rahat keçməsini təmin edir. Yemək aralarında və qidalanmadan sonra körpəni tullamaq və ya yuvarlamaq kimi sarsıdıcı hərəkətlərdən çəkinməli, əksinə, hər qidalanmadan sonra onu təxminən 20 dəqiqə dik tutmalısan. Həmçinin, körpənin altını dəyişərkən bezinin çox sıx olmamasına diqqət etməlisən. Bezin çox sıx bağlanması körpənin qarnındakı təzyiqi artıraraq qusmalara səbəb ola bilər. Körpən yatarkən başının altına yastıq qoyma: onu yastıqsız, düz və bərk döşəkdə arxası üstə yatırtmalısan. Körpənin siqaret tüstüsü ilə nəfəs alması digər zərərli təsirləri ilə yanaşı reflüksə də səbəb olduğu üçün, çəkinməli olduğun bir digər vacib məsələdir.$q$),
(9, 'baby_daily_info', 'ecec54a9-6b16-4860-9c1c-01c24cd2eac2', 'info', 'text', $q$Körpənin 4-cü ay müayinəsində vurulmalı olan peyvəndlər, 2-ci ayda vurulan vərəm peyvəndi istisna olmaqla, digər iki peyvəndin ikinci dozalarıdır. Bunlar pnevmokok (meningit) və beşli karma adlanan difteriya, göyöskürək, tetanus, hib və poliomielit peyvəndləridir. Əgər körpənin rotavirus peyvəndi 2-ci ayında edilibsə, ikinci dozası bu ay vurulmalıdır. 4-cü ay peyvəndlərindən sonra körpəndə qızdırma və narahatlıq olarsa, həkiminin məsləhət bildiyi qızdırmasalıcını verə bilərsən. Hər körpədə fərqli olsa da, adətən peyvənddən 2-4 saat sonra hərarət yüksələ bilər. Qızdırma bəzən 2-3 gün qədər davam edə bilər. Həmçinin iynə vurulan yerdə ağrı, şişkinlik və qızartı olması bütün peyvəndlərdən sonra müşahidə edilə bilər. Körpənin narahatlığını və şikayətlərini azaltmaq üçün iynə yerinə soyuq kompres edə və ağrıkəsici olaraq həkim məsləhəti ilə parasetamol tərkibli dərmanlardan istifadə edə bilərsən.$q$, $q$Körpənin 4-cü ay müayinəsində Azərbaycanın milli peyvənd təqviminə əsasən iki peyvəndin növbəti dozaları vurulur. Bunlar pnevmokok (meningit) peyvəndi və difteriya, göyöskürək, tetanus, hib və poliomielitə qarşı beşkomponentli (kombinə) peyvənddir. Əgər körpənə rotavirus peyvəndi vurulubsa, növbəti dozası da bu dövrə düşə bilər; dəqiq tarixləri həkimindən öyrən. 4-cü ay peyvəndlərindən sonra körpəndə qızdırma və narahatlıq olarsa, həkiminin məsləhət bildiyi qızdırmasalıcını verə bilərsən. Hər körpədə fərqli olsa da, adətən peyvənddən 2-4 saat sonra hərarət yüksələ bilər. Qızdırma bəzən 2-3 gün qədər davam edə bilər. Həmçinin iynə vurulan yerdə ağrı, şişkinlik və qızartı olması bütün peyvəndlərdən sonra müşahidə edilə bilər. Körpənin narahatlığını və şikayətlərini azaltmaq üçün iynə yerinə soyuq kompres edə və ağrıkəsici olaraq həkim məsləhəti ilə parasetamol tərkibli dərmanlardan istifadə edə bilərsən.$q$),
(10, 'baby_daily_info', 'ea44cd71-5051-4dfc-bbf3-dac92612f0a6', 'info', 'text', $q$Körpən artıq yuvarlanmaq, öz ətrafında dönmək, uzananda başını 45 dərəcəyə qədər qaldırmaq, başını və bədənini sağa-sola yelləmək kimi bacarıqlara sahibdir. Bu hərəkətlər inkişafın normal gedişatıdır. Hətta onu üzüüstə yatıranda irəliyə doğru sürünür kimi hərəkət etdiyini də görə bilərsən. Körpən, hər uşaq kimi yeni bacarıqlar öyrənməyə və öyrəndiklərini tez-tez təkrarlamağa çox həvəslidir. Ancaq unutma ki, hər körpənin inkişafı özünəməxsusdur; əgər sənin körpən bu bacarıqların bəzisinə hələ yiyələnməyibsə, narahat olma. Həmçinin, onun inkişafına düzgün dəstək olmaq üçün bəzi nüanslara diqqət etməlisən. Bunlardan biri də yürüteç (xodunok) istifadəsidir. Daim gəzmək və ətrafı kəşf etmək istəyən körpən səni bəzən yorsa da, çarəni yürüteçdə axtarmamalısan. 6 aydan kiçik və hələ oturmağa hazır olmayan körpəni buna məcbur etmək və ya yürüteçə qoymaq, gələcəkdə iməkləmə və sürünmə kimi vacib bacarıqlar üçün lazım olan əzələ inkişafına mane ola bilər.$q$, $q$Körpən artıq yuvarlanmaq, öz ətrafında dönmək, uzananda başını 45 dərəcəyə qədər qaldırmaq, başını və bədənini sağa-sola yelləmək kimi bacarıqlara sahibdir. Bu hərəkətlər inkişafın normal gedişatıdır. Hətta onu üzüüstə yatıranda irəliyə doğru sürünür kimi hərəkət etdiyini də görə bilərsən. Körpən, hər uşaq kimi yeni bacarıqlar öyrənməyə və öyrəndiklərini tez-tez təkrarlamağa çox həvəslidir. Ancaq unutma ki, hər körpənin inkişafı özünəməxsusdur; əgər sənin körpən bu bacarıqların bəzisinə hələ yiyələnməyibsə, narahat olma. Həmçinin, onun inkişafına düzgün dəstək olmaq üçün bəzi nüanslara diqqət etməlisən. Bunlardan biri də yeriyici (xodunok) istifadəsidir. Daim gəzmək və ətrafı kəşf etmək istəyən körpən səni bəzən yorsa da, çarəni yeriyicidə axtarmamalısan. Yeriyici (xodunok) heç bir yaşda tövsiyə olunmur: zədə riski yüksəkdir və iməkləmə ilə yeriməni ləngidir.$q$),
(11, 'baby_daily_info', '8360a204-f867-4fb6-bb2c-9a237526ca1c', 'info', 'text', $q$Vaxtında doğulmuş körpələrin bir çoxu hələ üç aylıq olanda belə bərk qidalara hazır vəziyyətə gələ bilərlər. Lakin bərk qidaya keçidə mane olan "dil çıxarma" refleksi adətən dördüncü aydan etibarən itməyə başlayır. Əslində əmmə funksiyasında mühüm rol oynayan bu refleks, körpənə verdiyin yeməkləri dili ilə itələməsinə səbəb olur. Bu aydan etibarən körpən qidaların bir qismini həzm edə biləcək sistemə sahibdir. Ancaq bu, inkişafın mərhələli bir hissəsidir və bərk qidalara tam hazır olduğunu göstərməz. Bu mövzuda Ümumdünya Səhiyyə Təşkilatının tövsiyəsi belədir: əgər körpə çəki itirmədən sağlam böyüyürsə, 6-cı aya qədər yalnız ana südü ilə davam edilməlidir. 6-cı aya qədər südün az olduğu və körpənin ayda 500 qramdan az çəki aldığı halda isə, davamlı süd qarışıqlarının qidalanmada əsas yer tutmalı olduğunu unutmamalısan. 6 ay tamam olduqdan sonra belə, əsas qida maddəsi yenə də ana südü olmalıdır. Ümumdünya Səhiyyə Təşkilatı 9 aylıq bir körpə üçün qidalanmanın 70%-nin ana südündən ibarət olmasını tövsiyə edir.$q$, $q$Körpələrin çoxu bərk qidaya təxminən 6 aylıqda hazır olur. Lakin bərk qidaya keçidə mane olan "dil çıxarma" refleksi adətən dördüncü aydan etibarən itməyə başlayır. Əslində əmmə funksiyasında mühüm rol oynayan bu refleks, körpənə verdiyin yeməkləri dili ilə itələməsinə səbəb olur. Bu aydan etibarən körpən qidaların bir qismini həzm edə biləcək sistemə sahibdir. Ancaq bu, inkişafın mərhələli bir hissəsidir və bərk qidalara tam hazır olduğunu göstərməz. Bu mövzuda Ümumdünya Səhiyyə Təşkilatının tövsiyəsi belədir: əgər körpə çəki itirmədən sağlam böyüyürsə, 6-cı aya qədər yalnız ana südü ilə davam edilməlidir. 6-cı aya qədər südün az olduğu və körpənin ayda 500 qramdan az çəki aldığı halda isə, davamlı süd qarışıqlarının qidalanmada əsas yer tutmalı olduğunu unutmamalısan. 6 ay tamam olduqdan sonra belə, əsas qida maddəsi yenə də ana südü olmalıdır. Ümumdünya Səhiyyə Təşkilatı 9 aylıq bir körpə üçün qidalanmanın 70%-nin ana südündən ibarət olmasını tövsiyə edir.$q$),
(12, 'baby_daily_info', '1fa3a9be-2b21-41b0-8e90-923545dc6c0e', 'info', 'text', $q$Hazırda hər hansı bir kriz dövründə olmasan belə, körpən yuxuya getməkdə çətinlik çəkə bilər. 5 aylıq körpənin yuxu rejimi, hər gün yeni hərəkət bacarıqları qazanması səbəbindən bir az pozula bilər. Körpən yeni qazandığı bu bacarıqları məşq etmək üçün yuxunu və qidalanmanı rədd edə, səni səhərlər tez oyada bilər. Əgər körpən yuxudan oyananda ağlamır, yatağında öz-özünə oynayıb vaxt keçirirsə, axşam onu yatızdırarkən yanına bir yuxu dostu qoya bilərsən. Bir müddət sonra körpən, yanına qoyduğun bu oyuncağı hər gördüyündə yuxu refleksi göstərməyə başlayacaq. Bu vərdişin düzgün formalaşması üçün yuxu dostunu yataqdan çıxarmamalı, yalnız yuxu vaxtı gələndə yanına qoymalısan. Yuxu dostu seçərkən oyuncağın üzvi ip və ya parçadan olmasına, zərərli boya və ya uda biləcəyi xırda detallar ehtiva etməməsinə əmin olmalısan.$q$, $q$Hazırda hər hansı bir kriz dövründə olmasan belə, körpən yuxuya getməkdə çətinlik çəkə bilər. 5 aylıq körpənin yuxu rejimi, hər gün yeni hərəkət bacarıqları qazanması səbəbindən bir az pozula bilər. Körpən yeni qazandığı bu bacarıqları məşq etmək üçün yuxunu və qidalanmanı rədd edə, səni səhərlər tez oyada bilər. Əgər körpən yuxudan oyananda ağlamır, yatağında öz-özünə oynayıb vaxt keçirirsə, 12 aylıqdan sonra axşam onu yatızdırarkən yanına bir yuxu dostu qoya bilərsən; o vaxta qədər yataqda yumşaq əşya olmasın. Bir müddət sonra körpən, yanına qoyduğun bu oyuncağı hər gördüyündə yuxu refleksi göstərməyə başlayacaq. Bu vərdişin düzgün formalaşması üçün yuxu dostunu yataqdan çıxarmamalı, yalnız yuxu vaxtı gələndə yanına qoymalısan. Yuxu dostu seçərkən oyuncağın üzvi ip və ya parçadan olmasına, zərərli boya və ya uda biləcəyi xırda detallar ehtiva etməməsinə əmin olmalısan.$q$),
(13, 'baby_daily_info', '57b7991c-272a-4ed5-898c-f9700be1db2a', 'info', 'text', $q$Körpənin əlavə qidaya keçid vaxtı, doğulması gözlənilən tarixdən 180 gün sonraya təsadüf edir. Bu da o deməkdir ki, 6-cı ayın sonu əlavə qida ilə tanışlıq üçün ən uyğun zamandır. Bəzi hallarda, həkimlərin məsləhəti ilə əlavə qidaya daha tez keçmək mümkündür, çünki körpələr artıq udma refleksini öyrənmiş olurlar. Yenə də bağırsaq florasının sağlamlığı üçün, əgər inkişafında bir ləngimə yoxdursa, bir az daha gözləmək daha doğru olar. 5-ci ayda körpənə verə biləcəyin əlavə qidalar mütləq maye halında olmalıdır; püre üçün hələ bir az daha gözləməlisən. Təbii hazırlanmış tərəvəz şorbalarının suyu və allergik olmayan meyvə şirələri körpən üçün uyğun ola bilər. Qida allergiyası riski səbəbindən, körpənin ilk dəfə dadacağı qidanı 1 çay qaşığı kimi çox az miqdarda verməyin tövsiyə olunur.$q$, $q$Körpənin əlavə qidaya keçid vaxtı, doğulması gözlənilən tarixdən 180 gün sonraya təsadüf edir. Bu da o deməkdir ki, 6-cı ayın sonu əlavə qida ilə tanışlıq üçün ən uyğun zamandır. Bəzi hallarda, həkimlərin məsləhəti ilə əlavə qidaya daha tez keçmək mümkündür, çünki körpələr artıq udma refleksini öyrənmiş olurlar. Yenə də bağırsaq florasının sağlamlığı üçün, əgər inkişafında bir ləngimə yoxdursa, bir az daha gözləmək daha doğru olar. 6 ay tamam olana qədər körpənə yalnız ana südü və ya süni qida ver; meyvə şirəsi isə 1 yaşa qədər tövsiyə olunmur. Qida allergiyası riski səbəbindən, körpənin ilk dəfə dadacağı qidanı 1 çay qaşığı kimi çox az miqdarda verməyin tövsiyə olunur.$q$),
(14, 'baby_daily_info', '95f9ad1b-63d6-45ba-b708-bf282b104620', 'info', 'text', $q$Bu ay səni və körpəni yeni təcrübələr və dəyişikliklər gözləyir. Körpəni xəstəliklərdən qorumaq üçün doğumdan etibarən peyvəndlərini vaxtlı-vaxtında etdirmək çox vacibdir. Peyvənd vasitəsilə körpənin orqanizminə qorunması hədəflənən xəstəliyin zəiflədilmiş bakteriya və ya virus forması daxil edilir. Bu proses immunitet yaratmaq məqsədi daşıyır və körpənin bədəni həmin xəstəliklərə qarşı anticisimlər istehsal etməyə başlayır. Beləliklə, gələcəkdə körpən bu mikroblarla qarşılaşdıqda, onun bədəni artıq güclü müdafiə mexanizminə sahib olur. 6-cı ayın peyvənd təqvimində Hepatit B-nin üçüncü dozası, beşli kombinə olunmuş peyvəndin üçüncü dozası və OPA (Oral Polio) peyvəndinin birinci dozası yer alır. Həmçinin, körpənin ilk dəfə qarşılaşacağı uşaq iflici (poliomielit) peyvəndi də bura əlavə olunub. Bütün bunlarla birlikdə, körpən üçün ilk 6 aylıq peyvənd təqvimi tamamlanmış olur.$q$, $q$Bu ay səni və körpəni yeni təcrübələr və dəyişikliklər gözləyir. Körpəni xəstəliklərdən qorumaq üçün doğumdan etibarən peyvəndlərini vaxtlı-vaxtında etdirmək çox vacibdir. Peyvənd vasitəsilə körpənin orqanizminə qorunması hədəflənən xəstəliyin zəiflədilmiş bakteriya və ya virus forması daxil edilir. Bu proses immunitet yaratmaq məqsədi daşıyır və körpənin bədəni həmin xəstəliklərə qarşı anticisimlər istehsal etməyə başlayır. Beləliklə, gələcəkdə körpən bu mikroblarla qarşılaşdıqda, onun bədəni artıq güclü müdafiə mexanizminə sahib olur. Azərbaycanın milli peyvənd təqviminə əsasən körpən ilk aylarda Hepatit B, difteriya, göyöskürək, tetanus, hib, uşaq iflici (poliomielit) və pnevmokok peyvəndlərinin əsas dozalarını alır; dəqiq tarixləri həkimindən öyrənə bilərsən. Bütün bunlarla birlikdə, körpən üçün ilk 6 aylıq peyvənd təqvimi tamamlanmış olur.$q$),
(15, 'baby_daily_info', '68a677bc-c6fd-496b-bd7c-d65d75f316ae', 'info', 'text', $q$Körpən 6 aylıq inkişaf dövründə gündə təxminən 11 saat yata bilər. Bu orta yuxu müddəti o demək deyil ki, körpən yalnız gecələr yatacaq; gündüz yuxusu da onun üçün hələ olduqca vacibdir. Amerika Pediatriya Akademiyasına görə, körpənin öz otağına keçməsi və səndən ayrı yata bilməsi üçün ideal vaxt məhz bu aydan etibarən başlayır. Bunun səbəbi, artıq əlavə qidaya keçən körpənin, ilk aylarda olduğu kimi ana südünə olan asılılığının nisbətən azalmasıdır. Lakin bu keçidi çox sürətli etmək körpənin ruhsal inkişafında bəzi narahatlıqlara səbəb ola bilər. Xüsusilə gecələr yuxudan oyanan körpənin qorxması və ağlaması tez-tez rast gəlinən hallardandır. Körpəni bu yeni vəziyyətə alışdırmaq üçün ona zaman tanımalı və prosesi yavaş-yavaş, səbirlə idarə etməlisən.$q$, $q$Körpən 6 aylıq inkişaf dövründə gündə təxminən 12-14 saat yata bilər. Bu orta yuxu müddəti o demək deyil ki, körpən yalnız gecələr yatacaq; gündüz yuxusu da onun üçün hələ olduqca vacibdir. Amerika Pediatriya Akademiyasına görə, körpənin öz otağına keçməsi və səndən ayrı yata bilməsi üçün ideal vaxt məhz bu aydan etibarən başlayır. Bunun səbəbi, artıq əlavə qidaya keçən körpənin, ilk aylarda olduğu kimi ana südünə olan asılılığının nisbətən azalmasıdır. Lakin bu keçidi çox sürətli etmək körpənin ruhsal inkişafında bəzi narahatlıqlara səbəb ola bilər. Xüsusilə gecələr yuxudan oyanan körpənin qorxması və ağlaması tez-tez rast gəlinən hallardandır. Körpəni bu yeni vəziyyətə alışdırmaq üçün ona zaman tanımalı və prosesi yavaş-yavaş, səbirlə idarə etməlisən.$q$),
(16, 'baby_daily_info', 'bdbf69c9-7362-46c7-9230-c6195ba35de7', 'info', 'text', $q$Əlavə qidalara keçdiyin bu günlərdə körpənə alma, şaftalı, armud kimi meyvələrin, eləcə də kartof, kök və balqabaq kimi tərəvəzlərin püresini və şirəsini verməyi seçə bilərsən. Bunlarla yanaşı, evdə öz hazırladığın qatığın içərisinə, həkimin məsləhəti ilə aptekdən alacağın probiotik tozlardan da əlavə edə bilərsən. Əlavə qida kimi uzaq durmalı olduğun qidaların başında inək südü, şəkərli və duzlu qidalar gəlir. İnək südü erkən dövrlərdə bağırsaqda gizli qanamalara səbəb ola bilər. Həmçinin dəmir tərkibinin kifayət etməməsi və tərkibindəki yad zülallar səbəbiylə allergiya yarada bilməsi riskinə görə, 1 yaşından əvvəl verilməməlidir. Hazır qidaların körpənin menyusunda yeri olmadığını da unutmamalısan. Bununla yanaşı, körpənə verdiyin qidaları şəkər tozu əvəzinə bəhməz və ya meyvə ilə dadlandırmağa üstünlük ver.$q$, $q$Əlavə qidalara keçdiyin bu günlərdə körpənə alma, şaftalı, armud kimi meyvələrin, eləcə də kartof, kök və balqabaq kimi tərəvəzlərin püresini verməyi seçə bilərsən. Bunlarla yanaşı, evdə öz hazırladığın qatığın içərisinə, həkimin məsləhəti ilə aptekdən alacağın probiotik tozlardan da əlavə edə bilərsən. Əlavə qida kimi uzaq durmalı olduğun qidaların başında inək südü, şəkərli və duzlu qidalar gəlir. İnək südü erkən dövrlərdə bağırsaqda gizli qanamalara səbəb ola bilər. Həmçinin dəmir tərkibinin kifayət etməməsi və tərkibindəki yad zülallar səbəbiylə allergiya yarada bilməsi riskinə görə, 1 yaşından əvvəl verilməməlidir. Hazır qidaların körpənin menyusunda yeri olmadığını da unutmamalısan. Bununla yanaşı, körpənə verdiyin qidalara heç bir şəkər və bəhməz əlavə etmə; şirə əvəzinə meyvə püresi ver.$q$),
(17, 'baby_daily_info', 'e926ea15-a8f6-4559-a5e9-18bd81abc58e', 'info', 'text', $q$Araşdırmalara görə, körpələrin orta dərəcədə stimullara məruz qaldıqları mühitdə daha yaxşı inkişaf etdiyi müşahidə olunub. Bu səbəbdən körpəni fərqli toxumalarla, fərqli formalarla və fərqli səslərlə tanış etməyin, beynində yeni bilik axınına şərait yaradır. 6 aylıq körpən üçün edəcəyin bu cür hissi qavrayış fəaliyyətləri onun zehni inkişafı üçün olduqca vacibdir. Bu dövrdə oynayacağınız ce-eee oyunu, qafiyəli laylalar və barmaq kuklaları həm əyləncəli olacaq, həm də körpənin inkişafına töhfə verəcək. Körpənin qarşısına qoyacağın hər yeni əşya ilə öz təcrübələrini aparmasını təmin etməli və xüsusiyyətlərini kəşf etməsi üçün ona vaxt verdiyindən əmin olmalısan. Məsələn, bu bir şüşə stəkan və bir qaşıq ola bilər. Körpənin hər iki əlinə verəcəyin bu əşyaları incələməsinə şərait yaratmalı və bunlarla necə səs çıxaracağı mövzusunda ona kömək etməlisən. Körpənin bu aktivlik sayəsində çox əylənəcəyindən əminik. Xoş oyunlar! 😊$q$, $q$Araşdırmalara görə, körpələrin orta dərəcədə stimullara məruz qaldıqları mühitdə daha yaxşı inkişaf etdiyi müşahidə olunub. Bu səbəbdən körpəni fərqli toxumalarla, fərqli formalarla və fərqli səslərlə tanış etməyin, beynində yeni bilik axınına şərait yaradır. 6 aylıq körpən üçün edəcəyin bu cür hissi qavrayış fəaliyyətləri onun zehni inkişafı üçün olduqca vacibdir. Bu dövrdə oynayacağınız ce-eee oyunu, qafiyəli laylalar və barmaq kuklaları həm əyləncəli olacaq, həm də körpənin inkişafına töhfə verəcək. Körpənin qarşısına qoyacağın hər yeni əşya ilə öz təcrübələrini aparmasını təmin etməli və xüsusiyyətlərini kəşf etməsi üçün ona vaxt verdiyindən əmin olmalısan. Məsələn, bu plastik (qırılmaz) stəkan və qaşıq ola bilər. Körpənin hər iki əlinə verəcəyin bu əşyaları incələməsinə şərait yaratmalı və bunlarla necə səs çıxaracağı mövzusunda ona kömək etməlisən. Körpənin bu aktivlik sayəsində çox əylənəcəyindən əminik. Xoş oyunlar! 😊$q$),
(18, 'baby_daily_info', '7ae42d6a-0c42-4144-b394-cfd8c4804b24', 'info', 'text', $q$Bu ay körpənin peyvənd təqvimində hər hansı bir aşı nəzərdə tutulmayıb. Bununla birlikdə, həkimin edəcəyi rutin müayinələrdə onun çəkisi, boyu və baş çevrəsi ölçüləcək. 7-ci ay etibarilə körpənin çəkisi adətən 6100 qram ilə 10100 qram aralığında olur. 7 aylıq körpələrin ortalama çəkisi isə 8100 qramdır. Ancaq xüsusilə vaxtından əvvəl doğulan körpələr üçün bu ortalama dəyərin daha aşağı ola biləcəyini unutmamalısan. Bu ay körpənin boyu 61 sm ilə 75 sm arasında dəyişir, ortalama isə təxminən 67 sm-dir. Körpənin beyin inkişafı haqqında ümumi məlumat verən baş çevrəsi isə bu ay 40.5 sm ilə 46.5 sm aralığında olur. Əgər körpənin fiziki inkişafının bu dəyərlər daxilində olmadığını düşünürsənsə, ən doğru məlumatı almaq üçün həkiminə müraciət edə bilərsən.$q$, $q$Bu ay körpənin peyvənd təqvimində hər hansı peyvənd nəzərdə tutulmayıb. Bununla birlikdə, həkimin edəcəyi rutin müayinələrdə onun çəkisi, boyu və baş çevrəsi ölçüləcək. 7-ci ay etibarilə körpənin çəkisi adətən 6100 qram ilə 10100 qram aralığında olur. 7 aylıq körpələrin ortalama çəkisi isə 8100 qramdır. Ancaq xüsusilə vaxtından əvvəl doğulan körpələr üçün bu ortalama dəyərin daha aşağı ola biləcəyini unutmamalısan. Bu ay körpənin boyu 61 sm ilə 75 sm arasında dəyişir, ortalama isə təxminən 67 sm-dir. Körpənin beyin inkişafı haqqında ümumi məlumat verən baş çevrəsi isə bu ay 40.5 sm ilə 46.5 sm aralığında olur. Əgər körpənin fiziki inkişafının bu dəyərlər daxilində olmadığını düşünürsənsə, ən doğru məlumatı almaq üçün həkiminə müraciət edə bilərsən.$q$),
(19, 'baby_daily_info', '84211613-fc78-4c1f-a816-22b155e0b89d', 'info', 'text', $q$Bu ay körpənin sosiallaşmasının xeyli inkişaf edəcəyi bir dövrdür. Buna görə də o, ünsiyyət qurduğu ailə üzvlərini diqqətlə izləməyə başlayır. Körpən bu mərhələyə qədər hafizəsinə yazdığı məlumatlar sayəsində səbəb-nəticə əlaqəsi qurmağı öyrənir. Qol, ayaq hərəkətlərini və hətta mimikalarını təqlid etməyə çalışsa, təəccüblənmə! 😊 Təbii ki, bu vəziyyət sənə bir məsuliyyət də yükləyir: yaxşı nümunə olmaq! Çünki körpənin maraq duyğusu çox güclüdür və hər şeyi kəşf etmək üçün böyük səy göstərir. Ona zərər verə biləcək hallarda məhdudiyyət qoya bilərsən, amma bu mövzuda aşırıya qaçmamalısan. Məsələn, körpənin uda biləcəyi ölçüdə bir əşya diqqətini çəkibsə və bunu incələmək üçün əlinə alıbsa, dərhal əlindən almaq və ya sərt reaksiya vermək əvəzinə, onu yaxından izləməli və yalnız həqiqətən lazım olduqda müdaxilə etməlisən.$q$, $q$Bu ay körpənin sosiallaşmasının xeyli inkişaf edəcəyi bir dövrdür. Buna görə də o, ünsiyyət qurduğu ailə üzvlərini diqqətlə izləməyə başlayır. Körpən bu mərhələyə qədər hafizəsinə yazdığı məlumatlar sayəsində səbəb-nəticə əlaqəsi qurmağı öyrənir. Qol, ayaq hərəkətlərini və hətta mimikalarını təqlid etməyə çalışsa, təəccüblənmə! 😊 Təbii ki, bu vəziyyət sənə bir məsuliyyət də yükləyir: yaxşı nümunə olmaq! Çünki körpənin maraq duyğusu çox güclüdür və hər şeyi kəşf etmək üçün böyük səy göstərir. Ona zərər verə biləcək hallarda məhdudiyyət qoya bilərsən, amma bu mövzuda aşırıya qaçmamalısan. Məsələn, körpənin uda biləcəyi ölçüdə bir əşya diqqətini çəkibsə və bunu incələmək üçün əlinə alıbsa, sərt reaksiya vermədən onu sakitcə əlindən almalı və yerinə təhlükəsiz bir oyuncaq verməlisən.$q$),
(20, 'baby_daily_info', '52c260d9-9803-4e1b-9fc5-0c188ff2d7d3', 'info', 'text', $q$Körpən üçün öyrədici stəkandan (alışdırma bardağı) nə vaxt istifadə etməyə başlayacağınla bağlı sualların ola bilər. Bunun üçün doğru zamanın gəldiyini ancaq körpəni müşahidə edərək anlaya bilərsən. Əgər körpəndə dili ilə itələmə refleksi itibsə, deməli, o, artıq öyrədici stəkan üçün hazırdır. Dili ilə itələmə refleksi ilk aylarda körpənin ağzına girən yad cismi avtomatik olaraq dili ilə çölə itələməsi deməkdir. Əslində bu refleks körpən üçün həyati əhəmiyyət daşıyır, çünki bu sayədə o, boğulma təhlükəsindən qorunur. Ortalama olaraq 4-cü aydan etibarən bu refleksdə azalma müşahidə olunur, 6-8-ci aylar arasında isə tamamilə yox olur. Bu refleksin itməsi həm də körpənin artıq butulka əvəzinə stəkanla su içəcəyinin ilk işarəsidir.$q$, $q$Körpən üçün öyrədici stəkandan nə vaxt istifadə etməyə başlayacağınla bağlı sualların ola bilər. Bunun üçün doğru zamanın gəldiyini ancaq körpəni müşahidə edərək anlaya bilərsən. Əgər körpəndə dili ilə itələmə refleksi itibsə, deməli, o, artıq öyrədici stəkan üçün hazırdır. Dili ilə itələmə refleksi ilk aylarda körpənin ağzına girən yad cismi avtomatik olaraq dili ilə çölə itələməsi deməkdir. Əslində bu refleks körpən üçün həyati əhəmiyyət daşıyır, çünki bu sayədə o, boğulma təhlükəsindən qorunur. Ortalama olaraq 4-cü aydan etibarən bu refleksdə azalma müşahidə olunur, 6-8-ci aylar arasında isə tamamilə yox olur. Bu refleksin itməsi həm də körpənin artıq butulka əvəzinə stəkanla su içəcəyinin ilk işarəsidir.$q$),
(21, 'baby_daily_info', 'd21c1f6a-5fc9-4cad-8563-f3edc47a4f56', 'info', 'text', $q$Körpən təxminən 2 aydır əlavə qidaya başlasa da, 2 yaşına qədər onun əsas yeməyi hələ də ana südüdür. Verdiyin əlavə qidalar sadəcə ara yeməkləri əvəz edir. Bu səbəbdən süd verməyi azaltmağın körpənin inkişafını ləngidə bilər. Əgər bu aralar körpənin iştahsız olduğunu düşünürsənsə, tək olmadığını xatırlatmaq istərdik. 😊 Aktiv oyun dövrünə girdiyi üçün körpən qidalanma və yuxu kimi ehtiyaclarına çox vaxt ayırmaq istəməyə bilər. Buna görə də onun ən sevdiyi məşğuliyyət olan oyunu yemək vaxtı ilə birləşdirə bilərsən! Yemək yeməyi əyləncəli hala gətirmək üçün ona maraqlı boşqablar hazırlaya, yemək yeyərkən ce-ee, təyyarə gəlir kimi oyunlar oynaya bilərsən. Həmçinin barmaq kuklalarından da kömək ala bilərsən. Yaxşı əyləncələr! 😊$q$, $q$Körpən təxminən 2 aydır əlavə qidaya başlayıb. Ana südü 2 yaşa qədər onun üçün vacib olaraq qalır, amma 1 yaşa yaxın əlavə qidalar əsas qidalanmaya çevrilir. Bu səbəbdən süd verməyi azaltmağın körpənin inkişafını ləngidə bilər. Əgər bu aralar körpənin iştahsız olduğunu düşünürsənsə, tək olmadığını xatırlatmaq istərdik. 😊 Aktiv oyun dövrünə girdiyi üçün körpən qidalanma və yuxu kimi ehtiyaclarına çox vaxt ayırmaq istəməyə bilər. Buna görə də onun ən sevdiyi məşğuliyyət olan oyunu yemək vaxtı ilə birləşdirə bilərsən! Yemək yeməyi əyləncəli hala gətirmək üçün ona maraqlı boşqablar hazırlaya, yemək yeyərkən ce-ee, təyyarə gəlir kimi oyunlar oynaya bilərsən. Həmçinin barmaq kuklalarından da kömək ala bilərsən. Yaxşı əyləncələr! 😊$q$),
(22, 'baby_daily_info', 'b6d3d34d-c066-4ccc-9ded-29b02d7dbff4', 'info', 'text', $q$Dünya Səhiyyə Təşkilatı (ÜST) Avropa regionundakı müxtəlif ölkələrdə baş verən epidemiyalar səbəbindən mütəmadi olaraq tövsiyələr verir. İmmunitet üzrə Məşvərət Şurasının qərarlarına əsasən, nəzarət strategiyası olaraq 9-11 aylıq körpələrin peyvəndlənməsi məsələsi dəyərləndirilir. Müəyyən edilmiş qaydalara görə, 9 aydan yuxarı və 12 aydan kiçik olan körpələrə həkim məsləhəti ilə əlavə qızılca peyvəndi vurula bilər. Bu doza, əvvəlki qızılca peyvəndi ilə arasında ən azı dörd həftə fərq olmaqla tətbiq edilir. Bu, rutin bir doza olmadığı üçün sistemdə adətən əlavə aşı kimi qeyd olunur. Bu barədə ən dəqiq məlumatı öz sahə həkimindən almağı unutma.$q$, $q$Dünya Səhiyyə Təşkilatı (ÜST) Avropa regionundakı müxtəlif ölkələrdə baş verən epidemiyalar səbəbindən mütəmadi olaraq tövsiyələr verir. İmmunitet üzrə Məşvərət Şurasının qərarlarına əsasən, nəzarət strategiyası olaraq 9-11 aylıq körpələrin peyvəndlənməsi məsələsi dəyərləndirilir. Müəyyən edilmiş qaydalara görə, 9 aydan yuxarı və 12 aydan kiçik olan körpələrə həkim məsləhəti ilə əlavə qızılca peyvəndi vurula bilər. Bu əlavə dozadan sonra 12 aylıq QPM (qızılca, parotit, məxmərək) peyvəndinə qədər ən azı 4 həftə keçməlidir. Bu, rutin bir doza olmadığı üçün sistemdə adətən əlavə peyvənd kimi qeyd olunur. Bu barədə ən dəqiq məlumatı öz sahə həkimindən almağı unutma.$q$),
(23, 'baby_daily_info', '69152415-f884-484c-9ae7-d7f46f63d572', 'info', 'text', $q$Körpənin zehni funksiyalarını oyatmaq üçün onunla birlikdə hissi (sensor) inkişaf oyunları oynaya bilərsən. Bu termin ilk baxışda qəliz görünsə də, əslində körpənin inkişafını ən yaxşı şəkildə dəstəkləyən və hətta müalicəvi xüsusiyyəti olan bir üsuldur. Bu yolla körpənin aktiv öyrənməsinə və müxtəlif sahələrdə inkişafına kömək edə bilərsən. Gəl bunu sadə bir nümunə ilə izah edim: Məsələn, körpəni mərkəzə qoyub ətrafında dönə bilərsən və ya qarşısına keçib maraqlı əşyaları çəkmə/itələmə hərəkətləri edə bilərsən. Körpəni arxası üstə uzadıb, ayağına bağladığın şarlara təpik vurmasını təmin edə bilərsən. Həmçinin, toxunma duyğusunu inkişaf etdirmək üçün onu tüklü və fərqli fakturalı səthlərlə tanış edə bilərsən. Əminəm ki, körpən çox əylənəcək! 😊$q$, $q$Körpənin zehni funksiyalarını oyatmaq üçün onunla birlikdə hissi (sensor) inkişaf oyunları oynaya bilərsən. Bu termin ilk baxışda qəliz görünsə də, əslində körpənin inkişafını ən yaxşı şəkildə dəstəkləyən və hətta müalicəvi xüsusiyyəti olan bir üsuldur. Bu yolla körpənin aktiv öyrənməsinə və müxtəlif sahələrdə inkişafına kömək edə bilərsən. Gəl bunu sadə bir nümunə ilə izah edim: Məsələn, körpəni mərkəzə qoyub ətrafında dönə bilərsən və ya qarşısına keçib maraqlı əşyaları çəkmə/itələmə hərəkətləri edə bilərsən. Körpəni arxası üstə uzadıb, ayağına yaxın asdığın yumşaq topa və ya oyuncağa təpik vurmasını təmin edə bilərsən. Həmçinin, toxunma duyğusunu inkişaf etdirmək üçün onu tüklü və fərqli fakturalı səthlərlə tanış edə bilərsən. Əminəm ki, körpən çox əylənəcək! 😊$q$),
(24, 'baby_daily_info', '0c97a7c0-87cb-4c6d-bccc-18d59ae9a64f', 'info', 'text', $q$Əgər körpən tez-tez xəstələnirsə, buna görə özünü günahlandırma və qeyri-kafi hiss etmə. Körpənin immunitet sistemi hələ tam inkişaf etmədiyi üçün soyuqdəymə və qrip tez-tez rastlaşa biləcəyin problemlər ola bilər. Körpələrin çoxu ilk iki ildə təxminən on dəfə soyuqdəyməyə yoluxurlar. İlk aylarda çətin görünən bu proses, o an üçün körpədə sadəcə narahatlıq hissi yaradır. Bu dövrü ən asan şəkildə keçirmək üçün sənə düşən vəzifə körpəni əlindən gəldiyi qədər rahat hiss etdirməkdir. Məsələn, xəstəlik zamanı körpənin bədəni daha çox yuxuya ehtiyac duyur. Buna görə də, hamamdan sonra ona edəcəyin rahatlaşdırıcı masaj yuxuya keçidi xeyli asanlaşdıracaq. Əgər burnu tutulubsa, yatarkən başının altına qoyduğun yastığı normaldan bir az daha hündür seçə bilərsən. Unutma ki, soyuqdəymə zamanı körpənin mayeyə ehtiyacı artır, ona görə də bol su içməsini və ana südü (və ya süni qida) qəbul etməsini təmin etməlisən.$q$, $q$Əgər körpən tez-tez xəstələnirsə, buna görə özünü günahlandırma və qeyri-kafi hiss etmə. Körpənin immunitet sistemi hələ tam inkişaf etmədiyi üçün soyuqdəymə və qrip tez-tez rastlaşa biləcəyin problemlər ola bilər. Körpələrin çoxu ilk iki ildə təxminən on dəfə soyuqdəyməyə yoluxurlar. İlk aylarda çətin görünən bu proses, o an üçün körpədə sadəcə narahatlıq hissi yaradır. Bu dövrü ən asan şəkildə keçirmək üçün sənə düşən vəzifə körpəni əlindən gəldiyi qədər rahat hiss etdirməkdir. Məsələn, xəstəlik zamanı körpənin bədəni daha çox yuxuya ehtiyac duyur. Buna görə də, hamamdan sonra ona edəcəyin rahatlaşdırıcı masaj yuxuya keçidi xeyli asanlaşdıracaq. Əgər burnu tutulubsa, başının altına yastıq qoyma; burnunu duzlu su ilə təmizlə və otağın havasını nəmləndir. Unutma ki, soyuqdəymə zamanı körpənin mayeyə ehtiyacı artır, ona görə də bol su içməsini və ana südü (və ya süni qida) qəbul etməsini təmin etməlisən.$q$),
(25, 'baby_daily_info', '7dcfd4f4-9aee-4c8d-9828-a2d3f2df221d', 'info', 'text', $q$Körpənin həzm sistemi artıq xeyli inkişaf edib və ailəvi səhər yeməyi süfrəsində ona da yer ayırmamaq üçün heç bir səbəb yoxdur. Məsələn, əmizdirdikdən sonra (və ya süni qida qəbul edirsə, bir stəkan süni qida ilə birlikdə) körpənə pendir, zeytun, taxıllı çörək, hətta təbii kərə yağı da verə bilərsən. Lakin körpən hələ hər şeyi yeməyə hazır deyil. Bu səbəbdən bu dövrdə də badımcan, yumurta ağı, bal, inək və keçi südündən, eləcə də allergen olduğu bilinən meyvələrdən uzaq durmalısan. Körpənin allergiya riskini minimuma endirmək üçün genetik quruluşu dəyişdirilmiş, güclü pestisidlərə məruz qalmış, tərkibində asılılıq yaradan dadlandırıcılar və qoruyucu maddələr olan qidalardan qaçınmalısan. Çünki bu proseslərdən keçən qidalar təbiiliyini tamamilə itirir və körpənin metabolizmi üçün yad maddəyə çevrilir. Ən çox allergiya yaradan qidalar arasında işlənmiş konservlər, geni ilə oynanılmış bəzi buğda məhsulları, kimyəvi maddə tərkibli meyvələr və süd məhsulları yer alır. Buna görə də körpən üçün konservləşdirilmiş qidalardan uzaq durub, meyvə və tərəvəzlərin də təbii olanını seçərək allergiya riskini azaltmağın çox vacibdir.$q$, $q$Körpənin həzm sistemi artıq xeyli inkişaf edib və ailəvi səhər yeməyi süfrəsində ona da yer ayırmamaq üçün heç bir səbəb yoxdur. Məsələn, əmizdirdikdən sonra (və ya süni qida qəbul edirsə, bir stəkan süni qida ilə birlikdə) körpənə pendir, zeytun, taxıllı çörək, hətta təbii kərə yağı da verə bilərsən. Lakin körpən hələ hər şeyi yeməyə hazır deyil. Bu səbəbdən bu dövrdə də badımcan, bal, inək və keçi südündən, eləcə də allergen olduğu bilinən meyvələrdən uzaq durmalısan. Körpənin sağlamlığı üçün genetik quruluşu dəyişdirilmiş, güclü pestisidlərə məruz qalmış, tərkibində asılılıq yaradan dadlandırıcılar və qoruyucu maddələr olan qidalardan qaçınmalısan. Çünki bu proseslərdən keçən qidalar təbiiliyini tamamilə itirir və körpənin metabolizmi üçün yad maddəyə çevrilir. Ən çox allergiya yaradan qidalar arasında süd, yumurta, yerfındığı, buğda, balıq və dəniz məhsulları yer alır. Buna görə də bu qidaları həkim nəzarətində, az miqdarda və tədricən tanıtmağın allergiya riskini azaltmaq üçün çox vacibdir.$q$),
(26, 'baby_daily_info', '37f66307-1b67-498c-b0b6-20e87a8898b8', 'info', 'text', $q$Diş baxımı hər kəs üçün olduğu kimi, körpən üçün də eyni dərəcədə vacibdir. Xüsusilə yeni çıxan dişlərin sağlam böyüməsi onun gələcəyi üçün çox önəmlidir. Körpənin diş fırçalama vərdişini qazanması üçün buna indidən başlamaq və rutin halına gətirmək lazımdır. İlk dövrlərdə dişlərə necə qulluq edəcəyin barədə sualların ola bilər. Körpənin ilk dişi çıxdıqda, tənzif və ya barmaq fırçalarla diş təmizliyini edə bilərsən. 1 yaşından sonra isə ona alacağın diş fırçasını əlinə verib, qarşısına keçərək necə fırçalayacağını göstərə bilərsən. Körpən əvvəlcə bacarmasa da, səni təqlid edərək qısa müddətdə bunu öyrənəcək. Ancaq unutmamaq lazımdır ki, diş məcunlarından istifadə etmək üçün hələ tezdir.$q$, $q$Diş baxımı hər kəs üçün olduğu kimi, körpən üçün də eyni dərəcədə vacibdir. Xüsusilə yeni çıxan dişlərin sağlam böyüməsi onun gələcəyi üçün çox önəmlidir. Körpənin diş fırçalama vərdişini qazanması üçün buna indidən başlamaq və rutin halına gətirmək lazımdır. İlk dövrlərdə dişlərə necə qulluq edəcəyin barədə sualların ola bilər. Körpənin ilk dişi çıxdıqda, tənzif və ya barmaq fırçalarla diş təmizliyini edə bilərsən. 1 yaşından sonra isə ona alacağın diş fırçasını əlinə verib, qarşısına keçərək necə fırçalayacağını göstərə bilərsən. Körpən əvvəlcə bacarmasa da, səni təqlid edərək qısa müddətdə bunu öyrənəcək. Unutma ki, ilk dişdən etibarən düyü dənəsi boyda flüorlu uşaq diş məcunundan istifadə edə bilərsən.$q$),
(27, 'baby_daily_info', '005de367-3aa8-4500-87f0-c7f5b37b1fe4', 'info', 'text', $q$Əgər körpəni əmizdirirsənsə və ya süni qida verirsənsə, bu mərhələdə onun gündəlik kalori ehtiyacının təxminən yarısı hələ də süddən qarşılanır. Ana südünün qida dəyəri orta hesabla 88% su, 55% yağ, 37% karbohidrat və 8% zülaldan ibarətdir. Südündə əsasən laktoza adlı karbohidrat var. Bu maddə süddən alınan kalori dəyərinin təxminən 40%-ni təmin edir. Olduqca enerji verən bu karbohidrat növü, eyni zamanda körpənin bağırsaqlarında zərərli bakteriyaların çoxalmasının qarşısını alan asidik bir mühit yaradır. Bağırsaqlardakı faydalı bakteriyaların yaranmasını sürətləndirərək, balanslı bir bağırsaq florasının formalaşmasına dəstək olur. Buna görə də, hələ sürətli inkişaf dövründə olan körpən üçün əmizdirmə müddətini bacardığın qədər uzatmağın vacibdir. Ana südü olmadıqda isə mütəxəssislər ən azı 1 yaşına qədər davamlı süd qarışıqlarının eyni qaydada verilməsini tövsiyə edirlər.$q$, $q$Əgər körpəni əmizdirirsənsə və ya süni qida verirsənsə, bu mərhələdə onun gündəlik kalori ehtiyacının təxminən yarısı hələ də süddən qarşılanır. Ana südünün təxminən 88%-i sudur; enerjisinin təxminən 55%-i yağdan, 37%-i karbohidratdan, 8%-i zülaldan gəlir. Südündə əsasən laktoza adlı karbohidrat var. Bu maddə süddən alınan kalori dəyərinin təxminən 40%-ni təmin edir. Olduqca enerji verən bu karbohidrat növü, eyni zamanda körpənin bağırsaqlarında zərərli bakteriyaların çoxalmasının qarşısını alan asidik bir mühit yaradır. Bağırsaqlardakı faydalı bakteriyaların yaranmasını sürətləndirərək, balanslı bir bağırsaq florasının formalaşmasına dəstək olur. Buna görə də, hələ sürətli inkişaf dövründə olan körpən üçün əmizdirmə müddətini bacardığın qədər uzatmağın vacibdir. Ana südü olmadıqda isə mütəxəssislər ən azı 1 yaşına qədər davamlı süd qarışıqlarının eyni qaydada verilməsini tövsiyə edirlər.$q$),
(28, 'baby_daily_info', '4b5a6bf3-177f-49f1-b076-3c5623ae0a32', 'info', 'text', $q$Körpənin ayaq əzələlərinin daha yaxşı güclənməsi üçün, onu evin içində mümkün qədər corabla gəzdirməyə davam etməlisən. Körpən yıxılmadan bir müddət yaxşı gəzməyə başlayana qədər, çöldə istifadə edəcəyin ayaqqabıların yumşaq və elastik olmasına diqqət etməlisən. Bilinənin əksinə, sərt dabanlı ayaqqabılar körpənin ayağının burxulmasına səbəb ola bilər. Sən nə qədər diqqət etsən də, o, sınaq mərhələsində tez-tez yıxılacaq. Yıxılanda böyük reaksiyalar verməsən, canı ağrımadığı müddətcə körpən buna ağlayaraq reaksiya verməz və səndən kömək istəməz. Hər hansı bir yıxılmada körpənin canı ağrıyar və ağlamağa başlayarsa, onu dərhal qucağına almaq əvəzinə, yanına çöməlib onu qucaqlaya bilərsən. Bu, körpənin gəzməkdən əl çəkməməsi və həvəsinin qırılmaması baxımından olduqca vacibdir.$q$, $q$Körpənin ayaq əzələlərinin daha yaxşı güclənməsi üçün, onu evin içində mümkün qədər ayaqyalın gəzdirməyə davam etməlisən. Körpən yıxılmadan bir müddət yaxşı gəzməyə başlayana qədər, çöldə istifadə edəcəyin ayaqqabıların yumşaq və elastik olmasına diqqət etməlisən. Bilinənin əksinə, sərt dabanlı ayaqqabılar körpənin ayağının burxulmasına səbəb ola bilər. Sən nə qədər diqqət etsən də, o, sınaq mərhələsində tez-tez yıxılacaq. Yıxılanda böyük reaksiyalar verməsən, canı ağrımadığı müddətcə körpən buna ağlayaraq reaksiya verməz və səndən kömək istəməz. Hər hansı bir yıxılmada körpənin canı ağrıyar və ağlamağa başlayarsa, onu dərhal qucağına almaq əvəzinə, yanına çöməlib onu qucaqlaya bilərsən. Bu, körpənin gəzməkdən əl çəkməməsi və həvəsinin qırılmaması baxımından olduqca vacibdir.$q$),
(29, 'baby_daily_info', 'bc4b0b1c-8079-4973-9564-32f3aa0c7c31', 'info', 'text', $q$Avtomobilində hələ də uşaq oturacağı yoxdursa, ən qısa zamanda əldə etməyini məsləhət görürük. Mütəxəssislər körpənin doğumundan 1 yaşına qədər olan dövrdə körpə oturacağından, hərəkətlənməyə başladığı 1 yaşından sonra isə uşaq oturacağından istifadə etməyi tövsiyə edirlər. Avtomobildəki uşaq oturacağı, yolçuluq zamanı körpənin xəsarət alma riskini 90% azaldır. Bu sayədə körpən, ehtimal olunan bir qəza zamanı avtomobildən kənara atılma, sıxılma və sarsılma kimi təhlükələrdən qorunmuş olar. Uşaq oturacaqları avtomobilə sabit şəkildə yerləşdirildikdə, körpən heç bir narahatlıq yaşamadan səyahət edə bilər. Bundan əlavə, körpə oturacaqlarından fərqli olaraq, uşaq oturacaqlarını tərs deyil, avtomobilin gediş istiqamətinə doğru sabitləyə bilərsən. Beləliklə, körpənin ürəkbulanma problemini minimuma endirə və ətrafı rahatlıqla müşahidə etməsini təmin edə bilərsən.$q$, $q$Avtomobilində hələ də uşaq oturacağı yoxdursa, ən qısa zamanda əldə etməyini məsləhət görürük. Mütəxəssislər körpənin doğumundan 1 yaşına qədər olan dövrdə körpə oturacağından, hərəkətlənməyə başladığı 1 yaşından sonra isə uşaq oturacağından istifadə etməyi tövsiyə edirlər. Avtomobildəki uşaq oturacağı, yolçuluq zamanı körpənin xəsarət alma riskini 90% azaldır. Bu sayədə körpən, ehtimal olunan bir qəza zamanı avtomobildən kənara atılma, sıxılma və sarsılma kimi təhlükələrdən qorunmuş olar. Uşaq oturacaqları avtomobilə sabit şəkildə yerləşdirildikdə, körpən heç bir narahatlıq yaşamadan səyahət edə bilər. Bundan əlavə, uşaq oturacağını mümkün qədər uzun müddət, ən azı 2 yaşa qədər və ya oturacağın icazə verdiyi maksimum çəki və boya çatana qədər, arxaya baxan vəziyyətdə saxlamalısan. Bu vəziyyət qəza zamanı körpənin başını, boynunu və onurğasını daha yaxşı qoruyur.$q$),
(30, 'baby_daily_info', '3120d7eb-f951-4312-bcfe-96b26a90343b', 'info', 'text', $q$Xüsusilə yay aylarında körpənin bişməcə olmaması üçün bir çox üsulu sınadığını bilirik. Uşaq pudrası da bu məqsədlə istifadə edilən vasitələrdən biridir. Mütəxəssislər toz pudraların körpələrin ağciyərlərinə zərərli təsir göstərə biləcəyi səbəbindən bu növ məhsulların istifadəsinə qarşı çıxırlar. Lakin yenə də körpənin baxımında pudradan istifadə edirsənsə, diqqət etməli olduğun bəzi məqamlar var. Məsələn, tərkibində alüminium, ətir və kanserojen təsirli qoruyucular olan markalardan uzaq durmalısan. Əgər Mən uşaq pudrasını özüm hazırlaya bilərəm deyirsənsə, bunun üçün sənə tam təbii bir təklifimiz var. Lazım olanlar sadəcə yarım çay stəkanı qarğıdalı nişastası və bir neçə damcı təbii efir yağıdır. Nişastanı bir qaba tök və üzərinə yağı damcılat. Topaqlanmaması üçün mətbəx robotundan keçirə bilərsən. Hazırladığın qarışığı köhnə bir pudra qabına və ya istifadə etmədiyin iri deşikli bir duz qabına tök. Təbii uşaq pudran hazırdır! 😊$q$, $q$Xüsusilə yay aylarında körpənin bişməcə olmaması üçün bir çox üsulu sınadığını bilirik. Uşaq pudrası da bu məqsədlə istifadə edilən vasitələrdən biridir. Mütəxəssislər toz pudraların körpələrin ağciyərlərinə zərərli təsir göstərə biləcəyi səbəbindən bu növ məhsulların istifadəsinə qarşı çıxırlar. Lakin yenə də körpənin baxımında pudradan istifadə edirsənsə, diqqət etməli olduğun bəzi məqamlar var. Məsələn, tərkibində alüminium, ətir və kanserojen təsirli qoruyucular olan markalardan uzaq durmalısan. Bişməcənin qarşısını almaq üçün isə bezi tez-tez dəyiş, dərini yaxşıca qurut və sink oksidli krem istifadə et. 😊$q$),
(31, 'baby_daily_info', '87ccab00-63bc-4286-b706-8a9dd745c897', 'info', 'text', $q$İlk 3 il, yəni 36 aylıq müddət körpənin sinir sisteminin inkişafı baxımından olduqca həssas bir dövr hesab olunur. Buna görə də körpənin bu dövrdə qəbul etdiyi qidalar onun sağlam böyüməsi və inkişafında son dərəcə əhəmiyyətlidir. Mütəxəssislər ilk 3 il ərzində körpələrin tamamilə orqanik qidalarla bəslənməsi mövzusunda həmfikirdirlər. Orqanik qidalar tarladan və ya bağçadan körpənə çatdırılana qədər tərkibində heç bir zərərli maddə olmayan qida qrupudur. Son illərdə dövrümüzün bəlası olan xərçəng, hormonal pozğunluqlar, hiperaktivlik, autizm və beyin şişləri kimi ciddi xəstəliklərin kökündə əsasən qeyri-sağlam qidalanma dayanır. Həmçinin, qeyri-sağlam qidalanma məktəb dövründə erkən yetkinlik, obezitet və diqqət əskikliyi kimi problemlərə də səbəb ola bilər. Buna görə də körpən üçün alış-veriş edərkən orqanik etiketi ilə satılan və təbii məhsullara üstünlük verməyin tövsiyə olunur.$q$, $q$İlk 3 il, yəni 36 aylıq müddət körpənin sinir sisteminin inkişafı baxımından olduqca həssas bir dövr hesab olunur. Buna görə də körpənin bu dövrdə qəbul etdiyi qidalar onun sağlam böyüməsi və inkişafında son dərəcə əhəmiyyətlidir. Orqanik və ya adi, yaxşı yuyulmuş təzə qidalar sağlam qidalanmanın əsasıdır. Orqanik qidalar tarladan və ya bağçadan körpənə çatdırılana qədər tərkibində heç bir zərərli maddə olmayan qida qrupudur. Qeyri-sağlam qidalanma məktəb dövründə erkən yetkinlik, piylənmə və diqqət əskikliyi kimi problemlərə də səbəb ola bilər. Buna görə də körpən üçün alış-veriş edərkən təzə və təbii məhsullara üstünlük verməyin tövsiyə olunur.$q$),
(32, 'baby_daily_info', 'd1d27c7e-e74b-46d9-99df-1056732e6f26', 'info', 'text', $q$Körpən artıq demək olar ki, hər cür meyvə, tərəvəz və paxlalı bitkiləri yeyə bilər. Ancaq unutmamaq lazımdır ki, onun həzm sistemi səninki ilə müqayisədə hələ tam inkişaf etməyib. Buna görə də körpənin bədəninin hələ də inək südü və bəzi allergen meyvələrə qarşı reaksiya verə biləcəyini yaddan çıxarmamalısan. Xüsusilə inək südü bəzi körpələrdə həddindən artıq qaz, qarın ağrısı və qusma kimi problemlərə səbəb ola bilər. İnək südü allergiyası körpənin bədəninin süddəki zülallara verdiyi anormal reaksiyadır. Buna görə bəzi mütəxəssislər inək südünün 2 yaşından əvvəl verilməməsi vacibliyini müdafiə edirlər. Həmçinin, allergen olduğu üçün mütəxəssislər tərəfindən bir yaşına qədər verilməməsi məsləhət görülən çiyələk, naringi və portağal kimi meyvələr hələ də körpəndə bəzi allergik reaksiyalara səbəb ola bilər. Odur ki, inkişafına uyğun olduğu bildirilən qidaları versən belə, ilk dəfə dadacağı bir qidanı yenə də üç gün qaydasına əməl edərək verməlisən. Bu sayədə körpənin hansı qidalara qarşı allergiyasının olduğunu anlamağın daha asan olacaq.$q$, $q$Körpən artıq demək olar ki, hər cür meyvə, tərəvəz və paxlalı bitkiləri yeyə bilər. Ancaq unutmamaq lazımdır ki, onun həzm sistemi səninki ilə müqayisədə hələ tam inkişaf etməyib. Buna görə də körpənin bədəninin hələ də inək südü və bəzi allergen meyvələrə qarşı reaksiya verə biləcəyini yaddan çıxarmamalısan. Xüsusilə inək südü bəzi körpələrdə həddindən artıq qaz, qarın ağrısı və qusma kimi problemlərə səbəb ola bilər. İnək südü allergiyası körpənin bədəninin süddəki zülallara verdiyi anormal reaksiyadır. Bununla belə, inək südü 1 yaşdan etibarən (gündə 500 ml-dən çox olmamaqla) verilə bilər. Həmçinin, allergen olduğu üçün mütəxəssislər tərəfindən bir yaşına qədər verilməməsi məsləhət görülən çiyələk, naringi və portağal kimi meyvələr hələ də körpəndə bəzi allergik reaksiyalara səbəb ola bilər. Odur ki, inkişafına uyğun olduğu bildirilən qidaları versən belə, ilk dəfə dadacağı bir qidanı yenə də üç gün qaydasına əməl edərək verməlisən. Bu sayədə körpənin hansı qidalara qarşı allergiyasının olduğunu anlamağın daha asan olacaq.$q$),
(33, 'baby_daily_info', '8d2b01ca-6cc3-467d-9372-bc9b93da9f40', 'info', 'text', $q$Körpənin qanındakı oksigenin toxumalara çatmasını təmin edən dəmir mineralı ən vacib maddələrdən biridir. Dəmir çatışmazlığı olan körpələrdə iştahsızlıq ən çox rast gəlinən problemlərdəndir. Həmçinin ağlayarkən göyərmə və nəfəsin kəsilməsi də tez-tez görülən əlamətlərdir. Əgər körpənin narahat, əsəbi olduğunu və diqqətini toplaya bilmədiyini müşahidə edirsənsə, həkimindən lazımi analizləri etməsini istəyə bilərsən. Ümumi rəyə görə, 1-3 yaş arası uşaqlar gündə təxminən 7 mq dəmir qəbul etməlidir. Bu səbəbdən körpənin qida rasionuna qırmızı və ağ ət, balıq, yumurta və süd kimi qidaları daha tez-tez daxil etməlisən. Əgər qırmızı və ağ ətin körpən tərəfindən çətin həzm edildiyini düşünürsənsə, onları mütəmadi olaraq tərəvəz yeməklərinə qata bilərsən. Unutma ki, bütün paxlalılar, lobya, ispanaq, yerkökü, kartof və quru meyvələr də kifayət qədər yeyildikdə körpənin gündəlik protein ehtiyacını qarşılaya bilər.$q$, $q$Körpənin qanındakı oksigenin toxumalara çatmasını təmin edən dəmir mineralı ən vacib maddələrdən biridir. Dəmir çatışmazlığı olan körpələrdə iştahsızlıq ən çox rast gəlinən problemlərdəndir. Həmçinin ağlayarkən göyərmə və nəfəsin kəsilməsi də tez-tez görülən əlamətlərdir. Əgər körpənin narahat, əsəbi olduğunu və diqqətini toplaya bilmədiyini müşahidə edirsənsə, həkimindən lazımi analizləri etməsini istəyə bilərsən. Ümumi rəyə görə, 1-3 yaş arası uşaqlar gündə təxminən 7 mq dəmir qəbul etməlidir. Bu səbəbdən körpənin qida rasionuna qırmızı ət, toyuq, balıq, yumurta və paxlalılar kimi qidaları daha tez-tez daxil etməlisən. Əgər qırmızı və ağ ətin körpən tərəfindən çətin həzm edildiyini düşünürsənsə, onları mütəmadi olaraq tərəvəz yeməklərinə qata bilərsən. Unutma ki, bütün paxlalılar, lobya, ispanaq, yerkökü, kartof və quru meyvələr də kifayət qədər yeyildikdə körpənin gündəlik dəmir ehtiyacını qarşılaya bilər.$q$),
(34, 'baby_daily_info', 'e1d2295d-b294-489f-9966-9998c1e7d923', 'info', 'text', $q$Bəzi dövrlərdə keçirdiyi xəstəliklər səbəbindən körpənin bədən hərarəti yüksələ bilər, yəni qızdırması ola bilər. Körpənin hərarətini müəyyən intervallarla izləmək, olası xəstəliyin erkən diaqnozu üçün çox vacibdir. Bədən hərarəti artdıqda orqanizm normaldan daha çox enerji sərf etməyə başlayır. Qan dövranı və tənəffüs sistemləri daha sürətli işləyir. Həmçinin, qızdırma zamanı qol və ayaqlardakı damarlar daraldığı üçün bu bölgələrə daha az qan gedir. Beyin, ürək, qaraciyər kimi həyati orqanlara isə daha çox qan axını təmin edilir. Bu o deməkdir ki, körpən qızdırma zamanı daha çox oksigenə və mayeyə ehtiyac duyur. Körpənin qızdırmasının qalxdığını hiss etdikdə; oynaqlarına ilıq su və pambıqla kompres edə bilər, maye ehtiyacını qarşılamaq üçün su içirə bilər və üzərində nazik geyimlər olmasına diqqət yetirə bilərsən. Əsas diqqət etməli olduğun məqam, körpənin hərarətinin 38.5°C-ni keçməməsidir. Bu dərəcəyə çatdıqda, qıcolma riski səbəbindən vaxt itirmədən körpəni ən yaxın tibb müəssisəsinə aparmağın həyati əhəmiyyət daşıyır.$q$, $q$Bəzi dövrlərdə keçirdiyi xəstəliklər səbəbindən körpənin bədən hərarəti yüksələ bilər, yəni qızdırması ola bilər. Körpənin hərarətini müəyyən intervallarla izləmək, olası xəstəliyin erkən diaqnozu üçün çox vacibdir. Bədən hərarəti artdıqda orqanizm normaldan daha çox enerji sərf etməyə başlayır. Qan dövranı və tənəffüs sistemləri daha sürətli işləyir. Həmçinin, qızdırma zamanı qol və ayaqlardakı damarlar daraldığı üçün bu bölgələrə daha az qan gedir. Beyin, ürək, qaraciyər kimi həyati orqanlara isə daha çox qan axını təmin edilir. Bu o deməkdir ki, körpən qızdırma zamanı daha çox oksigenə və mayeyə ehtiyac duyur. Körpənin qızdırmasının qalxdığını hiss etdikdə; oynaqlarına ilıq su və pambıqla kompres edə bilər, maye ehtiyacını qarşılamaq üçün su içirə bilər və üzərində nazik geyimlər olmasına diqqət yetirə bilərsən. Hərarət 38.5°C-dən yuxarı olduqda həkim məsləhəti ilə qızdırmasalıcı verə bilərsən. Hərarət 40°C-dən yuxarı qalxarsa, qıcolma, həddindən artıq süstlük, səpgi və ya nəfəs çətinliyi olarsa, vaxt itirmədən təcili yardıma müraciət et.$q$),
(35, 'baby_daily_info', '130cff01-0ee0-4d85-a9f9-730114f30e31', 'info', 'text', $q$Ənənəvi kənd təsərrüfatında istifadə olunan kimyəvi maddələrin böyük bir hissəsi körpənin bədənindəki piy toxumasında toplanır. Xüsusilə körpənin formalaşma mərhələsindən, yəni hələ doğulmadan əvvəl və doğulduqdan sonrakı ilk 36 ayda böyümə və piy hüceyrələrinin yaranması çox sürətlə gedir. Bu dövrlərdə körpənin kimyəvi maddələrə məruz qalması, gələcəkdə sağlamlığına ciddi təsir edən amillərdən birinə çevrilir. Orqanik olmayan meyvə və tərəvəzlərdəki ən böyük riski onların tərkibinə qarışan pestisid qalıqları yaradır. Körpənin orqanizmi səninkinə nisbətən qat-qat həssas və müdafiəsizdir. Buna görə də körpə həmin pestisid qalıqlarını bədənindən təhlükəsiz şəkildə təmizləyə bilmir. Bütün bu məlumatlar işığında, səhiyyə təşkilatları və pediatrlar körpələrin sağlamlığı üçün kritik olan bu dövrlərdə xüsusilə orqanik qidaların istehlakını tövsiyə edirlər. Odur ki, körpənin sağlamlığı üçün meyvə və tərəvəz seçimində orqanik məhsullar sənin ilk seçimin olmalıdır.$q$, $q$Ənənəvi kənd təsərrüfatında istifadə olunan kimyəvi maddələrin böyük bir hissəsi körpənin bədənindəki piy toxumasında toplanır. Xüsusilə körpənin formalaşma mərhələsindən, yəni hələ doğulmadan əvvəl və doğulduqdan sonrakı ilk 36 ayda böyümə və piy hüceyrələrinin yaranması çox sürətlə gedir. Bu dövrlərdə körpənin kimyəvi maddələrə məruz qalması, gələcəkdə sağlamlığına ciddi təsir edən amillərdən birinə çevrilir. Orqanik olmayan meyvə və tərəvəzlərdəki ən böyük riski onların tərkibinə qarışan pestisid qalıqları yaradır. Körpənin orqanizmi səninkinə nisbətən qat-qat həssas və müdafiəsizdir. Buna görə də körpə həmin pestisid qalıqlarını bədənindən təhlükəsiz şəkildə təmizləyə bilmir. Buna görə də meyvə-tərəvəzi yaxşıca yu. Orqanik məhsullar bir seçim ola bilər, amma körpənin sağlamlığı üçün əsas olan müxtəlif və balanslı qidalanmadır.$q$),
(36, 'baby_daily_info', 'f03f7ef6-1201-4627-b01c-144e9eca5d2c', 'info', 'text', $q$Körpənin qarşısına qoyduğun hər şeyi iştahla yeməsi səni xoşbəxt etsə də, əsas məqsəd onun qarnını sadəcə doyurmaq yox, inkişafı üçün ən faydalı qidaları vermək olmalıdır. Məsələn, körpənin bədəni sənə nisbətən gündəlik 6 dəfə daha çox D vitamininə ehtiyac duyur. Yeni sümük yaranması üçün böyüklərə nəzərən 4 qat artıq kalsium və 4 qat çox C vitamini tələb olunur. Eyni şəkildə sink və dəmir ehtiyacı da yüksəkdir. Buna görə də körpənin kiçik mədəsini həzmi çətin olan çörəklə və ya sadəcə sudan ibarət, qida dəyəri aşağı şorbalarla doldurmamalısan. Xüsusilə çörək, hələ tam formalaşmamış metabolizmi olan körpən üçün həzmi ağır bir qidadır və onun bədəninin həqiqi vitamin ehtiyaclarını qarşılamır.$q$, $q$Körpənin qarşısına qoyduğun hər şeyi iştahla yeməsi səni xoşbəxt etsə də, əsas məqsəd onun qarnını sadəcə doyurmaq yox, inkişafı üçün ən faydalı qidaları vermək olmalıdır. Məsələn, sürətlə böyüyən bədəni üçün D vitamini, kalsium və C vitamini xüsusilə vacibdir; yeni sümük yaranmasında kalsium və D vitamini mühüm rol oynayır. Eyni şəkildə sink və dəmir də onun inkişafı üçün çox önəmlidir. Buna görə də körpənin kiçik mədəsini həzmi çətin olan çörəklə və ya sadəcə sudan ibarət, qida dəyəri aşağı şorbalarla doldurmamalısan. Xüsusilə çörək, hələ tam formalaşmamış metabolizmi olan körpən üçün həzmi ağır bir qidadır və onun bədəninin həqiqi vitamin ehtiyaclarını qarşılamır.$q$),
(37, 'baby_daily_info', '4b17e497-f9cb-44ce-9613-c013217b2cc2', 'info', 'text', $q$Körpənizin bu mərhələdə gündə 3 əsas yeməyə ehtiyacı var. Qidalanma proqramını buna uyğun tənzimləmək vacibdir. Lakin unutmamaq lazımdır ki, körpəniz üçün əsas yeməklər qədər ara paylar da çox əhəmiyyətlidir. Əsas yeməklər kimi, ara payları da üç dəfəyə bölə bilərsiniz. Həmçinin bu zaman verilən atışdırmalıqların körpənizin əsas iştahına təsir etməməsinə diqqət yetirməlisiniz. Gün ərzində enerji ehtiyacını qarşılamaq və yorğunluqdan qaynaqlanan narahatlıqların qarşısını almaq üçün ara paylarda nə yediyi mühüm rol oynayır. Məsələn, quru meyvələr həm kifayət qədər enerji verir, həm də qida dəyəri yüksək olduğu üçün inkişafına müsbət təsir göstərir. Quru meyvələr C vitamini ilə zəngindir. Bu səbəbdən xüsusilə fəsil dəyişikliyi dövründə körpənizin xəstəliklərə qarşı immunitetini artırmaqda çox effektivdir. Körpələr üçün xüsusi hazırlanmış quru meyvələr ala bilərsiniz və ya mövsümündə meyvələri dilimləyib qurudaraq özünüz hazırlaya bilərsiniz. Nuş olsun! 😊$q$, $q$Körpənizin bu mərhələdə gündə 3 əsas yeməyə ehtiyacı var. Qidalanma proqramını buna uyğun tənzimləmək vacibdir. Lakin unutmamaq lazımdır ki, körpəniz üçün əsas yeməklər qədər ara paylar da çox əhəmiyyətlidir. Əsas yeməklər kimi, ara payları da üç dəfəyə bölə bilərsiniz. Həmçinin bu zaman verilən atışdırmalıqların körpənizin əsas iştahına təsir etməməsinə diqqət yetirməlisiniz. Gün ərzində enerji ehtiyacını qarşılamaq və yorğunluqdan qaynaqlanan narahatlıqların qarşısını almaq üçün ara paylarda nə yediyi mühüm rol oynayır. Məsələn, quru meyvələr həm kifayət qədər enerji verir, həm də qida dəyəri yüksək olduğu üçün inkişafına müsbət təsir göstərir. Quru meyvələr lif, kalium və dəmir mənbəyidir. Bu səbəbdən xüsusilə fəsil dəyişikliyi dövründə körpənizin balanslı qidalanması üçün faydalı əlavədir. Körpələr üçün xüsusi hazırlanmış quru meyvələr ala bilərsiniz və ya mövsümündə meyvələri dilimləyib qurudaraq özünüz hazırlaya bilərsiniz. Nuş olsun! 😊$q$),
(38, 'baby_daily_info', 'd8afee3a-b92b-4e65-9d4b-116cb3237d17', 'info', 'text', $q$Körpənizin sağlam qidalanması həm fiziki, həm də zehni inkişafı üçün böyük əhəmiyyət kəsb edir. Bunu, əlbəttə ki, bilirsiniz. Eyni zamanda, balanslı və nizamlı qidalanma rejimi körpənizin gələcəkdə, məktəb illərində daha uğurlu olması üçün indidən açar rol oynayır! 😊 Bu baxımdan körpənizin bütün tərəvəzlərə və onların tərkibindəki keyfiyyətli qida dəyərlərinə ehtiyacı var. Miqdarları fərqli olsa da, bütün tərəvəzlər vitaminlər, kalsium, natrium, kalium, dəmir, fosfor, maqnezium, selenyum, mis və manqan kimi elementlərlə zəngindir. Əgər körpəniz zülal tərkibi yüksək olan digər qidaları yemirsinizsə, yaşıl noxud kimi tərkibində protein olan tərəvəzlərdən yararlana bilərsiniz. Noxudun ölçüsü kiçik olsa da, tərkibində kalsium, A vitamini, C vitamini və dəmir var. Olduqca enerji verən bir tərəvəzdir və 100 qramında olan 5%-lik zülal dəyəri ilə körpənizin sağlam inkişafına böyük töhfə verir. Diqqət etməli olduğunuz məqam isə boğulma təhlükəsinə qarşı noxudu bişirdikdən sonra çəngəllə bir az əzməyinizdir. Nuş olsun! 😊$q$, $q$Körpənizin sağlam qidalanması həm fiziki, həm də zehni inkişafı üçün böyük əhəmiyyət kəsb edir. Bunu, əlbəttə ki, bilirsiniz. Eyni zamanda, balanslı və nizamlı qidalanma rejimi körpənizin gələcəkdə, məktəb illərində daha uğurlu olması üçün indidən açar rol oynayır! 😊 Bu baxımdan körpənizin bütün tərəvəzlərə və onların tərkibindəki keyfiyyətli qida dəyərlərinə ehtiyacı var. Miqdarları fərqli olsa da, bütün tərəvəzlər vitaminlər, kalsium, natrium, kalium, dəmir, fosfor, maqnezium, selenyum, mis və manqan kimi elementlərlə zəngindir. Əgər körpəniz zülal tərkibi yüksək olan digər qidaları yemirsə, yaşıl noxud kimi tərkibində protein olan tərəvəzlərdən yararlana bilərsiniz. Noxudun ölçüsü kiçik olsa da, tərkibində kalsium, A vitamini, C vitamini və dəmir var. Olduqca enerji verən bir tərəvəzdir və 100 qramında olan 5%-lik zülal dəyəri ilə körpənizin sağlam inkişafına böyük töhfə verir. Diqqət etməli olduğunuz məqam isə boğulma təhlükəsinə qarşı noxudu bişirdikdən sonra çəngəllə bir az əzməyinizdir. Nuş olsun! 😊$q$),
(39, 'baby_daily_info', '6b1536bb-dc88-4b75-bf0c-4f8004f171e6', 'info', 'text', $q$Körpənizin bu aykı peyvənd təqvimində olan və Hepatit A virusunun səbəb olduğu Hepatit A xəstəliyi, olduqca yoluxucu bir qaraciyər infeksiyasıdır. Bu virus qaraciyərin işinə təsir edən və iltihaba səbəb olan müxtəlif hepatit viruslarından biridir. Hepatit A dünyada hələ də geniş yayılmışdır və adətən payız və qışın ilk aylarında daha çox rast gəlinir. Ən effektiv qorunma üsulu 12 və 24-cü aylarda vurulan peyvəndlərdir. 6 ay fasilə ilə vurulan bu iki doza körpənizi təxminən 20 il boyunca bu xəstəlikdən qoruyur. Peyvəndin yerli yan təsirləri kimi iynə yerində ağrı, həssaslıq və ya qızartı ola bilər; bu hal körpələrin 15-20%-ində görülür. Hərarət, ishal və yorğunluq kimi hallar isə 10%-dən az müşahidə edilir. Ehtiyac olduqda həkim məsləhəti ilə tərkibində parasetamol olan dərmanlar istifadə edə bilərsiniz.$q$, $q$Körpənizin bu ayki peyvənd təqvimində olan və Hepatit A virusunun səbəb olduğu Hepatit A xəstəliyi, olduqca yoluxucu bir qaraciyər infeksiyasıdır. Bu virus qaraciyərin işinə təsir edən və iltihaba səbəb olan müxtəlif hepatit viruslarından biridir. Hepatit A dünyada hələ də geniş yayılmışdır və adətən payız və qışın ilk aylarında daha çox rast gəlinir. Ən effektiv qorunma üsulu 18 və 24-cü aylarda vurulan peyvəndlərdir. 6 ay fasilə ilə vurulan bu iki doza körpənizi təxminən 20 il boyunca bu xəstəlikdən qoruyur. Peyvəndin yerli yan təsirləri kimi iynə yerində ağrı, həssaslıq və ya qızartı ola bilər; bu hal körpələrin 15-20%-ində görülür. Hərarət, ishal və yorğunluq kimi hallar isə 10%-dən az müşahidə edilir. Ehtiyac olduqda həkim məsləhəti ilə tərkibində parasetamol olan dərmanlar istifadə edə bilərsiniz.$q$),
(40, 'baby_daily_info', 'e467989b-610e-431a-a5b3-8aea02815e27', 'info', 'text', $q$Körpənizin qidalanma proqramına daxil etdiyiniz yumurta həm ağı, həm də sarısı baxımından olduqca zəngin qida dəyərlərinə malikdir. Yumurtanın tərkibində A, B5, B12, B2, B6, D, E və K vitaminləri ilə yanaşı, kalsium, sink, fosfor, selenium və folat turşusu var. Lakin körpəniz üçün çox vacib olan bu qida yaxşı bişirilmədikdə bəzi problemlərə yol aça bilər. Salmonella virusu əsasən quşlar olmaqla digər heyvanların və insanların bağırsaq sistemində yaşayır. Adətən heyvan nəcisi ilə təmasda olan qidaların yeyilməsi ilə insanlara keçir. Bu səbəbdən yumurtanı körpənizə verməzdən əvvəl bişirmə mərhələsini düzgün tənzimləməlisiniz. Orta hesabla 10 dəqiqə qaynatmaq və çiy hissə qalmadığından əmin olmaq vacibdir. Çünki yumurta, quş əti, çiy tərəvəz və meyvə kimi riskli qidaların yaxşı bişirilməsi salmonella virusunu məhv edir. Lakin diqqət etməli olduğunuz məqam odur ki, yumurta gərəyindən artıq qaynadıldıqda qida dəyərini itirir. Buna görə də bişirmə müddətini doğru nizamlamalısınız.$q$, $q$Körpənizin qidalanma proqramına daxil etdiyiniz yumurta həm ağı, həm də sarısı baxımından olduqca zəngin qida dəyərlərinə malikdir. Yumurtanın tərkibində A, B5, B12, B2, B6, D, E və K vitaminləri ilə yanaşı, kalsium, sink, fosfor, selenium və folat turşusu var. Lakin körpəniz üçün çox vacib olan bu qida yaxşı bişirilmədikdə bəzi problemlərə yol aça bilər. Salmonella bakteriyası əsasən quşlar olmaqla digər heyvanların və insanların bağırsaq sistemində yaşayır. Adətən heyvan nəcisi ilə təmasda olan qidaların yeyilməsi ilə insanlara keçir. Bu səbəbdən yumurtanı körpənizə verməzdən əvvəl bişirmə mərhələsini düzgün tənzimləməlisiniz. Orta hesabla 10 dəqiqə qaynatmaq və çiy hissə qalmadığından əmin olmaq vacibdir. Çünki yumurta, quş əti, çiy tərəvəz və meyvə kimi riskli qidaların yaxşı bişirilməsi salmonella bakteriyasını məhv edir. Lakin diqqət etməli olduğunuz məqam odur ki, yumurta gərəyindən artıq qaynadıldıqda qida dəyərini itirir. Buna görə də bişirmə müddətini doğru nizamlamalısınız.$q$),
(41, 'baby_daily_info', 'fdc70af8-a3f8-4766-bbcc-b755e0c46b80', 'info', 'text', $q$Hətta 1 ədədi belə körpənizin gündəlik C vitamini ehtiyacının yarısını qarşılayan brokoli, xüsusilə qış aylarında körpənizin menyusunda mütləq olmalı tərəvəzlərdən biridir. Miniatür ağac görünüşü ilə körpənizin diqqətini çəkə biləcəyi üçün onu formasını qoruyaraq bişirmək yaxşı bir taktikadır. Brokoli tərkibindəki liflər sayəsində körpənizin həzm sistemini rahatlatmağa və onu qəbizlik kimi narahatlıqlardan qorumağa kömək edir. Körpənizin kalsium, maqnezium, dəmir, selenium, manqan, kalium və sink kimi minerallarla yanaşı; C, A, B16, B2 və E vitaminlərinə olan ehtiyacını da brokolidən asanlıqla təmin edə bilərsiniz. Brokolinin tərkibindəki sulforafan maddəsi körpənizin beyin hüceyrələrinə müsbət təsir göstərir. Son illərin araşdırmalarına görə, sulforafan tərkibli qidaların qəbulu beyin pozğunluqlarının müalicəsində faydalıdır. Brokolinin ən üst hissəsindəki cücərti hissəsi qalan hissələrinə nisbətən 20 dəfə daha çox sulforafan ehtiva edir, buna görə də körpənizin bu hissəni yediyindən əmin olmalısınız.$q$, $q$Hətta 1 ədədi belə körpənizin gündəlik C vitamini ehtiyacının yarısını qarşılayan brokoli, xüsusilə qış aylarında körpənizin menyusunda mütləq olmalı tərəvəzlərdən biridir. Miniatür ağac görünüşü ilə körpənizin diqqətini çəkə biləcəyi üçün onu formasını qoruyaraq bişirmək yaxşı bir taktikadır. Brokoli tərkibindəki liflər sayəsində körpənizin həzm sistemini rahatlatmağa və onu qəbizlik kimi narahatlıqlardan qorumağa kömək edir. Körpənizin kalsium, maqnezium, dəmir, selenium, manqan, kalium və sink kimi minerallarla yanaşı; C, A, B1, B6, B2 və E vitaminlərinə olan ehtiyacını da brokolidən asanlıqla təmin edə bilərsiniz. Brokolinin tərkibindəki sulforafan maddəsi körpənizin beyin hüceyrələrinə müsbət təsir göstərir. Son illərin araşdırmalarına görə, sulforafan tərkibli qidaların qəbulu beyin pozğunluqlarının müalicəsində faydalıdır. Brokolinin ən üst hissəsindəki cücərti hissəsi qalan hissələrinə nisbətən 20 dəfə daha çox sulforafan ehtiva edir, buna görə də körpənizin bu hissəni yediyindən əmin olmalısınız.$q$),
(42, 'baby_daily_info', 'fc4caf55-748d-4981-b396-817290848621', 'info', 'text', $q$Günümüzdə piylənmənin artdığı bütün ölkələr diabet baxımından risk altındadır. Əvvəllər ən tez 5-7 yaşlarında rast gəlinsə də, insulin çatışmazlığı səbəbindən yaranan Tip 1 diabet xəstəliyinə artıq körpələrdə belə rast gəlinə bilər. Tip 1 diabet yarandıqda hüceyrə səviyyəsində aclıq hissi yaranır və qaraciyərə daha çox enerji istehsal etməsi üçün siqnallar göndərilir. Bu vəziyyətdə qaraciyər enerji istehsalı üçün sürətli yağ yandırma prosesinə başlayır. Yağların yandırılması nəticəsində bədəndə keton adlanan asidik maddələr üzə çıxır. Ketonlar tez-tez ürəkbulanma və qusmaya səbəb olur. Çox yeməyə və artan iştahaya baxmayaraq, çəki itkisi də tez-tez görünən bir əlamətdir. Bundan əlavə, bədəndəki yüksək şəkər səviyyəsinə bağlı olaraq yaraların gec sağalması, qız körpələrin cinsiyyət bölgələrində tez-tez göbələk infeksiyaları ilə əlaqəli qaşıntı və qızartıların yaranması da diabetin əlamətləri sayıla bilər. Buna görə də diabetin erkən diaqnozu çox vacibdir. Körpənizin rutin həkim müayinələri və analizlərinin vaxtında edilməsi ehtimal olunan diabetin erkən fərqinə varılmasını təmin edəcək.$q$, $q$İnsulin çatışmazlığı səbəbindən yaranan Tip 1 diabet istənilən yaşda, hətta körpələrdə də yarana bilər. Tip 1 diabet yarandıqda hüceyrə səviyyəsində aclıq hissi yaranır və qaraciyərə daha çox enerji istehsal etməsi üçün siqnallar göndərilir. Bu vəziyyətdə qaraciyər enerji istehsalı üçün sürətli yağ yandırma prosesinə başlayır. Yağların yandırılması nəticəsində bədəndə keton adlanan turş maddələr üzə çıxır. Ketonlar tez-tez ürəkbulanma və qusmaya səbəb olur. Çox yeməyə və artan iştahaya baxmayaraq, çəki itkisi də tez-tez görünən bir əlamətdir. Bundan əlavə, bədəndəki yüksək şəkər səviyyəsinə bağlı olaraq yaraların gec sağalması, qız körpələrin cinsiyyət bölgələrində tez-tez göbələk infeksiyaları ilə əlaqəli qaşıntı və qızartıların yaranması da diabetin əlamətləri sayıla bilər. Buna görə də diabetin erkən diaqnozu çox vacibdir. Körpənizin rutin həkim müayinələri və analizlərinin vaxtında edilməsi ehtimal olunan diabetin erkən fərqinə varılmasını təmin edəcək.$q$),
(43, 'baby_daily_info', '2b51d001-1cfb-4b5b-bddc-35b70fcc2c0e', 'info', 'text', $q$Kalsium mineralı körpənin orqanizmində ən çox olan qeyri-təbii birləşmədir. Bu mərhələdə körpənin qanının hər 10 millilitrində təxminən 1 mq kalsium olur. Kalsium körpənin inkişaf etməkdə olan sümük metabolizması və əzələləri üçün ən vacib maddələrdən biridir. Yeni sümük yaranmasında, dişlərin strukturunda, qan laxtalanmasında, sinir sisteminin tənzimlənməsində və sağlam hormon balansının qorunmasında böyük rol oynayır. Körpən ehtiyacı olan kalsiumu qidalar vasitəsilə alır. Əgər kifayət qədər kalsium qəbul etməzsə, orqanizm dişlərdə və toxumalarda olan kalsiumu istifadə etməyə başlayır. Bu isə körpənin dişlərinin və sümüklərinin həssaslaşmasına, asan qırılmasına səbəb ola bilər. Körpənin gündəlik 800 mq kalsiuma ehtiyacı var. Süd və süd məhsulları, yaşıl yarpaqlı tərəvəzlər, qulançar, bəhməz, kişmiş, qara gavalı qurusu, paxlalılar, brokoli, bamya, balqabaq, kələm, qoz və balıq körpən üçün əla kalsium mənbələridir.$q$, $q$Kalsium körpənin orqanizmində ən çox olan mineraldır. Bu mərhələdə körpənin qanının hər 10 millilitrində təxminən 1 mq kalsium olur. Kalsium körpənin inkişaf etməkdə olan sümük metabolizması və əzələləri üçün ən vacib maddələrdən biridir. Yeni sümük yaranmasında, dişlərin strukturunda, qan laxtalanmasında, sinir sisteminin tənzimlənməsində və sağlam hormon balansının qorunmasında böyük rol oynayır. Körpən ehtiyacı olan kalsiumu qidalar vasitəsilə alır. Əgər kifayət qədər kalsium qəbul etməzsə, orqanizm dişlərdə və toxumalarda olan kalsiumu istifadə etməyə başlayır. Bu isə körpənin dişlərinin və sümüklərinin həssaslaşmasına, asan qırılmasına səbəb ola bilər. Körpənin gündəlik 800 mq kalsiuma ehtiyacı var. Süd və süd məhsulları, yaşıl yarpaqlı tərəvəzlər, qulançar, bəhməz, kişmiş, qara gavalı qurusu, paxlalılar, brokoli, bamya, balqabaq, kələm, qoz və balıq körpən üçün əla kalsium mənbələridir.$q$),
(44, 'baby_daily_info', '1738d682-243e-48b6-aebf-069b7de44903', 'info', 'text', $q$Körpənizin qidalarının mövsümünə uyğun və təbii olmasına diqqət yetirməlisiniz. Məsələn, yay aylarında yetişən pərpətöyün balıqdan sonra ən çox Omeqa-3 ehtiva edən qidadır. Əgər körpəniz balıq sevmirsə, pərpətöyün əla seçimdir. Payıza keçid dövründə körpənizin menyusuna çiy qoz-fındıq əlavə edərək onun immunitet sistemini qışa hazırlaya bilərsiniz. Payızda həmçinin körpələrin çox sevdiyi balqabaq mövsümü başlayır. Balqabağı şorbalara, yeməklərə qata və ya püre halına salıb qoz-fındıqla birlikdə ara pay kimi verə bilərsiniz. Qış aylarında isə ət bulyonu ilə hazırlanmış şorbalar körpənizin bədən müqavimətini artırmaq üçün ən yaxşı vasitədir.$q$, $q$Körpənizin qidalarının mövsümünə uyğun və təbii olmasına diqqət yetirməlisiniz. Məsələn, yay aylarında yetişən pərpətöyün bitki mənşəli Omeqa-3 ilə zəngin qidalardandır. Əgər körpəniz balıq sevmirsə, pərpətöyün faydalı əlavədir, lakin balığı tam əvəz etmir. Payıza keçid dövründə körpənizin menyusuna çiy qoz-fındığı üyüdülmüş və ya əzilmiş halda əlavə edərək onun immunitet sistemini qışa hazırlaya bilərsiniz. Payızda həmçinin körpələrin çox sevdiyi balqabaq mövsümü başlayır. Balqabağı şorbalara, yeməklərə qata və ya püre halına salıb əzilmiş qoz-fındıqla birlikdə ara pay kimi verə bilərsiniz. Qış aylarında isə ət bulyonu ilə hazırlanmış şorbalar körpənizin bədən müqavimətini artırmaq üçün ən yaxşı vasitədir.$q$),
(45, 'baby_daily_info', '91bdc58d-0298-42d1-becf-b47ed9613a9c', 'info', 'text', $q$Propolis arıların bitkilərin saplaqlarından, yarpaqlarından və tumurcuqlarından topladığı, güclü antibakterial və antioksidant təsirə malik bir maddədir. Dünyada kəşf edilən ən güclü antioksidant xüsusiyyətli bu maddə, nar şirəsindən 80 dəfə daha çox antioksidant ehtiva edir. Arılar yapışqan qatılıqda olan bu maddəni daha çox pətəklərini sterilizə etmək və zərərli mikroorqanizmləri zərərsizləşdirmək üçün istifadə edirlər. Düzgün emal edildikdə isə propolisin insanların immuniteti üzərində sübut olunmuş bir çox faydası var. Xüsusilə, immuniteti hələ tam formalaşmamış körpənizi qorumaq üçün propolisin immunitet gücləndirici təsirlərindən faydalana bilərsiniz. Əgər körpəniz bal yeyirsə və bala qarşı hər hansı bir allergiyası yoxdursa, propolisi rahatlıqla qəbul edə bilər. Propolis müntəzəm istifadə edildikdə körpənizin immunitetini gücləndirir, xəstəlik zamanı bədəndəki virus və bakteriyaları yox edir və xəstəliklərə yoluxma riskini böyük ölçüdə azaldır.$q$, $q$Propolis arıların bitkilərin saplaqlarından, yarpaqlarından və tumurcuqlarından topladığı, güclü antibakterial və antioksidant təsirə malik bir maddədir. Arılar yapışqan qatılıqda olan bu maddəni daha çox pətəklərini sterilizə etmək və zərərli mikroorqanizmləri zərərsizləşdirmək üçün istifadə edirlər. Propolisin insanlar üçün faydaları ilə bağlı araşdırmalar davam edir. Lakin propolis allergik reaksiyalara səbəb ola bilər və kiçik uşaqlar üçün rutin olaraq tövsiyə edilmir. Buna görə də propolisi körpənizə yalnız həkim məsləhəti ilə verin. Körpənizin immunitetini qorumağın ən etibarlı yolu isə balanslı qidalanma, kifayət qədər yuxu və peyvəndlərin vaxtında edilməsidir.$q$),
(46, 'baby_daily_info', '8b5577e9-8555-46ea-9858-e2aca89ca5d4', 'info', 'text', $q$Körpəniz üçün bu dövrdə evdə asanlıqla tapa biləcəyiniz vəsaitlərdən öyrədici materiallar hazırlaya bilərsiniz. Sizə lazım olanlar: şüşə butulka, plastik butulka, bir qədər su, düyü, quru lobya və mərci kimi müxtəlif paxlalı bitkilərdir. İlk növbədə bütün vəsaitləri körpənizə tanıtmaqla başlayın. Şüşə və plastik butulkanın qapağını açaraq, növbə ilə onları üfürməsini istəyin. Hər iki qabdan niyə fərqli səslər çıxdığını körpənizdən soruşa bilərsiniz. Sonra bu butulkalara bir az su tökərək sınağı təkrarlaya və səslərin niyə dəyişdiyi barədə bir-birinizə suallar verə bilərsiniz. Daha sonra şüşə butulkaya düyü kimi xırda dənəli paxlalıları doldurub körpənizin onu çalxalamasını təmin edin. Eyni prosesi plastik butulka üçün də edin və dənəciklər eyni olsa da, şüşə butulkadan çıxan səsin niyə daha zil olduğunu soruşun. Bu fəaliyyəti digər dənli bitkilərlə də təkrarlayaraq səslərin dəyişmə səbəblərini birlikdə anlamağa çalışın. Sizə xoş əyləncələr! 😊$q$, $q$Körpəniz üçün bu dövrdə evdə asanlıqla tapa biləcəyiniz vəsaitlərdən öyrədici materiallar hazırlaya bilərsiniz. Sizə lazım olanlar: iki fərqli ölçülü plastik butulka, bir qədər su, düyü, quru lobya və mərci kimi müxtəlif paxlalı bitkilərdir. İlk növbədə bütün vəsaitləri körpənizə tanıtmaqla başlayın. Butulkaların qapağını açaraq, növbə ilə onları üfürməsini istəyin. Hər iki qabdan niyə fərqli səslər çıxdığını körpənizdən soruşa bilərsiniz. Sonra bu butulkalara bir az su tökərək sınağı təkrarlaya və səslərin niyə dəyişdiyi barədə bir-birinizə suallar verə bilərsiniz. Daha sonra butulkalardan birinə düyü və paxlalıları doldurub qapağını möhkəm bağlayın və nəzarətiniz altında körpənizin onu çalxalamasını təmin edin. Eyni prosesi digər butulka üçün də edin və dənəciklər eyni olsa da, səslərin niyə fərqli olduğunu soruşun. Dənəciklər boğulma təhlükəsi yaratdığı üçün oyun boyu körpənizi nəzarətsiz qoymayın. Bu fəaliyyəti digər dənli bitkilərlə də təkrarlayaraq səslərin dəyişmə səbəblərini birlikdə anlamağa çalışın. Sizə xoş əyləncələr! 😊$q$),
(47, 'baby_daily_info', '6fd1f804-625f-4260-ad27-7db11651d8f4', 'info', 'text', $q$Son illərdə aparılan araşdırmalara görə, bəzi mütəxəssislər uşaqların ilk iki il ərzində inək südü və ya inək südündən hazırlanan dondurma qəbuluna ehtiyatla yanaşırlar. Bunun əsas səbəbi bağırsaq inkişafının yalnız 2 yaş civarında tam formalaşması və inək südünün qanazlığı riskini artıra biləcəyi ehtimalıdır. Körpəniz artıq 2 yaşına yaxınlaşır; əgər onun süd və süd məhsullarına qarşı məlum bir allergiyası yoxdursa, həkiminizlə məsləhətləşərək dondurma yeməsinə icazə verə bilərsiniz. Zülal və karbohidratlarla zəngin olan dondurma, demək olar ki, bütün vitaminləri, həmçinin kalsium, kalium, fosfor, maqnezium, dəmir və sink kimi mineralları özündə birləşdirir. Xüsusilə körpənizin sümük inkişafı üçün vacib olan kalsiumu digər qidalardan kifayət qədər ala bilmirsinizsə, dondurma yaxşı bir alternativ ola bilər. Lakin körpənizin dondurma qəbulunda həddi aşmamasına diqqət yetirməlisiniz. Karbohidrat və şəkər tərkibinə görə çox miqdarda yeyilən dondurmanın artıq kalori verəcəyini unutmayın.$q$, $q$Mütəxəssislər 1 yaşdan sonra uşağın rasionuna inək südünün daxil edilə biləcəyini bildirirlər. Körpəniz artıq 2 yaşına yaxınlaşır; əgər onun süd və süd məhsullarına qarşı məlum bir allergiyası yoxdursa, arabir az miqdarda dondurma yeməsinə icazə verə bilərsiniz. Lakin unutmayın ki, dondurma şəkərli şirniyyatdır və kalsium mənbəyi kimi tövsiyə olunmur. Körpənizin sümük inkişafı üçün vacib olan kalsiumu süd, qatıq və pendir kimi qidalardan almaq daha doğrudur. Lakin körpənizin dondurma qəbulunda həddi aşmamasına diqqət yetirməlisiniz. Karbohidrat və şəkər tərkibinə görə çox miqdarda yeyilən dondurmanın artıq kalori verəcəyini unutmayın.$q$),
(48, 'baby_daily_info', 'c6878c04-fea4-41bf-9978-ffa27c8ba4e7', 'info', 'text', $q$2 yaşını tamamlamağa az qalmış körpənizin bu günlərdə ayaqlarını göstərərək çox hərəkət etmək istəmədiyini müşahidə edə bilərsiniz. Körpəniz doğulduğu andan təxminən 12-13 yaşına qədər sümüklərin epifiz lövhəsi nahiyələrindən uzanması ilə fiziki olaraq böyüyür. Bu uzanma zamanı xüsusilə çiyin nahiyələri, biləklər və ayaqların dizdən aşağı və yuxarı hissələrində ağrıların olması normal sayılır. Qız və oğlan uşaqlarında eyni dərəcədə rast gəlinən bu ağrılar sümüyün böyümə sahəsində baş verən dəyişikliklər nəticəsində yaranır. Daha dəqiq desək, sümüklərin ətrafındakı əzələ, vətər və bağ toxuması kimi yumşaq toxumaların böyümə zamanı yaranan ödemlər səbəbindən həssaslaşması bu ağrılara yol açır. Körpəniz bu böyümə ağrılarını gündüz aktivliyi səbəbindən axşam saatlarında daha intensiv hiss edə bilər. Adətən müalicə tələb etməyən bu ağrıları dincəlməklə və həmin nahiyəyə yüngül masaj etməklə azalda bilərsiniz.$q$, $q$2 yaşını tamamlamağa az qalmış körpənizin ayaqlarını göstərərək ağrıdan şikayət etdiyini və ya yeriməkdən imtina etdiyini müşahidə etsəniz, mütləq həkimə müraciət edin. Böyümə ağrılarına isə adətən daha böyük yaşlarda, 3-12 yaş arasında rast gəlinir. Körpəniz doğulduğu andan təxminən 12-13 yaşına qədər sümüklərin epifiz lövhəsi nahiyələrindən uzanması ilə fiziki olaraq böyüyür. Bu uzanma zamanı xüsusilə çiyin nahiyələri, biləklər və ayaqların dizdən aşağı və yuxarı hissələrində ağrıların olması normal sayılır. Qız və oğlan uşaqlarında eyni dərəcədə rast gəlinən bu ağrılar sümüyün böyümə sahəsində baş verən dəyişikliklər nəticəsində yaranır. Daha dəqiq desək, sümüklərin ətrafındakı əzələ, vətər və bağ toxuması kimi yumşaq toxumaların böyümə zamanı yaranan ödemlər səbəbindən həssaslaşması bu ağrılara yol açır. Körpəniz bu böyümə ağrılarını gündüz aktivliyi səbəbindən axşam saatlarında daha intensiv hiss edə bilər. Adətən müalicə tələb etməyən bu ağrıları dincəlməklə və həmin nahiyəyə yüngül masaj etməklə azalda bilərsiniz.$q$),
(49, 'baby_daily_info', '94c13633-51b3-4740-9eed-f9195f6997ac', 'info', 'text', $q$Körpələrə televizor izlətmək xüsusilə yemək yeməkdə çətinlik çəkən anaların tez-tez müraciət etdiyi üsullar arasındadır. Texnologiya dövründə uşaqları planşet, telefon və televizordan tamamilə uzaq tutmaq bəzən çətin olur. Lakin araşdırmalar göstərir ki, xüsusilə 2 yaş və ondan kiçik yaşlarda televizor izləyən uşaqlarda autizm başda olmaqla ağır inkişaf pozuntuları riski artır. Bununla yanaşı, körpələrdə koqnitiv inkişafın mənfi təsirlənməsi, dil və nitq bacarıqlarının ləngiməsi, diqqət əskikliyi və hiperaktivlik kimi problemlər də yarana bilər. Bütün bu səbəblərə görə, Amerika Pediatriya Akademiyası daxil olmaqla bir çox qurum, 0-2 yaş arası körpələrin ekranlı texnoloji cihazlardan uzaq durmasını tövsiyə edir. Televizor vərdişinin əvəzinə körpənizlə birlikdə şəkilli kitablar oxumaq, rəsm çəkmək, nitq məşqləri etmək, həmyaşıdları ilə və öyrədici oyuncaqlarla oynamaq kimi fəaliyyətlərə üstünlük verməlisiniz. Yemək zamanı isə körpənizin diqqətini çəkmək üçün rəngli və maraqlı təqdimatlar hazırlaya, ona sevdiyi personajların təsviri olan qablar ala bilərsiniz.$q$, $q$Körpələrə televizor izlətmək xüsusilə yemək yeməkdə çətinlik çəkən anaların tez-tez müraciət etdiyi üsullar arasındadır. Texnologiya dövründə uşaqları planşet, telefon və televizordan tamamilə uzaq tutmaq bəzən çətin olur. Lakin araşdırmalar göstərir ki, xüsusilə 2 yaş və ondan kiçik yaşlarda çox televizor izləyən uşaqlarda dil və nitq bacarıqlarının ləngiməsi, yuxu və diqqət problemləri riski artır. Bununla yanaşı, körpələrdə koqnitiv inkişaf da mənfi təsirlənə bilər. Bütün bu səbəblərə görə, Amerika Pediatriya Akademiyası daxil olmaqla bir çox qurum, 0-2 yaş arası körpələrin ekranlı texnoloji cihazlardan uzaq durmasını tövsiyə edir. Televizor vərdişinin əvəzinə körpənizlə birlikdə şəkilli kitablar oxumaq, rəsm çəkmək, nitq məşqləri etmək, həmyaşıdları ilə və öyrədici oyuncaqlarla oynamaq kimi fəaliyyətlərə üstünlük verməlisiniz. Yemək zamanı isə körpənizin diqqətini çəkmək üçün rəngli və maraqlı təqdimatlar hazırlaya, ona sevdiyi personajların təsviri olan qablar ala bilərsiniz.$q$),
(50, 'baby_daily_info', '401eecb4-6ff0-4a6b-b5b2-6f546861d6f5', 'info', 'text', $q$Körpənizin öskürməsi, ümumiyyətlə, qısa müddətdə keçən bir narahatlıqdır. Lakin öskürəyin uzunmüddətli olması və şiddətlənməsi göyöskürəyə səbəb ola bilər. Göyöskürək xüsusilə 5 yaşından kiçik uşaqlarda ağır keçən, kəskin və yoluxucu bir tənəffüs yolu xəstəliyidir. Bütün dünyada yayılmış bu xəstəliyə Bordetella pertussis adlı bakteriya səbəb olur. Göyöskürək uzunmüddətli öskürək tutmalarına yol açır və yoluxmuş şəxsin öskürəyi ilə havaya yayılan damcılar vasitəsilə keçir. Göyöskürəyin qarşısını almağın ən yaxşı yolu peyvəndlənmədir. Həmçinin körpələr və göyöskürək ağırlaşmaları baxımından risk qrupuna daxil olan digər şəxslər xəstə insandan uzaq tutulmalıdır. Göyöskürək peyvəndi Səhiyyə Nazirliyinin peyvənd təqviminə əsasən 2-ci, 4-cü və 12-ci aylarda beşli kombinə edilmiş peyvənd şəklində vurulur. Son doza isə ibtidai məktəbin 1-ci sinfində dördlü kombinə edilmiş peyvənd şəklində olmaqla, cəmi 5 dəfə tətbiq edilir.$q$, $q$Körpənizin öskürməsi, ümumiyyətlə, qısa müddətdə keçən bir narahatlıqdır. Lakin uzun sürən və şiddətlənən öskürək göyöskürəyin əlaməti ola bilər. Göyöskürək xüsusilə 5 yaşından kiçik uşaqlarda ağır keçən, kəskin və yoluxucu bir tənəffüs yolu xəstəliyidir. Bütün dünyada yayılmış bu xəstəliyə Bordetella pertussis adlı bakteriya səbəb olur. Göyöskürək uzunmüddətli öskürək tutmalarına yol açır və yoluxmuş şəxsin öskürəyi ilə havaya yayılan damcılar vasitəsilə keçir. Göyöskürəyin qarşısını almağın ən yaxşı yolu peyvəndlənmədir. Həmçinin körpələr və göyöskürək ağırlaşmaları baxımından risk qrupuna daxil olan digər şəxslər xəstə insandan uzaq tutulmalıdır. Göyöskürək peyvəndi Səhiyyə Nazirliyinin peyvənd təqviminə əsasən körpəlik dövründə bir neçə dozada kombinə edilmiş peyvənd şəklində vurulur, sonra isə təkrar dozalarla möhkəmləndirilir. Övladınızın bütün dozaları vaxtında alıb-almadığını peyvənd kartı üzərindən həkiminizlə yoxlaya bilərsiniz.$q$),
(51, 'baby_daily_info', 'cfd2fffc-165b-4343-a449-c5ce0daed80c', 'info', 'text', $q$Qusma və reflü problemləri yeni doğulmuş körpələrdə tez-tez rast gəlinən fizioloji hallardan biridir. Adətən bərk qidaya keçidlə birlikdə azalmağa başlayan bu problem, bəzi körpələrdə bir müddət də davam edə bilər. Əgər körpəndə bu dövrdə qusma halları müşahidə olunursa və ya həkim tərəfindən reflü diaqnozu qoyulubsa, bir neçə ehtiyat tədbiri görməyin faydalı olar. İlk növbədə, körpəni bəsləyərkən onun mümkün qədər dik oturmasını təmin etməlisən. Daha az miqdarda, lakin daha tez-tez qidalanma rejimi qurmaq da effektiv olacaqdır. Qidalanmadan dərhal sonra körpənin hoppanma, yuvarlanma kimi hərəkətlər etməsinə icazə verməmək yediklərinın geri qayıtmasının qarşısını ala bilər. Bezin çox sıx bağlanması da körpənin qarnında təzyiqi artıraraq qaz və reflü yaranmasına səbəb ola bilər. Bundan əlavə, əgər körpənin yatağı tənzimlənəndirsə, baş hissəsini bir qədər yüksəkdə saxlaya bilər və ya xüsusi reflü yastıqlarından istifadə edə bilərsən.$q$, $q$Qusma və reflüks problemləri körpəlik dövründə tez-tez rast gəlinən fizioloji hallardan biridir. Adətən 1 yaş civarında azalan bu problem, bəzi uşaqlarda bir müddət də davam edə bilər. Əgər körpəndə bu dövrdə qusma halları müşahidə olunursa və ya həkim tərəfindən reflü diaqnozu qoyulubsa, bir neçə ehtiyat tədbiri görməyin faydalı olar. İlk növbədə, yemək zamanı onun dik oturmasını təmin etməlisən. Daha az miqdarda, lakin daha tez-tez qidalanma rejimi qurmaq da effektiv olacaqdır. Qidalanmadan dərhal sonra körpənin hoppanma, yuvarlanma kimi hərəkətlər etməsinə icazə verməmək yediklərinin geri qayıtmasının qarşısını ala bilər. Bezin və ya şalvar belinin çox sıx olması da körpənin qarnında təzyiqi artıraraq qaz və reflü yaranmasına səbəb ola bilər. Bundan əlavə, yatmazdan bir qədər əvvəl ağır yemək verməmək faydalı ola bilər. Yataqla bağlı hər hansı tədbiri isə yalnız həkiminin məsləhəti ilə gör.$q$),
(52, 'baby_daily_info', '3f0a45ad-f763-4336-92e9-52283443a724', 'info', 'text', $q$Bütün dünyada olduğu kimi, ölkəmizdə də mütəxəssislər körpələrin ilk 6 ay yalnız ana südü ilə qidalanmasını və bu prosesin orta hesabla 24 aya qədər davam etdirilməsini tövsiyə edirlər. Lakin əmizdirməni nə vaxt dayandıracağınızla bağlı tək bir doğru cavab yoxdur. Bu müddət 2 ildən daha az ola bildiyi kimi, 2 ildən daha uzun da çəkə bilər. Südverməni dayandırmaq üçün həm sənin, həm də körpənin buna hazır olması vacibdir. Bu, körpənin böyümə mərhələləri arasındakı ən mühüm qərarlardan biridir. Xüsusilə əmizdirməni kəsməyə qərar verdikdə, bir çox ana yüngül bir kədər və ya gərginlik hiss edə bilər. Bu, olduqca həssas bir dövr olduğu üçün əvvəlcədən planlama aparmaq faydalı olar. Körpənizlə daha çox fiziki təmasda olmaq, birlikdə keçirdiyiniz vaxtı artırmaq və ona bu prosesi anladığı dildə izah etməyə çalışmaq işinizi asanlaşdıracaq.$q$, $q$Bütün dünyada olduğu kimi, ölkəmizdə də mütəxəssislər körpələrin ilk 6 ay yalnız ana südü ilə qidalanmasını və bu prosesin orta hesabla 24 aya qədər davam etdirilməsini tövsiyə edirlər. Lakin əmizdirməni nə vaxt dayandıracağınızla bağlı tək bir doğru cavab yoxdur. Bu müddət 2 ildən daha az ola bildiyi kimi, 2 ildən daha uzun da çəkə bilər. Südverməni dayandırmaq üçün həm sizin, həm də körpənizin buna hazır olması vacibdir. Bu, körpənin böyümə mərhələləri arasındakı ən mühüm qərarlardan biridir. Xüsusilə əmizdirməni kəsməyə qərar verdikdə, bir çox ana yüngül bir kədər və ya gərginlik hiss edə bilər. Bu, olduqca həssas bir dövr olduğu üçün əvvəlcədən planlama aparmaq faydalı olar. Körpənizlə daha çox fiziki təmasda olmaq, birlikdə keçirdiyiniz vaxtı artırmaq və ona bu prosesi anladığı dildə izah etməyə çalışmaq işinizi asanlaşdıracaq.$q$),
(53, 'baby_daily_info', 'a12dbbd5-adef-4bb7-9633-097569e91a68', 'info', 'text', $q$Ana südü tayı-bərabəri olmayan möcüzəvi bir qidadır. Əgər körpəni bu vaxta qədər əmizdirmisənsə, səni təbrik edirik! 😊 Körpənin tezliklə 24 ayını tamamlaması onu dərhal süddən kəsməlisən demək deyil. Əmizdirməni nə vaxt bitirəcəyin sənin qərarın olsa da, hər şey qaydasındadırsa, ideal olanı 2 yaşına qədər davam etməkdir. Bəzi mütəxəssislər 2 yaşdan sonra süddən kəsilmənin əhəmiyyətini vurğulayırlar, çünki bu müddətdən sonra əmizdirmənin davam etməsi uşağın fərdiləşməsini gecikdirə və xarakter inkişafına təsir edə bilər. Diqqət etməli olduğun ən mühüm məqam prosesin birdən-birə baş verməməsidir. Körpənin ən əsas vərdişinin bir anda kəsilməsi onun psixologiyasında dərin izlər buraxa bilər.$q$, $q$Ana südü tayı-bərabəri olmayan möcüzəvi bir qidadır. Əgər körpəni bu vaxta qədər əmizdirmisənsə, səni təbrik edirik! 😊 Körpənin tezliklə 24 ayını tamamlaması onu dərhal süddən kəsməlisən demək deyil. Əmizdirməni nə vaxt bitirəcəyin sənin qərarın olsa da, hər şey qaydasındadırsa, ideal olanı 2 yaşına qədər davam etməkdir. 2 yaşdan sonra da ana və körpə istədikcə əmizdirməni davam etdirmək olar. Diqqət etməli olduğun ən mühüm məqam prosesin birdən-birə baş verməməsidir. Körpənin ən əsas vərdişinin bir anda kəsilməsi onun psixologiyasında dərin izlər buraxa bilər.$q$),
(54, 'baby_daily_info', '0cd3469d-8d4a-4f4e-bc31-4c507bf9612c', 'info', 'text', $q$Körpəniz artıq mənasını bildiyi və aktiv şəkildə istifadə edə bildiyi 4-5 sözü birləşdirərək cümlə qura bilər. Bu cümlələr özü haqqında, sevdiyi və sevmədiyi vəziyyətlər, istəkləri və suallarını əhatə edə bilər. Sizi danışarkən diqqətlə dinləyir və daha əvvəl eşitmədiyi bir sözü təkrar edə bilir. Beləliklə, söz ehtiyatına yeni sözlər əlavə edir. Hətta körpənizin tez-tez dinlədiyiniz və sadə sözlərdən ibarət mahnıları oxumağa çalışdığını müşahidə edə bilərsiniz! 😊 Doğulduğu andan etibarən daim eşitdiyi dili və o dilə aid səsləri öyrənən körpənizin, danışıq bacarığı qazanmaq üçün hələ öyrənəcəyi çox şey var. Körpənizin dil və danışıq bacarığını inkişaf etdirmək üçün ona tez-tez mahnılar oxumağı, gün ərzində etdiyiniz fəaliyyətləri ona danışmağı və gününüzün necə keçdiyi barədə söhbət etməyi unutmamalısınız. Xüsusilə onu sosiallaşa biləcəyi və həmyaşıdlarının olduğu mühitlərə çıxarmağınız dil bacarığını olduqca inkişaf etdirəcək.$q$, $q$Körpəniz artıq mənasını bildiyi və aktiv şəkildə istifadə edə bildiyi 2-3 sözü birləşdirərək sadə cümlələr qura bilər. Bu cümlələr özü haqqında, sevdiyi və sevmədiyi vəziyyətlər, istəkləri və suallarını əhatə edə bilər. Sizi danışarkən diqqətlə dinləyir və daha əvvəl eşitmədiyi bir sözü təkrar edə bilir. Beləliklə, söz ehtiyatına yeni sözlər əlavə edir. Hətta körpənizin tez-tez dinlədiyiniz və sadə sözlərdən ibarət mahnıları oxumağa çalışdığını müşahidə edə bilərsiniz! 😊 Doğulduğu andan etibarən daim eşitdiyi dili və o dilə aid səsləri öyrənən körpənizin, danışıq bacarığı qazanmaq üçün hələ öyrənəcəyi çox şey var. Körpənizin dil və danışıq bacarığını inkişaf etdirmək üçün ona tez-tez mahnılar oxumağı, gün ərzində etdiyiniz fəaliyyətləri ona danışmağı və gününüzün necə keçdiyi barədə söhbət etməyi unutmamalısınız. Xüsusilə onu sosiallaşa biləcəyi və həmyaşıdlarının olduğu mühitlərə çıxarmağınız dil bacarığını olduqca inkişaf etdirəcək.$q$),
(55, 'baby_daily_info', '98b637d9-7d59-44a7-bf65-65315858e258', 'info', 'text', $q$Körpənin hər istəyinə yox demək aranızdakı münasibətə xələl gətirə bilər. Həmçinin, sənin yox dediyinə həyat yoldaşın hə deyirsə, bu, körpənin beynini qarışdıracaq və gərginliyi artıracaqdır. Buna görə də yox dediyin məqamlarda ardıcıl və qətiyyətli olmağın çox vacibdir. Bəzən valideynlər yox sözünü işlətmədikdə uşağın özünəinamının artacağını düşünürlər, lakin bu sözün yerində və zamanında deyilməsi əslində inkişafa töhfə verir. Çünki hər istəyi yerinə yetirilən körpə harada dayanmalı olduğunu və sərhədlərini bilməyəcəkdir. Körpənə yox larına hörmət etməkdir. Beləliklə, o, bu sözü eşitdikdə inadkarlıq etmək əvəzinə, razılığa gəlməyə daha meyilli olacaqdır.$q$, $q$Körpənin hər istəyinə yox demək aranızdakı münasibətə xələl gətirə bilər. Həmçinin, sənin yox dediyinə həyat yoldaşın hə deyirsə, bu, körpənin beynini qarışdıracaq və gərginliyi artıracaqdır. Buna görə də yox dediyin məqamlarda ardıcıl və qətiyyətli olmağın çox vacibdir. Bəzən valideynlər yox sözünü işlətmədikdə uşağın özünəinamının artacağını düşünürlər, lakin bu sözün yerində və zamanında deyilməsi əslində inkişafa töhfə verir. Çünki hər istəyi yerinə yetirilən körpə harada dayanmalı olduğunu və sərhədlərini bilməyəcəkdir. Körpənə yox deməyin bir yolu da onun öz “yox”larına hörmət etməkdir. Beləliklə, o, bu sözü eşitdikdə inadkarlıq etmək əvəzinə, razılığa gəlməyə daha meyilli olacaqdır.$q$),
(56, 'baby_daily_info', '9051f36c-fed8-4ab1-82c1-a9cb54f63349', 'info', 'text', $q$Hər uşaq özünəməxsus inkişaf xüsusiyyətlərinə sahib olsa da, 2 yaş ümumi mənada ünsiyyətin sürətləndiyi bir dövrdür. Bu yaşda olan uşaqlar ortalama 20-30 fərqli söz deyə bilir və iki-üç sözdən ibarət cümlələr qura bilirlər. Qısa müddət ərzində bəsit cümlələr qurmaq bacarığı daha da inkişaf edəcək və o, dildən daha effektiv istifadə etməyə başlayacaqdır. Körpən bu dövrdə sözləri qarışdıra, birləşdirə, yeni şeylər öyrənməyə və deməyə çalışa bilər. Öyrənmə sürətinə paralel olaraq, o, dediyin demək olar hər şeyi anlayır, komandalarını yerinə yetirir və suallarının səbəbini qavrayır. Bəzi hallarda isə, sanki işinə gəlməyəndə səni eşitməzliyə vura bilər! 😊 Bütün bu davranışlar onun inkişaf prosesinin bir hissəsidir. Buna görə də övladının fərdi inkişaf tempinə hörmətlə yanaşmalı və ona qarşı daha anlayışlı olmalısan.$q$, $q$Hər uşaq özünəməxsus inkişaf xüsusiyyətlərinə sahib olsa da, 2 yaş ümumi mənada ünsiyyətin sürətləndiyi bir dövrdür. Bu yaşda olan uşaqlar adətən 50 və daha çox söz deyə bilir və iki-üç sözdən ibarət cümlələr qura bilirlər. Qısa müddət ərzində bəsit cümlələr qurmaq bacarığı daha da inkişaf edəcək və o, dildən daha effektiv istifadə etməyə başlayacaqdır. Körpən bu dövrdə sözləri qarışdıra, birləşdirə, yeni şeylər öyrənməyə və deməyə çalışa bilər. Öyrənmə sürətinə paralel olaraq, o, dediyin demək olar hər şeyi anlayır, komandalarını yerinə yetirir və suallarının səbəbini qavrayır. Bəzi hallarda isə, sanki işinə gəlməyəndə səni eşitməzliyə vura bilər! 😊 Bütün bu davranışlar onun inkişaf prosesinin bir hissəsidir. Buna görə də övladının fərdi inkişaf tempinə hörmətlə yanaşmalı və ona qarşı daha anlayışlı olmalısan.$q$),
(57, 'baby_daily_info', '0102cad4-afdc-443f-9c50-810c77e5f6b0', 'info', 'text', $q$Körpəniz bu dövrdə kifayət qədər aqressiv davranışlar nümayiş etdirə bilər. Bu aqressiya başqalarına vurmaq, dişləmək, yemək boşqabını aşırmaq və ya istəyi yerinə yetirilmədikdə sinir böhranı keçirmək şəklində ola bilər. Belə davranışlar uşağın öz duyğularını idarə edə bilməməsinin nəticəsidir. Uşaqlar əslində doğulduqları andan duyğularını idarə etməyi bilirlər, lakin bəzi yanlış davranışlar bu qabiliyyəti baltalaya bilər. Başqa sözlə, bir valideyn olaraq körpənizin hisslərini istəmədən də olsa sıxışdırdıqda, o, hisslərini gizlətməyi və ya sağlam olmayan yollarla ifadə etməyi öyrənir. Məsələn, sizin yanaşmanız doğru olsa belə, körpəniz sizdən aqressiya və ya mənfi rəftar görərsə, bunu normallaşdırmağa başlayar. Bir-birinizə və ya başqalarına olan qəzəbinizi şifahi zorakılıqla deyil, izahlı sözlərlə ifadə edərək körpənizə nümunə olmağınız vacibdir.$q$, $q$Körpəniz bu dövrdə kifayət qədər aqressiv davranışlar nümayiş etdirə bilər. Bu aqressiya başqalarına vurmaq, dişləmək, yemək boşqabını aşırmaq və ya istəyi yerinə yetirilmədikdə sinir böhranı keçirmək şəklində ola bilər. Belə davranışlar uşağın öz duyğularını idarə edə bilməməsinin nəticəsidir. Duyğuları idarə etmə bacarığı isə illər ərzində, valideynin dəstəyi ilə formalaşır və bəzi yanlış davranışlar bu prosesi çətinləşdirə bilər. Başqa sözlə, bir valideyn olaraq körpənizin hisslərini istəmədən də olsa sıxışdırdıqda, o, hisslərini gizlətməyi və ya sağlam olmayan yollarla ifadə etməyi öyrənir. Məsələn, sizin yanaşmanız doğru olsa belə, körpəniz sizdən aqressiya və ya mənfi rəftar görərsə, bunu normallaşdırmağa başlayar. Bir-birinizə və ya başqalarına olan qəzəbinizi şifahi zorakılıqla deyil, izahlı sözlərlə ifadə edərək körpənizə nümunə olmağınız vacibdir.$q$),
(58, 'baby_daily_info', '5c08add0-1273-45c1-b0fd-3449a7f6de9c', 'info', 'text', $q$Körpənizin digər həmyaşıdları kimi bu dövrdə çəki itirməsi tamamilə təbiidir. Lakin onun inkişafının ləngiməməsi və bədəninin ehtiyacı olan qida dəyərlərini ən yaxşı şəkildə alması üçün qidalanma proqramına yenidən nəzər salmalısınız. Hazırladığınız menyuda yüksək lifli və zülalla zəngin qidaların olması vacibdir. Bir müddət çox yağlı yeməklərdən uzaq dura bilərsiniz, lakin bu, rasionun tamamilə "yağsız" olması demək deyil. Çünki yağlar körpənizin həm fiziki, həm də zehni inkişafı üçün çox vacib bir makro qidadır. Əsas məqam odur ki, bu yağlar mütləq sağlam mənbələrdən gəlsin. Məsələn, avokado və balıq mükəmməl sağlam yağ mənbəyidir. Balıq tərkibindəki zəngin minerallar və Omeqa-3 sayəsində körpənizin sağlam böyüməsində böyük rol oynayır.$q$, $q$Körpənizin digər həmyaşıdları kimi bu dövrdə çəki artımının yavaşlaması tamamilə təbiidir; çəki itkisi varsa, həkimə müraciət edin. Lakin onun inkişafının ləngiməməsi və bədəninin ehtiyacı olan qida dəyərlərini ən yaxşı şəkildə alması üçün qidalanma proqramına yenidən nəzər salmalısınız. Hazırladığınız menyuda yüksək lifli və zülalla zəngin qidaların olması vacibdir. Bir müddət çox yağlı yeməklərdən uzaq dura bilərsiniz, lakin bu, rasionun tamamilə "yağsız" olması demək deyil. Çünki yağlar körpənizin həm fiziki, həm də zehni inkişafı üçün çox vacib bir makro qidadır. Əsas məqam odur ki, bu yağlar mütləq sağlam mənbələrdən gəlsin. Məsələn, avokado və balıq mükəmməl sağlam yağ mənbəyidir. Balıq tərkibindəki zəngin minerallar və Omeqa-3 sayəsində körpənizin sağlam böyüməsində böyük rol oynayır.$q$),
(59, 'baby_daily_info', '067c1fbe-4e1e-4749-96ff-19097dcc209e', 'info', 'text', $q$Övladın hələ də 2 yaş sindromunun əlamətlərini intensiv şəkildə yaşaya bilər. Bəzi uşaqlar bu dövrdən daha çox təsirlənir və uşaqlar arasında dişləmək kimi istənilməyən davranışlar müşahidə oluna bilər. Əgər balacada dişləmək, vurmaq, qəfil hirslənmək kimi hallar varsa, ilk növbədə səbirli və təmkinli olmağın vacibdir. Unutma ki, uşağının bu davranışı əslində bir vasitədir; o, istədiyi bir şeyi əldə etmək üçün belə davranır. Dişləyən və ya vuran uşaqlara qarşı davranışlarımızda net və qətiyyətli olmaq onun sağlam emosional inkişafı üçün çox önəmlidir. Əgər övladın hisslərini sözlərlə ifadə edə bilmirsə, bunu onun əvəzinə sən və ya atan edə bilərsiniz. Belə hallarda Sən çox qəzəblisən, elədir? kimi cümlələr quraraq, onun anlaşıldığını hiss etməsini təmin edə bilərsən.$q$, $q$Övladın hələ də 2 yaş sindromunun əlamətlərini intensiv şəkildə yaşaya bilər. Bəzi uşaqlar bu dövrdən daha çox təsirlənir və uşaqlar arasında dişləmək kimi istənilməyən davranışlar müşahidə oluna bilər. Əgər balacada dişləmək, vurmaq, qəfil hirslənmək kimi hallar varsa, ilk növbədə səbirli və təmkinli olmağın vacibdir. Unutma ki, uşağının bu davranışı əslində bir vasitədir; o, istədiyi bir şeyi əldə etmək üçün belə davranır. Dişləyən və ya vuran uşaqlara qarşı davranışlarımızda aydın və qətiyyətli olmaq onun sağlam emosional inkişafı üçün çox önəmlidir. Əgər övladın hisslərini sözlərlə ifadə edə bilmirsə, bunu onun əvəzinə sən və ya atası edə bilərsiniz. Belə hallarda Sən çox qəzəblisən, elədir? kimi cümlələr quraraq, onun anlaşıldığını hiss etməsini təmin edə bilərsən.$q$),
(60, 'baby_daily_info', '5abe92b5-f52e-400b-a5f6-cabd63afd859', 'info', 'text', $q$27 aylıq körpənizin inkişafı zamanı onun intensiv bir kimlik axtarışında olduğunu söyləmək olar. Bu dövrlərdə onun yanında hərəkətlərinizə və sözlərinizə diqqət yetirməyiniz olduqca vacibdir. Bir çox valideyn üçün arzuolunmaz bir hal olsa da, uşaqlar bu dövrdə eşitdikləri hər bir sözü istifadə etməyə başlaya bilərlər. Bu səbəbdən, körpənizin olduğu mühitdə xoşagəlməz və ya nalayiq ifadələr işlədən insanlara xəbərdarlıq etmək yaxşı fikir ola bilər. Eyni şəkildə, siz də körpənizin yanında mübahisə etməməyə, pis sözlər istifadə etməməyə və səs tonunuzu tənzimləməyə diqqət etməlisiniz. Çünki körpəniz sizdən gördüyü demək olar ki, hər şeyi təqlid etməyə başlayacaqdır. Buna görə də yaxşı bir rol model olmağa çalışın. Bu dövrdə övladınızın həm motor bacarıqlarını inkişaf etdirməsinə kömək etməli, həm də özünə qulluq vərdişləri qazanması üçün ona təlim verməlisiniz. Məsələn, körpəniz artıq sizin köməyiniz olmadan dişlərini fırçalaya bilməli və əllərini yuya bilməlidir.$q$, $q$27 aylıq körpənizin inkişafı zamanı onun intensiv bir kimlik axtarışında olduğunu söyləmək olar. Bu dövrlərdə onun yanında hərəkətlərinizə və sözlərinizə diqqət yetirməyiniz olduqca vacibdir. Bir çox valideyn üçün arzuolunmaz bir hal olsa da, uşaqlar bu dövrdə eşitdikləri hər bir sözü istifadə etməyə başlaya bilərlər. Bu səbəbdən, körpənizin olduğu mühitdə xoşagəlməz və ya nalayiq ifadələr işlədən insanlara xəbərdarlıq etmək yaxşı fikir ola bilər. Eyni şəkildə, siz də körpənizin yanında mübahisə etməməyə, pis sözlər istifadə etməməyə və səs tonunuzu tənzimləməyə diqqət etməlisiniz. Çünki körpəniz sizdən gördüyü demək olar ki, hər şeyi təqlid etməyə başlayacaqdır. Buna görə də yaxşı bir rol model olmağa çalışın. Bu dövrdə övladınızın həm motor bacarıqlarını inkişaf etdirməsinə kömək etməli, həm də özünə qulluq vərdişləri qazanması üçün ona təlim verməlisiniz. Məsələn, körpəniz sizin köməyinizlə dişlərini fırçalamağa və əllərini yumağa öyrəşməlidir.$q$),
(61, 'baby_daily_info', 'e03558fa-2b62-46f8-8b8d-62974309090d', 'info', 'text', $q$Bu aylarda körpəndə eqosentrik (özünəqapanma) meyilləri hələ də yüksək səviyyədə davam edir. Buna görə də o, bəzən eqoist davranışlar nümayiş etdirə bilər. Ancaq unutma ki, bu vəziyyət dövri xarakter daşıyır və zamanla keçib gedəcəkdir. Bu cür davranışların səbəbi körpənin məntiqinin hələ kifayət qədər inkişaf etməməsi, başqası anlayışını tam dərk etməməsi, paylaşmaq hissinin formalaşmaması və mücərrəd mənaları qavraya bilməməsidir. Eyni zamanda, o, hadisələri təsnif etmək, sıralamaq və ya qruplaşdırmaq bacarığına hələ tam sahib deyil. Bütün bunların nəticəsi olaraq, körpən sənin də daxil olmaqla, digər insanların fikir və düşüncələrini çox vaxt nəzərə almır. Çünki o, hələ bu idraki yetkinlik səviyyəsinə çatmayıb. Odur ki, narahat olmağına əsas yoxdur. Lakin bu vəziyyət səni çox qayğılandırırsa, bir mütəxəssislə məsləhətləşməyin faydalı ola bilər.$q$, $q$Bu aylarda körpəndə eqosentrik (mən-mərkəzçi) meyilləri hələ də yüksək səviyyədə davam edir. Buna görə də o, bəzən eqoist davranışlar nümayiş etdirə bilər. Ancaq unutma ki, bu vəziyyət dövri xarakter daşıyır və zamanla keçib gedəcəkdir. Bu cür davranışların səbəbi körpənin məntiqinin hələ kifayət qədər inkişaf etməməsi, başqası anlayışını tam dərk etməməsi, paylaşmaq hissinin formalaşmaması və mücərrəd mənaları qavraya bilməməsidir. Eyni zamanda, o, hadisələri təsnif etmək, sıralamaq və ya qruplaşdırmaq bacarığına hələ tam sahib deyil. Bütün bunların nəticəsi olaraq, körpən sənin də daxil olmaqla, digər insanların fikir və düşüncələrini çox vaxt nəzərə almır. Çünki o, hələ bu idraki yetkinlik səviyyəsinə çatmayıb. Odur ki, narahat olmağına əsas yoxdur. Lakin bu vəziyyət səni çox qayğılandırırsa, bir mütəxəssislə məsləhətləşməyin faydalı ola bilər.$q$),
(62, 'baby_daily_info', '42d066ad-b938-4b87-8fff-39d96cc2a17e', 'info', 'text', $q$Balıq körpənin qidalanmasında bəlkə də ən vacib protein mənbəyidir. Balığın təzəsini tapmaq, bişirmək və sümüklərini təmizləmək çətin gəldiyi üçün bir çox valideyn konservlərə üstünlük verir. Lakin konservləşdirilmiş balıqlar barədə diqqətli olmalısan. Konserv ton balıqları müxtəlif növ balıqlardan hazırlanır və bəzi növlərdə kiçik dozalarda belə toksik təsir göstərə bilən civə ola bilər. Ağ ton balığında civə miqdarı light ton balığına nisbətən daha yüksəkdir. Böyüklər üçün ağ ton balığı həftədə maksimum 170 qramla məhdudlaşdırılsa da, bu miqdar körpə üçün təhlükəli ola bilər. Çünki bu yaşda uşağa ayda cəmi 85 qram balıq kifayətdir. Odur ki, daha zəhmətli olsa da, konserv yerinə təzə dəniz məhsullarına üstünlük verməyin körpənin sağlamlığı üçün çox daha faydalıdır.$q$, $q$Balıq körpənin qidalanmasında bəlkə də ən vacib protein mənbəyidir. Balığın təzəsini tapmaq, bişirmək və sümüklərini təmizləmək çətin gəldiyi üçün bir çox valideyn konservlərə üstünlük verir. Lakin konservləşdirilmiş balıqlar barədə diqqətli olmalısan. Konserv ton balıqları müxtəlif növ balıqlardan hazırlanır və bəzi növlərdə kiçik dozalarda belə toksik təsir göstərə bilən civə ola bilər. Ağ ton balığında civə miqdarı açıq (light) ton balığına nisbətən daha yüksəkdir. Böyüklər üçün ağ ton balığı həftədə maksimum 170 qramla məhdudlaşdırılsa da, bu miqdar körpə üçün təhlükəli ola bilər. Çünki bu yaşda uşağa həftədə 2 dəfə kiçik porsiya az civəli balıq tövsiyə olunur. Odur ki, daha zəhmətli olsa da, konserv yerinə təzə dəniz məhsullarına üstünlük verməyin körpənin sağlamlığı üçün çox daha faydalıdır.$q$),
(63, 'baby_daily_info', '5d36b2bf-f065-4e27-b7dc-33f78f228aae', 'info', 'text', $q$Körpənin böyümə və inkişafının problemsiz davam etməsi üçün sağlam və balanslı qidalanma çox önəmlidir. Bu prosesdə zülalların (proteinlərin) rolu böyükdür. Bədənin əsas tikinti materialı olan zülallar əzələ və hüceyrələrin bərpası üçün zəruridir. Ana südü 1 yaşına qədər bu ehtiyacı qarşılayır. 1 yaşdan sonra isə gündəlik alınan zülalın 20%-i heyvani, 80%-i isə bitki mənşəli olmalıdır. Bu dövrdə körpənin hər kiloqram çəkisinə görə gündə 2 qram zülal alması kifayətdir. Bu da orta hesabla gündəlik 16 qram zülal deməkdir. Məsələn, 2 kasa qatıq və ya bir boşqab pendirli makaron körpənin gündəlik zülal ehtiyacını tam ödəyə bilər. Süd, yumurta, ət, toyuq və balıq kimi qidalar tam zülal mənbəyi olub, bədən üçün lazımlı bütün amin turşularını ehtiva edir. Bununla yanaşı, zülal ehtiyacını tam qarşılamaq üçün taxılları, paxlalıları və tərəvəzləri birlikdə verməyin faydalıdır.$q$, $q$Körpənin böyümə və inkişafının problemsiz davam etməsi üçün sağlam və balanslı qidalanma çox önəmlidir. Bu prosesdə zülalların (proteinlərin) rolu böyükdür. Bədənin əsas tikinti materialı olan zülallar əzələ və hüceyrələrin bərpası üçün zəruridir. Ana südü 1 yaşına qədər bu ehtiyacı qarşılayır. 1 yaşdan sonra isə zülal həm heyvani, həm də bitki mənşəli müxtəlif qidalardan alınmalıdır. Bu dövrdə körpənin hər kiloqram çəkisinə görə gündə təxminən 1 qram zülal alması kifayətdir. Bu da orta hesabla gündəlik 13-16 qram zülal deməkdir. Məsələn, 2 kasa qatıq və ya bir boşqab pendirli makaron körpənin gündəlik zülal ehtiyacını tam ödəyə bilər. Süd, yumurta, ət, toyuq və balıq kimi qidalar tam zülal mənbəyi olub, bədən üçün lazımlı bütün amin turşularını ehtiva edir. Bununla yanaşı, zülal ehtiyacını tam qarşılamaq üçün taxılları, paxlalıları və tərəvəzləri birlikdə verməyin faydalıdır.$q$),
(64, 'baby_daily_info', 'a10c3d04-e569-47ea-bad2-70a751db07a2', 'info', 'text', $q$Arıların bala arıları bəsləmək üçün öz bədənlərindən ifraz etdikləri dəyərli bir məhsul olan arı südü, körpənizin sağlamlığı və qidalanmasında mühüm yer tutur. Qidalandırıcı xüsusiyyəti çox yüksək olan arı südü, 1 həftəlik arıların ifraz etdiyi gelvari maddədən ibarətdir. İmmunitet sistemini gücləndirdiyi bilinən arı südünün hər səhər 1 çay qaşığı bal ilə birlikdə qəbul edilməsi təsirini daha da artırır. 100 qramında təxminən 15 qram zülal olan arı südü, həmçinin B qrupu vitaminləri, fol turşusu, maqnezium, sink və dəmir mineralları ilə zəngindir. Arı südünün tərkibində başqa heç bir qidada tapılmayan royalaktin adlı xüsusi bir zülal və 10-HDA adlı dəyərli bir yağ turşusu var. Bütün bu xüsusiyyətləri ilə arı südü körpənizin böyümə və inkişafına dəstək məqsədilə istifadə edilə biləcək təbii məhsuldur. Müntəzəm istifadə etdikdə körpənizdə immuniteti artıran, fiziki və zehni inkişafı dəstəkləyən, iştahı tənzimləyən təsirlərini görəcəksiniz.$q$, $q$Arıların bala arıları bəsləmək üçün öz bədənlərindən ifraz etdikləri dəyərli bir məhsul olan arı südü, bir çox ailənin maraq göstərdiyi təbii məhsuldur. Qidalandırıcı xüsusiyyəti çox yüksək olan arı südü, 1 həftəlik arıların ifraz etdiyi gelvari maddədən ibarətdir. Lakin arı südü astma tutması və anafilaksiya kimi ağır allergik reaksiyalara səbəb ola bilər. 100 qramında təxminən 15 qram zülal olan arı südü, həmçinin B qrupu vitaminləri, fol turşusu, maqnezium, sink və dəmir mineralları ilə zəngindir. Arı südünün tərkibində başqa heç bir qidada tapılmayan royalaktin adlı xüsusi bir zülal və 10-HDA adlı dəyərli bir yağ turşusu var. Bununla belə, arı südünün uşaqların böyümə və inkişafına faydası sübut olunmayıb və kiçik uşaqlar üçün tövsiyə edilmir. Buna görə də arı südünü körpənizə yalnız həkim məsləhəti ilə verə bilərsiniz.$q$),
(65, 'baby_daily_info', '8d79c984-59c4-461b-b19e-f63da9c3b917', 'info', 'text', $q$Övladınız tualet təlimini tamamlasa da, gecələr hələ də altını islada bilər. Tibdə buna "enurez" deyilir. Normalda uşaqların çoxu həm tualet təlimi, həm də sidik kisəsinin inkişafı sayəsində 2 yaş civarında sidiyini həm gecə, həm də gündüz saxlamağı öyrənir. Gecə alt islatma problemi çox vaxt sidik kisəsinin inkişafındakı ləngimədən qaynaqlanır və yaş artdıqca keçib gedir. Belə bir hal müşahidə edirsinizsə, ilk növbədə sidik yolu infeksiyası kimi bir problemin olub-olmadığını dəqiqləşdirmək üçün həkimlə məsləhətləşin. Əgər səbəb xəstəlik deyilsə, bəzi nüanslara diqqət edə bilərsiniz: yatmazdan 2 saat əvvəl maye qəbulunu azaldın və tərkibində kofein olan içkilərdən uzaq durun. Ən əsası, təmizlik xatirinə uşağa gecə bezi bağlamayın; bu, onun gecə oyanma motivasiyasını zəiflədir.$q$, $q$Övladınız tualet təlimini tamamlasa da, gecələr hələ də altını islada bilər. Bu yaşda bu tamamilə normaldır; tibdə "enurez" anlayışı 5 yaşdan sonra davam edən hallara aid edilir. Normalda uşaqların çoxu həm tualet təlimi, həm də sidik kisəsinin inkişafı sayəsində əvvəlcə gündüz, daha sonra, adətən 3-5 yaş arasında gecə də sidiyini saxlamağı öyrənir. Gecə alt islatma problemi çox vaxt sidik kisəsinin inkişafındakı ləngimədən qaynaqlanır və yaş artdıqca keçib gedir. Gecə islatma 5 yaşdan sonra da davam edərsə və ya sidik zamanı ağrı, hərarət kimi əlamətlər varsa, sidik yolu infeksiyası kimi bir problemin olub-olmadığını dəqiqləşdirmək üçün həkimlə məsləhətləşin. Əgər səbəb xəstəlik deyilsə, bəzi nüanslara diqqət edə bilərsiniz: yatmazdan 2 saat əvvəl maye qəbulunu azaldın və tərkibində kofein olan içkilərdən uzaq durun. Bu yaşda gecələr bezdən istifadə etmək tamamilə normaldır.$q$),
(66, 'baby_daily_info', 'df299f90-e498-4bad-8aac-c9ce133896e2', 'info', 'text', $q$Körpənizin bu ay ərzində Hepatit A peyvəndinin təkrar dozasını qəbul etməsi lazım gələ bilər. Hepatit A xəstəliyi eyni adlı virusun yoluxması nəticəsində yaranan qaraciyər infeksiyasıdır. Bu xəstəlik sosial-iqtisadi vəziyyətdən və yaşayış bölgəsindən asılı olaraq fərqlənsə də, bütün dünyada geniş yayılmışdır. Xəstəliyə payız və qışın ilk aylarında daha tez-tez rast gəlinir. Hepatit A peyvəndi bu xəstəliyin qarşısını almaqda ən effektiv yoldur. Tibbi tədqiqatlar göstərir ki, kütləvi peyvəndlənmə sayəsində illik yoluxma halları kəskin şəkildə azalmışdır. Bu baxımdan, peyvənd övladınızın Hepatit A xəstəliyinə tutulmaması üçün olduqca mühüm bir qoruyucu funksiya daşıyır.$q$, $q$Körpəniz Hepatit A peyvəndinin hər iki dozasını 18 və 24-cü aylarda almış olmalıdır; hər hansı doza buraxılıbsa, həkiminizlə məsləhətləşərək tamamlaya bilərsiniz. Hepatit A xəstəliyi eyni adlı virusun yoluxması nəticəsində yaranan qaraciyər infeksiyasıdır. Bu xəstəlik sosial-iqtisadi vəziyyətdən və yaşayış bölgəsindən asılı olaraq fərqlənsə də, bütün dünyada geniş yayılmışdır. Xəstəliyə payız və qışın ilk aylarında daha tez-tez rast gəlinir. Hepatit A peyvəndi bu xəstəliyin qarşısını almaqda ən effektiv yoldur. Tibbi tədqiqatlar göstərir ki, kütləvi peyvəndlənmə sayəsində illik yoluxma halları kəskin şəkildə azalmışdır. Bu baxımdan, peyvənd övladınızın Hepatit A xəstəliyinə tutulmaması üçün olduqca mühüm bir qoruyucu funksiya daşıyır.$q$),
(67, 'baby_daily_info', '158b48bc-de87-4a18-8590-049c1345f651', 'info', 'text', $q$24 aydan etibarən uşaqlar getdikcə müstəqillik qazanmağa başlayırlar. 2,5 yaş dövründə körpəniz ailə daxilində özünü daha çox müstəqil bir fərd kimi göstərmək istəyir. Bu müstəqillik hissi onun qidalanma vərdişlərinə də təsir edir. Bu dövrdə övladınız dadını sevmədiyi yeməkləri yeməməkdə inad edə bilər və ya müəyyən bir qidaya qarşı aludəçilik göstərə bilər. Əgər övladınızın inad etdiyi qida zərərlidirsə, ona seçim imkanı təqdim edin. Məsələn: Tərəvəz yeməyini bitirdikdən sonra kartof qızartmasını yeyə bilərsən kimi cümlələrlə həm onun istəyini nəzərə ala, həm də faydalı qidalanmasını təmin edə bilərsiniz.$q$, $q$24 aydan etibarən uşaqlar getdikcə müstəqillik qazanmağa başlayırlar. 2,5 yaş dövründə körpəniz ailə daxilində özünü daha çox müstəqil bir fərd kimi göstərmək istəyir. Bu müstəqillik hissi onun qidalanma vərdişlərinə də təsir edir. Bu dövrdə övladınız dadını sevmədiyi yeməkləri yeməməkdə inad edə bilər və ya müəyyən bir qidaya qarşı aludəçilik göstərə bilər. Əgər övladınızın inad etdiyi qida zərərlidirsə, ona seçim imkanı təqdim edin. Məsələn: Şam yeməyində brokoli, yoxsa yerkökü yemək istəyirsən? kimi cümlələrlə həm onun istəyini nəzərə ala, həm də faydalı qidalanmasını təmin edə bilərsiniz.$q$),
(68, 'baby_daily_info', '4caba1ee-fe4e-4f39-9676-eeb0deb3ad9f', 'info', 'text', $q$Körpənizin indiyə qədər cəmi 20 ədəd olan süd dişləri tamamlanmış ola bilər. Əgər hələ tamamlanmayıbsa, yaxın 1-2 ay ərzində ikinci azı dişləri də çıxacaqdır. Bundan sonrakı müddətdə ilk qalıcı dişlər 6 yaşından etibarən çıxan 1-ci böyük azı dişləri olacaq. Diş çıxarma prosesində körpənizdə hərarət, ürəkbulanma və ishal kimi əlamətlər müşahidə edə bilərsiniz. Həmçinin bu dövrdə uşağın daha narahat olması və iştahının azalması normaldır. İkinci azı dişi çıxarkən damaqlarda qızartı və tüpürcək axıntısının artması da gözləniləndir. Bu səbəbdən övladınızın yemək yemək istəməməsini və iştahsızlığını bir müddət anlayışla qarşılamalısınız.$q$, $q$Körpənizin indiyə qədər cəmi 20 ədəd olan süd dişləri tamamlanmış ola bilər. Əgər hələ tamamlanmayıbsa, yaxın 1-2 ay ərzində ikinci azı dişləri də çıxacaqdır. Bundan sonrakı müddətdə ilk qalıcı dişlər 6 yaşından etibarən çıxan 1-ci böyük azı dişləri olacaq. Diş çıxarma yüksək hərarət, qusma və ya ishala səbəb olmur; belə əlamətlər varsa, bunu dişə bağlamayın, həkimə müraciət edin. Həmçinin bu dövrdə uşağın daha narahat olması və iştahının azalması normaldır. İkinci azı dişi çıxarkən damaqlarda qızartı və tüpürcək axıntısının artması da gözləniləndir. Bu səbəbdən övladınızın yemək yemək istəməməsini və iştahsızlığını bir müddət anlayışla qarşılamalısınız.$q$),
(69, 'baby_daily_info', '8d37727a-164c-4cf0-b23a-460dee8cf99d', 'info', 'text', $q$Övladınızın diş qulluğu olduqca vacib və diqqət tələb edən bir mövzudur. “Onsuz da süd dişləridir, töküləcək!” deyib diş baxımına etinasız yanaşmaq diş əti iltihabı və diş çürüməsi kimi fəsadlara yol aça bilər. Bunun qarşısını almaq üçün körpənizə müntəzəm diş təmizliyi vərdişini aşılamaq ona qazandıra biləcəyiniz ən yaxşı xüsusiyyətlərdən biridir. Diş təmizliyi dedikdə ağıla gələn ilk vasitə olan diş pastası uşaqlar üçün ilkin mərhələdə tövsiyə edilmir. Bu dövrdə övladınız dişlərini pastasız fırçalaya bilər. Bəzi mütəxəssislər diş pastası istifadəsini orta hesabla 3 yaşınadək məsləhət görmürlər. Bu yaşdan sonra isə noxud boyda diş pastasından istifadə etmək olar. Sizin üzərinizə düşən isə yeməklərdən sonra və gecə yatmazdan əvvəl ona nümunə olaraq dişlərinizi fırçalamağınızdır. Unutmayın ki, körpəniz bu vərdişi sizi təqlid edərək mənimsəyəcək.$q$, $q$Övladınızın diş qulluğu olduqca vacib və diqqət tələb edən bir mövzudur. “Onsuz da süd dişləridir, töküləcək!” deyib diş baxımına etinasız yanaşmaq diş əti iltihabı və diş çürüməsi kimi fəsadlara yol aça bilər. Bunun qarşısını almaq üçün körpənizə müntəzəm diş təmizliyi vərdişini aşılamaq ona qazandıra biləcəyiniz ən yaxşı xüsusiyyətlərdən biridir. Diş təmizliyi dedikdə ağıla gələn ilk vasitə olan flüorlu diş pastası uşaqlar üçün ilk dişdən etibarən tövsiyə edilir. İlk dişdən 3 yaşadək düyü dənəsi boyda, 3 yaşdan sonra isə noxud boyda flüorlu uşaq diş pastası ilə dişləri gündə 2 dəfə fırçalayın. Sizin üzərinizə düşən isə yeməklərdən sonra və gecə yatmazdan əvvəl ona nümunə olaraq dişlərinizi fırçalamağınızdır. Unutmayın ki, körpəniz bu vərdişi sizi təqlid edərək mənimsəyəcək.$q$),
(70, 'baby_daily_info', '6a9442ee-d5d9-453f-a3b4-67e47e360e31', 'info', 'text', $q$Övladınızın hazırkı oyun dövründə qidalanması artıq böyüklərinkinə yaxın bir səviyyəyə çatıb. Bu mərhələdə, böyüklərin rasionunda olduğu kimi yağlardan çox qorxmağınıza ehtiyac yoxdur. Çünki mədə həcmi kiçik olan uşağınızın daha az miqdarda daha yüksək enerji verən yağlara ehtiyacı var. Yağın 1 qramı 9 kalori daşıyır ki, bu da uşağın gün ərzində ehtiyac duyduğu enerjini böyük ölçüdə qarşılayır. Lakin miqdarı həddindən artıq artırmaq olmaz; çox yağ istehlakı gələcəkdə ürək-damar sağlamlığı üçün risk yarada bilər. Odur ki, həm sizin, həm də övladınızın sağlam qidalanma vərdişi qazanması üçün faydalı yağlara üstünlük verin. Məsələn, yeməklərdə zeytun yağı istifadə etmək, avokado, badam, fındıq və qoz kimi yağlı toxumlar vermək ən yaxşı seçimdir.$q$, $q$Övladınızın hazırkı oyun dövründə qidalanması artıq böyüklərinkinə yaxın bir səviyyəyə çatıb. Bu mərhələdə, böyüklərin rasionunda olduğu kimi yağlardan çox qorxmağınıza ehtiyac yoxdur. Çünki mədə həcmi kiçik olan uşağınızın daha az miqdarda daha yüksək enerji verən yağlara ehtiyacı var. Yağın 1 qramı 9 kalori daşıyır ki, bu da uşağın gün ərzində ehtiyac duyduğu enerjini böyük ölçüdə qarşılayır. Lakin miqdarı həddindən artıq artırmaq olmaz; çox yağ istehlakı gələcəkdə ürək-damar sağlamlığı üçün risk yarada bilər. Odur ki, həm sizin, həm də övladınızın sağlam qidalanma vərdişi qazanması üçün faydalı yağlara üstünlük verin. Məsələn, yeməklərdə zeytun yağı istifadə etmək, avokado vermək, badam, fındıq və qozu isə üyüdülmüş və ya əzilmiş halda vermək ən yaxşı seçimdir (bütöv qoz-fındıq boğulma riski yaradır).$q$),
(71, 'baby_daily_info', '35e3ed0f-aad4-4c45-9de0-b5a3eebc1289', 'info', 'text', $q$Övladına qarşı, xüsusilə başqalarının yanında “utancaq”, “dəcəl” və ya “huysuz” kimi ifadələr işlətməməyə diqqət etməlisən. Körpən sənin onu eşitmədiyini və ya önəm vermədiyini düşünsən belə, bu sözləri deyərkən bədən dilindən hər şeyi anlayır. Onun şəxsiyyətinə qarşı bu cür yanaşma mənlik inkişafına mənfi təsir göstərəcək. Əgər belə xarakterik xüsusiyyətləri olan bir övladın varsa, onun ehtiyaclarını nəzərə alaraq hərəkət etməlisən. Məsələn, utancaq bir uşağı 10 uşağın arasına qoyub ondan liderlik gözləmək doğru olmazdı. Onu sosial həyata tədricən, kiçik addımlarla hazırlaya bilərsən. Unutma ki, biz müəyyən xarakterlə doğuluruq, lakin ətraf mühitin təsiri bu xarakteri formalaşdıra və dəyişdirə bilər.$q$, $q$Övladına qarşı, xüsusilə başqalarının yanında “utancaq”, “dəcəl” və ya “huysuz” kimi ifadələr işlətməməyə diqqət etməlisən. Sən körpənin bunu eşitmədiyini və ya önəm vermədiyini düşünsən belə, bu sözləri deyərkən bədən dilindən hər şeyi anlayır. Onun şəxsiyyətinə qarşı bu cür yanaşma mənlik inkişafına mənfi təsir göstərəcək. Əgər belə xarakterik xüsusiyyətləri olan bir övladın varsa, onun ehtiyaclarını nəzərə alaraq hərəkət etməlisən. Məsələn, utancaq bir uşağı 10 uşağın arasına qoyub ondan liderlik gözləmək doğru olmazdı. Onu sosial həyata tədricən, kiçik addımlarla hazırlaya bilərsən. Unutma ki, biz müəyyən xarakterlə doğuluruq, lakin ətraf mühitin təsiri bu xarakteri formalaşdıra və dəyişdirə bilər.$q$),
(72, 'baby_daily_info', 'e2dc9a31-e473-4137-a35c-bba202f969bf', 'info', 'text', $q$Artıq 3 yaşına yaxınlaşan körpən üçün çiçək tozu (polen) kimi arı məhsullarından rahatlıqla istifadə edə bilərsən. Çiçək tozu 22 növ aminturşu, karbohidrat, kalsium, sink və bir çox vitaminləri özündə birləşdirən təbii qidadır. Həmçinin tərkibindəki flavonoidlər güclü antioksidant xüsusiyyətə malikdir. Antioksidant təsiri ilə immuniteti gücləndirir, xəstəliklərə qarşı qoruyur və bədəni yeniləyir. Tərkibindəki aminturşular, karbohidratlar və vitaminlər sayəsində körpənin fiziki və beyin inkişafını dəstəkləyir. Bu dövrdə körpənin gündə təxminən 10-15 qram çiçək tozu qəbul etməsi kifayətdir. Lakin övladının bal və ya arı məhsullarına allergiyası varsa, bu cür məhsullardan uzaq durmalısan. Sonda isə çiçək tozunu etibarlı, təbii və orqanik mənbələrdən əldə etməyin olduqca vacibdir.$q$, $q$Çiçək tozu (polen) kimi arı məhsulları ciddi allergiya riski daşıdığı üçün 3 yaşına yaxınlaşan körpənə yalnız həkim məsləhəti ilə verilə bilər. Çiçək tozu 22 növ aminturşu, karbohidrat, kalsium, sink və bir çox vitaminləri özündə birləşdirən təbii qidadır. Həmçinin tərkibindəki flavonoidlər güclü antioksidant xüsusiyyətə malikdir. Antioksidant təsiri ilə immuniteti gücləndirir, xəstəliklərə qarşı qoruyur və bədəni yeniləyir. Tərkibindəki aminturşular, karbohidratlar və vitaminlər sayəsində körpənin fiziki və beyin inkişafını dəstəkləyir. Lakin övladının bal və ya arı məhsullarına allergiyası varsa, bu cür məhsullardan uzaq durmalısan. Sonda isə çiçək tozunu etibarlı, təbii və orqanik mənbələrdən əldə etməyin olduqca vacibdir.$q$),
(73, 'baby_daily_info', 'a8ffabb9-3040-4b25-bec5-5f9659629255', 'info', 'text', $q$Körpənizlə birlikdə daha bir ayı geridə qoydunuz. 34-cü aya xoş gəldiniz! 😊 34 aylıq uşağınızın bu dövrdəki inkişafı əvvəlki ayla demək olar ki, eynidir. Bu ayın ən vacib yeniliyi odur ki, övladınız artıq məktəbəqədər təhsilə tam hazırdır. Həmçinin qeyd etməliyik ki, 3 yaş sindromuna qədəm qoyan körpənizlə bir qədər çətin, lakin maraqlı bir proses sizi gözləyir. 3 yaş böhranı kimi də adlandırılan bu mərhələdə uşağınız öz eqosunu kəşf edəcək. Eqo şəxsiyyət strukturunun ən vacib hissələrindən biridir. Şəxsiyyət dediyimiz quruluş bir-biri ilə əlaqəli üç təməl hissədən — impulslar, istəklər, ehtiyaclar, eqo, dəyərlər, inanclar və vicdandan ibarətdir. Eqo bu strukturun tarazlaşdırıcısı rolunu oynayır. Bu baxımdan yanaşdıqda, eqonun ruh sağlamlığımızda çox mühüm yer tutduğu aydındır. Anacan ailəsi olaraq hər zaman yanınızdayıq!$q$, $q$Körpənizlə birlikdə daha bir ayı geridə qoydunuz. 34-cü aya xoş gəldiniz! 😊 34 aylıq uşağınızın bu dövrdəki inkişafı əvvəlki ayla demək olar ki, eynidir. Bu ayın ən vacib yeniliyi odur ki, övladınız artıq məktəbəqədər təhsilə tam hazırdır. Həmçinin qeyd etməliyik ki, 3 yaş sindromuna qədəm qoyan körpənizlə bir qədər çətin, lakin maraqlı bir proses sizi gözləyir. 3 yaş böhranı kimi də adlandırılan bu mərhələdə uşağınız öz eqosunu kəşf edəcək. Eqo şəxsiyyət strukturunun ən vacib hissələrindən biridir. Şəxsiyyət dediyimiz quruluş bir-biri ilə əlaqəli üç təməl hissədən ibarətdir: impulslar və ehtiyaclar (id), eqo, dəyərlər və vicdan (superego). Eqo bu strukturun tarazlaşdırıcısı rolunu oynayır. Bu baxımdan yanaşdıqda, eqonun ruh sağlamlığımızda çox mühüm yer tutduğu aydındır. Anacan ailəsi olaraq hər zaman yanınızdayıq!$q$),
(74, 'baby_daily_info', '443f9eda-baee-4eb9-a55b-b12c4d58ecb1', 'info', 'text', $q$Körpənizin bu dövrdə qidalanma rejimi və porsiya miqdarı ilə bağlı ağlında suallar ola bilər. Sənin üçün nümunəvi bir günlük qidalanma menyusu hazırladıq! 😊 Səhər yeməyinə 1 dilim tam buğda çörəyindən tost, 1 çay qaşığı fıstıq əzməsi və yarım stəkan süd ilə başlamaq əla olar. Ara pay olaraq yarım stəkan çiyələk, yarım stəkan qatıq və ya sağlam qarğıdalı lopalarından (müsli) birini seçə bilərsən. Günorta yeməyində 1 dilim kəpəkli çörək, bir az balıq, kiçik qaynadılmış kartof və 1 kiçik portağal ilə zəngin bir menyu yarada bilərsən. Növbəti ara pay üçün evdə hazırladığın 5 ədəd taxıllı kraker, 5 ədəd çiy badam və ya üzərinə bəhməz/bal çəkilmiş 1 dilim tam buğda çörəyi verə bilərsən. Axşam yeməyində isə yarım yerkökü, 30 qram tərəvəzə əlavə olaraq 30 qram dana və ya toyuq əti, həmçinin yarım kasa bulqur plovu həm doyumlu, həm də faydalı olacaqdır.$q$, $q$Körpənin bu dövrdə qidalanma rejimi və porsiya miqdarı ilə bağlı ağlında suallar ola bilər. Sənin üçün nümunəvi bir günlük qidalanma menyusu hazırladıq! 😊 Səhər yeməyinə 1 dilim tam buğda çörəyindən tost, 1 çay qaşığı fıstıq əzməsi və yarım stəkan süd ilə başlamaq əla olar. Ara pay olaraq yarım stəkan çiyələk, yarım stəkan qatıq və ya sağlam qarğıdalı lopalarından (müsli) birini seçə bilərsən. Günorta yeməyində 1 dilim kəpəkli çörək, bir az balıq, kiçik qaynadılmış kartof və 1 kiçik portağal ilə zəngin bir menyu yarada bilərsən. Növbəti ara pay üçün evdə hazırladığın 5 ədəd taxıllı kraker, bir az üyüdülmüş badam və ya üzərinə bəhməz/bal çəkilmiş 1 dilim tam buğda çörəyi verə bilərsən. Axşam yeməyində isə yarım yerkökü, 30 qram tərəvəzə əlavə olaraq 30 qram dana və ya toyuq əti, həmçinin yarım kasa bulqur plovu həm doyumlu, həm də faydalı olacaqdır.$q$),
(75, 'baby_daily_info', 'a7f6f0c5-f1b1-4f0e-b9c2-28b4975c766e', 'info', 'text', $q$Övladınızın dil inkişafında son dövrlərdə yeni sıçrayışlar yaşanır. Artıq danışıq zamanı qurduğu cümlələrin qrammatik cəhətdən formalaşdığını müşahidə edə bilərsiniz. Həmçinin düşüncələri arasında səbəb-nəticə əlaqəsi qurmağa başlayıb. Orta hesabla 300 fərqli söz ehtiyatına malikdir. Öz-özünə, sizinlə, oyuncaqları və dostları ilə uzun-uzun danışa bilər. Yeni sözlərə marağı artıb. "Və" bağlayıcısını cümlələrdə istifadə məqsədini kəşf etməyə başlayıb. İndiki və gələcək zamanı, "mən", "sən" kimi əvəzlikləri dərk edir. Sadə qoşmaları və əvəzlikləri əvvəlkinə nisbətən daha düzgün istifadə edir. Rənglərin adlarını öyrənir, lakin hələ rənglə adını tam dəqiq uyğunlaşdıra bilməyə bilər. Məsələn, qırmızı və çəhrayı, yaxud sarı və narıncı kimi bir-birinə yaxın rəngləri qarışdıra bilər.$q$, $q$Övladınızın dil inkişafında son dövrlərdə yeni sıçrayışlar yaşanır. Artıq danışıq zamanı qurduğu cümlələrin qrammatik cəhətdən formalaşdığını müşahidə edə bilərsiniz. Həmçinin düşüncələri arasında səbəb-nəticə əlaqəsi qurmağa başlayıb. Söz ehtiyatı orta hesabla 900-1000 sözə çatır. Öz-özünə, sizinlə, oyuncaqları və dostları ilə uzun-uzun danışa bilər. Yeni sözlərə marağı artıb. "Və" bağlayıcısını cümlələrdə istifadə məqsədini kəşf etməyə başlayıb. İndiki və gələcək zamanı, "mən", "sən" kimi əvəzlikləri dərk edir. Sadə qoşmaları və əvəzlikləri əvvəlkinə nisbətən daha düzgün istifadə edir. Rənglərin adlarını öyrənir, lakin hələ rənglə adını tam dəqiq uyğunlaşdıra bilməyə bilər. Məsələn, qırmızı və çəhrayı, yaxud sarı və narıncı kimi bir-birinə yaxın rəngləri qarışdıra bilər.$q$),
(76, 'baby_daily_info', 'ef688bea-192e-4e4e-8e2b-89b299796329', 'info', 'text', $q$Paxlalılar lif tərkibi ən yüksək olan qida qrupudur. Beləliklə, mədənin boşalma sürətini və nazik bağırsaqlardan qlükoza sorulmasını ləngidərək qan şəkərini tarazlayır. Eyni zamanda qan xolesterolu və qan təzyiqini də arzu olunan səviyyədə saxlamağa kömək edir. Mədədə su ilə birlikdə şişərək toxluq hissi verir və övladının gün ərzində ehtiyac duyduğu enerjini təmin edir. Bunlarla yanaşı, noxud, quru lobya, brokoli, gül kələmi kimi bəzi tərəvəzlər və quru qidalar sağlam olduqları qədər qaz əmələgətirmə xüsusiyyətinə də malikdir. Övladının bu qidaları qəbul etməsi olduqca faydalıdır! Ancaq sən yenə də onun bunları ard-arda və çox miqdarda yemədiyindən əmin olmalısan. Hazırladığın yeməklər üçün paxlalıları islatdığın suyu mütləq atmalı və sonra yaxşıca yumalısan. Yeməklərə bir qaşıq razyana və ya muskat qozu əlavə etmən də qazın qarşısını almağa kömək edəcəkdir.$q$, $q$Paxlalılar lif tərkibi ən yüksək olan qida qrupudur. Beləliklə, mədənin boşalma sürətini və nazik bağırsaqlardan qlükoza sorulmasını ləngidərək qan şəkərini tarazlayır. Eyni zamanda qan xolesterolu və qan təzyiqini də arzu olunan səviyyədə saxlamağa kömək edir. Mədədə su ilə birlikdə şişərək toxluq hissi verir və övladının gün ərzində ehtiyac duyduğu enerjini təmin edir. Bunlarla yanaşı, noxud, quru lobya, brokoli, gül kələmi kimi bəzi tərəvəzlər və quru qidalar sağlam olduqları qədər qaz əmələgətirmə xüsusiyyətinə də malikdir. Övladının bu qidaları qəbul etməsi olduqca faydalıdır! Ancaq sən yenə də onun bunları ard-arda və çox miqdarda yemədiyindən əmin olmalısan. Hazırladığın yeməklər üçün paxlalıları islatdığın suyu mütləq atmalı və sonra yaxşıca yumalısan. Yeməklərə bir çimdik razyana və ya zirə əlavə etmən də qazın azalmasına kömək edə bilər.$q$),
(77, 'baby_daily_info', 'e2ff4d89-6e44-49f2-8f66-9efbff6dfaad', 'info', 'text', $q$Uşaqlarda qidalanma qaydalarının başında yemək saatlarını ötürməməyin gəldiyini unutma. Övladının xüsusilə günün ən vacib yeməyi olan səhər yeməyini mütləq yeməsini təmin etməlisən. Sağlam qəlyanaltı kimi quru meyvələr, xurma və çərəzlərə üstünlük verə bilərsən. Qoz, fındıq, badam kimi faydalı çərəzlərin və tam taxıllı məhsulların gündəlik rasionda olmasına diqqət yetir. Meyvə və tərəvəzləri təzə və mövsümünə uyğun seçməyə çalış. Kənd təsərrüfatı dərmanlarından qorunmaq üçün onları çox yaxşı yumaq lazımdır. Meyvəni sadəcə şirə kimi deyil, lifləri ilə birlikdə vermək daha faydalıdır. Araşdırmalar göstərir ki, balıq uşaqların immunitet sisteminə çox müsbət təsir edir və bədənin xəstəliklərə qarşı müqavimətini artırır. Bu səbəbdən həftədə bir dəfə balıq yeməyi vərdiş halına gətirməlisən.$q$, $q$Uşaqlarda qidalanma qaydalarının başında yemək saatlarını ötürməməyin gəldiyini unutma. Övladının xüsusilə günün ən vacib yeməyi olan səhər yeməyini mütləq yeməsini təmin etməlisən. Sağlam qəlyanaltı kimi quru meyvələr, xurma və çərəzlərə üstünlük verə bilərsən. Qoz, fındıq, badam kimi faydalı çərəzlərin (üyüdülmüş və ya əzmə halında, çünki bütöv qoz-fındıq 4-5 yaşadək boğulma riski yaradır) və tam taxıllı məhsulların gündəlik rasionda olmasına diqqət yetir. Meyvə və tərəvəzləri təzə və mövsümünə uyğun seçməyə çalış. Kənd təsərrüfatı dərmanlarından qorunmaq üçün onları çox yaxşı yumaq lazımdır. Meyvəni sadəcə şirə kimi deyil, lifləri ilə birlikdə vermək daha faydalıdır. Araşdırmalar göstərir ki, balıq uşaqların immunitet sisteminə çox müsbət təsir edir və bədənin xəstəliklərə qarşı müqavimətini artırır. Bu səbəbdən həftədə bir dəfə balıq yeməyi vərdiş halına gətirməlisən.$q$),
(78, 'baby_daily_info', '8821b078-f268-490e-aff6-43d6dec5162e', 'info', 'text', $q$Övladınızın kiçik bir yetkin kimi davranması sizi kifayət qədər çətinliyə sala bilər. Qarşılaşdığınız problemləri yeni qaydalar qoyaraq həll edə bilərsiniz. Əlbəttə, qayda qoymaq çətin işdir; həddindən artıq sərt olmaq çox mülayim olmaq qədər təhlükəlidir. Çocuğunuza uyğun olan davranış formasını seçin və bunu gündən-günə dəyişməyin, ardıcıl olun. Unutmayın ki, qayda qoymaq uşaq tərbiyəsinin bir hissəsidir, bu yolla siz onu həm qoruyur, həm də yetişdirirsiniz. Düzgün qoyulmuş qaydaların onun xeyrinə olduğunu övladınız zamanla anlayacaq və bunun sevginizin bir parçası olduğunu hiss edəcəkdir. Həmçinin, qayda qoymaq ona olan inamınızı hiss etdirmək üçün də effektiv bir yoldur.$q$, $q$Övladınızın kiçik bir yetkin kimi davranması sizi kifayət qədər çətinliyə sala bilər. Qarşılaşdığınız problemləri yeni qaydalar qoyaraq həll edə bilərsiniz. Əlbəttə, qayda qoymaq çətin işdir; həddindən artıq sərt olmaq çox mülayim olmaq qədər təhlükəlidir. Övladınıza uyğun olan davranış formasını seçin və bunu gündən-günə dəyişməyin, ardıcıl olun. Unutmayın ki, qayda qoymaq uşaq tərbiyəsinin bir hissəsidir, bu yolla siz onu həm qoruyur, həm də yetişdirirsiniz. Düzgün qoyulmuş qaydaların onun xeyrinə olduğunu övladınız zamanla anlayacaq və bunun sevginizin bir parçası olduğunu hiss edəcəkdir. Həmçinin, qayda qoymaq ona olan inamınızı hiss etdirmək üçün də effektiv bir yoldur.$q$),
(79, 'baby_daily_info', '214f43d5-3cc9-418c-b873-438c22b36c11', 'info', 'text', $q$Əgər uşağınızın danışığında kəkələmə müşahidə edirsinizsə, bu yaşlarda belə hal normal hesab oluna bilər. Kəkələmə hallarının 90%-i müvəqqəti olsa da, 10%-i qalıcı ola bilər. Kəkələmə zamanı uşağın danışığının axıcılığı pozulur, səslərin və hecaların uzadılması və ya təkrar edilməsi baş verir. Sözləri deyərkən duraksamalar ola bilər. Bəzən uşaq çətinlik çəkdiyi sözü deməmək üçün onu başqa kəlmə ilə əvəz etməyə çalışır. Əgər kəkələmə müəyyən müddət ərzində keçib getmirsə, vaxt itirmədən uşaq psixiatrına müraciət etməlisiniz. Müəyyən yaşdan sonra kəkələməni aradan qaldırmaq üçün xüsusi danışıq, nəfəs və ritm məşqləri verilir. Bu məşqlərlə yanaşı, uşağın həyəcanını azaltmaq məqsədilə həkim tərəfindən dərman müalicəsi də tətbiq oluna bilər.$q$, $q$Əgər uşağınızın danışığında kəkələmə müşahidə edirsinizsə, bu yaşlarda belə hal normal hesab oluna bilər. Kəkələmə hallarının 90%-i müvəqqəti olsa da, 10%-i qalıcı ola bilər. Kəkələmə zamanı uşağın danışığının axıcılığı pozulur, səslərin və hecaların uzadılması və ya təkrar edilməsi baş verir. Sözləri deyərkən duraksamalar ola bilər. Bəzən uşaq çətinlik çəkdiyi sözü deməmək üçün onu başqa kəlmə ilə əvəz etməyə çalışır. Əgər kəkələmə müəyyən müddət ərzində keçib getmirsə, vaxt itirmədən loqopedə (nitq terapevtinə) müraciət etməlisiniz. Müəyyən yaşdan sonra kəkələməni aradan qaldırmaq üçün xüsusi danışıq, nəfəs və ritm məşqləri verilir.$q$),
(80, 'baby_daily_info', '7f8e3411-817d-4aa5-8fbc-2434b38bd6c6', 'info', 'text', $q$Havaların soyuması, bədənin enerji itirib yorulması, qapalı və izdihamlı məkanlar, bağça mühiti kimi amillər uşaqların daha tez-tez xəstələnməsinə səbəb olur. Bu dövrdə körpənizi qorumaq üçün bəzi tədbirlər görə bilərsiniz. İlk növbədə onun balanslı bəslənməsini və lazımi vitaminləri almasını təmin edin. Dəmir və D vitamini çatışmazlığı olan uşaqlar xəstəliklərə daha meyilli olurlar. Yoluxucu xəstəliklərdən qorunmağın ən effektiv yolu isə peyvənddir; 3 yaşlı uşağınıza qrip peyvəndi vurdura bilərsiniz (xüsusilə allergik və ya astması olan uşaqlara tövsiyə edilir). Ticarət mərkəzləri kimi qapalı yerlər əvəzinə açıq havada vaxt keçirməyə üstünlük verin. Evinizi və uşağın otağını mütəmadi olaraq havalandırın. Unutmayın ki, yuxusuzluq immuniteti zəiflədir, ona görə də uşağınızın gündə 8-10 saat yatmasına diqqət edin. Həmçinin ona asqırarkən və ya öskürərkən ağzını salfetlə tutmağı və sonra həmin salfeti atmağı öyrətməlisiniz.$q$, $q$Havaların soyuması, bədənin enerji itirib yorulması, qapalı və izdihamlı məkanlar, bağça mühiti kimi amillər uşaqların daha tez-tez xəstələnməsinə səbəb olur. Bu dövrdə körpənizi qorumaq üçün bəzi tədbirlər görə bilərsiniz. İlk növbədə onun balanslı bəslənməsini və lazımi vitaminləri almasını təmin edin. Dəmir və D vitamini çatışmazlığı olan uşaqlar xəstəliklərə daha meyilli olurlar. Yoluxucu xəstəliklərdən qorunmağın ən effektiv yolu isə peyvənddir; 3 yaşlı uşağınıza qrip peyvəndi vurdura bilərsiniz (xüsusilə allergik və ya astması olan uşaqlara tövsiyə edilir). Ticarət mərkəzləri kimi qapalı yerlər əvəzinə açıq havada vaxt keçirməyə üstünlük verin. Evinizi və uşağın otağını mütəmadi olaraq havalandırın. Unutmayın ki, yuxusuzluq immuniteti zəiflədir, ona görə də uşağınızın gündə 10-13 saat (günorta yuxusu daxil) yatmasına diqqət edin. Həmçinin ona asqırarkən və ya öskürərkən ağzını salfetlə tutmağı və sonra həmin salfeti atmağı öyrətməlisiniz.$q$),
(81, 'baby_daily_info', '9e8a4ff2-cd35-4ca1-9f39-9f919100e6ad', 'info', 'text', $q$Körpəniz müsbət davranışları öyrəndiyi kimi, bəzən sizin yönləndirmənizlə mənfi davranışları da mənimsəyə bilər. Əgər övladınızla problem yaşayırsınızsa, bu problemin bir parçası da sizsiniz deməkdir. Əgər problemin hissəsisinizsə, deməli həllin də bir hissəsi olmalısınız. Həll üçün öz davranışlarınızı da dəyişməli olduğunuzu unutmayın. Əgər uşağınızın bütün məsuliyyətlərini öz üzərinizə götürürsünüzsə, onun ağlamaq növbələri qarşısında təslim olub özünüzü günahkar hiss edirsinizsə, deməli uşağınız sizi idarə edir. Bu vəziyyətdə problem yalnız uşağa boyun əyməklə həll olunur ki, bu da yanlışdır. Siz onun davranışlarını deyil, o sizinkiləri yönləndirmiş olur. Buna görə də səhv yanaşmalardan əl çəkməli və valideyn nüfuzunu bərpa etməlisiniz. Unutmayın ki, uşaq bir maye kimidir; daxil olduğu qabın formasını alır. Siz Anacan ailəsi olaraq ona necə tərbiyə versəniz, o da elə formalaşacaqdır.$q$, $q$Körpəniz müsbət davranışları öyrəndiyi kimi, bəzən sizin yönləndirmənizlə mənfi davranışları da mənimsəyə bilər. Əgər övladınızla problem yaşayırsınızsa, bu problemin bir parçası da sizsiniz deməkdir. Əgər problemin hissəsisinizsə, deməli həllin də bir hissəsi olmalısınız. Həll üçün öz davranışlarınızı da dəyişməli olduğunuzu unutmayın. Əgər uşağınızın bütün məsuliyyətlərini öz üzərinizə götürürsünüzsə, onun ağlamaq növbələri qarşısında təslim olub özünüzü günahkar hiss edirsinizsə, deməli uşağınız sizi idarə edir. Bu vəziyyətdə problem yalnız uşağa boyun əyməklə həll olunur ki, bu da yanlışdır. Siz onun davranışlarını deyil, o sizinkiləri yönləndirmiş olur. Buna görə də səhv yanaşmalardan əl çəkməli və valideyn nüfuzunu bərpa etməlisiniz. Unutmayın ki, uşaq bir maye kimidir; daxil olduğu qabın formasını alır. Siz ona necə tərbiyə versəniz, o da elə formalaşacaqdır.$q$),
(82, 'baby_daily_info', 'fabedbe0-aa31-4f39-8c1a-cb32f87df3dd', 'info', 'text', $q$Ayrılıq qorxusu, düşünülənin əksinə, yalnız işləyən anaların uşaqlarında rast gəlinmir. Doğru dildə izah edildikdə, uşaqlar analarının işə getməli olduğunu və axşam geri dönəcəyini anlayıb qəbul edirlər. Hər bir uşaq anasından ayrılanda müəyyən dərəcədə narahatlıq və onun geri dönüb-dönməyəcəyi barədə narahatlıq keçirir. Anaya həddindən artıq bağlı olan uşaqlarda isə bu narahatlıq daha kəskin olur. Belə uşaqlar bağçaya getməkdə və uyğunlaşmaqda da çətinlik çəkirlər. Unutmayın ki, bağça sadəcə uşağa baxılan və ya oyun oynanan bir yer deyil; bura uşağın sosiallaşdığı, qaydalara tabe olmağı, həmyaşıdları ilə ünsiyyət qurmağı və paylaşmağı öyrəndiyi mühümdür. Xüsusilə anadan asılılığı yüksək olan uşaqlar üçün bağçaya getmək bu bağlılığın azalmasına və uşağın müstəqilləşməsinə kömək edir.$q$, $q$Ayrılıq qorxusu, düşünülənin əksinə, yalnız işləyən anaların uşaqlarında rast gəlinmir. Doğru dildə izah edildikdə, uşaqlar analarının işə getməli olduğunu və axşam geri dönəcəyini anlayıb qəbul edirlər. Hər bir uşaq anasından ayrılanda müəyyən dərəcədə narahatlıq və onun geri dönüb-dönməyəcəyi barədə narahatlıq keçirir. Anaya həddindən artıq bağlı olan uşaqlarda isə bu narahatlıq daha kəskin olur. Belə uşaqlar bağçaya getməkdə və uyğunlaşmaqda da çətinlik çəkirlər. Unutmayın ki, bağça sadəcə uşağa baxılan və ya oyun oynanan bir yer deyil; bura uşağın sosiallaşdığı, qaydalara tabe olmağı, həmyaşıdları ilə ünsiyyət qurmağı və paylaşmağı öyrəndiyi mühüm bir mühitdir. Xüsusilə anadan asılılığı yüksək olan uşaqlar üçün bağçaya getmək bu bağlılığın azalmasına və uşağın müstəqilləşməsinə kömək edir.$q$),
(83, 'baby_daily_info', 'c4f2aeb3-8fc8-4e06-8bd0-e81a062fc9f1', 'info', 'text', $q$3,5 yaşındakı övladınız artıq suallara danışaraq və ya mimikalarla cavab verməlidir. Ən azı 2 sözdən ibarət olan 1-2 cümləni mübtəda-xəbər ardıcıllığı ilə düzgün qura bilməlidir. Ardıcıl verilən tapşırıqları yerinə yetirməyi bacarmalıdır. Orta hesabla 200-ə yaxın söz bazasına malik olmalıdır. Suallara cavab verərkən eyni sözləri təkrar etmədən cavab verməsi gözlənilir. Ailə xaricindəki insanlar da onun danışığını başa düşməlidir. O, asanlıqla danışıb dərdini izah edə bilər, evdə və ya bağçada etdiklərini fərqli mühitlərdə paylaşa bilər. 3-4, hətta 5 sözlük cümlələr qura bilər və istədiyi əşyaların adlarını söyləyərək onları tələb edər.$q$, $q$3,5 yaşındakı övladınız artıq suallara danışaraq və ya mimikalarla cavab verməlidir. Ən azı 2 sözdən ibarət olan 1-2 cümləni mübtəda-xəbər ardıcıllığı ilə düzgün qura bilməlidir. Ardıcıl verilən tapşırıqları yerinə yetirməyi bacarmalıdır. Orta hesabla 1000-1500 söz ehtiyatına malik olur. Suallara cavab verərkən eyni sözləri təkrar etmədən cavab verməsi gözlənilir. Ailə xaricindəki insanlar da onun danışığını başa düşməlidir. O, asanlıqla danışıb dərdini izah edə bilər, evdə və ya bağçada etdiklərini fərqli mühitlərdə paylaşa bilər. 3-4, hətta 5 sözlük cümlələr qura bilər və istədiyi əşyaların adlarını söyləyərək onları tələb edər.$q$),
(84, 'baby_daily_info', 'c4b115b3-ef2f-472a-953f-e45e211c4cd3', 'info', 'text', $q$Övladınızın 3,5 yaşı olmasına baxmayaraq, hələ də körpə kimi danışdığını müşahidə edə bilərsiniz. Bu hal yaşıdları tərəfindən mənfi qarşılanmasına, sosial həyatda çətinlik çəkməsinə və özünəinamının zədələnməsinə səbəb ola bilər. Belə vəziyyətdə valideynlərin doğru yanaşması ilə daha sürətli irəliləyiş əldə etmək mümkündür. İlk növbədə, uşaqla eyni tərzdə, körpə dilində danışaraq onun yanlış tələffüzlərini möhkəmləndirməməlisiniz. Digər tərəfdən, danışıq tərzi ilə əsla lağ edilməməlidir. Düzgün deyə bilmədiyi sözləri tənqid edirmiş kimi düzəltməkdən qaçın. O, yanlış tələffüz etdikdən dərhal sonra həmin sözün doğrusunu təbii bir şəkildə sizdən eşitməlidir. Məsələn, uşaq Qapını badadım dedikdə, siz Afərin, balam qapını bağladı deyərək doğru nümunə göstərməlisiniz.$q$, $q$Övladınızın 3,5 yaşı olmasına baxmayaraq, hələ də körpə kimi danışdığını müşahidə edə bilərsiniz. Bu hal yaşıdları tərəfindən mənfi qarşılanmasına, sosial həyatda çətinlik çəkməsinə və özünəinamının zədələnməsinə səbəb ola bilər. Belə vəziyyətdə valideynlərin doğru yanaşması ilə daha sürətli irəliləyiş əldə etmək mümkündür. İlk növbədə, uşaqla eyni tərzdə, körpə dilində danışaraq onun yanlış tələffüzlərini möhkəmləndirməməlisiniz. Digər tərəfdən, danışıq tərzi ilə əsla lağ edilməməlidir. Düzgün deyə bilmədiyi sözləri tənqid edirmiş kimi düzəltməkdən qaçın. O, yanlış tələffüz etdikdən dərhal sonra həmin sözün doğrusunu təbii bir şəkildə sizdən eşitməlidir. Məsələn, uşaq "Qapını badadım" dedikdə, siz "Afərin, balam, qapını bağladın" deyərək doğru nümunə göstərməlisiniz.$q$),
(85, 'baby_daily_info', '325b0b4a-e376-48f0-a0fe-eb9238a52843', 'info', 'text', $q$D vitamini sümük-əzələ inkişafı, beyin fəaliyyəti və immunitet sistemi üçün çox vacibdir. Günəş bədənin D vitamini ehtiyacının 90-95%-ni qarşılayır. Qalan hissə isə qidalardan əldə edilir. Parkda gündə cəmi 10 dəqiqə əllərin və üzün günəş görməsi D vitamini sintezi üçün kifayət edəcəkdir. Bundan artığı uşağınız üçün zərərli ola bilər. Xüsusilə günəş şüalarının ən dik gəldiyi saat 10:00 ilə 14:00 arası günəşdən qaçınmaq lazımdır. Bu saatları qapalı məkanlarda keçirmək daha məqsədəuyğundur.$q$, $q$D vitamini sümük-əzələ inkişafı, beyin fəaliyyəti və immunitet sistemi üçün çox vacibdir. Günəş bədənin D vitamini ehtiyacının 90-95%-ni qarşılayır. Qalan hissə isə qidalardan əldə edilir. Parkda qısa müddət əllərin və üzün günəş görməsi D vitamini sintezinə kömək edir. Uzun müddət günəşdə qalanda isə günəş kremi və papaqdan istifadə edin. Xüsusilə günəş şüalarının ən dik gəldiyi saat 10:00 ilə 16:00 arası uşağınızı birbaşa günəşdən qoruyun. Bu saatlarda kölgədə oynamaq daha məqsədəuyğundur.$q$),
(86, 'baby_daily_info', '692f9786-05ee-4a06-925c-e91c4c28f381', 'info', 'text', $q$Uşaqlarda zaman anlayışı əsasən 4 yaş civarında formalaşmağa başlayır. Təbii ki, bu, böyüklərin başa düşdüyü təqvim anlayışı ilə eyni deyil. Məsələn, övladınız o günün bazar günü olduğunu bilə bilər, lakin bu, dünün şənbə, sabahın isə bazar ertəsi olduğunu və ya günün dəqiq tarixini bildiyi mənasına gəlmir. O, sadəcə atası evdə olduğu üçün bu günün bazar olduğunu düşünə bilər. Eyni şəkildə, 4 yaşında olduğunu bilməsi, 3 yaşlı uşağın ondan daha kiçik olduğunu tam qavraması demək deyil. O, yaşını tez-tez təkrar etdiyi üçün bilir, lakin '5 yaşında olmaq nə deməkdir?' deyə soruşsanız, çox güman ki, sadəcə yenidən 5 yaşında olduğunu təkrar edəcək.$q$, $q$Uşaqlarda zaman anlayışı əsasən 4 yaş civarında formalaşmağa başlayır. Təbii ki, bu, böyüklərin başa düşdüyü təqvim anlayışı ilə eyni deyil. Məsələn, övladınız o günün bazar günü olduğunu bilə bilər, lakin bu, dünün şənbə, sabahın isə bazar ertəsi olduğunu və ya günün dəqiq tarixini bildiyi mənasına gəlmir. O, sadəcə atası evdə olduğu üçün bu günün bazar olduğunu düşünə bilər. Eyni şəkildə, 4 yaşında olduğunu bilməsi, 3 yaşlı uşağın ondan daha kiçik olduğunu tam qavraması demək deyil. O, yaşını tez-tez təkrar etdiyi üçün bilir, lakin '4 yaşında olmaq nə deməkdir?' deyə soruşsanız, çox güman ki, sadəcə yenidən 4 yaşında olduğunu təkrar edəcək.$q$),
(87, 'mommy_daily_messages', '1fddfb5f-0320-4827-b223-17100c2c0495', 'message', 'text', $q$Artıq körpənin gülüşləri refleks deyil, tamamilə şüurludur! Sən ona gülümsəyəndə, qıdıqlayanda və ya "cee-eee" (gizlənqaç) oynayanda səsli gülməyə başlaya bilər. Bu səs dünyanın ən gözəl musiqisidir, elə deyilmi? Onun húmor hissi formalaşır. Qəribə səslər çıxarmaq, üzünü müxtəlif formalara salmaq onun çox xoşuna gələcək. Gülmək həm də onun ağciyərlərini inkişaf etdirir və stress hormonlarını azaldır.$q$, $q$Artıq körpənin gülüşləri refleks deyil, tamamilə şüurludur! Sən ona gülümsəyəndə, qıdıqlayanda və ya "cee-eee" (gizlənqaç) oynayanda səsli gülməyə başlaya bilər. Bu səs dünyanın ən gözəl musiqisidir, elə deyilmi? Onun yumor hissi formalaşır. Qəribə səslər çıxarmaq, üzünü müxtəlif formalara salmaq onun çox xoşuna gələcək. Gülmək həm də onun ağciyərlərini inkişaf etdirir və stress hormonlarını azaldır.$q$),
(88, 'mommy_daily_messages', '01937078-adcb-4cc4-9337-fd91b288734f', 'message', 'text', $q$Axşam saatlarında körpənin südü rədd etdiyini, döşlə dalaşdığını və ya ağlayaraq əmdiyini görürsən? Buna "Yalançı süd imtinası" deyilir. Səbəbi südün azlığı yox, körpənin yorğunluğu və ya həddindən artıq stimullaşmasıdır. Onu sakitləşdirmək üçün "bəyaz küy" (white noise) yandır, otağı qaranlıqlaşdır və ya gəzərək əmizdir. Əgər yenə də imtina edərsə, məcbur etmə, 15-20 dəqiqə fasilə ver, sakitləşdir və yenidən yoxla.$q$, $q$Axşam saatlarında körpənin südü rədd etdiyini, döşlə dalaşdığını və ya ağlayaraq əmdiyini görürsən? Buna "Yalançı süd imtinası" deyilir. Səbəbi südün azlığı yox, körpənin yorğunluğu və ya həddindən artıq stimullaşmasıdır. Onu sakitləşdirmək üçün "ağ səs" (white noise) yandır, otağı qaranlıqlaşdır və ya gəzərək əmizdir. Əgər yenə də imtina edərsə, məcbur etmə, 15-20 dəqiqə fasilə ver, sakitləşdir və yenidən yoxla.$q$),
(89, 'mommy_daily_messages', '440c73d7-8d87-4380-afc8-4a3037eff65e', 'message', 'text', $q$Dördüncü ayda körpənin yuxu rejimini qurmaq üçün "Yuxu pəncərəsi" (Sleep Associations) yarada bilərsən. Əgər o, yalnız əmərək və ya yırğalanaraq yatmağa öyrəşibsə, bunu yavaş-yavaş dəyişməyə başla. Məsələn, yuxulamağa başlayanda (tam yatmamış) yatağına qoy və sadəcə əlini üzərinə qoyaraq "şşş" de. İlk günlər etiraz edəcək, amma səbrli olsan, o, öz-özünə sakitləşməyi (self-soothing) öyrənməyə başlayacaq. Bu, uzun bir yoldur, tələsmə.$q$, $q$Dördüncü ayda körpənin yuxu rejimini qurmaq üçün "Yuxu vərdişləri" (sleep associations) yarada bilərsən. Əgər o, yalnız əmərək və ya yırğalanaraq yatmağa öyrəşibsə, bunu yavaş-yavaş dəyişməyə başla. Məsələn, yuxulamağa başlayanda (tam yatmamış) yatağına qoy və sadəcə əlini üzərinə qoyaraq "şşş" de. İlk günlər etiraz edəcək, amma səbrli olsan, o, öz-özünə sakitləşməyi (self-soothing) öyrənməyə başlayacaq. Bu, uzun bir yoldur, tələsmə.$q$),
(90, 'mommy_daily_messages', '3c6e4f71-0ba2-4930-a133-04552c20e1dd', 'message', 'text', $q$Güzgüyə baxanda özünü baxımsız, yorğun hiss edirsən? Analıq məzuniyyəti bəzən "Dug groundhog günü"nə (eyni günün təkrarı) bənzəyir. Bu gün körpəni atasına və ya nənəsinə verib 1 saatlıq evdən çıx. Sadəcə marketə getmək, parkda tək gəzmək və ya saçını kəsdirmək sənə "oksigen maskası" kimi təsir edəcək. Sən xoşbəxt olsan, körpən də xoşbəxt olar.$q$, $q$Güzgüyə baxanda özünü baxımsız, yorğun hiss edirsən? Analıq məzuniyyəti bəzən hər gün eyni günü yaşamağa bənzəyir. Bu gün körpəni atasına və ya nənəsinə verib 1 saatlıq evdən çıx. Sadəcə marketə getmək, parkda tək gəzmək və ya saçını kəsdirmək sənə "oksigen maskası" kimi təsir edəcək. Sən xoşbəxt olsan, körpən də xoşbəxt olar.$q$),
(91, 'mommy_daily_messages', '026af185-68d2-497b-b2e5-6cbcde3b4230', 'message', 'text', $q$Körpəni oturtmaq üçün "yastıq qalalarından" istifadə etməyə tələsmə. Əgər o, özü oturmağa cəhd etmirsə və belini büküb "C" hərfi kimi durursa (ozonlaşmış vəziyyət), deməli əzələləri hələ hazır deyil. Məcburi oturtmaq onurğasına zərər verə bilər. Qoy yerdə daha çox vaxt keçirsin, özü "Tripod" vəziyyətinə (əllərini qabağa qoyaraq) gələcək. Təbii inkişaf hər zaman ən təhlükəsizidir.$q$, $q$Körpəni oturtmaq üçün "yastıq qalalarından" istifadə etməyə tələsmə. Əgər o, özü oturmağa cəhd etmirsə və belini büküb "C" hərfi kimi durursa (bel əyilmiş vəziyyət), deməli əzələləri hələ hazır deyil. Məcburi oturtmaq onurğasına zərər verə bilər. Qoy yerdə daha çox vaxt keçirsin, özü "Tripod" vəziyyətinə (əllərini qabağa qoyaraq) gələcək. Təbii inkişaf hər zaman ən təhlükəsizidir.$q$),
(92, 'mommy_daily_messages', '348776a6-90b7-44de-bed5-439f8ce3ea57', 'message', 'text', $q$Yumurta sarısı ilə tanışlıq vaxtıdır! Yumurtanı bərk bişir və sarısından cəmi noxud dənəsi boyda bir hissəni ana südü və ya püre ilə qarışdırıb ver. Yumurta sarısı beyin inkişafı üçün vacib olan xolin və yağ turşuları ilə zəngindir. Diqqətli ol: yumurta ağı (protein) güclü allergen olduğu üçün 1 yaşına qədər tövsiyə edilmir. Sarısının miqdarını hər dəfə bir az artıraraq reaksiyanı izlə.$q$, $q$Yumurta sarısı ilə tanışlıq vaxtıdır! Yumurtanı bərk bişir və sarısından cəmi noxud dənəsi boyda bir hissəni ana südü və ya püre ilə qarışdırıb ver. Yumurta sarısı beyin inkişafı üçün vacib olan xolin və yağ turşuları ilə zəngindir. Yaxşı bişmiş yumurtanın ağını da 6 aydan sonra kiçik miqdarda verə bilərsən; ailədə ciddi allergiya varsa, əvvəlcə həkimlə məsləhətləş. Miqdarı hər dəfə bir az artıraraq reaksiyanı izlə.$q$),
(93, 'mommy_daily_messages', 'c73b10f1-26e8-49f8-a842-9fc9eb05c61a', 'message', 'text', $q$Körpənin dərisində, xüsusilə ağız ətrafında və ya bədənində qəfil qızartılar görsən, son 3 gündə verdiyin yeni qidaları xatırla. Əgər hər hansı allergik reaksiya şübhəsi varsa, həmin qidanı dərhal dayandır və 1-2 həftə sonra yenidən (kiçik miqdarda) yoxla. Bəzən bədən sadəcə qidanın teksturasına reaksiya verir, bəzən isə bu, əsl allergiyadır. Şübhəli məqamlarda pediatrla məsləhətləşmək ən doğrusudur.$q$, $q$Körpənin dərisində, xüsusilə ağız ətrafında və ya bədənində qəfil qızartılar görsən, son 3 gündə verdiyin yeni qidaları xatırla. Əgər hər hansı allergik reaksiya şübhəsi varsa, həmin qidanı dərhal dayandır və yenidən verməzdən əvvəl pediatrla məsləhətləş; tənəffüs çətinliyi, üz-dodaq şişkinliyi olarsa, dərhal təcili yardım çağır. Bəzən bədən sadəcə qidanın teksturasına reaksiya verir, bəzən isə bu, əsl allergiyadır. Şübhəli məqamlarda pediatrla məsləhətləşmək ən doğrusudur.$q$),
(94, 'mommy_daily_messages', 'eeeb250d-7860-4dbd-adfd-8f04383dcc0f', 'message', 'text', $q$Təbriklər, tam 8 ayı geridə qoyduq! Körpən artıq doğum çəkisini təxminən üçqat artırıb (orta rəqəmdir). O, artıq çox aktivdir, səsləri fərqləndirir və ailə üzvlərini tanıyır. Bu gün onunla yerdə "top-top" oyna; topu ona doğru diyirlə, o da onu tutmağa çalışsın. Bu oyun həm göz koordinasiyasını, həm də növbələşmə (sosial qayda) bacarığını inkişaf etdirir. Sən möhtəşəm bir yol gəlmisən, Ana!$q$, $q$Təbriklər, tam 8 ayı geridə qoyduq! Körpən artıq doğum çəkisini ikiqatdan çox artırıb (üçqat artım adətən 1 yaşa yaxın olur). O, artıq çox aktivdir, səsləri fərqləndirir və ailə üzvlərini tanıyır. Bu gün onunla yerdə "top-top" oyna; topu ona doğru diyirlə, o da onu tutmağa çalışsın. Bu oyun həm göz koordinasiyasını, həm də növbələşmə (sosial qayda) bacarığını inkişaf etdirir. Sən möhtəşəm bir yol gəlmisən, Ana!$q$),
(95, 'mommy_daily_messages', '953f792e-f8bd-44cc-a2d0-c3b8471c1a51', 'message', 'text', $q$Diş çıxarma zamanı damaqların qaşınması və ağrısı körpənin gecə yuxusuna təsir edə bilər. Əgər körpən yuxuda huzursuzdursa, damaqlarını təmiz, nəm və sərin bir dəsmalla yüngülcə masaj et. Diş çıxarma dövründə iştahın azalması da normaldır; onu məcbur etmə, daha çox maye və ana südü/süni qida təklif et. Sənin şəfqətin onun ən böyük ağrıkəsicisidir.$q$, $q$Diş çıxarma dövründə körpə hər şeyi ağzına aparmağa və çeynəməyə çalışır. Ona soyuducuda sərinlədilmiş (dondurulmamış) silikon dişləmə halqası ver; bu, damaqlardakı təzyiqi yüngülləşdirir. Ağzından tez-tez axan selik çənəsində qızartı yarada bilər, ona görə də çənəsini yumşaq dəsmalla tez-tez qurula. Sənin səbrin onun ən yaxşı dəstəyidir.$q$),
(96, 'mommy_daily_messages', 'b5fee624-3a8a-4073-bf22-e9bf23545a25', 'message', 'text', $q$Təbriklər, 9 ayı tamamladıq! Körpən artıq öz adını hər zaman tanıyır və çağıranda dərhal sənə tərəf dönür. O, artıq ailə üzvlərini digərlərindən aydın şəkildə fərqləndirir və sənə qarşı xüsusi bağlılıq göstərir. Bu gün onunla yerdə "kitab oxuma" saatı keçir; o şəkilləri göstərsin, sən isə adlarını de. Sən onun ən etibarlı müəllimi və qəhrəmanısan, Ana!$q$, $q$Təbriklər, 9 ayı tamamladıq! Körpən artıq baş və şəhadət barmağı ilə kiçik əşyaları götürməyə (qısqac tutuşu) çalışır və "bay-bay" deyə əl yelləməyi öyrənir. Bir çox körpə bu dövrdə mebelə tutunaraq ayağa qalxır. Bu gün ona yumşaq, kiçik qida tikələri ver ki, barmaqları ilə götürməyi məşq etsin, amma yemək vaxtı onu tək qoyma. Hər yeni bacarığında sənin alqışın onun ən böyük motivasiyasıdır, Ana!$q$),
(97, 'mommy_daily_messages', 'aee72c71-4ab2-40ae-a72a-f441c99bcf9d', 'message', 'text', $q$Özünü dərk etmə: Körpən artıq güzgüdəki əksinin özü olduğunu anlamağa başlayır. Onun burnuna kiçik bir rəngli ləkə qoyub güzgüyə baxdırsaq, o öz üzündəki ləkəni silməyə çalışacaq (buna "ruj testi" deyilir). Bu, onun mənlik şüurunun (self-awareness) inkişafıdır. Onunla güzgü qarşısında durub "bu sənin burnundur, bu isə ananın burnudur" deyərək fərqləri göstər. Bu, həm də bədən sxemini formalaşdırmaq üçün əla məşqdir.$q$, $q$Güzgü ilə tanışlıq: Körpən güzgüdəki əksi ilə çox maraqlanır, ona gülümsəyir və toxunmağa çalışır. Özünü güzgüdə tanıması (ruj testi) adətən 18-24 ayda olur. Bu maraq onun mənlik şüurunun (self-awareness) inkişafına aparan ilk addımlardır. Onunla güzgü qarşısında durub "bu sənin burnundur, bu isə ananın burnudur" deyərək fərqləri göstər. Bu, həm də bədən sxemini formalaşdırmaq üçün əla məşqdir.$q$),
(98, 'mommy_daily_messages', '7871caf2-41cf-4c3f-b2a8-4d60c9c5acd7', 'message', 'text', $q$Qidalanmada müstəqillik: Artıq körpən qaşığı tamamilə özü tutub ağzına aparmaq istəyir. Bəli, yeməyin çoxu yerdə və önlükdə olacaq, amma bu, incə motorikanın və əl-göz koordinasiyasının ən vacib məşqidir. Ona özü üçün rahat, silikon və ya qalın saplı qaşıq ver. Sən də eyni vaxtda başqa bir qaşıqla ona kömək edə bilərsən. Bu, "komanda işi" kimidir!$q$, $q$Qidalanmada müstəqillik: Körpən artıq barmaqları ilə kiçik, yumşaq tikələri götürüb özü yeməyə can atır. Ona buxarda bişmiş yerkökü, banan və ya yumşaq makaron kimi asan tutulan qidalar təklif et. Yemək vaxtı onu tək qoyma və hər tikənin yumşaq olmasına diqqət et. Qoy öz sürəti ilə yesin, bu, onun toxluq hissini tanımasına kömək edir. Səliqəsizlik müvəqqətidir, öyrənmək isə qalıcıdır!$q$),
(99, 'mommy_daily_messages', '627b69c9-1a97-4379-b790-7b2e4d39bfb2', 'message', 'text', $q$"Yox" sözünün gücü: Körpən artıq sənin "Yox" deməyinə etiraz edə, hətta yerə uzanıb ağlaya bilər (ilk tandemlər). Bu, onun emosiyalarını idarə etməyi hələ bilməməsindən irəli gəlir. Sakit qal, onun yanına en və hisslərini adlandır: "Sən indi hirslisən, çünki oyuncağı vermədim, anlayıram". Sənin bu sakitliyin ona emosional sabitliyi öyrədən ən yaxşı dərsdir.$q$, $q$"Yox" sözünün gücü: Körpən artıq sənin "Yox" deməyinə etiraz edə, hətta yerə uzanıb ağlaya bilər (ilk isterik tutmalar, yəni tantrumlar). Bu, onun emosiyalarını idarə etməyi hələ bilməməsindən irəli gəlir. Sakit qal, onun yanına en və hisslərini adlandır: "Sən indi hirslisən, çünki oyuncağı vermədim, anlayıram". Sənin bu sakitliyin ona emosional sabitliyi öyrədən ən yaxşı dərsdir.$q$),
(100, 'mommy_daily_messages', '3e342e5d-4541-4b82-ae58-b2cc792f784b', 'message', 'text', $q$İlk ad gününə cəmi 10 gün qaldı! Körpən artıq kitab səhifələrini (hələ ki, bir neçəsini birdən) çevirə bilirmi? Bu, onun həm incə motorikasının, həm də kitaba olan marağının göstəricisidir. Ona böyük və rəngli şəkilləri olan kitablar oxumağa davam et. Şəkildəki itə baxıb "Haf-haf haradadır?" dedikdə onu barmağı ilə göstərməsi onun dərketmə qabiliyyətinin zirvəsidir.$q$, $q$İlk ad gününə cəmi 14 gün qaldı! Körpən artıq kitab səhifələrini (hələ ki, bir neçəsini birdən) çevirə bilirmi? Bu, onun həm incə motorikasının, həm də kitaba olan marağının göstəricisidir. Ona böyük və rəngli şəkilləri olan kitablar oxumağa davam et. Şəkildəki itə baxıb "Haf-haf haradadır?" dedikdə onu barmağı ilə göstərməsi onun dərketmə qabiliyyətinin zirvəsidir.$q$),
(101, 'mommy_daily_messages', '74f434ee-a5bf-498f-af06-34cc0939c106', 'message', 'text', $q$Sabah körpənin tam 1 yaşı tamam olur! Bu gün son 12 ayın macərasını xatırla. İlk gülümsəmə, ilk diş, ilk imkləmə... Nə qədər çətin olsa da, sən bacardın! Körpən artıq köməksiz bir körpə deyil, öz xarakteri və istəkləri olan balaca bir insandır. Bu gecə yuxuya gedəndə özünə də bir "afərin" de. Sən möhtəşəm bir anasan!$q$, $q$Körpənin 1 yaşının tamam olmasına cəmi bir neçə gün qaldı! Bu gün son 12 ayın macərasını xatırla. İlk gülümsəmə, ilk diş, ilk imkləmə... Nə qədər çətin olsa da, sən bacardın! Körpən artıq köməksiz bir körpə deyil, öz xarakteri və istəkləri olan balaca bir insandır. Bu gecə yuxuya gedəndə özünə də bir "afərin" de. Sən möhtəşəm bir anasan!$q$),
(102, 'mommy_daily_messages', '56917d9b-b358-4310-b651-30aecbaf8560', 'message', 'text', $q$TƏBRİKLƏR! İLK AD GÜNÜNÜZ MÜBARƏK! 🎂 Körpən artıq rəsmi olaraq 1 yaşındadır. Bu bir il həm onun, həm də sənin həyatında ən böyük dəyişikliklərin olduğu il idi. O artıq yeriməyə, danışmağa və dünyanı fəth etməyə hazır olan bir "Toddler"dir (yeriməyə başlayan uşaq). Bu günü stressiz, sadəcə onun gülüşü və sizin sevginizlə qeyd edin. Yolunuz açıq, ömrünüz bərəkətli olsun!$q$, $q$HAZIR OLUN! İLK AD GÜNÜNƏ CƏMİ 5 GÜN QALDI! 🎂 Körpən bir neçə gündən sonra rəsmi olaraq 1 yaşında olacaq. Bu bir il həm onun, həm də sənin həyatında ən böyük dəyişikliklərin olduğu il idi. O artıq yeriməyə, danışmağa və dünyanı fəth etməyə hazırlaşan bir "Toddler"dir (yeriməyə başlayan uşaq). Ad gününü stressiz, sadəcə onun gülüşü və sizin sevginizlə qeyd edin. Yolunuz açıq, ömrünüz bərəkətli olsun!$q$),
(103, 'mommy_daily_messages', '165b6f1d-3374-4097-b9a4-8e514ea4fdd0', 'message', 'text', $q$2-ci ilə xoş gəldin! İlk ad gününün həyəcanı geridə qaldı, amma əsl macəra indi başlayır. Körpən artıq rəsmən "yeriməyə başlayan uşaq" (toddler) statusundadır. Bu aydan etibarən o, dünyanı daha çox "dik" vəziyyətdə kəşf etmək istəyəcək. Onun hərəkətliliyi artdıqca, enerji ehtiyacı da dəyişir. Amma unutma, hələ də ana sütü və ya süni qida onun rasionunun vacib hissəsi olaraq qala bilər.$q$, $q$2-ci ilə xoş gəldin! İlk ad gününün həyəcanı geridə qaldı, amma əsl macəra indi başlayır. Körpən artıq rəsmən "yeriməyə başlayan uşaq" (toddler) statusundadır. Bu aydan etibarən o, dünyanı daha çox "dik" vəziyyətdə kəşf etmək istəyəcək. Onun hərəkətliliyi artdıqca, enerji ehtiyacı da dəyişir. Amma unutma, hələ də ana südü və ya süni qida onun rasionunun vacib hissəsi olaraq qala bilər.$q$),
(104, 'mommy_daily_messages', 'c278e801-c9bd-49de-b0fb-e7e23f4f7d75', 'message', 'text', $q$Yerimə bacarığı möhkəmlənir! Əgər körpən artıq sərbəst addımlayırsa, onun addımlarının hələ bir az "sərxosh" və enli olduğunu görərsən. Bu, tarazlığı saxlamaq üçün təbii bir mexanizmdir. Onu evdə mümkün qədər yalınayaq burax. Bu, ayaq dabanının düzgün formalaşması və beyninə yerin teksturası haqqında daha çox məlumat getməsi üçün ən yaxşı üsuldur.$q$, $q$Yerimə bacarığı möhkəmlənir! Əgər körpən artıq sərbəst addımlayırsa, onun addımlarının hələ bir az "yırğalanan" və enli olduğunu görərsən. Bu, tarazlığı saxlamaq üçün təbii bir mexanizmdir. Onu evdə mümkün qədər yalınayaq burax. Bu, ayaq dabanının düzgün formalaşması və beyninə yerin teksturası haqqında daha çox məlumat getməsi üçün ən yaxşı üsuldur.$q$),
(105, 'mommy_daily_messages', '6948a89f-6493-4c6e-9adb-708a1f0063cb', 'message', 'text', $q$Təhlükəsizlikdə "Hündürlük" faktoru. Körpən artıq stullara dırmaşır, masanın üstünə çıxmağa çalışır. O, hələ yüksəklik qorxusunu və riskləri tam dərk etmir. Pəncərə kilidlərini yoxla, hündür mebelləri divara bərkit. Onun hərəkət azadlığını kısıtlamadan, mühiti "yıxılma-davamlı" hala gətirmək sənin əsas vəzifəndir.$q$, $q$Təhlükəsizlikdə "Hündürlük" faktoru. Körpən artıq stullara dırmaşır, masanın üstünə çıxmağa çalışır. O, hələ yüksəklik qorxusunu və riskləri tam dərk etmir. Pəncərə kilidlərini yoxla, hündür mebelləri divara bərkit. Onun hərəkət azadlığını məhdudlaşdırmadan, mühiti "yıxılma-davamlı" hala gətirmək sənin əsas vəzifəndir.$q$),
(106, 'mommy_daily_messages', '4d85c160-6a89-4bf6-8f45-da46fe9e61c0', 'message', 'text', $q$Nitqdə "Sual və Maraq". Uşaq artıq "Bu nədir?" (və ya öz dilində oxşar səs) deyərək əşyaları göstərir. Sən səbrlə hər şeyi adlandır: "Bu qırmızı maşındır", "Bu böyük ağacdır". Onun marağını cavabsız qoymamaq lüğət fondunun həm passiv, həm də aktiv şəkildə zənginləşməsinə kömək edir.$q$, $q$Nitqdə "Göstər və adlandır". Uşaq artıq şəkillərdə tanış əşyaları barmağı ilə göstərməyi sevir. Kitab vərəqləyərkən ondan soruş: "Pişik haradadır?", sonra özün də adını de: "Bəli, bu pişikdir, miyav edir". Bu oyun onun passiv lüğətini genişləndirir və ilk sözlərini daha tez işlətməsinə kömək edir.$q$),
(107, 'mommy_daily_messages', '597fce8a-7564-428a-aa97-6b8b166f2f7c', 'message', 'text', $q$Qidalanmada "Seçicilik" və "Nəzarət". Uşaq bəzən yeməkdən sadəcə "nəzarət onda olsun" diye imtina edə bilər. Onu məcbur etmə. Bunun əvəzinə süfrəyə iki sağlam seçim qoy: "Brokkoli istəyirsən, yoxsa kök?". Seçim etmək imkanı onun etirazını azaldır və öz qərarlarına hörmət edildiyini hiss etdirir.$q$, $q$Qidalanmada "Seçicilik" və "Nəzarət". Uşaq bəzən yeməkdən sadəcə "nəzarət onda olsun" deyə imtina edə bilər. Onu məcbur etmə. Bunun əvəzinə süfrəyə iki sağlam seçim qoy: "Brokkoli istəyirsən, yoxsa kök?". Seçim etmək imkanı onun etirazını azaldır və öz qərarlarına hörmət edildiyini hiss etdirir.$q$),
(108, 'mommy_daily_messages', '9ec78a78-6722-4c40-af92-d0238d028cd3', 'message', 'text', $q$Uşaq artıq 22-ci ayın ortasındadır və lüğət ehtiyatında "söz partlayışı" davam edir. O, artıq sadəcə əşyaları yox, mürəkkəb duyğuları və hərəkətləri də adlandırmağa çalışır. Sən onunla danışarkən cümlələrini bir az daha mürəkkəbləşdir: "Gəl, qırmızı papağını geyinək və çölə çıxaq". Bu, onun eşitmə yaddaşını və qrammatik qavrayışını gücləndirir.$q$, $q$Uşaq artıq 21-ci ayın sonuna yaxınlaşır və lüğət ehtiyatında "söz partlayışı" davam edir. O, artıq sadəcə əşyaları yox, mürəkkəb duyğuları və hərəkətləri də adlandırmağa çalışır. Sən onunla danışarkən cümlələrini bir az daha mürəkkəbləşdir: "Gəl, qırmızı papağını geyinək və çölə çıxaq". Bu, onun eşitmə yaddaşını və qrammatik qavrayışını gücləndirir.$q$),
(109, 'mommy_daily_messages', '179a1147-4671-4989-8a35-24a67964487b', 'message', 'text', $q$Uşaq artıq rəngləri sadəcə tanımır, onları eyniləşdirməkdə ustadlaşır. Ona "Qırmızı corabının tayını tap" dedikdə bunu düzgün edirsə, bu onun vizual məntiqinin inkişafıdır. Gündəlik geyimlərində rəngləri tez-tez vurğula: "Bu gün yaşıl köynəyini geyinək?". Bu, onun lüğət fondundakı sifətləri möhkəmləndirir.$q$, $q$Uşaq artıq eyni rəngli əşyaları bir yerə toplamağa maraq göstərir. Ona bir neçə rəngli qab və kublar ver, "Qırmızıları bu qaba qoyaq" de. Hələ rənglərin adlarını qarışdırsa da, eyni rəngi seçməsi onun vizual müqayisə bacarığının inkişafıdır. Oyunda rəngləri adlandır: "Bu sarı kubdur". Bu, onun lüğətinə yeni sifətlər qatır.$q$),
(110, 'mommy_daily_messages', 'ce938ec0-b1a1-418d-9c79-f5996a2ee822', 'message', 'text', $q$Nitqdə "Heyvanlar və onların balaları". Uşaq artıq heyvanların adlarını bilir, indi isə onların balalarını (məsələn, pişik və kütan) fərqləndirməyə maraq göstərə bilər. Kitab oxuyarkən bu detallara toxun. Bu, onun həm kateqoriyalar üzrə düşünmək bacarığını, həm də təbiətə olan marağını artırır.$q$, $q$Nitqdə "Heyvanlar və onların balaları". Uşaq artıq heyvanların adlarını bilir, indi isə onların balalarını (məsələn, pişik və pişik balası) fərqləndirməyə maraq göstərə bilər. Kitab oxuyarkən bu detallara toxun. Bu, onun həm kateqoriyalar üzrə düşünmək bacarığını, həm də təbiətə olan marağını artırır.$q$),
(111, 'mommy_daily_messages', '7aacd700-e4fe-464f-89ef-4b8e3945aa5a', 'message', 'text', $q$23-cü ayın son on günlüyünə başlayırıq! Uşaq artıq "Mən" əvəzliyini tam dərk edərək istifadə edir. "Mən gəldim", "Mən yedim" kimi cümlələr onun özünü ətrafdan ayrı bir fərd kimi gördüyünü sübut edir. Onun bu müstəqil ifadələrini dəstəklə və dialoqlarını genişləndir: "Bəli, sən dadlı yeməyini yedin, afərin sənə!".$q$, $q$22-ci ayın son on günlüyünə başlayırıq! Uşaq artıq "Mən" əvəzliyini tam dərk edərək istifadə edir. "Mən gəldim", "Mən yedim" kimi cümlələr onun özünü ətrafdan ayrı bir fərd kimi gördüyünü sübut edir. Onun bu müstəqil ifadələrini dəstəklə və dialoqlarını genişləndir: "Bəli, sən dadlı yeməyini yedin, afərin sənə!".$q$),
(112, 'mommy_daily_messages', '916356ea-060f-4a2e-8be7-98dcab3ad0ee', 'message', 'text', $q$"Müstəqil təmizlik" vərdişi. Uşaq artıq əllərini yuyarkən sabunlayıb yaxalamağı demək olar ki, təkbaşına bacarır. Gigiyena vərdişlərinin bu yaşda möhkəmlənməsi çox vacibdir. Ona öz boyuna uyğun bir pilləkən (step stool) təmin et ki, bu prosesdən zövq alsın.$q$, $q$"Gigiyena ritualı". Uşaq artıq yeməkdən əvvəl və tualetdən sonra əl yumağın vacib olduğunu öyrənir. Bunu əyləncəli etmək üçün əl yuyarkən onunla birlikdə qısa bir mahnı oxu ki, sabunlama müddəti uzansın. Hər dəfə özü xatırlayanda onu təriflə; bu, vərdişin möhkəmlənməsinə kömək edir.$q$),
(113, 'mommy_daily_messages', 'bf415e92-93fc-4c0c-8e41-d0e69018f7ba', 'message', 'text', $q$Fiziki hərəkətlilikdə "Pilləkən sərbəstliyi". Uşaq artıq pilləkənləri hər pilləyə bir addım qoymaqla (yerini dəyişərək) və cəmi bir əlindən tutmaqla inamla çıxır. Bu, onun böyük motorikasının tam yetkinləşdiyini göstərir. Sən sadəcə yanında olaraq ona mənəvi dəstək ver.$q$, $q$Fiziki hərəkətlilikdə "Tarazlıq oyunları". Uşaq artıq yerə çəkilmiş düz xətt üzrə yeriməyə, bir anlıq bir ayaq üstə durmağa çalışır. Evdə yerə yapışqan lentlə xətt çək və onunla "körpüdən keçmə" oyunu oyna. Bu, onun böyük motorikasını və tarazlığını gücləndirir. Sən sadəcə yanında olaraq onu ruhlandır.$q$),
(114, 'mommy_daily_messages', '458401f2-485d-418a-8b89-143f552eb250', 'message', 'text', $q$1000 günlük böyük marafondan sonra ilk günümüz! Uşaq artıq 4-cü ilinə addım atır. Bu dövrdə "Niyə?" sualları yeni bir keyfiyyət qazanır. O, sadəcə məlumat yox, hadisələr arasındakı məntiqi əlaqəni axtarır. Səbrlə cavab ver, çünki bu suallar onun intellektual təməlini qoyur.$q$, $q$1000 günlük böyük marafondan sonra ilk günümüz! Uşaq 3 yaşına doğru inamla addımlayır. Bu dövrdə "Niyə?" sualları yeni bir keyfiyyət qazanır. O, sadəcə məlumat yox, hadisələr arasındakı məntiqi əlaqəni axtarır. Səbrlə cavab ver, çünki bu suallar onun intellektual təməlini qoyur.$q$),
(115, 'mommy_daily_messages', '1e35d34e-147e-430a-a51b-7c615ecdd852', 'message', 'text', $q$İncə motorikada "Yazı Öncesi Bacarıqlar". Uşaq artıq qələmi barmaqları ilə (ovucu ilə yox) tutur və qapalı dairələr, xaç və hətta bəzi hərflərə bənzər cizgilər çəkir. Bu, onun gələcək yazı vərdişləri üçün ən kritik fiziki mərhələdir.$q$, $q$İncə motorikada "Yazıya hazırlıq bacarıqları". Uşaq artıq qələmi barmaqları ilə (ovucu ilə yox) tutur və qapalı dairələr, xaç və hətta bəzi hərflərə bənzər cizgilər çəkir. Bu, onun gələcək yazı vərdişləri üçün ən kritik fiziki mərhələdir.$q$),
(116, 'mommy_daily_messages', 'd8ae8173-4cc7-42b0-8737-2bedce267dcb', 'message', 'text', $q$Uşaq artıq rəngləri və formaları birləşdirərək dünyanı təsvir edir. "Mənə o sarı kvadrat bloku ver" deyirsə, bu onun beynində eyni vaxtda bir neçə xüsusiyyəti emal etdiyini göstərir. Onun bu bacarığını gündəlik həyatda kiçik tapşırıqlarla (məsələn, "göy corablarını tap") dəstəklə.$q$, $q$Uşaq artıq əşyaları bir neçə əlamətə görə çeşidləməyi bacarır. Ondan oyuncaqları həm rənginə, həm də ölçüsünə görə ayırmasını istə: "Böyük qırmızı topları bu qutuya, kiçikləri o birinə qoyaq". Bu oyun onun diqqətini və məntiqi düşüncəsini gücləndirir. Gündəlik işlərdə də ondan kömək istə, məsələn, paltarları rənglərinə görə ayırsın.$q$),
(117, 'mommy_daily_messages', '0aedbd42-1452-4a3e-aa54-4adb1ad4a556', 'message', 'text', $q$Uşaq artıq ətrafındakı yazılara maraq göstərir. Mağaza adları və ya kitab başlıqlarında tanıdığı hərfləri (məsələn, adının baş hərfini) görüb sevinə bilər. Bu, "ilkin savadlılıq" mərhələsidir. Ona hərfləri məcburi öyrətmə, sadəcə marağını stimullaşdır.$q$, $q$Uşaq artıq kitablardakı hekayələri yadda saxlayır və tanış nağılda bir söz dəyişəndə səni düzəldə bilər. Oxuyarkən barmağını sətir boyu gəzdir ki, yazının soldan sağa oxunduğunu görsün. Bu, "ilkin savadlılıq" bacarıqlarının bir hissəsidir. Hərfləri öyrənməyə tələsmə, kitaba olan sevgisini qoru.$q$),
(118, 'mommy_daily_messages', '0ec14802-bab2-45c4-8cbf-788bdfa85e13', 'message', 'text', $q$Uşaq artıq əşyaları təkcə görünüşünə görə yox, həm də materialına görə fərqləndirir: "Bu plastikdir, bu isə dəmirdir". Ona müxtəlif teksturalı əşyalar ver və fərqləri soruş. Bu, onun ətraf aləmi daha detallı analiz etməsinə və fiziki dünya haqqında məlumatlarını sistemləşdirməsinə kömək edir.$q$, $q$Uşaq artıq əşyaların hansının suda batdığını, hansının üzdüyünü maraqla müşahidə edir. Vanna vaxtı ona plastik qaşıq, taxta kub, kiçik daş kimi müxtəlif əşyalar ver və əvvəlcə soruş: "Səncə, bu batacaq?" Sonra birlikdə yoxlayın. Bu sadə təcrübə onun proqnoz vermək, müşahidə etmək və nəticə çıxarmaq bacarığını inkişaf etdirir.$q$),
(119, 'mommy_day_notifications', '1b82205e-3e0a-48f0-abf7-dac783f4bce8', 'title', 'text', $q$Südünüz artıq kalorili olğun südə çevrilir. 🥛$q$, $q$Südünüz artıq kalorili yetkin südə çevrilir. 🥛$q$),
(120, 'mommy_day_notifications', 'da011889-3632-43ce-aa11-c46cc9ffe260', 'title', 'text', $q$Körpə baxımı üçün nə eksikdir? 🧴$q$, $q$Körpə baxımı üçün nə çatışmır? 🧴$q$),
(121, 'mommy_day_notifications', '51cd27c2-62e8-409d-8a08-48c1ba2f8c3b', 'title', 'text', $q$Aynadakı dost 👀$q$, $q$Güzgüdəki dost 👀$q$),
(122, 'mommy_day_notifications', '4f713889-2b51-4db7-8d5d-7ee8676555a4', 'body', 'text', $q$İnana bilirsiniz? Düz {milestone_days} gündür ki, bu sehirli yolu birlikdə addımlayırsınız! Körpə fotosessiyasında ilə bu anı xatirəyə çevirin!$q$, $q$İnana bilirsiniz? Düz {milestone_days} gündür ki, bu sehrli yolu birlikdə addımlayırsınız! Körpə fotosessiyası ilə bu anı xatirəyə çevirin!$q$),
(123, 'mommy_day_notifications', '46a6fe4d-c7d7-4c66-88f8-3a6a534cd295', 'title', 'text', $q$Həkim qədər ağıllı 🤖$q$, $q$Ağıllı köməkçiniz 🤖$q$),
(124, 'mommy_day_notifications', 'c057830d-8790-40ec-a09d-53a252d3ee15', 'body', 'text', $q$Bu gün səbrin bitdi və səsini ucaltdın? Özünü pis hiss etmə. Sən yorulmaz bir robot deyilsən. Yarın yenidən cəhd edərsən.$q$, $q$Bu gün səbrin bitdi və səsini ucaltdın? Özünü pis hiss etmə. Sən yorulmaz bir robot deyilsən. Sabah yenidən cəhd edərsən.$q$),
(125, 'mommy_day_notifications', '87133947-89a5-414b-a6d4-637285ff301e', 'body', 'text', $q$İnana bilirsiniz? Düz 200 gündür ki, bu sehirli yolu birlikdə addımlayırsınız! Körpə fotosessiyasında xüsusi stikerlə bu anı şölənləndirin və Cəmiyyətdə paylaşın!$q$, $q$İnana bilirsiniz? Düz 200 gündür ki, bu sehrli yolu birlikdə addımlayırsınız! Körpə fotosessiyasında xüsusi stikerlə bu anı şənləndirin və Cəmiyyətdə paylaşın!$q$),
(126, 'mommy_day_notifications', 'ea452c1a-6484-41b5-9042-60a3abcf409d', 'body', 'text', $q$Oyuncaq ayısına və ya kuklasına su içirməyə çalışır? Təxəyyülü inkişaf edir və simvolik oyunlar başlayır. Kənardan bu şirin rejissoru izləməkdən zövq alın.$q$, $q$Oyuncaqları bir-birinə vurur, ağzına aparır və ya yerə atır? Bu, onun səbəb-nəticə əlaqəsini kəşf etdiyini göstərir. Kənardan bu balaca tədqiqatçını izləməkdən zövq alın.$q$),
(127, 'mommy_day_notifications', 'ed75b4ae-9703-498c-a857-64016faef6cc', 'body', 'text', $q$Yuxuya 1 saat qalmış evdəki bütün tünd işıqları və ekranları söndürün. Melatonin yalnız sakit və az işıqlı mühitdə sürətlə ifraz olunur.$q$, $q$Yuxuya 1 saat qalmış evdəki bütün parlaq işıqları və ekranları söndürün. Melatonin yalnız sakit və az işıqlı mühitdə sürətlə ifraz olunur.$q$),
(128, 'mommy_day_notifications', '7a757f5f-8810-4a3e-a344-a9b3d9a89548', 'title', 'text', $q$Aıdır yoxsa yorğun? 😭$q$, $q$Acdır, yoxsa yorğun? 😭$q$),
(129, 'mommy_day_notifications', 'd08fdb3f-542d-478d-95e6-72b2d85a8a9a', 'body', 'text', $q$Geri sayım bitmək üzrədir! Artıq ocaqda gəzən, hər şeyi anlayan balaca bir fərdlə eyni evi bölüşürsünüz. Gülümsəyin!$q$, $q$Geri sayım bitmək üzrədir! Artıq otaqda gəzən, hər şeyi anlayan balaca bir fərdlə eyni evi bölüşürsünüz. Gülümsəyin!$q$),
(130, 'mommy_day_notifications', 'e0bce3ef-dd35-48ce-9b1d-dc4a7ba30ba8', 'body', 'text', $q$Oyuncaqları böyük bir qutuya yığmaq, sonra isə hamısını biryerdə yerə boşaltmaq! Bu səbəb-nəticə oyunu onun məntiqini inkişaf etdirir.$q$, $q$Qutunun qapağını açıb-bağlamaq, içinə nəsə qoyub yenidən çıxarmaq! Bu sadə oyun onun əşyaların yox olmadığını anlamasına və əl bacarığına kömək edir.$q$),
(131, 'mommy_day_notifications', '8e91be33-56a9-43aa-bf49-8aa525510abf', 'body', 'text', $q$Parkda gəzərkən fərqli yarpaqlar və ya qozalar toplayın. Ana Dostu Məkanlardan fərqli təbiət mənzərələri olan yeni parklar kəşf edin.$q$, $q$Bu gün parkda daşlara, ağac qabıqlarına birlikdə toxunun və hissləri adlandırın: kələ-kötür, hamar, soyuq. Ana Dostu Məkanlardan yaxınlıqdakı yeni bir parkı kəşf edin.$q$),
(132, 'mommy_day_notifications', 'd3ed901e-4f05-435d-a1d6-02b2847be818', 'body', 'text', $q$Yuxuya getməkdə çətinlik çəkir? Bəyaz küylərdə yalnız çay səsləri ibarət sakitləşdirici bir fon qoşun.$q$, $q$Yuxuya getməkdə çətinlik çəkir? Ağ Səslərdə yalnız çay səslərindən ibarət sakitləşdirici bir fon qoşun.$q$),
(133, 'mommy_day_notifications', 'f00a5e44-ed12-4c77-9249-e4246b2b108d', 'body', 'text', $q$Hələ tez olsa da, qorşoku banyoda saxlamaq vizual hazırlıq yaradır. Tövsiyə Məhsullardan onun diqqətini çəkəcək rahat və maraqlı modellərə baxın.$q$, $q$Hələ tez olsa da, qorşoku (uşaq tualetini) vanna otağında saxlamaq vizual hazırlıq yaradır. Tövsiyə Məhsullardan onun diqqətini çəkəcək rahat və maraqlı modellərə baxın.$q$),
(134, 'mommy_day_notifications', 'f00a5e44-ed12-4c77-9249-e4246b2b108d', 'title', 'text', $q$Qorşokla ilk tanışlıq 🚽$q$, $q$Qorşokla (uşaq tualeti ilə) ilk tanışlıq 🚽$q$),
(135, 'mommy_day_notifications', 'c2f59a7d-198f-4c77-831a-cca0b1b7e5e6', 'body', 'text', $q$Sizinlə banyoya gəlmək istəyir? Bu, vizual hazırlıqdır. Bloqlar bölməsində qorşok təliminə nə vaxt və necə başlamaq lazım olduğunu oxuyub hazırlıqlı olun.$q$, $q$Sizinlə vanna otağına gəlmək istəyir? Bu, vizual hazırlıqdır. Bloqlar bölməsində qorşok (uşaq tualeti) təliminə nə vaxt və necə başlamaq lazım olduğunu oxuyub hazırlıqlı olun.$q$),
(136, 'mommy_day_notifications', 'cc7b1b1f-1c7c-4424-996a-a223a00c890e', 'body', 'text', $q$Səhər yoxlanışı! Əgər bezi uzun müddət quru qalırsa, qorşok vaxtı yaxınlaşır. Bez izləyicisinə qeyd edib statistikanı yoxlayın.$q$, $q$Səhər yoxlanışı! Əgər bezi uzun müddət quru qalırsa, qorşok (uşaq tualeti) vaxtı yaxınlaşır. Bez izləyicisinə qeyd edib statistikanı yoxlayın.$q$),
(137, 'mommy_day_notifications', '8fc02957-0717-4600-94a0-03ec95b3ecc9', 'title', 'text', $q$Qorşok siqnalları? 🚽$q$, $q$Qorşok (uşaq tualeti) siqnalları? 🚽$q$),
(138, 'mommy_day_notifications', '178de938-0734-4759-bd61-91671bd355ba', 'body', 'text', $q$Tualet təliminə vizual hazırlıq başlasın! Tövsiyə Məhsullarda anaların sınaqdan keçirdiyi ən rahat və cəlbedici qorşok modellərinə mütləq göz atın.$q$, $q$Tualet təliminə vizual hazırlıq başlasın! Tövsiyə Məhsullarda anaların sınaqdan keçirdiyi ən rahat və cəlbedici qorşok (uşaq tualeti) modellərinə mütləq göz atın.$q$),
(139, 'mommy_day_notifications', '178de938-0734-4759-bd61-91671bd355ba', 'title', 'text', $q$Qorşok üçün doğru seçim 🚽$q$, $q$Qorşok (uşaq tualeti) üçün doğru seçim 🚽$q$),
(140, 'mommy_day_notifications', '379a5991-8f1e-48b3-9f27-5e21468d8859', 'body', 'text', $q$Səhər bezini dəyişərkən quru olduğunu fərq etdiniz? Qorşok təliminə start vermək üçün Anacan AI-dan ən doğru vaxtı və psixoloji metodları dərhal soruşun.$q$, $q$Səhər bezini dəyişərkən quru olduğunu fərq etdiniz? Qorşok (uşaq tualeti) təliminə start vermək üçün Anacan AI-dan ən doğru vaxtı və psixoloji metodları dərhal soruşun.$q$),
(141, 'mommy_day_notifications', '406278a2-debe-4851-9b00-479abeb4b13e', 'body', 'text', $q$Səhər bezi qupqurudur? Tualet təliminə başlamaq üçün ideal vaxt ola bilər. Bez izləyicisinə qeyd edin və Tövsiyə Məhsullardan erqonomik qorşok seçiminə baxın.$q$, $q$Səhər bezi qupqurudur? Tualet təliminə başlamaq üçün ideal vaxt ola bilər. Bez izləyicisinə qeyd edin və Tövsiyə Məhsullardan erqonomik qorşok (uşaq tualeti) seçiminə baxın.$q$),
(142, 'mommy_day_notifications', '406278a2-debe-4851-9b00-479abeb4b13e', 'title', 'text', $q$Qorşok siqnalları? 🚽$q$, $q$Qorşok (uşaq tualeti) siqnalları? 🚽$q$),
(143, 'mommy_day_notifications', '97ab1430-c17a-4645-93d1-2d0b7261c822', 'body', 'text', $q$Zülal və tərəvəzləri kənara itələyib yalnız karbohidrat istəyir? Qidalanmaya nəzarət aləti ilə bu gün nə qədər faydalı qida aldığını hesablayın və normanı tənzimləyin.$q$, $q$Yeni tərəvəzi boşqabda görən kimi üz çevirir? Onu bir neçə dəfə, təzyiqsiz təklif edin. Qidalanmaya nəzarət aləti ilə həftə ərzində hansı qidaları sınadığını qeyd edin və irəliləyişi izləyin.$q$),
(144, 'mommy_day_notifications', '053139e2-7d9f-4a00-9462-2ddb17d7e133', 'body', 'text', $q$Səhər bezini dəyişərkən quru olduğunu fərq etdiniz? Bu, fiziki olaraq qorşoka hazır olduğunun əsas göstəricisidir! Bez izləyicisinə qeyd edib statistikanı diqqətlə izləyin.$q$, $q$Səhər bezini dəyişərkən quru olduğunu fərq etdiniz? Bu, fiziki olaraq qorşoka (uşaq tualetinə) hazır olduğunun əsas göstəricisidir! Bez izləyicisinə qeyd edib statistikanı diqqətlə izləyin.$q$),
(145, 'mommy_day_notifications', 'a23bc347-ea83-491e-af00-0e80deaecf0f', 'body', 'text', $q$Səhər bezi tamamilə quru qalır və o, narahat olur? Bu möhtəşəm bir siqnaldır. Bez izləyicisinə qeyd edib Bloqlar bölməsində qorşok təliminə hazırlıq mərhələlərini oxumağa başlayın.$q$, $q$Səhər bezi tamamilə quru qalır və o, narahat olur? Bu möhtəşəm bir siqnaldır. Bez izləyicisinə qeyd edib Bloqlar bölməsində qorşok (uşaq tualeti) təliminə hazırlıq mərhələlərini oxumağa başlayın.$q$),
(146, 'mommy_day_notifications', '8144388a-1733-475c-83c3-62e4fa74eb05', 'title', 'text', $q$Qorşoka etiraz? 🚽$q$, $q$Qorşoka (uşaq tualetinə) etiraz? 🚽$q$),
(147, 'mommy_day_notifications', '7a5b3c40-a866-426b-8ed4-dd68302d6513', 'body', 'text', $q$Banyoda tualet kağızlarını rulondan açıb oynayır? Bu marağı fürsətə çevirin, dərhal Bloqlardan qorşok təliminə oyunla keçid məqaləsini oxumağa başlayın.$q$, $q$Vanna otağında tualet kağızlarını rulondan açıb oynayır? Bu marağı fürsətə çevirin, dərhal Bloqlardan qorşok (uşaq tualeti) təliminə oyunla keçid məqaləsini oxumağa başlayın.$q$),
(148, 'mommy_day_notifications', '5f17b1b2-9554-4ba7-b535-5f0af1522385', 'body', 'text', $q$Pərdənin arxasına və ya küncə çəkilib ifrazat edir? Bu, qorşok hazırlığının ən böyük psixoloji siqnalıdır! Bez izləyicisinə qeyd edib Bloqlarda təlim məqalələrini oxuyun.$q$, $q$Pərdənin arxasına və ya küncə çəkilib ifrazat edir? Bu, qorşok (uşaq tualeti) hazırlığının ən böyük psixoloji siqnalıdır! Bez izləyicisinə qeyd edib Bloqlarda təlim məqalələrini oxuyun.$q$),
(149, 'mommy_day_notifications', '33f7b16f-fd6e-4686-be50-8b9aabfa4a20', 'body', 'text', $q$Ocaqları, düymələri və ya oyuncaqları rənginə görə qruplaşdırır? Zəkasını daha da zorlayacaq, məntiqi inkişaf etdirən taxta pazlları dərhal Tövsiyə Məhsullar bölməsində kəşf edin.$q$, $q$Qapaqları, düymələri və ya oyuncaqları rənginə görə qruplaşdırır? Zəkasını daha da zorlayacaq, məntiqi inkişaf etdirən taxta pazlları dərhal Tövsiyə Məhsullar bölməsində kəşf edin.$q$),
(150, 'mommy_day_notifications', '54668cb8-852a-467f-9492-c88f3b1ba329', 'body', 'text', $q$Qorşok təlimi ərəfəsində ayaqüstə durub kaka etməyi saxlayır? Bu psixoloji qəbizlik yarada bilər. Bez izləyicisinə bunu qeyd edib, menyuya dərhal ərik və ya yulaf əlavə edin.$q$, $q$Qorşok (uşaq tualeti) təlimi ərəfəsində ayaqüstə durub kaka etməyi saxlayır? Bu psixoloji qəbizlik yarada bilər. Bez izləyicisinə bunu qeyd edib, menyuya dərhal ərik və ya yulaf əlavə edin.$q$),
(151, 'mommy_day_notifications', 'c3d03381-340f-4ce1-b075-de3e6584aed7', 'body', 'text', $q$Çox qaçır, az su içir? Bez dəyişərkən (və ya qorşokda) ifrazatı izləyin. Qəbizlik riski varsa, tətbiqə qeyd edib dərhal Qidalanmaya nəzarət aləti ilə menyuya qara gavalı və ya yulaf əlavə edin.$q$, $q$Çox qaçır, az su içir? Bez dəyişərkən və ya qorşokda (uşaq tualetində) ifrazatı izləyin. Qəbizlik riski varsa, tətbiqə qeyd edib dərhal Qidalanmaya nəzarət aləti ilə menyuya qara gavalı və ya yulaf əlavə edin.$q$),
(152, 'mommy_day_notifications', 'f13502d3-76f4-47c6-bfef-ed2cb1d9fcf7', 'title', 'text', $q$Suyun sehrligGücü 🛀$q$, $q$Suyun sehrli gücü 🛀$q$),
(153, 'mommy_day_notifications', '69b61ce4-2f0a-419f-8ea0-47c763ae7f20', 'body', 'text', $q$Qorşok təliminə başlamaq üçün doğru vaxtdırmı? Tərəddüd edirsinizsə, Anacan tətbiqinin bloqlar bölməsinə daxil olun və mütəxəssislərin yazdığı pediatr təsdiqli məqalələri oxuyun.$q$, $q$Qorşok (uşaq tualeti) təliminə başlamaq üçün doğru vaxtdırmı? Tərəddüd edirsinizsə, Anacan tətbiqinin bloqlar bölməsinə daxil olun və mütəxəssislərin yazdığı pediatr təsdiqli məqalələri oxuyun.$q$),
(154, 'mommy_day_notifications', '561010fd-17de-4698-b582-1c91bc73389a', 'body', 'text', $q$Heç bir alətə, kitaba və ya nağıla ehtiyac yoxdur. Bu axşam sadəcə onu köksünüzə sıxın, kokusunu içinizə çəkin və qaranlıqda ona sevginizi pıçıldayın.$q$, $q$Heç bir alətə, kitaba və ya nağıla ehtiyac yoxdur. Bu axşam sadəcə onu köksünüzə sıxın, qoxusunu içinizə çəkin və qaranlıqda ona sevginizi pıçıldayın.$q$),
(155, 'mommy_day_notifications', 'ba544f24-4325-4cce-9fad-539f5e144287', 'body', 'text', $q$İki qaşıq yeyib doydum deyir? Onu zorlamayın. Qida ilə sağlam münasibət qurmaq zorla yedirtməkdən daha vacibdir. Porsiyaları çoxaldın, miqdarı azaldın.$q$, $q$İki qaşıq yeyib doydum deyir? Onu zorlamayın. Qida ilə sağlam münasibət qurmaq zorla yedirtməkdən daha vacibdir. Yemək sayını çoxaldın, porsiyaların həcmini azaldın.$q$),
(156, 'mommy_day_notifications', '99409d74-b463-47c8-b5a8-30d9e195253d', 'body', 'text', $q$Çox qaçır, az su içir? Bez dəyişərkən (və ya qorşokda) ifrazatı izləyin. Qəbizlik riski varsa, menyuya yulaf əlavə edin.$q$, $q$Çox qaçır, az su içir? Bez dəyişərkən və ya qorşokda (uşaq tualetində) ifrazatı izləyin. Qəbizlik riski varsa, menyuya yulaf əlavə edin.$q$),
(157, 'mommy_day_notifications', '0727c4e7-7433-410a-9da5-27fff69d9877', 'body', 'text', $q$Çox qaçır, az su içir? Qorşokda və ya bezdə ifrazatı izləyin. Qəbizlik riski varsa, tətbiqə qeyd edib dərhal Qidalanmaya nəzarət aləti ilə menyuya yulaf və ya armud əlavə edin.$q$, $q$Çox qaçır, az su içir? Qorşokda (uşaq tualetində) və ya bezdə ifrazatı izləyin. Qəbizlik riski varsa, tətbiqə qeyd edib dərhal Qidalanmaya nəzarət aləti ilə menyuya yulaf və ya armud əlavə edin.$q$),
(158, 'mommy_day_notifications', 'ade78fe2-3290-467b-9d4f-4aa0e7d81802', 'body', 'text', $q$Qorşoka özü getmək istəyir? Bu, 2.5 yaşın ən böyük zəfəridir! Bez/Qorşok izləyicisinə bu uğuru qeyd edib Bloqlarda keçidi necə daha da asanlaşdıracağınızı oxuyun.$q$, $q$Qorşoka (uşaq tualetinə) özü getmək istəyir? Bu, 2.5 yaşın ən böyük zəfəridir! Bez/Qorşok izləyicisinə bu uğuru qeyd edib Bloqlarda keçidi necə daha da asanlaşdıracağınızı oxuyun.$q$),
(159, 'mommy_day_notifications', '7212233e-c5da-4c83-bd8d-a74e469e3fcc', 'body', 'text', $q$Yuxuya 1 saat qalmış evdəki bütün tünd işıqları və mavi ekranları söndürün. Melatonin hormonunun işə düşməsi üçün evdə axşamürpərdici bir mühit yaradın.$q$, $q$Yuxuya 1 saat qalmış evdəki bütün parlaq işıqları və mavi ekranları söndürün. Melatonin hormonunun işə düşməsi üçün evdə sakit, yuxugətirici bir mühit yaradın.$q$),
(160, 'mommy_day_notifications', 'ead40251-f5fc-4b01-b344-4b041fbbf0eb', 'body', 'text', $q$Gün boyu sizi dəli etdi, hər şeyə ağladı. Amma axşam yuxuya gedərkən köksünüzə sığınan o isti, kiçik bədənin kokusu... Bax bu, dünyanın ən gözəl hissidir.$q$, $q$Gün boyu sizi dəli etdi, hər şeyə ağladı. Amma axşam yuxuya gedərkən köksünüzə sığınan o isti, kiçik bədənin qoxusu... Bax bu, dünyanın ən gözəl hissidir.$q$),
(161, 'mommy_day_notifications', 'c32299af-eeac-42f3-ab67-01688b0d4551', 'body', 'text', $q$Çətin bir qərar verməlisiniz? (Bağça, qorşok, yuxu). Anacan Cəmiyyətindəki təcrübəli anaların məsləhətləri heç bir kitabda yazılmayan ən real həll yollarıdır.$q$, $q$Bağça, qorşok (uşaq tualeti) və ya yuxu ilə bağlı çətin bir qərar verməlisiniz? Anacan Cəmiyyətindəki təcrübəli anaların məsləhətləri heç bir kitabda yazılmayan ən real həll yollarıdır.$q$),
(162, 'mommy_day_notifications', '438805fb-6787-4d0d-b1d5-b2a1a747c30c', 'body', 'text', $q$Çox qaçır, amma su içməyi unudur? Qorşokda ifrazatı izləyin. Menyuya mütləq lifli yulaf, gavalı əlavə edin.$q$, $q$Çox qaçır, amma su içməyi unudur? Qorşokda (uşaq tualetində) ifrazatı izləyin. Menyuya mütləq lifli yulaf, gavalı əlavə edin.$q$),
(163, 'mommy_day_notifications', 'c0129df7-df96-4659-882d-c3fd4d3c25e7', 'body', 'text', $q$İki qaşıq yeyib doydum deyir və qaçır? Onu zorlamayın. Qida ilə sağlam münasibət qurmaq zorla yedirtməkdən daha vacibdir. Porsiyaları çoxaldın, miqdarı azaldın.$q$, $q$İki qaşıq yeyib doydum deyir və qaçır? Onu zorlamayın. Qida ilə sağlam münasibət qurmaq zorla yedirtməkdən daha vacibdir. Yemək sayını çoxaldın, porsiyaların həcmini azaldın.$q$),
(164, 'mommy_day_notifications', '8805c85d-beba-4d76-905f-2991bc6002f2', 'body', 'text', $q$İfrazat ehtiyacını hiss edib özü qorşoka qaçır? Bu, böyük bir zəfərdir!$q$, $q$İfrazat ehtiyacını hiss edib özü qorşoka (uşaq tualetinə) qaçır? Bu, böyük bir zəfərdir!$q$),
(165, 'mommy_day_notifications', '8805c85d-beba-4d76-905f-2991bc6002f2', 'title', 'text', $q$Qorşok zəfəri 🚽$q$, $q$Qorşok (uşaq tualeti) zəfəri 🚽$q$),
(166, 'mommy_day_notifications', '98562e83-4876-4c00-8dbc-2ad2897e54b5', 'body', 'text', $q$TƏBRİKLƏR! Siz düz 1000 gündür ki, bu fırtınalı, yorucu, amma dünyanın ən dəyərli yolunu addımlayırsınız! Dərhal bu xüsusi zəfər gününü şölənləndirin və Anacan Cəmiyyətində fəxrlə paylaşın!$q$, $q$TƏBRİKLƏR! Siz düz 1000 gündür ki, bu fırtınalı, yorucu, amma dünyanın ən dəyərli yolunu addımlayırsınız! Dərhal bu xüsusi zəfər gününü bayram edin və Anacan Cəmiyyətində fəxrlə paylaşın!$q$),
(167, 'mommy_day_notifications', '88b776b7-0d43-49f1-b31c-da27294feb6f', 'body', 'text', $q$Qorşok təlimində (potty training) geriləmə yaşayırsınız? Özünüzü yormayın, Anacan AI-dan bu psixoloji prosesin həll yollarını soruşun.$q$, $q$Qorşok (uşaq tualeti) təlimində geriləmə yaşayırsınız? Özünüzü yormayın, Anacan AI-dan bu psixoloji prosesin həll yollarını soruşun.$q$),
(168, 'mommy_day_notifications', '60323c41-a0d6-4029-8b71-994315dcb0cf', 'body', 'text', $q$Qorşok təlimi zamanı yenə xalçaya çiş etdi? Dərin nəfəs al. Əsəbləşmək onun geri addım atmasına səbəb olar. Təmizlənəcək bir şey üçün psixologiyanızı yormayın, bu sadəcə öyrənmə prosesidir.$q$, $q$Qorşok (uşaq tualeti) təlimi zamanı yenə xalçaya çiş etdi? Dərin nəfəs al. Əsəbləşmək onun geri addım atmasına səbəb olar. Təmizlənəcək bir şey üçün psixologiyanızı yormayın, bu sadəcə öyrənmə prosesidir.$q$),
(169, 'mommy_day_notifications', '60323c41-a0d6-4029-8b71-994315dcb0cf', 'title', 'text', $q$Qorşok qəzaları 🚽$q$, $q$Qorşok (uşaq tualeti) qəzaları 🚽$q$),
(170, 'mommy_day_notifications', 'df191a16-4b37-4a90-bbd4-c8972ecc1670', 'body', 'text', $q$Pijaması yemək, üst-başı boya ləkəsidir? Uşaqlar təmiz böyüməməlidir, onlar kəşf edərək kirlənməlidir. Dağınıqlıq onun yaradıcılığının imnasıdır, stress olmayın.$q$, $q$Pijaması yemək, üst-başı boya ləkəsidir? Uşaqlar təmiz böyüməməlidir, onlar kəşf edərək kirlənməlidir. Dağınıqlıq onun yaradıcılığının imzasıdır, stress keçirməyin.$q$),
(171, 'mommy_day_notifications', 'b7283d95-1357-4ff9-9423-db4159e19c31', 'body', 'text', $q$Çətin bir günü daha geridə qoydunuz. Yoldaşınızla üz-üzə əyləşib bir stəkan çay toqquşdurun: Biz həqiqətən əfsanəvi komandasınız və bu işi əla bacarırıq!$q$, $q$Çətin bir günü daha geridə qoydunuz. Yoldaşınızla üz-üzə əyləşib bir stəkan çay toqquşdurun: Biz həqiqətən əfsanəvi komandayıq və bu işi əla bacarırıq!$q$),
(172, 'mommy_day_notifications', '9a4e49fa-28ce-4422-86d1-9b77699fd24c', 'body', 'text', $q$Çox qaçır, amma su içməyi unudur. Qorşokda ifrazatı izləyin. Qəbizlik riski varsa, menyuya yulaf və gavalı əlavə edin.$q$, $q$Çox qaçır, amma su içməyi unudur. Qorşokda (uşaq tualetində) ifrazatı izləyin. Qəbizlik riski varsa, menyuya yulaf və gavalı əlavə edin.$q$),
(173, 'mommy_day_notifications', 'b948ea64-f471-4d36-958a-85e04a0250f1', 'body', 'text', $q$Tualet ehtiyacı olanda pərdənin arxasına və ya divanın kənarına gizlənir? Bloqlar bölməsinə keçid edib qorşok təliminə necə başlamağın elmi addımlarını oxumağın əsl vaxtıdır.$q$, $q$Tualet ehtiyacı olanda pərdənin arxasına və ya divanın kənarına gizlənir? Bloqlar bölməsinə keçid edib qorşok (uşaq tualeti) təliminə necə başlamağın elmi addımlarını oxumağın əsl vaxtıdır.$q$),
(174, 'mommy_day_notifications', 'b948ea64-f471-4d36-958a-85e04a0250f1', 'title', 'text', $q$Qorşok gizlənqaçı 🚽$q$, $q$Qorşok (uşaq tualeti) gizlənqaçı 🚽$q$),
(175, 'mommy_day_notifications', 'e612b840-bcec-4199-920b-e4d2f37aa7cb', 'body', 'text', $q$Yubiley günü üçün lazım olan hər şeyi Alış-veriş siyahısına əlavə etdiniz? Əmin olun ki, şarlar və kiçik sürprizlər də oradadır. Yoldaşınıza tətbiqdən son xatırlatmanı atın.$q$, $q$Gələn həftənin planları üçün lazım olan hər şeyi Alış-veriş siyahısına əlavə etdiniz? Əmin olun ki, uşağın sevdiyi meyvələr və kiçik sürprizlər də oradadır. Yoldaşınıza tətbiqdən xatırlatma göndərin.$q$),
(176, 'mommy_day_notifications', '4d45db57-1817-4fc6-ad71-f2aeb4cd1050', 'body', 'text', $q$Uşaq yatdıqdan sonra yoldaşınızla sabahkı böyük rəqəm üçün bir-birinizi təbrik edib kiçik bir çiyin masajı edin. Yubiley gününün enerjisi üçün ikinizin də dincəlməsi şərtdir.$q$, $q$Uşaq yatdıqdan sonra yoldaşınızla bir-birinizə kiçik bir çiyin masajı edin. Sabahkı günün enerjisi üçün ikinizin də dincəlməsi şərtdir.$q$),
(177, 'mommy_day_notifications', '0cd42656-20ce-4f47-aca2-4978ae93880d', 'body', 'text', $q$Qorşoka getməyi öyrənmişdi, indi yenə qaçır? Bu çox normal geriləmədir. Təzyiq etməyin, Anacan AI-dan bu psixoloji bariyeri krizsiz aşmağın yollarını soruşun.$q$, $q$Qorşoka (uşaq tualetinə) getməyi öyrənmişdi, indi yenə qaçır? Bu çox normal geriləmədir. Təzyiq etməyin, Anacan AI-dan bu psixoloji bariyeri krizsiz aşmağın yollarını soruşun.$q$),
(178, 'mommy_day_notifications', 'ff22b088-7f8b-4366-a32b-7bd8cd1aa92f', 'body', 'text', $q$Potty training (qorşok təlimi) sizi depressiyaya salıb? Dərhal Anacan Cəmiyyətinə daxil olun. Oradakı digər anaların uğur və uğursuzluq hekayələri sizə güc verəcək.$q$, $q$Qorşok (uşaq tualeti) təlimi sizi depressiyaya salıb? Dərhal Anacan Cəmiyyətinə daxil olun. Oradakı digər anaların uğur və uğursuzluq hekayələri sizə güc verəcək.$q$),
(179, 'mommy_day_notifications', 'b17158eb-f894-42c6-8d84-cab6d30d297a', 'title', 'text', $q$Oyuncaqların Gecən Xeyrəsi 🧸$q$, $q$Oyuncaqlara "Gecən xeyrə qalsın" 🧸$q$),
(180, 'mommy_day_notifications', '3b1d044a-5917-48bd-b4f3-847b5ba6d5db', 'body', 'text', $q$O qədər bahalı oyuncaq var, amma o mətbəxdən bir çömçə tapıb və bütün axşamı onunla gəzir, onu yatırdır. Uşaq beyninin fetişləri izaholunmazdır. Mane olmayın, qoyun o çömçəyə sevgi versin.$q$, $q$O qədər bahalı oyuncaq var, amma o mətbəxdən bir çömçə tapıb və bütün axşamı onunla gəzir, onu yatırdır. Uşaq beyninin bağlılıqları izaholunmazdır. Mane olmayın, qoyun o çömçəyə sevgi versin.$q$),
(181, 'mommy_day_notifications', '5b89452a-e411-4130-87b7-6e1e33b0701e', 'body', 'text', $q$Yuxuya getdiyi anlarda həssaslıq artır. Küçədən gələn səsləri neytrallaşdırmaq üçün otaqda Səs ölçənin arxa fon səsini aktiv edib, otağa qalıcı bir hüzur gətirin.$q$, $q$Yuxuya getdiyi anlarda həssaslıq artır. Küçədən gələn səsləri neytrallaşdırmaq üçün otaqda Ağ Səslərdən fon səsini aktiv edib, otağa qalıcı bir hüzur gətirin.$q$),
(182, 'mommy_day_notifications', '08d5ac7d-b540-46e7-9f43-7f771edfd887', 'title', 'text', $q$Zəfər jazırlığı 💆‍♂️$q$, $q$Zəfər hazırlığı 💆‍♂️$q$),
(183, 'mommy_day_notifications', '6148534d-dac4-4ca6-9b42-87f0242f8cdb', 'body', 'text', $q$Təbriklər! O artıq 3 yaşındadır! Düz {milestone_days} gündür ki, bu fırtınalı, yorucu, amma dünyanın ən ləzzətli yolunu addımlayırsınız! Dərhal bu xüsusi günü şölənləndirin və sevincinizi hər kəslə paylaşın!$q$, $q$Təbriklər! O artıq 3 yaşındadır! Düz {milestone_days} gündür ki, bu fırtınalı, yorucu, amma dünyanın ən ləzzətli yolunu addımlayırsınız! Dərhal bu xüsusi günü bayram edin və sevincinizi hər kəslə paylaşın!$q$),
(184, 'mommy_day_notifications', '94dba968-6bd5-4b01-b8ef-b33b80729320', 'body', 'text', $q$Uşağınız nə qədər böyük yol qət edib! İlk günlərin o kövrək qorxusu yerini indi nəhəng bir inama və bilməşə verib. Sən bu 3 ili böyük qürurla gəldin! Sən həqiqətən əla anasan!$q$, $q$Uşağınız nə qədər böyük yol qət edib! İlk günlərin o kövrək qorxusu yerini indi nəhəng bir inama və biliyə verib. Sən bu 3 ili böyük qürurla gəldin! Sən həqiqətən əla anasan!$q$),
(185, 'mommy_day_notifications', '1efb2536-bf55-4365-890d-581fbbac3193', 'body', 'text', $q$Çətin bir qərar verməlisiniz? (Bağça, qorşok, yuxu). Anacan Cəmiyyətindəki təcrübəli anaların məsləhətləri heç bir kitabda yazılmayan, həyatdan götürülmüş ən real həll yollarıdır.$q$, $q$Çətin bir qərar verməlisiniz? (Bağça, qorşok (uşaq tualeti), yuxu). Anacan Cəmiyyətindəki təcrübəli anaların məsləhətləri heç bir kitabda yazılmayan, həyatdan götürülmüş ən real həll yollarıdır.$q$),
(186, 'mommy_day_notifications', '7daa2d64-db1d-42ea-8cec-a0101d304bbf', 'body', 'text', $q$Çox qaçır, amma su içməyi unudur. Qorşokda ifrazatı izləyin. Qəbizlik riski varsa, tətbiqə qeyd edib dərhal Qidalanmaya nəzarət aləti ilə menyuya yulaf və gavalı əlavə edin.$q$, $q$Çox qaçır, amma su içməyi unudur. Qorşokda (uşaq tualetində) ifrazatı izləyin. Qəbizlik riski varsa, tətbiqə qeyd edib dərhal Qidalanmaya nəzarət aləti ilə menyuya yulaf və gavalı əlavə edin.$q$),
(187, 'mommy_day_notifications', 'cbfa1fac-401d-41c2-974d-c9424b7436ce', 'body', 'text', $q$Mənim uşağım niyə hələ də qorşoka tam öyrəşməyib? düşüncəsi sizi yorur? Anacan Cəmiyyətinə daxil olun, hər uşağın fərqli tempi olduğunu görəcəksiniz.$q$, $q$Mənim uşağım niyə hələ də qorşoka (uşaq tualetinə) tam öyrəşməyib? düşüncəsi sizi yorur? Anacan Cəmiyyətinə daxil olun, hər uşağın fərqli tempi olduğunu görəcəksiniz.$q$),
(188, 'mommy_day_notifications', '4e5540da-110f-46b1-a6fe-0833314d27a6', 'body', 'text', $q$Əlavə qida menyusu üçün ideyalarınız tükənib? İnternetdə itməyin, Sağlam reseptlər bölməsindən yeni ləzzətlər tapın.$q$, $q$Uşağın menyusu üçün ideyalarınız tükənib? İnternetdə itməyin, Sağlam reseptlər bölməsindən yeni ləzzətlər tapın.$q$),
(189, 'mommy_day_notifications', '37ed4aaf-5c8b-418c-8274-802f79f0bf41', 'body', 'text', $q$Klassik kitabları əzbərləmisiniz. Ağıllı nağılları açın, baş qəhrəmanı uşağınız, fəth ediləcək yeri isə onun otağı kimi yaradı qeyri-adi, heç bir səy tələb etməyən yuxu seansı yaradın.$q$, $q$Klassik kitabları əzbərləmisiniz. Ağıllı nağılları açın, baş qəhrəmanı uşağınız, fəth ediləcək yeri isə onun otağı kimi dizayn edib qeyri-adi, heç bir səy tələb etməyən yuxu seansı yaradın.$q$),
(190, 'mommy_day_notifications', '1bf9463f-7457-4983-af0a-2e62627ce701', 'body', 'text', $q$Bu gün fetiş günü! Yalnız qırmızı şeylər istəyir? Qidalanma planına bax, ona bu gün qırmızı pomidor, çiyələk ver, qoy bu qəribə arzusu həyata keçsin, savaşma.$q$, $q$Bu gün qırmızı gündür! Yalnız qırmızı şeylər istəyir? Qidalanma planına bax, ona bu gün qırmızı pomidor, çiyələk ver, qoy bu qəribə arzusu həyata keçsin, savaşma.$q$),
(191, 'mommy_day_notifications', 'a5284401-af40-43a4-aa11-663792a88d21', 'body', 'text', $q$Boşqabda ancaq yaşıl şeylər axtarır? Qidalanma planına bax, göyərtilərdən necə şirin formalı, yaşıl tərəvəz topları düzəldəcəyini öyrən və bu qəribə fetişi doyur.$q$, $q$Boşqabda ancaq yaşıl şeylər axtarır? Qidalanma planına bax, göyərtilərdən necə şirin formalı, yaşıl tərəvəz topları düzəldəcəyini öyrən və bu qəribə istəyini təmin et.$q$),
(192, 'mommy_day_notifications', '7b85f446-78f0-4be5-9cc1-c336a25ea658', 'body', 'text', $q$Kimsə sənin bu gün nə qədər əsəb keçirdiyini görmür və hər kəsə gülümsəmək səni boğur? Əhval gündəliyini aç. İçindəki bütün o zəhəri, qəzəbi ekrana tök. Rəqəmsal qusmaq səni psixoloqdan daha tez sağaldacaq.$q$, $q$Kimsə sənin bu gün nə qədər əsəb keçirdiyini görmür və hər kəsə gülümsəmək səni boğur? Əhval gündəliyini aç. İçindəki bütün o zəhəri, qəzəbi ekrana tök. Hisslərini yazmaq sənə yüngüllük gətirəcək; ağırlıq keçmirsə, mütəxəssisə müraciət etməkdən çəkinmə.$q$),
(193, 'pregnancy_daily_content', '3082b660-7bbe-45c6-906d-ed38816fac24', 'body_changes', 'text', $q$Bu gün menstruasiya dövrünüzün ilk günüdür və hamiləlik təqvimi rəsmən buradan başlayır. Hamiləliyin ilk həftələrində hələ ortada bir körpə yoxdur. Lakin bədəniniz yumurtlama günü və mümkün hamiləlik prosesi üçün hazırlıq mərhələsindədir. Bu hazırlıq prosesi, uşaqlığın endometrium adlanan daxili təbəqəsinin, bədəninizin hər ay yetkinləşdirdiyi mayalanacaq yumurta hüceyrəsinin tutunması məqsədilə damarlanması və qalınlaşması ilə baş verir.;;;
Bədəniniz hər ay bu döngüdə həm uşaqlıqdan, həm də beyində yerləşən hipofiz vəzisindən ifraz olunan hormonlarla böyük dəyişikliklər keçirir. Aylıq döngənizdəki bu ilk iki həftə, hələ ortada körpə və mayalanmağa hazır yumurta hüceyrəsi olmamasına baxmayaraq, hamiləlik prosesinə daxil edilir. Bunun səbəbi, hər qadının yumurtlama dövrünün fərqli olması ilə əlaqədar olaraq, son aybaşı tarixinin hamiləliyin başlanğıcı kimi qəbul edilməsidir.;;;
Biz də ANACAN AİLƏSİ olaraq, daxilinizdə hər gün bir az daha böyüyüb inkişaf edən möcüzəniz haqqında günbəgün məlumatlar, tövsiyələr paylaşmaq və bütün bu prosesdə maraqlandığınız sualları cavablandırmaq üçün yanınızda olacağıq! 😊$q$, $q$Bu gün menstruasiya dövrünüzün ilk günüdür və hamiləlik təqvimi rəsmən buradan başlayır. Hamiləliyin ilk həftələrində hələ ortada bir körpə yoxdur. Lakin bədəniniz yumurtlama günü və mümkün hamiləlik prosesi üçün hazırlıq mərhələsindədir. Bu hazırlıq prosesi, uşaqlığın endometrium adlanan daxili təbəqəsinin, bədəninizin hər ay yetkinləşdirdiyi mayalanacaq yumurta hüceyrəsinin tutunması məqsədilə damarlanması və qalınlaşması ilə baş verir.;;;
Bədəniniz hər ay bu döngüdə həm yumurtalıqlardan, həm də beyində yerləşən hipofiz vəzisindən ifraz olunan hormonlarla böyük dəyişikliklər keçirir. Aylıq döngənizdəki bu ilk iki həftə, hələ ortada körpə və mayalanmağa hazır yumurta hüceyrəsi olmamasına baxmayaraq, hamiləlik prosesinə daxil edilir. Bunun səbəbi, hər qadının yumurtlama dövrünün fərqli olması ilə əlaqədar olaraq, son aybaşı tarixinin hamiləliyin başlanğıcı kimi qəbul edilməsidir.;;;
Biz də ANACAN AİLƏSİ olaraq, daxilinizdə hər gün bir az daha böyüyüb inkişaf edən möcüzəniz haqqında günbəgün məlumatlar, tövsiyələr paylaşmaq və bütün bu prosesdə maraqlandığınız sualları cavablandırmaq üçün yanınızda olacağıq! 😊$q$),
(194, 'pregnancy_daily_content', 'c852b157-989c-44ce-a4ea-0f5d022c7159', 'baby_development', 'text', $q$Mayalanmadan əvvəlki ilk iki həftə ərzində bədəninizdə böyük hazırlıq işləri gedir. Son aybaşı tarixinizdən təxminən iki həftə sonra, rəhminiz və beyninizdəki hipofiz vəzinin ifraz etdiyi hormonlar nəticəsində yumurtalarınızdan biri yetkinləşir, yumurtalıq boyunca irəliləyərək fallop borusuna çatır. Hormonların təsiri ilə inkişaf edən yumurta hüceyrəniz sperm hüceyrəsi ilə müqayisədə olduqca böyükdür. Buna baxmayaraq, sperm hüceyrəsinə nisbətən hərəkətsizdir və yumurtalıq daxilində hərəkəti passiv şəkildə baş verir.;;;
Bədən hüceyrələrindən fərqli olaraq, yumurta və sperm hüceyrəsi 23 xromosomdan ibarətdir və hər iki hüceyrədə özünəməxsus minlərlə gen var. Körpənizin saç rəngi, boyu, cinsiyyəti, hətta burnunun forması belə bu genlərin daxilində gizlənmişdir.$q$, $q$Mayalanmadan əvvəlki ilk iki həftə ərzində bədəninizdə böyük hazırlıq işləri gedir. Son aybaşı tarixinizdən təxminən iki həftə sonra, yumurtalıqlarınız və beyninizdəki hipofiz vəzinin ifraz etdiyi hormonlar nəticəsində yumurtalarınızdan biri yetkinləşir, yumurtalıqdan çıxaraq fallop borusuna çatır. Hormonların təsiri ilə inkişaf edən yumurta hüceyrəniz sperm hüceyrəsi ilə müqayisədə olduqca böyükdür. Buna baxmayaraq, sperm hüceyrəsinə nisbətən hərəkətsizdir və fallop borusu daxilində hərəkəti passiv şəkildə baş verir.;;;
Bədən hüceyrələrindən fərqli olaraq, yumurta və sperm hüceyrəsi 23 xromosomdan ibarətdir və hər iki hüceyrədə özünəməxsus minlərlə gen var. Körpənizin saç rəngi, boyu, cinsiyyəti, hətta burnunun forması belə bu genlərin daxilində gizlənmişdir.$q$),
(195, 'pregnancy_daily_content', '65c15460-76e7-4ea7-90a9-a58b6acebcfe', 'baby_development', 'text', $q$Hər ay aybaşı dövrünüzdə uşaqlığınızda olan yumurta ehtiyatlarından biri yetkinləşərək mayalanmaya hazır vəziyyətə gətirilir. Hormonlarınız yumurtanı yetkinləşdirmədiyi təqdirdə hamiləlik baş tuta bilməz. Daşıdığınız bu yumurtalar hələ doğulmamışdan əvvəl uşaqlığınızda istehsal olunan milyonlarla rüşeym hüceyrədən yaranır və menopoz dövrünə qədər hər aybaşı tsiklində rəhminiz tərəfindən onlardan biri istifadə olunur.$q$, $q$Hər ay aybaşı dövrünüzdə yumurtalıqlarınızda olan yumurta ehtiyatlarından biri yetkinləşərək mayalanmaya hazır vəziyyətə gətirilir. Hormonlarınız yumurtanı yetkinləşdirmədiyi təqdirdə hamiləlik baş tuta bilməz. Daşıdığınız bu yumurtalar hələ doğulmamışdan əvvəl yumurtalıqlarınızda istehsal olunan milyonlarla rüşeym hüceyrədən yaranır və menopoz dövrünə qədər hər aybaşı tsiklində yumurtalıqlarınız tərəfindən onlardan biri istifadə olunur.$q$),
(196, 'pregnancy_daily_content', 'e510f21d-5c69-49bc-a4d8-ea262a0bda7b', 'baby_development', 'text', $q$Uşaqlıq daxilində olan yumurta rüşeymlərinin hamısı tükəndikdə menopoz adlanan hal inkişaf edir. Menopoz, yumurta rüşeymlərinin aktivliyini itirməsi nəticəsində hər ay baş verən aybaşı dövrünün daimi olaraq kəsilməsidir. Dünya miqyasında menopoz yaşı 45-55 aralığında dəyişir.  Lakin bəzi hallarda bu yaşlara çatmadan erkən menopoz inkişaf edə bilər. Erkən menopoz aybaşı dövrünün 45 yaşından əvvəl dayanması halıdır. Bəzi qadınlar hətta 20-li yaşlarında belə menopoz dövrünə keçid edə bilərlər. Erkən menopoz; səbəbi bəlli olmayan hallar, bəzi autoimmun xəstəliklər, radioterapiya, kimyaterapiya, ağır infeksiyalar, ətraf mühit amilləri, abort və düşüklər, tez-tez hamiləlik yaşanması, həddindən artıq piylənmə və irəli dərəcəli hipotiroidizm kimi səbəblərdən qaynaqlana bilər. Bununla yanaşı, siqaret istifadəsi, psixoloji travmalar, soyuq iqlim və çətin ətraf mühit şəraitində yaşamaq da menopozun inkişafını sürətləndirərək menopoz yaşını xeyli aşağı sala bilər.$q$, $q$Yumurtalıqlarda olan yumurta rüşeymlərinin hamısı tükəndikdə menopoz adlanan hal inkişaf edir. Menopoz, yumurta rüşeymlərinin aktivliyini itirməsi nəticəsində hər ay baş verən aybaşı dövrünün daimi olaraq kəsilməsidir. Dünya miqyasında menopoz yaşı 45-55 aralığında dəyişir.  Lakin bəzi hallarda bu yaşlara çatmadan erkən menopoz inkişaf edə bilər. Erkən menopoz aybaşı dövrünün 45 yaşından əvvəl dayanması halıdır. Bəzi qadınlar hətta 20-li yaşlarında belə menopoz dövrünə keçid edə bilərlər. Erkən menopoz; səbəbi bəlli olmayan hallar, bəzi autoimmun xəstəliklər, radioterapiya, kimyaterapiya, ağır infeksiyalar, ətraf mühit amilləri, abort və düşüklər, tez-tez hamiləlik yaşanması, həddindən artıq piylənmə və irəli dərəcəli hipotiroidizm kimi səbəblərdən qaynaqlana bilər. Bununla yanaşı, siqaret istifadəsi, psixoloji travmalar, soyuq iqlim və çətin ətraf mühit şəraitində yaşamaq da menopozun inkişafını sürətləndirərək menopoz yaşını xeyli aşağı sala bilər.$q$),
(197, 'pregnancy_daily_content', '367c8044-41d2-441f-8aec-78399bc382c5', 'baby_development', 'text', $q$Bu həftə yumurta rüşeymlərinizdən biri hormonların köməyi ilə uşaqlığınız tərəfindən yetkinləşdirilməyə davam edir. Yumurta hüceyrənizin yetkinləşməsində və mayalanmaya hazır vəziyyətə gətirilməsində beyninizdə yerləşən hipotalamus bölgəsi, hipofiz vəzi və yumurtalıqlarınızdan ifraz olunan hormonlar iştirak edir. Hipofiz vəzisindən ifraz olunan FSH hormonu isə seçilmiş yumurta rüşeyminin yetkinləşməsini və mayalanmaya hazır hala gəlməsini təmin edərkən, yumurta hüceyrənizdən estrogen ifraz olunmasını stimullaşdırır. Hipofiz vəzisindən ifraz olunan digər hormon- LH hormonu isə yetkinləşmiş yumurta hüceyrənizin folikuldan çıxaraq ovulyasiyanın baş tutmasını və partlamış folikulun "sarı cismə" çevrilməsini təmin edir.$q$, $q$Bu həftə yumurta rüşeymlərinizdən biri hormonların köməyi ilə yumurtalığınızda yetkinləşməyə davam edir. Yumurta hüceyrənizin yetkinləşməsində və mayalanmaya hazır vəziyyətə gətirilməsində beyninizdə yerləşən hipotalamus bölgəsi, hipofiz vəzi və yumurtalıqlarınızdan ifraz olunan hormonlar iştirak edir. Hipofiz vəzisindən ifraz olunan FSH hormonu isə seçilmiş yumurta rüşeyminin yetkinləşməsini və mayalanmaya hazır hala gəlməsini təmin edərkən, yumurta hüceyrənizdən estrogen ifraz olunmasını stimullaşdırır. Hipofiz vəzisindən ifraz olunan digər hormon- LH hormonu isə yetkinləşmiş yumurta hüceyrənizin folikuldan çıxaraq ovulyasiyanın baş tutmasını və partlamış folikulun "sarı cismə" çevrilməsini təmin edir.$q$),
(198, 'pregnancy_daily_content', 'cf28e232-185c-40c5-9616-39e6df91cf1f', 'body_changes', 'text', $q$İlk həftənin sonunda bədəninizdə hormonal dəyişikliklər pik həddə yaxınlaşır. Estrogen səviyyəsinin artması ilə uşaqlıq daxili divarı artıq tamamilə bərpa olunub və qalınlığı artmağa davam edir. Bu günlərdə özünüzü daha sosial, enerjili və özünəinamlı hiss edə bilərsiniz. Libidonuzun artması bədəninizin təbii olaraq reproduktiv dövrə, yəni hamiləlik şansının ən yüksək olduğu günlərə hazırlaşdığının bir işarəsidir.;;;
Sağlam bir hamiləlik prosesi yaşamağınız üçün hamiləlikdən əvvəl rutin tibbi müayinələrdən keçməyiniz lazımdır.;;;
Hamiləlikdən əvvəlki tibbi müayinə, xüsusilə irəli yaşlarda və ya xroniki hər hansı bir narahatlıq olduqda daha böyük əhəmiyyət kəsb edir. Hamiləlikdən əvvəlki müayinədə sizin və həyat yoldaşınızın ailə tarixçəsi nəzərə alınaraq, irsi xüsusiyyət daşıya biləcek hər hansı bir xəstəliyin olub-olmaması araşdırılmalıdır. Həkiminiz tərəfindən ginekoloji müayinə və ultrasonoqrafiya ilə uşaqlıq və yumurtalıqlarınızın qiymətləndirilməsi, uşaqlığa aid mioma və polip kimi problemlərin aşkarlanması baxımından önəmlidir. Əgər həkiminiz lazımi görərsə, "smear testi" adlanan uşaqlıq boynundan yaxma götürülməsi proseduru tətbiq olunmalıdır. Həmçinin laboratoriya testləri ilə qaraciyər, böyrək funksiyalarınız, şəkər, hepatit və toksoplazma kimi xroniki xəstəliklərin olub-olmaması araşdırılmalıdır. Xüsusilə hamiləlikdən əvvəlki müayinələrdə indiyə qədər istifadə olunan doğuma nəzarət üsulları nəzərə alınmalıdır. Uzun müddət istifadə olunan hamiləlik əleyhinə həblər məhsuldarlığı müəyyən bir müddət məhdudlaşdıra bilər. Qadınların təxminən 50%-i sonuncu həbi qəbul etdikdən ən az 6 ay sonra hamilə qala bilər.$q$, $q$İlk həftənin sonunda bədəninizdə hormonal dəyişikliklər pik həddə yaxınlaşır. Estrogen səviyyəsinin artması ilə uşaqlıq daxili divarı artıq tamamilə bərpa olunub və qalınlığı artmağa davam edir. Bu günlərdə özünüzü daha sosial, enerjili və özünəinamlı hiss edə bilərsiniz. Libidonuzun artması bədəninizin təbii olaraq reproduktiv dövrə, yəni hamiləlik şansının ən yüksək olduğu günlərə hazırlaşdığının bir işarəsidir.;;;
Sağlam bir hamiləlik prosesi yaşamağınız üçün hamiləlikdən əvvəl rutin tibbi müayinələrdən keçməyiniz lazımdır.;;;
Hamiləlikdən əvvəlki tibbi müayinə, xüsusilə irəli yaşlarda və ya xroniki hər hansı bir narahatlıq olduqda daha böyük əhəmiyyət kəsb edir. Hamiləlikdən əvvəlki müayinədə sizin və həyat yoldaşınızın ailə tarixçəsi nəzərə alınaraq, irsi xüsusiyyət daşıya biləcek hər hansı bir xəstəliyin olub-olmaması araşdırılmalıdır. Həkiminiz tərəfindən ginekoloji müayinə və ultrasonoqrafiya ilə uşaqlıq və yumurtalıqlarınızın qiymətləndirilməsi, uşaqlığa aid mioma və polip kimi problemlərin aşkarlanması baxımından önəmlidir. Əgər həkiminiz lazımi görərsə, "smear testi" adlanan uşaqlıq boynundan yaxma götürülməsi proseduru tətbiq olunmalıdır. Həmçinin laboratoriya testləri ilə qaraciyər, böyrək funksiyalarınız, şəkər, hepatit və toksoplazma kimi xroniki xəstəliklərin olub-olmaması araşdırılmalıdır. Xüsusilə hamiləlikdən əvvəlki müayinələrdə indiyə qədər istifadə olunan doğuma nəzarət üsulları nəzərə alınmalıdır. Hamiləlik əleyhinə həbləri dayandırdıqdan sonra məhsuldarlıq adətən tez bərpa olunur; qadınların əksəriyyəti ilk il ərzində hamilə qalır.$q$),
(199, 'pregnancy_daily_content', '254bd95f-c06d-46bb-b688-86a0b498dcb9', 'body_changes', 'text', $q$Birinci trimester dövrünə daxil olan hamiləliyin 2-ci həftəsində uşaqlıqda olan yumurtalıqlarınızdakı yumurta hüceyrəsinin inkişafı davam edir. Bu həftədə endometrium adlanan uşaqlıq daxili qişası hormonların təsiri ilə qalınlaşmağa davam edir. Uşaqlıq qişasındakı bu qalınlaşmanın məqsədi isə mayalanma baş verdikdən sonra körpənizi formalaşdıracaq hüceyrələrin uşaqlıq daxilində rahatlıqla tutunmasını təmin etməkdir. Qalınlaşan endometrium təbəqəsi, bu hissənin rahat qanla təchiz olunmasını təmin edəcək şəkildə körpəniz üçün optimal şəraitdə bir yuva yaradır. Mayalanma baş vermədiyi və hamiləlik yaranmadığı təqdirdə isə bu təbəqə hər ay aybaşı dövründə qanaxma ilə bədəndən xaric olunur. Bu döngü hər ay eyni şəkildə davam edir. Hamiləliyin yaranması və sağlam şəkildə davam etməsi üçün uşaqlıq daxili təbəqəsinin tamamilə sağlam olması lazımdır. Bu səbəblə uşaqlığın daxili təbəqəsinin həm qalınlıq, həm də struktur olaraq həkiminiz tərəfindən qiymətləndirilməsi vacibdir.$q$, $q$Birinci trimester dövrünə daxil olan hamiləliyin 2-ci həftəsində yumurtalıqlarınızdakı yumurta hüceyrəsinin inkişafı davam edir. Bu həftədə endometrium adlanan uşaqlıq daxili qişası hormonların təsiri ilə qalınlaşmağa davam edir. Uşaqlıq qişasındakı bu qalınlaşmanın məqsədi isə mayalanma baş verdikdən sonra körpənizi formalaşdıracaq hüceyrələrin uşaqlıq daxilində rahatlıqla tutunmasını təmin etməkdir. Qalınlaşan endometrium təbəqəsi, bu hissənin rahat qanla təchiz olunmasını təmin edəcək şəkildə körpəniz üçün optimal şəraitdə bir yuva yaradır. Mayalanma baş vermədiyi və hamiləlik yaranmadığı təqdirdə isə bu təbəqə hər ay aybaşı dövründə qanaxma ilə bədəndən xaric olunur. Bu döngü hər ay eyni şəkildə davam edir. Hamiləliyin yaranması və sağlam şəkildə davam etməsi üçün uşaqlıq daxili təbəqəsinin tamamilə sağlam olması lazımdır. Bu səbəblə uşaqlığın daxili təbəqəsinin həm qalınlıq, həm də struktur olaraq həkiminiz tərəfindən qiymətləndirilməsi vacibdir.$q$),
(200, 'pregnancy_daily_content', 'e69ee309-4b20-4b3c-a0f6-c04d62440aa9', 'baby_development', 'text', $q$Ovulyasiya adlanan, yumurta hüceyrənizin yetkinləşərək mayalanmaya hazır vəziyyətə gəlməsi prosesi yaxın bir neçə gün ərzində baş tutacaq. Yumurtlama dövrü hər qadında fərqli ola bilsə də, bu barədə ümumi rəy ondan ibarətdir ki, aybaşı dövrü bitdikdən sonrakı 14-cü gün yumurtlama dövrüdür. Bu qayda aybaşı tsikli müntəzəm olan qadınlara şamil edilir. Aybaşı pozğunluğu olan qadınlarda isə yumurtlama gününü hesablamaq çox vaxt mümkün olmur.;;;
Uşaqlıq yolu ifrazatındakı selik səviyyəsini müşahidə etmək effektiv bir yoldur. Çünki yumurtlamaya yaxın qadınların axıntısında artım müşahidə olunur. Qadınlar bu vəziyyəti islanma olaraq adlandırırlar. Ovulyasiya dövrü keçdikdən sonra axıntı yenidən normal halına qayıdır. Bədən hərarətiniz də bu dövrdə bəzi dəyişikliklər nümayiş etdirir. Əvvəlcə düşən bədən hərarəti, yumurtlama zamanı qəfil yüksəlməyə başlayır.$q$, $q$Ovulyasiya adlanan, yumurta hüceyrənizin yetkinləşərək mayalanmaya hazır vəziyyətə gəlməsi prosesi yaxın bir neçə gün ərzində baş tutacaq. Yumurtlama dövrü hər qadında fərqli ola bilsə də, bu barədə ümumi rəy ondan ibarətdir ki, aybaşının ilk günündən sayılan təxminən 14-cü gün (28 günlük tsikldə) yumurtlama dövrüdür. Bu qayda aybaşı tsikli müntəzəm olan qadınlara şamil edilir. Aybaşı pozğunluğu olan qadınlarda isə yumurtlama gününü hesablamaq çox vaxt mümkün olmur.;;;
Uşaqlıq yolu ifrazatındakı selik səviyyəsini müşahidə etmək effektiv bir yoldur. Çünki yumurtlamaya yaxın qadınların axıntısında artım müşahidə olunur. Qadınlar bu vəziyyəti islanma olaraq adlandırırlar. Ovulyasiya dövrü keçdikdən sonra axıntı yenidən normal halına qayıdır. Bədən hərarətiniz də bu dövrdə bəzi dəyişikliklər nümayiş etdirir. Əvvəlcə düşən bədən hərarəti, yumurtlama zamanı qəfil yüksəlməyə başlayır.$q$),
(201, 'pregnancy_daily_content', '29e7920b-060e-4fac-ad72-d19dda159289', 'body_changes', 'text', $q$Hamiləliyin ilk həftələri, tam olaraq fərqində olmasanız belə, yumurtalıqlarınızda və uşaqlığınızda çox sürətli dəyişikliklərin baş verdiyi dövrdür. Hipofiz vəziniz və uşaqlığınızdan ifraz olunan bəzi hormonlar, bədəninizi hamiləliyə hazırlamaq üçün olduqca effektiv şəkildə çalışmağa davam edir. Yumurtalıqlarınızda isə hələ embrion dövrünüzdə yaranan yumurta hüceyrəsi rüşeymlərinizdən biri bu hormonların təsiri ilə yetkinləşməyə və mayalanmaya hazır vəziyyətə gətirilir. Yaxın bir neçə gün ərzində yetkinləşməsini tamamlayan yumurta hüceyrəniz, spermlə qarşılaşdıqda mayalana biləcək qədər inkişaf etmiş bir vəziyyətə gəlir. Yetkinləşən yumurta hüceyrəsinin ömrü, sperm hüceyrələrindən fərqli olaraq çox daha qısadır və hamiləlik istənilirsə, yumurtlama baş verdikdən sonra 48 saat ərzində mayalanma tamamlanmalıdır. Yetkinləşən yumurta hüceyrəniz yumurtalıqlarınızdan fallop borusuna passiv şəkildə ötürülür və burada sperm hüceyrələri ilə mayalanmanın baş verməsini gözləyir. Yumurta hüceyrəsinin ömrü tamamlanana qədər sperm hüceyrəsi ilə qarşılaşmasa, hamiləlik baş tutmaz. Buna qarşılıq, yumurta hüceyrəniz yetkinləşmədən sperm hüceyrələri uşaqlıq boynuna daxil olarsa, mühitin asidik quruluşuna baxmayaraq 72 saatadək canlılığını qoruya bilər.$q$, $q$Hamiləliyin ilk həftələri, tam olaraq fərqində olmasanız belə, yumurtalıqlarınızda və uşaqlığınızda çox sürətli dəyişikliklərin baş verdiyi dövrdür. Hipofiz vəziniz və yumurtalıqlarınızdan ifraz olunan bəzi hormonlar, bədəninizi hamiləliyə hazırlamaq üçün olduqca effektiv şəkildə çalışmağa davam edir. Yumurtalıqlarınızda isə hələ embrion dövrünüzdə yaranan yumurta hüceyrəsi rüşeymlərinizdən biri bu hormonların təsiri ilə yetkinləşməyə və mayalanmaya hazır vəziyyətə gətirilir. Yaxın bir neçə gün ərzində yetkinləşməsini tamamlayan yumurta hüceyrəniz, spermlə qarşılaşdıqda mayalana biləcək qədər inkişaf etmiş bir vəziyyətə gəlir. Yetkinləşən yumurta hüceyrəsinin ömrü, sperm hüceyrələrindən fərqli olaraq çox daha qısadır və hamiləlik istənilirsə, yumurtlama baş verdikdən sonra 12-24 saat ərzində mayalanma tamamlanmalıdır. Yetkinləşən yumurta hüceyrəniz yumurtalıqlarınızdan fallop borusuna passiv şəkildə ötürülür və burada sperm hüceyrələri ilə mayalanmanın baş verməsini gözləyir. Yumurta hüceyrəsinin ömrü tamamlanana qədər sperm hüceyrəsi ilə qarşılaşmasa, hamiləlik baş tutmaz. Buna qarşılıq, yumurta hüceyrəniz yetkinləşmədən sperm hüceyrələri uşaqlıq boynuna daxil olarsa, mühitin asidik quruluşuna baxmayaraq 5 günədək canlılığını qoruya bilər.$q$),
(202, 'pregnancy_daily_content', '4859f891-b414-45fe-8a1d-106b1caebec7', 'baby_development', 'text', $q$Rəhminizdə müxtəlif hormonların köməyi ilə yetkinləşən yumurta hüceyrəniz, bu gündən etibarən artıq mayalanmaya hazırdır. İnkişafını tamamlayaraq yetkinləşmiş yumurta hüceyrəniz yumurtalıqlardan sərbəst buraxıldıqdan sonra, fallop borularının ucundakı fimbriya adlanan, barmaq formalı və olduqca həssas olan bir struktur tərəfindən tutulur. Fimbriya tutduğu yetkin yumurta hüceyrəsini fallop borusunun daxilinə doğru yönəldir. Fallop borusunun etdiyi mütəmadi gərilmə və yığılma hərəkətləri sayəsində borunun içində yavaş-yavaş irəliləyən yumurta hüceyrəniz, cinsi əlaqədən sonra rəhmə daxil olan milyonlarla sperm hüceyrəsinin irəliləməsi nəticəsində mayalanmanın baş tutması üçün ən uyğun yer olan borunun orta hissəsinə daşınır. Yığılmanın baş verdiyi hissədən sonrakı hissədə yerləşən əzələlər isə yumurta hüceyrənizin irəliləməsini təmin etmək üçün boşalır. Əzələlərin təmin etdiyi bu mexaniki hərəkətlər, yumurta hüceyrənizi olması lazımi yerə çatdırana qədər davam edir.$q$, $q$Yumurtalığınızda müxtəlif hormonların köməyi ilə yetkinləşən yumurta hüceyrəniz, bu gündən etibarən artıq mayalanmaya hazırdır. İnkişafını tamamlayaraq yetkinləşmiş yumurta hüceyrəniz yumurtalıqlardan sərbəst buraxıldıqdan sonra, fallop borularının ucundakı fimbriya adlanan, barmaq formalı və olduqca həssas olan bir struktur tərəfindən tutulur. Fimbriya tutduğu yetkin yumurta hüceyrəsini fallop borusunun daxilinə doğru yönəldir. Fallop borusunun etdiyi mütəmadi gərilmə və yığılma hərəkətləri sayəsində borunun içində yavaş-yavaş irəliləyən yumurta hüceyrəniz, cinsi əlaqədən sonra rəhmə daxil olan milyonlarla sperm hüceyrəsinin irəliləməsi nəticəsində mayalanmanın baş tutması üçün ən uyğun yer olan borunun orta hissəsinə daşınır. Yığılmanın baş verdiyi hissədən sonrakı hissədə yerləşən əzələlər isə yumurta hüceyrənizin irəliləməsini təmin etmək üçün boşalır. Əzələlərin təmin etdiyi bu mexaniki hərəkətlər, yumurta hüceyrənizi olması lazımi yerə çatdırana qədər davam edir.$q$),
(203, 'pregnancy_daily_content', 'c870b9dc-4e80-4fec-9e7f-794942ed46c8', 'body_changes', 'text', $q$Aybaşı döngünüzün tam ortasına təsadüf edən bu günlərdə yumurta hüceyrəniz yetkinləşmiş, hətta sperm ilə mayalanmışdırsa, körpəniz artıq formalaşmış vəziyyətdədir. 😊 Bədəninizdə progesteron hormonu hakimiyyəti tamamilə ələ alıb. Bu hormon uşaqlıq əzələlərini rahatladır ki, embrion gəlib yerləşəndə heç bir maneə ilə qarşılaşmasın. Körpənizin formalaşması ilə bədəninizdə miqdarı sürətlə artan estrogen və progesteron hormonları döşlərinizdə dolğunluq və həssaslıq yarada bilər. Lakin bu əlamətlər eyni zamanda aybaşı döngüsünün də bir simptomu olduğundan, döşlərinizdə baş verən bu dəyişikliklər qəti hamiləlik əlaməti kimi qəbul edilməyə bilər. Körpələrin demək olar ki, hamısı 38-ci həftədə dünyaya gəlir. Buna qarşılıq, yumurta və sperm hüceyrələrinin tam olaraq nə zaman birləşdiyini və mayalanmanın hansı tarixdə baş verdiyini müəyyən etmək adətən çətindir. Bu səbəblə həkimlər körpənizin doğum vaxtını hesablamaq üçün aylıq aybaşı döngünüzün ilk günündən etibarən keçən müddəti əsas götürürlər. Bütün bu təxminlər aybaşı dövrünün uzunluğuna görə təxminən 4 həftəyədək dəyişə bilər. Bəzi qadınlar daha qısa və ya daha uzun bir aybaşı döngüsü keçirdiyi üçün doğum vaxtı və körpənizin inkişafı ultrasəs müayinəsi (USM) vasitəsilə həkiminiz tərəfindən daha dəqiq şəkildə müəyyən edilə bilər.$q$, $q$Aybaşı döngünüzün tam ortasına təsadüf edən bu günlərdə yumurta hüceyrəniz yetkinləşmiş, hətta sperm ilə mayalanmışdırsa, körpəniz artıq formalaşmış vəziyyətdədir. 😊 Bədəninizdə progesteron hormonu hakimiyyəti tamamilə ələ alıb. Bu hormon uşaqlıq əzələlərini rahatladır ki, embrion gəlib yerləşəndə heç bir maneə ilə qarşılaşmasın. Körpənizin formalaşması ilə bədəninizdə miqdarı sürətlə artan estrogen və progesteron hormonları döşlərinizdə dolğunluq və həssaslıq yarada bilər. Lakin bu əlamətlər eyni zamanda aybaşı döngüsünün də bir simptomu olduğundan, döşlərinizdə baş verən bu dəyişikliklər qəti hamiləlik əlaməti kimi qəbul edilməyə bilər. Körpələrin əksəriyyəti 37-42-ci həftələr arasında dünyaya gəlir. Buna qarşılıq, yumurta və sperm hüceyrələrinin tam olaraq nə zaman birləşdiyini və mayalanmanın hansı tarixdə baş verdiyini müəyyən etmək adətən çətindir. Bu səbəblə həkimlər körpənizin doğum vaxtını hesablamaq üçün aylıq aybaşı döngünüzün ilk günündən etibarən keçən müddəti əsas götürürlər. Bütün bu təxminlər aybaşı dövrünün uzunluğuna görə təxminən 4 həftəyədək dəyişə bilər. Bəzi qadınlar daha qısa və ya daha uzun bir aybaşı döngüsü keçirdiyi üçün doğum vaxtı və körpənizin inkişafı ultrasəs müayinəsi (USM) vasitəsilə həkiminiz tərəfindən daha dəqiq şəkildə müəyyən edilə bilər.$q$),
(204, 'pregnancy_daily_content', '5b11fc22-b976-4d28-ade3-c7ba82a43750', 'baby_development', 'text', $q$Bədəninizdə bir aybaşı dövrü ərzində yalnız 1 yumurta rüşeymi yetkinləşdirilir və mayalanmaya hazır vəziyyətə gətirilir. Lakin nadir hallarda rast gəlinsə də, bəzi vəziyyətlərdə rəhminiz birdən çox yumurta yetkinləşdirə bilər. Müxtəlif yumurta əkizləri və üçəmlərində bu hal baş verir və uşaqlıq tərəfindən yetkinləşdirilən yumurta hüceyrələrinin hamısı mayalanaraq çoxdöllü hamiləlik yarana bilər. Körpə sayının ikidən çox olduğu hallarda körpələr ayrı-ayrı yumurta hüceyrələrindən yarana bildiyi kimi, tək bir yumurta hüceyrəsindən də yarana bilərlər. Bütün əkiz hamiləliklərin üçdə ikisi müxtəlif yumurta əkizləri, üçdə biri isə eyni yumurta əkizləri şəklində ortaya çıxır. Xüsusilə ailə keçmişində çoxdöllü hamiləliklərin çox olduğu hallarda, aybaşı dövründə birdən çox yumurtanın yetkinləşməsinə daha tez-tez rast gəlinir. Müxtəlif yumurta əkizliyi ana namizədinin doğum sayı artdıqca və ya yaşı irəlilədikcə daha çox görülür. Bununla yanaşı, süni mayalanma müalicəsində yumurtlamanı təmin edən dərmanların istifadə edilməsi, bu müalicələrdə adətən birdən çox yumurta hüceyrəsinin yaranması səbəbindən müxtəlif yumurta əkizliyi ehtimalını artırır.$q$, $q$Bədəninizdə bir aybaşı dövrü ərzində yalnız 1 yumurta rüşeymi yetkinləşdirilir və mayalanmaya hazır vəziyyətə gətirilir. Lakin nadir hallarda rast gəlinsə də, bəzi vəziyyətlərdə yumurtalıqlarınız birdən çox yumurta yetkinləşdirə bilər. Müxtəlif yumurta əkizləri və üçəmlərində bu hal baş verir və yumurtalıqlar tərəfindən yetkinləşdirilən yumurta hüceyrələrinin hamısı mayalanaraq çoxdöllü hamiləlik yarana bilər. Körpə sayının ikidən çox olduğu hallarda körpələr ayrı-ayrı yumurta hüceyrələrindən yarana bildiyi kimi, tək bir yumurta hüceyrəsindən də yarana bilərlər. Bütün əkiz hamiləliklərin üçdə ikisi müxtəlif yumurta əkizləri, üçdə biri isə eyni yumurta əkizləri şəklində ortaya çıxır. Xüsusilə ailə keçmişində çoxdöllü hamiləliklərin çox olduğu hallarda, aybaşı dövründə birdən çox yumurtanın yetkinləşməsinə daha tez-tez rast gəlinir. Müxtəlif yumurta əkizliyi ana namizədinin doğum sayı artdıqca və ya yaşı irəlilədikcə daha çox görülür. Bununla yanaşı, süni mayalanma müalicəsində yumurtlamanı təmin edən dərmanların istifadə edilməsi, bu müalicələrdə adətən birdən çox yumurta hüceyrəsinin yaranması səbəbindən müxtəlif yumurta əkizliyi ehtimalını artırır.$q$),
(205, 'pregnancy_daily_content', 'cb0cb4a0-60ab-4796-9f3a-e0d285d2a27e', 'baby_development', 'text', $q$Körpənizi formalaşdıracaq hüceyrələrin yerləşdiyi kisəciyin daxili "amnion mayesi" deyilən bir maye ilə əhatə olunmuşdur. Hamiləlik kisəsinin daxilində isə sarılıq kisəsi adlanan və bu hüceyrələri əhatə edən kiçik halqaşəkilli bir struktur bəlli olmağa başlayır. Sarılıq kisəsi özünəməxsus bir maye ehtiva edir və hamiləliyin ilk həftələrində körpənizə qida daşınmasına kömək edir. Plasenta formalaşmasını tamamlayana qədər körpənizin qidalanması məhz sarılıq kisəsi sayəsində mümkün olur. Sarılıq kisəsi hamiləlik kisəsinin ultrasəs müayinəsində görünəcək səviyyəyə çatmasından qısa müddət sonra özünü büruzə verir və onun mövcudluğu kisənin daxilində körpənin olduğunun sübutudur. Həmçinin bu struktur "boş hamiləlik" adlanan, yəni kisənin daxilində körpənin olmaması vəziyyətinin müəyyən edilməsində vacib göstəricidir. Təxminən 8-9-cu həftələrdən etibarən yolk kisəsi kiçilərək təxminən 5 mm diametrində armudvari bir qalıq halına gəlir və körpənizin orta bağırsağından nazik bir sapla asılı vəziyyətdə qalır. Körpənizin inkişafının təxminən 20-ci həftəsindən etibarən isə o, tamamilə yox olur.$q$, $q$Körpənizi formalaşdıracaq hüceyrələrin yerləşdiyi kisəciyin daxili "amnion mayesi" deyilən bir maye ilə əhatə olunmuşdur. Hamiləlik kisəsinin daxilində isə sarı kisə (yumurta sarısı kisəsi) adlanan və bu hüceyrələri əhatə edən kiçik halqaşəkilli bir struktur bəlli olmağa başlayır. Sarı kisə özünəməxsus bir maye ehtiva edir və hamiləliyin ilk həftələrində körpənizə qida daşınmasına kömək edir. Plasenta formalaşmasını tamamlayana qədər körpənizin qidalanması məhz sarı kisə sayəsində mümkün olur. Sarı kisə hamiləlik kisəsinin ultrasəs müayinəsində görünəcək səviyyəyə çatmasından qısa müddət sonra özünü büruzə verir və onun mövcudluğu kisənin daxilində körpənin olduğunun sübutudur. Həmçinin bu struktur "boş hamiləlik" adlanan, yəni kisənin daxilində körpənin olmaması vəziyyətinin müəyyən edilməsində vacib göstəricidir. Təxminən 8-9-cu həftələrdən etibarən sarı kisə kiçilərək təxminən 5 mm diametrində armudvari bir qalıq halına gəlir və körpənizin orta bağırsağından nazik bir sapla asılı vəziyyətdə qalır. Körpənizin inkişafının təxminən 20-ci həftəsindən etibarən isə o, tamamilə yox olur.$q$),
(206, 'pregnancy_daily_content', 'd7e6900c-92fc-4e29-8c33-6b171bf14f64', 'body_changes', 'text', $q$Yumurtalıqlarınız hər ay ehtiyatınızda olan yumurta hüceyrəsi rüşeymlərindən birini hormonlar vasitəsilə yetkinləşdirir və mayalanmaya hazır vəziyyətə gətirir. Yetkinləşən yumurta hüceyrəniz uşaqlıq borularının daxili ilə uşaqlığın iç hissəsinə doğru irəliləyir və bu nöqtədə özünü gözləyən sperm hüceyrələri ilə qarşılaşır. Uşaqlıq boynuna buraxılan milyonlarla sperm hüceyrəsi içərisindən yalnız bir neçə mini çətin bir yolçuluğun ardından uşaqlığın daxilinə qədər uşaqlıq daxilinə çata bilir. Spermlərin yumurta hüceyrəsinə doğru getməsi, yumurta hüceyrəsinin ifraz etdiyi xüsusi bir maddə sayəsində baş verir. Bu mərhələdə isə ən kritik an yaşanır. Yumurta hüceyrəsi ilə qarşılaşan minlərlə sperm hüceyrəsi öz strukturlarında olan asidik ifrazatla yumurtanın xarici qabığında dəlik açaraq içəri girməyə çalışırlar. Lakin bu sperm hüceyrələri içərisində ən güclü olanı yumurta hüceyrəsi tərəfindən qəbul edilir və tək bir sperm hüceyrəsinin yumurtanın xarici qabığını keçməsi ilə birlikdə yumurtanız digər spermlərin içəri girməsini əngəlləyəcək şəkildə özünü bağlayır. İçəri alınan sperm hüceyrəsi isə quyruğunu baş hissəsindən ayıraraq, daxilindəki genetik materialı yumurta hüceyrəsinin nüvəsinə çatdıraraq vəzifəsini tamamlamış olur.;;;
Bu gün aybaşınızın başlamalı olduğu gündür, lakin o, başlamır. Səbəb sadədir: hamiləsiniz! Progesteron səviyyəsi düşmək əvəzinə yüksək qalır. Bədən istiliyiniz yüksəkdir. Artıq hamiləlik testləri (sidik testləri) hCG hormonunu təyin edə biləcək səviyyəyə çatıb. İki xətti görmək ehtimalınız çox yüksəkdir.$q$, $q$Yumurtalıqlarınız hər ay ehtiyatınızda olan yumurta hüceyrəsi rüşeymlərindən birini hormonlar vasitəsilə yetkinləşdirir və mayalanmaya hazır vəziyyətə gətirir. Yetkinləşən yumurta hüceyrəniz uşaqlıq borularının daxili ilə uşaqlığın iç hissəsinə doğru irəliləyir və bu nöqtədə özünü gözləyən sperm hüceyrələri ilə qarşılaşır. Uşaqlıq boynuna buraxılan milyonlarla sperm hüceyrəsi içərisindən yalnız bir neçə yüzü çətin bir yolun ardından uşaqlıq borusuna çata bilir. Spermlərin yumurta hüceyrəsinə doğru getməsi, yumurta hüceyrəsinin ifraz etdiyi xüsusi bir maddə sayəsində baş verir. Bu mərhələdə isə ən kritik an yaşanır. Yumurta hüceyrəsi ilə qarşılaşan minlərlə sperm hüceyrəsi öz strukturlarında olan asidik ifrazatla yumurtanın xarici qabığında dəlik açaraq içəri girməyə çalışırlar. Lakin bu sperm hüceyrələri içərisində ən güclü olanı yumurta hüceyrəsi tərəfindən qəbul edilir və tək bir sperm hüceyrəsinin yumurtanın xarici qabığını keçməsi ilə birlikdə yumurtanız digər spermlərin içəri girməsini əngəlləyəcək şəkildə özünü bağlayır. İçəri alınan sperm hüceyrəsi isə quyruğunu baş hissəsindən ayıraraq, daxilindəki genetik materialı yumurta hüceyrəsinin nüvəsinə çatdıraraq vəzifəsini tamamlamış olur.;;;
Bu gün aybaşınızın başlamalı olduğu gündür, lakin o, başlamır. Səbəb sadədir: hamiləsiniz! Progesteron səviyyəsi düşmək əvəzinə yüksək qalır. Bədən istiliyiniz yüksəkdir. Artıq hamiləlik testləri (sidik testləri) hCG hormonunu təyin edə biləcək səviyyəyə çatıb. İki xətti görmək ehtimalınız çox yüksəkdir.$q$),
(207, 'pregnancy_daily_content', 'aeee39a9-79a9-4e00-b2e5-3d55b7831226', 'body_changes', 'text', $q$Hamiləliyinizin bu həftəsi, körpənizin uşaqlığa tutunması ilə birlikdə yüksələn hamiləlik hormonlarınıza bağlı olaraq ürəkbulanma, yorğunluq, halsızlıq kimi erkən hamiləlik əlamətlərinin görülməyə başladığı bir dövrdür. Tez-tez istirahət etmək və qidalanma rejiminizi nəzarətdə saxlamağa diqqət yetirmək bu növ mənfi əlamətlərin verdiyi narahatlıqları azalda bilə Xüsusilə ilk hamiləliyinizi yaşayırsınızsa, emosional vəziyyətinizdə baş verən qəfil dəyişikliklər üçün edə biləcəyiniz ən yaxşı şey, mümkün qədər stresdən uzaq durmağa çalışmağınızdır. Sizə yaxşı təsir edəcək və xoşbəxt olacağınız işləri görməyi vərdiş halına gətirməli və mümkünsə gün ərzində təmiz havada qısa gəzintilər etməyə çalışmalısınız. Hamiləliyin bu mərhələsi demək olar ki, hər qadında bəzi mənfi əlamətlərlə müşayiət olunur. Bədəninizin yeni bir rejimə uyğunlaşmağa çalışdığı müddət ərzində yaşadığınız əlamətlər, hamiləliyinizin ilk trimester dövrünün sonunda, yəni 12-ci həftədən etibarən azalmağa başlayır. Bu prosesdə emosional vəziyyətinizi yaxınlarınızla bölüşməyiniz və öhdəsindən gələ bilmədiyiniz məqamlarda hamiləliyə adaptasiya olmaq üçün bir mütəxəssisdən yardım almağınız faydalı olacaqdır.$q$, $q$Hamiləliyinizin bu həftəsi, körpənizin uşaqlığa tutunması ilə birlikdə yüksələn hamiləlik hormonlarınıza bağlı olaraq ürəkbulanma, yorğunluq, halsızlıq kimi erkən hamiləlik əlamətlərinin görülməyə başladığı bir dövrdür. Tez-tez istirahət etmək və qidalanma rejiminizi nəzarətdə saxlamağa diqqət yetirmək bu növ mənfi əlamətlərin verdiyi narahatlıqları azalda bilər. Xüsusilə ilk hamiləliyinizi yaşayırsınızsa, emosional vəziyyətinizdə baş verən qəfil dəyişikliklər üçün edə biləcəyiniz ən yaxşı şey, mümkün qədər stresdən uzaq durmağa çalışmağınızdır. Sizə yaxşı təsir edəcək və xoşbəxt olacağınız işləri görməyi vərdiş halına gətirməli və mümkünsə gün ərzində təmiz havada qısa gəzintilər etməyə çalışmalısınız. Hamiləliyin bu mərhələsi demək olar ki, hər qadında bəzi mənfi əlamətlərlə müşayiət olunur. Bədəninizin yeni bir rejimə uyğunlaşmağa çalışdığı müddət ərzində yaşadığınız əlamətlər, hamiləliyinizin ilk trimester dövrünün sonunda, yəni 12-ci həftədən etibarən azalmağa başlayır. Bu prosesdə emosional vəziyyətinizi yaxınlarınızla bölüşməyiniz və öhdəsindən gələ bilmədiyiniz məqamlarda hamiləliyə adaptasiya olmaq üçün bir mütəxəssisdən yardım almağınız faydalı olacaqdır.$q$),
(208, 'pregnancy_daily_content', '6de955ee-457a-4e70-930b-f733f0792dec', 'body_changes', 'text', $q$Hamiləlik hər nə qədər möcüzəvi bir hadisə və fizioloji dəyişiklik kimi adlandırılsa da, tibbi ədəbiyyatda xəstəlik kimi qeyd olunur. Hamiləliyin tibdə xəstəlik kimi adlandırılmasının başlıca səbəbi, normaldan dəfələrlə çox böyüyən uşaqlığınızın yaratdığı mexaniki təzyiq nəticəsində bağırsaqların yerini dəyişməsi və sıxılmasıdır. Həmçinin hamiləliyin gətirdiyi, qanda olan estrogen və progesteron hormonlarının səviyyəsinin xeyli artmasına bağlı olaraq döşlərdə böyümə, üzdə və qarın divarında piqment dəyişikliyi kimi hallar da hamiləliyin xəstəlik kimi adlandırılma səbəblərindəndir. Yüksək progesteron səviyyəsi mədə və bağırsaqlarınızın boşalmasına nəzərəçarpacaq dərəcədə təsir etməyə başlayır. Həzm sisteminizdə qidaların irəliləmə sürəti hamilə olmayan bir insana nisbətən olduqca yavaşlayır. Bu səbəbdən hamiləlik dövründə qaz yaranması və qəbizliyə meyllilik başlayır. Qəbul etdiyiniz qidaların mədədə qalma müddəti hamiləlikdən əvvəlki dövrlə müqayisədə demək olar ki, iki dəfə uzanmış vəziyyətdədir. Həzmin bu qədər uzanması tez-tez gəyirmə, mədə qıcqırması və yanması problemlərinə səbəb ola bilər. Həkimlər tərəfindən tövsiyə olunan az-az və tez-tez yeməyin əhəmiyyəti də məhz bu problemlərin qarşısını almaq üçündür.$q$, $q$Hamiləlik fizioloji vəziyyətdir, lakin bədəndə ciddi dəyişikliklərə səbəb olur. Bunlardan biri, normaldan dəfələrlə çox böyüyən uşaqlığınızın yaratdığı mexaniki təzyiq nəticəsində bağırsaqların yerini dəyişməsi və sıxılmasıdır. Həmçinin hamiləliyin gətirdiyi, qanda olan estrogen və progesteron hormonlarının səviyyəsinin xeyli artmasına bağlı olaraq döşlərdə böyümə, üzdə və qarın divarında piqment dəyişikliyi kimi hallar da bu dəyişikliklərdəndir. Yüksək progesteron səviyyəsi mədə və bağırsaqlarınızın boşalmasına nəzərəçarpacaq dərəcədə təsir etməyə başlayır. Həzm sisteminizdə qidaların irəliləmə sürəti hamilə olmayan bir insana nisbətən olduqca yavaşlayır. Bu səbəbdən hamiləlik dövründə qaz yaranması və qəbizliyə meyllilik başlayır. Qəbul etdiyiniz qidaların mədədə qalma müddəti hamiləlikdən əvvəlki dövrlə müqayisədə demək olar ki, iki dəfə uzanmış vəziyyətdədir. Həzmin bu qədər uzanması tez-tez gəyirmə, mədə qıcqırması və yanması problemlərinə səbəb ola bilər. Həkimlər tərəfindən tövsiyə olunan az-az və tez-tez yeməyin əhəmiyyəti də məhz bu problemlərin qarşısını almaq üçündür.$q$),
(209, 'pregnancy_daily_content', 'b95c279c-175e-4f8c-ab41-1f4ffe11bc78', 'body_changes', 'text', $q$Körpənizin bu mərhələdə sağlam inkişafı üçün kalsium və fosfor olduqca böyük əhəmiyyət kəsb edir. D2 və D3 vitaminləri körpənizin inkişafı üçün çox vacibdir. Hamiləlikdə D vitamini adətən gündəlik 400-600 IU (10-15 mkq) səviyyəsində qəbul edilir, daha yüksək dozanı yalnız həkim təyin etməlidir. D vitamini hüceyrə bölünməsi, sümük inkişafı və immunitet sistemi üçün bədənin ehtiyac duyduğu maddələrdən biridir. Bu vitamin həkim nəzarəti altında və müəyyən analizlərdən sonra istifadə edilməlidir. Körpənizin formalaşma mərhələsində; hüceyrə və toxumaların böyüməsini təmin edən A vitamini, immunitet, sümük və diş sağlamlığı üçün D vitamini, immunitet sistemi üçün C vitamini, qanazlığı və sümük inkişafı üçün isə D vitamini hamiləliyinizin bu dövründə qəbul edilməli olan vitaminlərdir. Həkim nəzarəti altında D vitamini istifadə edərək həm öz sağlığınızı, həm də körpənizin sağlığını qorumuş olursunuz. Lakin şüursuz şəkildə D vitamini qəbul etmək körpənizə zərər verə bilər.$q$, $q$Körpənizin bu mərhələdə sağlam inkişafı üçün kalsium və fosfor olduqca böyük əhəmiyyət kəsb edir. D2 və D3 vitaminləri körpənizin inkişafı üçün çox vacibdir. Hamiləlikdə D vitamini adətən gündəlik 400-600 IU (10-15 mkq) səviyyəsində qəbul edilir, daha yüksək dozanı yalnız həkim təyin etməlidir. D vitamini hüceyrə bölünməsi, sümük inkişafı və immunitet sistemi üçün bədənin ehtiyac duyduğu maddələrdən biridir. Bu vitamin həkim nəzarəti altında və müəyyən analizlərdən sonra istifadə edilməlidir. Körpənizin formalaşma mərhələsində; hüceyrə və toxumaların böyüməsini təmin edən A vitamini, immunitet, sümük və diş sağlamlığı üçün D vitamini, immunitet sistemi üçün C vitamini, qanazlığının qarşısını almaq üçün isə dəmir və fol turşusu hamiləliyinizin bu dövründə qəbul edilməli olan vitamin və minerallardır. Həkim nəzarəti altında D vitamini istifadə edərək həm öz sağlığınızı, həm də körpənizin sağlığını qorumuş olursunuz. Lakin şüursuz şəkildə D vitamini qəbul etmək körpənizə zərər verə bilər.$q$),
(210, 'pregnancy_daily_content', '158bcd04-6d72-45a1-8559-e12705e1aa90', 'baby_development', 'text', $q$Körpənizin plasentası bu gündən etibarən formalaşmağa başlamışdır. Plasenta bədəninizdən gələn qanı süzərək körpənizə göbək cifti vasitəsilə oksigen, qlükoza və digər qida maddələrini çatdıran bir orqandır. Bu orqan həmçinin körpəniz üçün zərərli ola biləcək maddələri filtrdən keçirir, karbon qazını və tullantı məhsullarını körpənizin qanından təmizləyir. Bu səbəbdən plasenta körpənizin böyüməsi, inkişafı və həyat fəaliyyətinin davam etməsi baxımından həyati əhəmiyyət kəsb edir. Bu mərhələdə plasentanın yaranması uşaqlıqda yerləşən arteriya və venalar, onların şaxələri, körpənizin qan damarları və sarı (yolk) kisəsinin divarlarının birləşməsi ilə başlayır.;;;
Plasenta həmçinin hamiləlik zamanı prosesin davamlılığı üçün lazım olan estrogen və progesteron kimi bir sıra hormonlar istehsal edir. Bununla yanaşı, körpənizi infeksiyalardan qorumaq üçün sizin bədəninizdə dövr edən qanla körpənizin qanını bir-birindən ayrı saxlayır. Hamiləliyin sonuna doğru isə bədəninizdən plasenta vasitəsilə körpəni doğuşdan sonra qorumaq üçün antitellər keçir.$q$, $q$Körpənizin plasentası bu gündən etibarən formalaşmağa başlamışdır. Plasenta bədəninizdən gələn qanı süzərək körpənizə göbək ciyəsi (göbək bağı) vasitəsilə oksigen, qlükoza və digər qida maddələrini çatdıran bir orqandır. Bu orqan həmçinin körpəniz üçün zərərli ola biləcək maddələri filtrdən keçirir, karbon qazını və tullantı məhsullarını körpənizin qanından təmizləyir. Bu səbəbdən plasenta körpənizin böyüməsi, inkişafı və həyat fəaliyyətinin davam etməsi baxımından həyati əhəmiyyət kəsb edir. Bu mərhələdə plasentanın yaranması uşaqlıqda yerləşən arteriya və venalar, onların şaxələri, körpənizin qan damarları və sarı (yolk) kisəsinin divarlarının birləşməsi ilə başlayır.;;;
Plasenta həmçinin hamiləlik zamanı prosesin davamlılığı üçün lazım olan estrogen və progesteron kimi bir sıra hormonlar istehsal edir. Bununla yanaşı, körpənizi infeksiyalardan qorumaq üçün sizin bədəninizdə dövr edən qanla körpənizin qanını bir-birindən ayrı saxlayır. Hamiləliyin sonuna doğru isə bədəninizdən plasenta vasitəsilə körpəni doğuşdan sonra qorumaq üçün antitellər keçir.$q$),
(211, 'pregnancy_daily_content', '8a7c667d-259c-4117-9c65-d0fc403d0248', 'body_changes', 'text', $q$Hamiləliyin hər hansı bir dövründə qanaxmalar baş verə bilər. Qanın rəngi qırmızı və ya qəhvəyi ola bilər. Demək olar ki, bütün hamilələr hamiləliyin ilk həftələrində kiçik bir ləkələnmə və ya qanaxma yaşayırlar. Vaginal qanaxmalar hamiləliyin hansı dövründə görülürsə görülsün və miqdarı nə qədər olursa olsun, hər zaman həkimə müraciət edilməli olan ciddi vəziyyətlərdir. İlk 3 ayda görülən az miqdardakı qanaxmalar, adətən, düşmə təhlükəsi kimi qəbul edilir. İkinci 3 ayda görülən az miqdardakı qanaxmalar isə, adətən, uşaqlıq boynu çatışmazlığının əlamətidir və yüngül ağrı ilə müşayiət olunur. Son 3 aydakı qanaxmalar isə az miqdarda olsa belə, son dərəcə vacibdir. Bu, ciftin uşaqlığın aşağı hissəsində yerləşməsi və ya ciftin vaxtından əvvəl ayrılması kimi problemlərin əlaməti ola bilər.;;;
Hamiləlik müddətində özünüzü çox yormaqdan və ağır işlər görməkdən çəkinməlisiniz. Bu hərəkətlər uşaqlıqda yığılmalara (sancılara) səbəb olur. Uşaqlıqda yığılmaların yaranması isə qanaxmaya yol aça bilər.$q$, $q$Hamiləliyin hər hansı bir dövründə qanaxmalar baş verə bilər. Qanın rəngi qırmızı və ya qəhvəyi ola bilər. Hamilələrin təxminən dörddə biri ilk həftələrdə kiçik ləkələnmə və ya qanaxma yaşaya bilər. Vaginal qanaxmalar hamiləliyin hansı dövründə görülürsə görülsün və miqdarı nə qədər olursa olsun, hər zaman həkimə müraciət edilməli olan ciddi vəziyyətlərdir. İlk 3 ayda görülən az miqdardakı qanaxmalar, adətən, düşmə təhlükəsi kimi qəbul edilir. İkinci 3 ayda görülən az miqdardakı qanaxmalar isə, adətən, uşaqlıq boynu çatışmazlığının əlamətidir və yüngül ağrı ilə müşayiət olunur. Son 3 aydakı qanaxmalar isə az miqdarda olsa belə, son dərəcə vacibdir. Bu, ciftin uşaqlığın aşağı hissəsində yerləşməsi və ya ciftin vaxtından əvvəl ayrılması kimi problemlərin əlaməti ola bilər.;;;
Hamiləlik müddətində özünüzü çox yormaqdan və ağır işlər görməkdən çəkinməlisiniz. Bu hərəkətlər uşaqlıqda yığılmalara (sancılara) səbəb olur. Uşaqlıqda yığılmaların yaranması isə qanaxmaya yol aça bilər.$q$),
(212, 'pregnancy_daily_content', 'a614becc-2914-4d7d-98c2-e4eb413c2293', 'baby_development', 'text', $q$Bu həftədən etibarən körpənizin artıq mədəaltı vəzisi var və o, qan şəkərini tənzimləyən insulin hormonunu istehsal etməyə hazırdır. İnsulin qandakı şəkərin hüceyrələrə ötürülməsini təmin edərək hüceyrələrin enerji ehtiyacını qarşılayır. Bunun sayəsində qandakı şəkərin səviyyəsi də azalmış olur.;;;
Həzm sistemi üçün lazım olan faydalı bakteriyaları saxlayan appendisit bu həftədən etibarən formalaşmağa başladı. Körpənizin bədəni formalaşmağa başlayan bu appendisit sayəsində qızdırma, ishal, bulantı və qarın ağrısı ilə müşayiət olunan xəstəliklərə qarşı 4 qat daha dözümlü olacaq.;;;
Sürətlə inkişaf edən körpənizin süd dişi rüşeymləri və dad tumurcuqları yaranmağa başlamışdır. Körpəniz tezliklə amniotik mayeni udmağa başlayacaq və bəzi dadları bu maye vasitəsilə fərqləndirəcək.$q$, $q$Bu həftədən etibarən körpənizin artıq mədəaltı vəzisi var və o, qan şəkərini tənzimləyən insulin hormonunu istehsal etməyə hazırdır. İnsulin qandakı şəkərin hüceyrələrə ötürülməsini təmin edərək hüceyrələrin enerji ehtiyacını qarşılayır. Bunun sayəsində qandakı şəkərin səviyyəsi də azalmış olur.;;;
Həzm sistemi üçün faydalı bakteriyaları saxladığı düşünülən appendiks (soxulcanvari çıxıntı) bu həftədən formalaşmağa başlayır.;;;
Sürətlə inkişaf edən körpənizin süd dişi rüşeymləri və dad tumurcuqları yaranmağa başlamışdır. Körpəniz tezliklə amniotik mayeni udmağa başlayacaq və bəzi dadları bu maye vasitəsilə fərqləndirəcək.$q$),
(213, 'pregnancy_daily_content', '56fa6e29-fd7a-4a03-984e-0590d982556b', 'body_changes', 'text', $q$Uşaqlıq böyüdükcə çanaq sümüklərindən yuxarıya doğru qalxmağa başlayır. Bu, sidik kisəsinə olan təzyiqi bir az azalda bilər. Qarnınızın aşağı hissəsində sərtlik hiss edə bilərsiniz.;;;
Hamiləlikdə hemoqlobin göstəricilərinin yuxarı həddinin doğuş zamanı orta hesabla 11-12% səviyyələrində olduğu qəbul edilir. Bu göstəricilərdən aşağı olan hallarda əlavə dəmir dəstəyinə ehtiyac yaranır. Beynin qidası kimi tanınan dəmir, sağlam hamiləlik pəhrizinin ən vacib elementlərindən biridir və körpənizin idrak inkişafı üçün zəruridir. Sağlam qırmızı qan hüceyrələrinə sahib olmaq anemiya riskini azaldır. Bəzən dəmir çatışmazlığı kimi də adlandırılan anemiya sizi yorğun, bitkin və halsız hiss etdirir. Hamiləlikdə dəmir ehtiyacını qarşılamaq üçün qırmızı ət, ispanaq, brokoli, yaşıl mərci, qara kələm, nohud və lobya kimi qidalar qəbul etməniz faydalı olacaqdır.$q$, $q$Uşaqlıq böyüdükcə çanaq sümüklərindən yuxarıya doğru qalxmağa başlayır. Bu, sidik kisəsinə olan təzyiqi bir az azalda bilər. Qarnınızın aşağı hissəsində sərtlik hiss edə bilərsiniz.;;;
Hamiləlikdə hemoqlobinin aşağı həddi təxminən 11 q/dL qəbul edilir. Bu göstəricidən aşağı olan hallarda əlavə dəmir dəstəyinə ehtiyac yaranır. Beynin qidası kimi tanınan dəmir, sağlam hamiləlik pəhrizinin ən vacib elementlərindən biridir və körpənizin idrak inkişafı üçün zəruridir. Sağlam qırmızı qan hüceyrələrinə sahib olmaq anemiya riskini azaldır. Bəzən dəmir çatışmazlığı kimi də adlandırılan anemiya sizi yorğun, bitkin və halsız hiss etdirir. Hamiləlikdə dəmir ehtiyacını qarşılamaq üçün qırmızı ət, ispanaq, brokoli, yaşıl mərci, qara kələm, nohud və lobya kimi qidalar qəbul etməniz faydalı olacaqdır.$q$),
(214, 'pregnancy_daily_content', '2519d258-d4d3-4114-9156-6af5c1a49493', 'baby_development', 'text', $q$Körpənizin xarici qulaqları artıq son formasını alıb. Hazırda bir qədər aşağıda yerləşsələr də, körpəniz böyüdükcə onlar yuxarıya, öz əsl yerlərinə doğru qalxacaqlar. Gözlərində isə görməni təmin edən əsas optik hissələr formalaşıb; göz qapaqları artıq gözləri tamamilə örtür.;;;
Ağızda diş tumurcuqları inkişaf edir, üzdə isə ilk nazik qaş tükləri görünməyə başlayır. Bu mərhələdə körpəniz artıq "C" hərfi formasından çıxaraq, daha çox insan bədəni quruluşuna sahib olur.;;;
Bundan əlavə, göbək cifti kimi şəkillənən plasenta uzanmağa davam edir. Bu struktur ana ilə körpə arasında kritik bir rol oynayır. Onun əsas vəzifələri arasında qaz mübadiləsini təmin etmək, qidaları körpəyə gətirərkən tullantı maddələrini körpədən alıb anaya daşımaq və körpənin böyüməsində mühüm rol oynayan bəzi hormonları ifraz etmək yer alır. Plasenta həmçinin qlükoza, amin turşuları, yağ turşuları, kalsium, D vitamini və oksigeni anadan körpəyə ötürür, karbon qazı və digər tullantı maddələrini isə körpədən anaya daşıyır.$q$, $q$Körpənizin xarici qulaqları artıq son formasını alıb. Hazırda bir qədər aşağıda yerləşsələr də, körpəniz böyüdükcə onlar yuxarıya, öz əsl yerlərinə doğru qalxacaqlar. Gözlərində isə görməni təmin edən əsas optik hissələr formalaşıb; göz qapaqları artıq gözləri tamamilə örtür.;;;
Ağızda diş tumurcuqları inkişaf edir, üzdə isə ilk nazik qaş tükləri görünməyə başlayır. Bu mərhələdə körpəniz artıq "C" hərfi formasından çıxaraq, daha çox insan bədəni quruluşuna sahib olur.;;;
Bundan əlavə, plasenta və göbək ciyəsi (göbək bağı) inkişaf etməyə davam edir. Plasenta ana ilə körpə arasında kritik bir rol oynayır. Onun əsas vəzifələri arasında qaz mübadiləsini təmin etmək, qidaları körpəyə gətirərkən tullantı maddələrini körpədən alıb anaya daşımaq və körpənin böyüməsində mühüm rol oynayan bəzi hormonları ifraz etmək yer alır. Plasenta həmçinin qlükoza, amin turşuları, yağ turşuları, kalsium, D vitamini və oksigeni anadan körpəyə ötürür, karbon qazı və digər tullantı maddələrini isə körpədən anaya daşıyır.$q$),
(215, 'pregnancy_daily_content', '726669c0-162f-4b1a-a70b-ca60baf4c509', 'body_changes', 'text', $q$Hormonların tarazlaşması və ürəkbulanmalarınızın azalması ilə iştahınız artmış ola bilər. Artıq həm özünüz, həm də körpəniz üçün qidalanırsınız. Bu səbəbdən zərərli qidalardan, siqaret və alkoqollu içkilərdən uzaq durmalısınız. Lazımsız kalori ehtiva edən qidaların miqdarını tənzimləmək artıq çəki almağınıza mane olacaq. Gecə yemək yemək istəyi bir çox ana namizədində rast gəlinən bir haldır. Lakin qan şəkərini tənzimləyən leptin hormonu gecə yeyilən yeməklər səbəbindən ifraz oluna bilmir. Leptin hormonunun ifraz oluna bilməməsi sürətli şəkildə çəki almağınıza səbəb ola bilər. Bunun üçün axşam saat 9-dan etibarən su istisna olmaqla heç nə yeməmək və içməmək həm mədə sağlamlığınız, həm də çəki nəzarətiniz baxımından önəmlidir.$q$, $q$Hormonların tarazlaşması və ürəkbulanmalarınızın azalması ilə iştahınız artmış ola bilər. Artıq həm özünüz, həm də körpəniz üçün qidalanırsınız. Bu səbəbdən zərərli qidalardan, siqaret və alkoqollu içkilərdən uzaq durmalısınız. Lazımsız kalori ehtiva edən qidaların miqdarını tənzimləmək artıq çəki almağınıza mane olacaq. Gecə yemək yemək istəyi bir çox ana namizədində rast gəlinən bir haldır. Gecə acsanız, yüngül və sağlam qəlyanaltıya (qatıq, meyvə, bir ovuc qoz) üstünlük verin.$q$),
(216, 'pregnancy_daily_content', 'f769e4b1-414a-408e-8810-543b96add6b7', 'body_changes', 'text', $q$Hamiləlik dövründə arıqlamaq və pəhriz saxlamaq körpənin inkişafı baxımından tövsiyə edilmir. Lakin həddindən artıq çəki artımı da zaman-zaman körpənizə mənfi təsir göstərə bilər. Sürətlə aldığınız çəkinin qarşısını almaq və hamiləlik müddətində doğru miqdarda çəki artımını təmin etmək üçün qidalanmanıza diqqət yetirməlisiniz.;;;
Bundan əlavə, şəkər əlavə edilmiş hazır qidalardan, bərk yağlardan, qida dəyəri az olub boş kalori verən məhsulların istehlakından qaçınmaq faydalıdır. Karbohidrat qəbulunun artması və gecə yemək vərdişi də çəki artımının səbəblərindəndir. Həmçinin, hormonların təsiri ilə hamiləlik dövründə maddələr mübadiləsi yavaşlayır və hərəkətlərdə məhdudiyyət olarsa, qaçılmaz çəki artımı baş verə bilər. Gün ərzində qəfil yaranan aclıq hissi ilə mübarizə aparmaq üçün sağlam qəlyanaltılar etmək çəki artımının qarşısını ala bilər. Əgər hər hansı bir sağlamlıq probleminiz yoxdursa, hamiləlik üçün xüsusi hazırlanmış bəzi məşqləri etmək də sürətli çəki almağınızın qarşısını alacaqdır.;;;
Eyni zamanda, pasterizə edilməmiş hər növ süd və süd məhsullarından uzaq durmalısınız. Bilinənin əksinə, pasterizasiya əsrin icadı sayılır; o, südün qida dəyərinin itməsinə yol vermədən tərkibindəki zərərli mikroorqanizmlərin və ən əsası sporlu bakteriyaların sterilizasiyasını təmin edir. Çiy şəkildə aldığınız südü evdə qaynatmaq tərkibindəki xeyirli və zərərli bütün mikroorqanizmləri öldürdüyü halda, əsl zərərli olan sporlu bakteriyaların sterilizasiyasını təmin edə bilmir. Bu səbəblə çiy və ya qutu südü əvəzinə, pasterizə edilmiş gündəlik südlər istehlak etməlisiniz.$q$, $q$Hamiləlik dövründə arıqlamaq və pəhriz saxlamaq körpənin inkişafı baxımından tövsiyə edilmir. Lakin həddindən artıq çəki artımı da zaman-zaman körpənizə mənfi təsir göstərə bilər. Sürətlə aldığınız çəkinin qarşısını almaq və hamiləlik müddətində doğru miqdarda çəki artımını təmin etmək üçün qidalanmanıza diqqət yetirməlisiniz.;;;
Bundan əlavə, şəkər əlavə edilmiş hazır qidalardan, bərk yağlardan, qida dəyəri az olub boş kalori verən məhsulların istehlakından qaçınmaq faydalıdır. Karbohidrat qəbulunun artması və gecə yemək vərdişi də çəki artımının səbəblərindəndir. Həmçinin, hormonların təsiri ilə hamiləlik dövründə maddələr mübadiləsi yavaşlayır və hərəkətlərdə məhdudiyyət olarsa, qaçılmaz çəki artımı baş verə bilər. Gün ərzində qəfil yaranan aclıq hissi ilə mübarizə aparmaq üçün sağlam qəlyanaltılar etmək çəki artımının qarşısını ala bilər. Əgər hər hansı bir sağlamlıq probleminiz yoxdursa, hamiləlik üçün xüsusi hazırlanmış bəzi məşqləri etmək də sürətli çəki almağınızın qarşısını alacaqdır.;;;
Eyni zamanda, pasterizə edilməmiş hər növ süd və süd məhsullarından uzaq durmalısınız. Pasterizasiya südün qida dəyərini çox itirmədən zərərli mikroorqanizmləri (məsələn, listeriya) məhv edir. Buna görə çiy süd əvəzinə pasterizə edilmiş və ya yüksək temperaturda işlənmiş (qutu) süd istehlak etməlisiniz.$q$),
(217, 'pregnancy_daily_content', 'e16dc0a2-01a9-4a7e-990c-b0f97835b682', 'baby_development', 'text', $q$Körpənizin bədənində ən həssas üzvlərdən biri olan səs telləri artıq tam formalaşıb. Baxmayaraq ki, o, bu tellərdən ilk dəfə yalnız doğulanda (ilk ağlayışı ilə) istifadə edəcək, hazırlıqlar tamamdır. Səs telləri qırtlaqda yerləşən iki nazik pərdə kimidir. Bu pərdələr titrədikcə aralarındakı boşluq daralıb-genişlənir və səsin tonunu tənzimləyir. Boşluq dar olanda incə, geniş olanda isə qalın səslər yaranır. Doğuş anında ağciyərlərdən gələn hava bu telləri titrədir və körpənizin səsi eşidilir. Maraqlı bir fakt: qızların səs telləri daha qısa və nazik, oğlanlarınkı isə daha uzun və qalın formalaşır. Körpəniz doğulanda bu tellərin uzunluğu cəmi 6 mm olur. Bundan əlavə, körpəniz artıq barmağını əmməyə başlayıb! Bu, onun ən erkən və şirin vərdişlərindən biridir, lakin ultrasəsdə bunu görmək üçün hələ bir qədər tezdir.$q$, $q$Körpənizin skeleti indi sürətlə möhkəmlənir. Əvvəlcə yumşaq qığırdaqdan ibarət olan sümüklərdə sümükləşmə, yəni kalsiumun toplanaraq qığırdağı bərk sümük toxumasına çevirməsi prosesi gedir. Bu proses kəllə sümüklərində, qollarda və ayaqlarda xüsusilə fəaldır, lakin doğuşdan sonra da illərlə davam edəcək. Kəllə sümükləri arasındakı yumşaq nahiyələr (əmgəklər) isə açıq qalır və doğuş zamanı başın doğuş yolundan rahat keçməsinə imkan verəcək. Bundan əlavə, inkişafın ilk həftələrində yer çatışmazlığı səbəbindən müvəqqəti olaraq göbək ciyəsinin içində böyüyən bağırsaqlar artıq qarın boşluğuna qayıdıb öz yerini tutur. Böyrəklər də fəaliyyətə başlayıb: körpəniz amniotik mayeni udur və onu sidik şəklində yenidən mayeyə qaytarır. Bu dövrdə qidalanmanızda kalsium mənbələrinə (süd, qatıq, pendir, yaşıl yarpaqlı tərəvəzlər) yer vermək körpənizin sümük inkişafına dəstək olacaq.$q$),
(218, 'pregnancy_daily_content', '6a2c14a8-03ef-4ac3-8457-485f9afcbef3', 'baby_development', 'text', $q$Körpəniz artıq bir avokado böyüklüyünə çatmışdır!  Bu həftənin ən maraqlı yeniliyi körpənizin dadbilmə duyğusunun inkişafıdır.;;;
Körpənizin dilinin səthində dad tumurcuqları artıq formalaşıb. Dadbilmə mexanizmi olduqca mürəkkəb və maraqlıdır: qidalar ağızdakı tüpürcək mayesində həll olur, sonra dilin üst hissəsindəki reseptorlar bu dadı qəbul edərək beyindəki duyğu mərkəzinə ötürür.;;;
Hər bir canlı kimi, körpəniz də ətrafındakı qıcıqlara (bu halda udduğu amniotik mayenin dadına) reaksiya verməyi öyrənir. Maraqlıdır ki, dilin hər tərəfi hər dadı eyni dərəcədə güclü hiss etmir:;;;
Sizin yediyiniz qidaların dadı amniotik mayeyə keçdiyi üçün körpəniz indidən müxtəlif dadlarla tanış olur. Bu, onun gələcəkdə qida seçimlərinə belə təsir edə bilər.$q$, $q$Körpəniz artıq bir avokado böyüklüyünə çatmışdır!  Bu həftənin ən maraqlı yeniliyi körpənizin dadbilmə duyğusunun inkişafıdır.;;;
Körpənizin dilinin səthində dad tumurcuqları artıq formalaşıb. Dadbilmə mexanizmi olduqca mürəkkəb və maraqlıdır: qidalar ağızdakı tüpürcək mayesində həll olur, sonra dilin üst hissəsindəki reseptorlar bu dadı qəbul edərək beyindəki duyğu mərkəzinə ötürür.;;;
Hər bir canlı kimi, körpəniz də ətrafındakı qıcıqlara (bu halda udduğu amniotik mayenin dadına) reaksiya verməyi öyrənir.;;;
Sizin yediyiniz qidaların dadı amniotik mayeyə keçdiyi üçün körpəniz indidən müxtəlif dadlarla tanış olur. Bu, onun gələcəkdə qida seçimlərinə belə təsir edə bilər.$q$),
(219, 'pregnancy_daily_content', 'ae23805e-1ec4-470c-a370-e36eb29268eb', 'body_changes', 'text', $q$Əgər əvvəlcədən şəkər xəstəliyiniz varsa, hamiləlik dövründə daha çox diqqətli olmalısınız. Hamiləlik müddətində qanda şəkərin səviyyəsini nəzarətdə saxlamaq hamiləlikdən əvvəlki dövrlə müqayisədə daha çətin ola bilər. Həmçinin insulin dozasının dəyişdirilməsinə ehtiyac duyula bilər. Bu vəziyyətdə həkim müayinələriniz daha da tez-tez baş tutacaqdır.;;;
Şəkər xəstəliyi qanda yüksək şəkər səviyyəsinin yaranmasına səbəb olan bir xəstəlikdir. Normalda şəkər xəstəliyiniz olmasa belə, gestasion diabet olaraq adlandırılan hamiləlik şəkəri ortaya çıxa bilər. Hamiləliyin 24-28-ci həftələri arasında şəkər testi kimi tanınan qlükoza yükləmə testi vasitəsilə tarama aparılır. Nəticələr 50-75-100 qramlıq oral qlükoza testi ilə dəqiqləşdirilir və qəti diaqnoz qoyulur. Təxminən hər 150 hamiləlikdən birində hamiləliyə bağlı şəkər xəstəliyi inkişaf edə bilər. Susuzluq hissi, çəki itkisi, həddindən artıq yemək yemə ehtiyacı, normaldan daha çox su qəbulu və sidiyə çıxma, daimi yorğunluq halı kimi əlamətləriniz varsa, həkiminizlə məsləhətləşməlisiniz.$q$, $q$Əgər əvvəlcədən şəkər xəstəliyiniz varsa, hamiləlik dövründə daha çox diqqətli olmalısınız. Hamiləlik müddətində qanda şəkərin səviyyəsini nəzarətdə saxlamaq hamiləlikdən əvvəlki dövrlə müqayisədə daha çətin ola bilər. Həmçinin insulin dozasının dəyişdirilməsinə ehtiyac duyula bilər. Bu vəziyyətdə həkim müayinələriniz daha da tez-tez baş tutacaqdır.;;;
Şəkər xəstəliyi qanda yüksək şəkər səviyyəsinin yaranmasına səbəb olan bir xəstəlikdir. Normalda şəkər xəstəliyiniz olmasa belə, gestasion diabet olaraq adlandırılan hamiləlik şəkəri ortaya çıxa bilər. Hamiləliyin 24-28-ci həftələri arasında şəkər testi kimi tanınan qlükoza yükləmə testi vasitəsilə skrininq aparılır. Nəticələr 50-75-100 qramlıq oral qlükoza testi ilə dəqiqləşdirilir və qəti diaqnoz qoyulur. Hamilələrin təxminən 2-10%-ində hamiləliyə bağlı şəkər xəstəliyi inkişaf edə bilər. Susuzluq hissi, çəki itkisi, həddindən artıq yemək yemə ehtiyacı, normaldan daha çox su qəbulu və sidiyə çıxma, daimi yorğunluq halı kimi əlamətləriniz varsa, həkiminizlə məsləhətləşməlisiniz.$q$),
(220, 'pregnancy_daily_content', '5dba3d5c-bb87-4502-8385-7f27405dc9b2', 'baby_development', 'text', $q$Körpənizin diş emalı formalaşmağa başladı. Dişin emal təbəqəsi dentin, sement və diş özü kimi tanınan pulpadan ibarətdir. Emal bədəndəki ən bərk maddədir. Dişi ən xaricdən qoruyucu bir qat kimi əhatə edir.;;;
Körpənizin bu mərhələdə diş emalının tərkibinə daxil olan kalsium duzları orqanik diş maketi üzərində yavaş-yavaş çökərək toplanır və kristallaşır. Bu toplanma körpənizin dişləri çıxana qədər davam edir. Hamiləlik dövründə diş emalının formalaşması baxımından istifadə edilən bəzi dərmanlar bu prosesi ləngidə bilər. Bunun nəticəsində dişlərdə sarı, boz və ya qəhvəyi piqmentlər yarana bilər. Bəzən də hipoplaziya adlanan diş əskikliyi və ya inkişafdan qalması baş verə bilər.$q$, $q$Körpənizin diş minası formalaşmağa başladı. Diş mina, dentin, sement və pulpadan (diş özəyi) ibarətdir. Mina bədəndəki ən bərk maddədir. Dişi ən xaricdən qoruyucu bir qat kimi əhatə edir.;;;
Körpənizin bu mərhələdə diş minasının tərkibinə daxil olan kalsium duzları orqanik diş maketi üzərində yavaş-yavaş çökərək toplanır və kristallaşır. Bu toplanma körpənizin dişləri çıxana qədər davam edir. Hamiləlik dövründə diş minasının formalaşması baxımından istifadə edilən bəzi dərmanlar bu prosesi ləngidə bilər. Bunun nəticəsində dişlərdə sarı, boz və ya qəhvəyi piqmentlər yarana bilər. Bəzən də hipoplaziya adlanan diş əskikliyi və ya inkişafdan qalması baş verə bilər.$q$),
(221, 'pregnancy_daily_content', '39505edc-cdd2-40ac-b9cb-aa04fd0c51af', 'baby_development', 'text', $q$Körpənizin ürək döyüntülərini stetoskop cihazı ilə dinləmək artıq mümkündür! Həkim müayinələrində bu cihazla körpənizin ürək döyüntülərini yoxlamaq olar. Sizin və körpənizin ürək döyüntülərini bir-birindən ayırmaq olduqca asandır: körpənizin ürəyi sizinkindən təxminən 2 qat daha sürətli döyünür.;;;
Körpənizin sürətli inkişafının əsas qəhrəmanlarından biri də göbək ciftidir (umbilical cord). Bütün hamiləlik boyu o, körpəniz üçün həyati əhəmiyyət kəsb edən qida və oksigenin ötürülməsini təmin edir. Göbək ciftinin uzunluğu orta hesabla 50-55 santimetrdir və o, spiralvari bir formaya malikdir.$q$, $q$Körpənizin ürək döyüntülərini stetoskop cihazı ilə dinləmək artıq mümkündür! Həkim müayinələrində bu cihazla körpənizin ürək döyüntülərini yoxlamaq olar. Sizin və körpənizin ürək döyüntülərini bir-birindən ayırmaq olduqca asandır: körpənizin ürəyi sizinkindən təxminən 2 qat daha sürətli döyünür.;;;
Körpənizin sürətli inkişafının əsas qəhrəmanlarından biri də göbək ciyəsidir (göbək bağı). Bütün hamiləlik boyu o, körpəniz üçün həyati əhəmiyyət kəsb edən qida və oksigenin ötürülməsini təmin edir. Göbək ciyəsinin uzunluğu orta hesabla 50-55 santimetrdir və o, spiralvari bir formaya malikdir.$q$),
(222, 'pregnancy_daily_content', 'f395dae9-427a-4c8d-8ba3-bfb8922cadf2', 'baby_development', 'text', $q$Bu həftə 4 ay 3 həftəlik hamilə olduğunuz mənasına gəlir. Yəni 5-ci ayı tamamlamağınıza cəmi 1 həftə qaldı! ;;;
Hamiləlik təqibləri zamanı ən çox maraqlandığınız mövzulardan biri körpənizin inkişafı, olduğu həftədə çəkisinin və boyunun nə qədər olmasıdır. Ultrasəs müayinəsi vasitəsilə təyin olunan parametrlər qiymətləndirilərək edilən çəki və boy təxminlərinin tibbi əhəmiyyəti böyükdür; bu göstəricilər xüsusilə körpənizin çəki qazanmasını, inkişafını və doğum formasını müəyyən edir.;;;
Aşağı çəkili və ya hədsiz iri doğulan körpələr doğum zamanı və ya doğumdan sonra bəzi fəsadlar və risklərlə qarşı-karşıya qala bilərlər. Ümumdünya Səhiyyə Təşkilatının (ÜST) məlumatına görə, çəkisi 4500 qram və daha yuxarı olan körpələr təbii doğum üçün uyğun hesab edilmirlər. Azərbaycandakı təcrübədə isə bu vəziyyət sizin və həkiminizin qərarından asılı olaraq dəyişsə də, ümumilikdə 4 kq və üzəri çəkidə olan körpələr üçün keysəriyyə əməliyyatı tövsiyə olunur.$q$, $q$Bu həftə 4 ay 3 həftəlik hamilə olduğunuz mənasına gəlir. Yəni 5-ci ayı tamamlamağınıza cəmi 1 həftə qaldı! ;;;
Hamiləlik təqibləri zamanı ən çox maraqlandığınız mövzulardan biri körpənizin inkişafı, olduğu həftədə çəkisinin və boyunun nə qədər olmasıdır. Ultrasəs müayinəsi vasitəsilə təyin olunan parametrlər qiymətləndirilərək edilən çəki və boy təxminlərinin tibbi əhəmiyyəti böyükdür; bu göstəricilər xüsusilə körpənizin çəki qazanmasını, inkişafını və doğum formasını müəyyən edir.;;;
Aşağı çəkili və ya hədsiz iri doğulan körpələr doğum zamanı və ya doğumdan sonra bəzi fəsadlar və risklərlə üz-üzə qala bilərlər. İri körpələrdə (məsələn, ehtimal olunan çəki 4500-5000 qramdan çox olduqda) doğuş üsulunu həkiminiz fərdi olaraq qiymətləndirəcək.$q$),
(223, 'pregnancy_daily_content', 'da8c9afd-1f7d-4478-b2fc-5b192ee0259f', 'baby_development', 'text', $q$Körpənizin reproduktiv sistemi yetkinləşməyə və inkişaf etməyə davam edir. Əgər körpəniz oğlandırsa, onun xayaları bu günlərdə sperm istehsalına başlayacaqdır. Hələ bətndə olan körpənizin xayalarının daxilindəki borucuqlarda yerləşən sperm ana hüceyrələri 2n xromosomludur. Yəni onlar hələ yetkin sperm quruluşuna sahib deyillər; reproduktiv hüceyrə deyil, bədən hüceyrələri kimi hərəkət edirlər. Bunun səbəbi reproduktiv hüceyrələrin n xromosom, bədən hüceyrələrinin isə 2n xromosom daşımasıdır.;;;
Yeniyetməlik dövrünə çatmamış oğlanlarda sperm hüceyrələri 2n xromosomuna sahib olduqları üçün mitoz bölünmə yolu ilə çoxalırlar. Yeniyetməlik dövrünə daxil olan fərddə isə bu hüceyrələr müəyyən bir yetkinliyə çatır və meyoz bölünməyə uyğun quruluşa çevrilir. Bu sayədə onlar olması gərəkən n xromosom quruluşuna sahib olurlar.$q$, $q$Körpənizin reproduktiv sistemi yetkinləşməyə və inkişaf etməyə davam edir. Əgər körpəniz oğlandırsa, xayalarında gələcək sperm hüceyrələrinin ana hüceyrələri (spermatoqoniyalar) formalaşır; sperm istehsalı yalnız yeniyetməlikdə başlayacaq. Hələ bətndə olan körpənizin xayalarının daxilindəki borucuqlarda yerləşən sperm ana hüceyrələri 2n xromosomludur. Yəni onlar hələ yetkin sperm quruluşuna sahib deyillər; reproduktiv hüceyrə deyil, bədən hüceyrələri kimi hərəkət edirlər. Bunun səbəbi reproduktiv hüceyrələrin n xromosom, bədən hüceyrələrinin isə 2n xromosom daşımasıdır.;;;
Yeniyetməlik dövrünə çatmamış oğlanlarda sperm hüceyrələri 2n xromosomuna sahib olduqları üçün mitoz bölünmə yolu ilə çoxalırlar. Yeniyetməlik dövrünə daxil olan fərddə isə bu hüceyrələr müəyyən bir yetkinliyə çatır və meyoz bölünməyə uyğun quruluşa çevrilir. Bu sayədə onlar olması gərəkən n xromosom quruluşuna sahib olurlar.$q$),
(224, 'pregnancy_daily_content', 'a0633b87-cd3d-42be-95e2-2574a37bda58', 'baby_development', 'text', $q$Körpənizin ağciyərlərində formalaşan qan damarları sayəsində kiçik qan dövranı reallaşır. İlk olaraq sağ mədəcikdə toplanan oksigeni az, karbon qazı bol olan qan ağciyər arteriyası vasitəsilə ağciyərlərə çatdırılır. Sağ və sol ağciyərə çatan bu qan ağciyərlərdə maddələr mübadiləsi nəticəsində karbon qazını buraxıb oksigen qəbul edərək təmizlənir. Təmizlənmiş qanın ağciyər venası ilə ürəyin sol qulaqcığına gəlməsi və aorta arteriyası vasitəsilə bədənə pompalanması ilə kiçik qan dövranı tamamlanmış olur.$q$, $q$Körpənizin ağciyərlərində formalaşan qan damarları kiçik qan dövranının əsasını yaradır. İlk olaraq sağ mədəcikdə toplanan oksigeni az, karbon qazı bol olan qan ağciyər arteriyası vasitəsilə ağciyərlərə çatdırılır. Ağciyər damarları formalaşır, lakin doğuşa qədər qaz mübadiləsini plasenta həyata keçirir; ağciyərlər bu funksiyanı ilk nəfəslə öz üzərinə götürəcək. Doğuşdan sonra ağciyərlərə çatan qan karbon qazını buraxıb oksigen qəbul edərək təmizlənəcək. Təmizlənmiş qanın ağciyər venası ilə ürəyin sol qulaqcığına gəlməsi ilə kiçik qan dövranı tamamlanır; qanın aorta vasitəsilə bədənə pompalanması isə böyük qan dövranına aiddir.$q$),
(225, 'pregnancy_daily_content', '3d485358-4a99-4889-8e24-ba3824e8665d', 'body_changes', 'text', $q$Qan və sidik analizlərinizi müntəzəm olaraq etdirməyi unutmayın. Hər ay müntəzəm olaraq etdirilən qan analizləri; mümkün dəmir çatışmazlığı, əvvəllər bilinməyən və hamiləlikdə aktivləşə bilən qalxanabənzər vəzi xəstəlikləri, fərq edilməyən qan uyuşmazlıqları, toksoplazma və məxmərək kimi infeksiyalar, hepatit və gizli sidik yolu infeksiyaları kimi problemlərin qarşısını almağa kömək edir.;;;
Fərq edilməyən tiroid xəstəlikləri metabolizmanıza birbaşa təsir etdiyi üçün körpənizin inkişafına da mənfi təsir göstərir. Hamiləliyin ilk 12 həftəsi ərzində körpənizin qalxanabənzər vəzi inkişafını tamamlamadığı və buna bağlı olaraq hormon istehsal edə bilmədiyi üçün sizin istehsal etdiyiniz hormonların bir hissəsi körpəyə keçir. 12 həftədən sonra və xüsusilə hamiləliyin üçüncü trimestr dövründə plasentadan ifraz olunan bəzi hormonlar səbəbindən TSH səviyyələri müntəzəm olaraq artım göstərir.;;;
Hamiləlik müddətində rast gəlinən gizli sidik yolu infeksiyaları isə erkən dövr düşüklərinin ən çox rast gəlinən səbəblərindən biridir. Bu səbəbdən müntəzəm olaraq tam sidik analizinin verilməsi mütləqdir.$q$, $q$Qan və sidik analizlərinizi müntəzəm olaraq etdirməyi unutmayın. Hər ay müntəzəm olaraq etdirilən qan analizləri; mümkün dəmir çatışmazlığı, əvvəllər bilinməyən və hamiləlikdə aktivləşə bilən qalxanabənzər vəzi xəstəlikləri, fərq edilməyən qan uyuşmazlıqları, toksoplazma və məxmərək kimi infeksiyalar, hepatit və gizli sidik yolu infeksiyaları kimi problemlərin qarşısını almağa kömək edir.;;;
Fərq edilməyən tiroid xəstəlikləri metabolizmanıza birbaşa təsir etdiyi üçün körpənizin inkişafına da mənfi təsir göstərir. Hamiləliyin ilk 12 həftəsi ərzində körpənizin qalxanabənzər vəzi inkişafını tamamlamadığı və buna bağlı olaraq hormon istehsal edə bilmədiyi üçün sizin istehsal etdiyiniz hormonların bir hissəsi körpəyə keçir. 12 həftədən sonra və xüsusilə hamiləliyin üçüncü trimestr dövründə plasentadan ifraz olunan bəzi hormonlar səbəbindən TSH səviyyələri müntəzəm olaraq artım göstərir.;;;
Hamiləlik müddətində rast gəlinən gizli sidik yolu infeksiyaları isə müalicə olunmadıqda böyrək iltihabına və vaxtından əvvəl doğuşa səbəb ola bilər. Bu səbəbdən müntəzəm olaraq tam sidik analizinin verilməsi mütləqdir.$q$),
(226, 'pregnancy_daily_content', '45b37fad-6e16-4ec4-9e5c-d3eea98a5a6d', 'baby_development', 'text', $q$Körpənizin bütün hamiləlik müddəti ərzində ən aktiv olduğu 27 və 32-ci həftələr arasına daxil oldunuz. Bundan əlavə, bu həftələr artıq körpənizin müntəzəm olaraq hərəkət edəcəyi dövrdür. Bu o deməkdir ki, onun oyaq olduğu hər saat üçün ən azı 10 hərəkət hiss etməlisiniz. Körpənizin ən aktiv olduğu saatlar amniotik mayenin hərəkət etmədiyi gecə saatlarıdır. Gün ərzində sizin hərəkətləriniz nəticəsində amniotik maye dalğalanır, bu isə körpənizin yatmasını təmin edir. Yəni körpəniz artıq yuxularınızı qaçıra bilər. 😊;;;
Bu mərhələdə körpənizin hərəkətlərini olduqca güclü və çox sayda hiss etmənizin ən böyük səbəbi, onun ölçü olaraq kifayət qədər böyüməsi və daxilində bu hərəkətlərə imkan verəcək qədər amniotik mayeyə sahib olmasıdır.;;;
Həftələr irəlilədikcə körpəniz udduğu amniotik maye miqdarından daha azını sidik yolu ilə amnion kisəsinə boşaldır. Bunun nəticəsində isə daxilində olduğu mayenin miqdarı yavaş-yavaş azalmağa başlayır. Maye həcminin azalması, körpəniz böyüdükcə daha çox yerə ehtiyac duyacağı üçün baş verməsi zəruri olan bir haldır.$q$, $q$Körpənizin bütün hamiləlik müddəti ərzində ən aktiv olduğu 27 və 32-ci həftələr arasına daxil oldunuz. Bundan əlavə, bu həftələr artıq körpənizin müntəzəm olaraq hərəkət edəcəyi dövrdür. Adətən 2 saat ərzində 10 hərəkət hiss etmək normal hesab olunur; hərəkətlər azalarsa dərhal həkiminizlə əlaqə saxlayın. Körpənizin ən aktiv olduğu saatlar amniotik mayenin hərəkət etmədiyi gecə saatlarıdır. Gün ərzində sizin hərəkətləriniz nəticəsində amniotik maye dalğalanır, bu isə körpənizin yatmasını təmin edir. Yəni körpəniz artıq yuxularınızı qaçıra bilər. 😊;;;
Bu mərhələdə körpənizin hərəkətlərini olduqca güclü və çox sayda hiss etmənizin ən böyük səbəbi, onun ölçü olaraq kifayət qədər böyüməsi və daxilində bu hərəkətlərə imkan verəcək qədər amniotik mayeyə sahib olmasıdır.;;;
Həftələr irəlilədikcə körpəniz udduğu amniotik maye miqdarından daha azını sidik yolu ilə amnion kisəsinə boşaldır. Bunun nəticəsində isə daxilində olduğu mayenin miqdarı yavaş-yavaş azalmağa başlayır. Maye həcminin azalması, körpəniz böyüdükcə daha çox yerə ehtiyac duyacağı üçün baş verməsi zəruri olan bir haldır.$q$),
(227, 'pregnancy_daily_content', 'd388c035-3ae4-451c-bcce-e8ae700cd74b', 'daily_tip', 'text', $q$Bel ağrısı üçün "Kedi-İnək" (Cat-Cow) yoqa hərəkətini yoxlayın (dörd ayaq üstündə durub beli bükmək və açmaq). Bu, onurğadakı təzyiqi azaldır və körpənin daha rahat pozisiyaya keçməsinə kömək edir.$q$, $q$Bel ağrısı üçün "Pişik-İnək" (Cat-Cow) yoqa hərəkətini yoxlayın (dörd ayaq üstündə durub beli bükmək və açmaq). Bu, onurğadakı təzyiqi azaldır və körpənin daha rahat pozisiyaya keçməsinə kömək edir.$q$),
(228, 'pregnancy_daily_content', '124477a3-06f6-44dd-a276-41487168c5e0', 'body_changes', 'text', $q$Hamiləlik dövrünüz boyunca bədəninizdə olduğu kimi beyin biokimyanızda da mühüm dəyişikliklər meydana gəlir. Bu dəyişikliklərlə bağlı olaraq, xüsusilə həssas birisinizsə, depressiyaya meyllilik göstərə bilərsiniz. Depressiya halı adətən doğuşdan sonra artsa da, bəzən hamiləlik dövrlərində də ilk əlamətlərini verməyə başlaya bilər. Özünüzü daim əsəbi, dəyərsiz və günahkar hiss etməniz, iştah və qidalanma pozğunluqlarınız, müalicəyə cavab verməyən ağrılarınız, sizi normalda xoşbəxt edən şeylərin artıq zövq verməməsi, maraq duyduğunuz hadisələrə marağınızın azalması, ciddi yuxu pozğunluqları, diqqət yetirmə və fokuslanmada çətinlik çəkməniz kimi hallar depressiya əlamətləridir. Bu dövrdə yoldaşınızdan və ailə üzvlərinizdən dəstək almağınız, yaxşı olan şeylərə köklənməyiniz və zihninizi sizi üzən məsələlərlə məşğul etməməyiniz lazımdır.$q$, $q$Hamiləlik dövrünüz boyunca bədəninizdə olduğu kimi beyin biokimyanızda da mühüm dəyişikliklər meydana gəlir. Bu dəyişikliklərlə bağlı olaraq, xüsusilə həssas birisinizsə, depressiyaya meyllilik göstərə bilərsiniz. Depressiya halı adətən doğuşdan sonra artsa da, bəzən hamiləlik dövrlərində də ilk əlamətlərini verməyə başlaya bilər. Özünüzü daim əsəbi, dəyərsiz və günahkar hiss etməniz, iştah və qidalanma pozğunluqlarınız, müalicəyə cavab verməyən ağrılarınız, sizi normalda xoşbəxt edən şeylərin artıq zövq verməməsi, maraq duyduğunuz hadisələrə marağınızın azalması, ciddi yuxu pozğunluqları, diqqət yetirmə və fokuslanmada çətinlik çəkməniz kimi hallar depressiya əlamətləridir. Bu dövrdə yoldaşınızdan və ailə üzvlərinizdən dəstək almağınız, yaxşı olan şeylərə köklənməyiniz və zehninizi sizi üzən məsələlərlə məşğul etməməyiniz lazımdır. Bu əlamətlər iki həftədən çox davam edirsə, mütləq həkiminizlə və ya psixoloqla danışın; depressiya müalicə olunan bir vəziyyətdir.$q$),
(229, 'pregnancy_daily_content', '98a97832-2773-43d8-bf72-e6458dfbc947', 'body_changes', 'text', $q$Əgər qeysəriyyə əməliyyatını zəruri edən bir hal yoxdursa, doğum formanız hələ dəqiq bəlli deyil. Son trimestr dövrünə daxil olmağınızla birlikdə, doğum şəkli haqqında düşünməyə başlamalısınız. Doğum növləri; təbii doğum, qeysəriyyə, epidural doğum və suda doğum şəklindədir.;;;
Normal doğum olaraq adlandırılan vaginal doğumda proses olduqca uzundur. Vaginal doğumun baş tutması üçün uşaqlıq boynunun 10 sm açılması lazımdır. İlk 4 sm-lik hissə passiv faza adlanır və uşaqlıq boynu 4 sm açılana qədər hətta 2 həftəlik bir vaxt tələb oluna bilər. 4 sm-dən 10 sm-ə qədər olan müddət isə orta hesabla 4 saatla 12 saat arasında dəyişə bilər və bu müddətin sonunda uşaqlıq boynu tam açılmış olur.;;;
Körpənin tərs vəziyyətdə olması, həddindən artıq iri olması, başının kanala yerləşməməsi, ürək döyüntüsü pozğunluqları və plasentanın uşaqlıq boynunu bağlaması kimi körpədən qaynaqlanan hallar, həmçinin HPV virusu, hamiləlik zəhərlənməsi, həddindən artıq çəki və çanaq sümüyü darlığı kimi sizdən qaynaqlanan vəziyyətlər varsa, normal doğum baş tutmur və məcburi qeysəriyyə əməliyyatı həyata keçirilir.$q$, $q$Əgər qeysəriyyə əməliyyatını zəruri edən bir hal yoxdursa, doğum formanız hələ dəqiq bəlli deyil. Son trimestr dövrünə daxil olmağınızla birlikdə, doğum şəkli haqqında düşünməyə başlamalısınız. Doğum növləri; təbii doğum, qeysəriyyə, epidural doğum və suda doğum şəklindədir.;;;
Normal doğum olaraq adlandırılan vaginal doğumda proses olduqca uzundur. Vaginal doğumun baş tutması üçün uşaqlıq boynunun 10 sm açılması lazımdır. İlk 4 sm-lik hissə passiv faza adlanır və uşaqlıq boynu 4 sm açılana qədər hətta 2 həftəlik bir vaxt tələb oluna bilər. 4 sm-dən 10 sm-ə qədər olan müddət isə orta hesabla 4 saatla 12 saat arasında dəyişə bilər və bu müddətin sonunda uşaqlıq boynu tam açılmış olur.;;;
Körpənin tərs vəziyyətdə olması, həddindən artıq iri olması, başının kanala yerləşməməsi, ürək döyüntüsü pozğunluqları və plasentanın uşaqlıq boynunu bağlaması kimi körpədən qaynaqlanan hallarda, həmçinin aktiv genital herpes, çanaq sümüyü darlığı kimi sizdən qaynaqlanan vəziyyətlərdə həkiminiz qeysəriyyə əməliyyatını tövsiyə edə bilər.$q$),
(230, 'pregnancy_daily_content', '2a9f34ac-1247-4ead-b172-d62294531480', 'body_changes', 'text', $q$Çoxdöllü hamiləliklərlə bağlı ən böyük problemlər vaxtından əvvəl doğuşlardır. Körpə sayı artdıqca hamiləlik həftəsinin müddəti və hər bir körpənin doğum çəkisi azalır. Əkizlər üçün orta hamiləlik müddəti təxminən 37 həftə olduğu halda, üçüzlər üçün bu müddət 35 həftədir. Körpələrin uşaqlıqda qaldığı hər həftə orqanların və sistemlərin yetkinləşməsi ilə yanaşı, doğum çəkiləri də artır. Çoxdöllü hamiləliklərdə məqsəd, vaxtından əvvəl doğuşdan qaçınmaq üçün hamiləliyi mümkün qədər davam etdirməkdir. Bunun ən yaxşı yolu yataq rejimidir. Bütün hamiləlik boyunca müntəzəm fəaliyyətlərə davam etmək mümkün olmaya bilər. Həkimin yataq rejimi tövsiyəsinə əməl etmək lazım gələ bilər.$q$, $q$Çoxdöllü hamiləliklərlə bağlı ən böyük problemlər vaxtından əvvəl doğuşlardır. Körpə sayı artdıqca hamiləlik həftəsinin müddəti və hər bir körpənin doğum çəkisi azalır. Əkizlər üçün orta hamiləlik müddəti təxminən 37 həftə olduğu halda, üçəmlər üçün bu müddət 35 həftədir. Körpələrin uşaqlıqda qaldığı hər həftə orqanların və sistemlərin yetkinləşməsi ilə yanaşı, doğum çəkiləri də artır. Çoxdöllü hamiləliklərdə məqsəd, vaxtından əvvəl doğuşdan qaçınmaq üçün hamiləliyi mümkün qədər davam etdirməkdir. Rutin yataq rejiminin vaxtından əvvəl doğuşun qarşısını aldığı sübut olunmayıb; fəaliyyət səviyyənizi həkiminizlə müəyyənləşdirin.$q$),
(231, 'pregnancy_daily_content', '195a150b-6bd1-4a69-9196-35f5d6e3f9f4', 'baby_development', 'text', $q$Hər keçən gün körpənizin beynində milyardlarla neyron yaranmağa davam edir. Bu mərhələdə cəmi neyronların sayı bir neçə trilyona çatmış vəziyyətdədir. Körpənizin bədənində olan cəmi 100 trilyon civarında hüceyrənin təxminən 7%-ni sinir sistemi təşkil edir. Bu vəziyyət informasiya ötürülməsinin həyati əhəmiyyət kəsb etdiyinin göstəricisidir. Sinir hüceyrələri vəzifələrinə görə; duyğu sinirləri, motor sinirlər və ara sinirlər olmaqla 3 başlıq altında araşdırılır. Duyğu sinirləri, duyğu reseptorlarından aldığı qıcıqları beyin, onurğa beyni kimi mərkəzi sinir sistemi orqanlarına ötürən sinirlərdir. Motor sinirlər, mərkəzi sinir sistemindən aldığı əmrləri əzələlərə və ya vəzilərə ötürən sinirlərdir. Ara sinirlər isə mərkəzi sinir sistemində yerləşərək motor və duyğu sinirləri arasındakı əlaqəni təmin edən sinirlərdir.$q$, $q$Hər keçən gün körpənizin beynində milyardlarla neyron yaranmağa davam edir. Bu mərhələdə beyində təxminən 100 milyard neyron formalaşmış olur. Bu, informasiya ötürülməsinin həyati əhəmiyyət kəsb etdiyinin göstəricisidir. Sinir hüceyrələri vəzifələrinə görə; duyğu sinirləri, motor sinirlər və ara sinirlər olmaqla 3 başlıq altında araşdırılır. Duyğu sinirləri, duyğu reseptorlarından aldığı qıcıqları beyin, onurğa beyni kimi mərkəzi sinir sistemi orqanlarına ötürən sinirlərdir. Motor sinirlər, mərkəzi sinir sistemindən aldığı əmrləri əzələlərə və ya vəzilərə ötürən sinirlərdir. Ara sinirlər isə mərkəzi sinir sistemində yerləşərək motor və duyğu sinirləri arasındakı əlaqəni təmin edən sinirlərdir.$q$),
(232, 'pregnancy_daily_content', '1dccc97f-570f-4f2a-ba96-d46cdb785a71', 'body_changes', 'text', $q$Hamiləliyinizin sonuna yaxınlaşdığınız bu həftələrdə, doğumun başladığını anlamaq üçün bilməli olduğunuz bəzi məlumatlar vardır. Doğum nişanı, doğumdan 1 ay əvvəl bədəndən atıla biləcəyi kimi, doğumdan bir neçə saat əvvəl də gələ bilər. Doğumdan qısa müddət əvvəl gələn amniotik maye isə digər bir doğum əlamətidir. Bu maye su kimi axıcı və çox açıq sarı rəngdə ola bilər. Amniotik maye çox ani bir şəkildə gəlir və bu baş verdikdə dərhal xəstəxanaya getmək ən doğrusudur. Mayenin boşalması ilə körpəniz mikroblara qarşı müdafiəsiz qala bilər.;;;
Amniotik mayenin boşalması nəticəsində ən geci 48 saat ərzində doğumun baş tutması lazımdır. Daha uzun müddət keçərsə, körpənizin infeksiyaya yoluxması qaçınılmazdır.$q$, $q$Hamiləliyinizin sonuna yaxınlaşdığınız bu həftələrdə, doğumun başladığını anlamaq üçün bilməli olduğunuz bəzi məlumatlar vardır. Doğum nişanı, doğumdan 1 ay əvvəl bədəndən atıla biləcəyi kimi, doğumdan bir neçə saat əvvəl də gələ bilər. Doğumdan qısa müddət əvvəl gələn amniotik maye isə digər bir doğum əlamətidir. Bu maye su kimi axıcı və çox açıq sarı rəngdə ola bilər. Amniotik maye çox ani bir şəkildə gəlir və bu baş verdikdə dərhal xəstəxanaya getmək ən doğrusudur. Mayenin boşalması ilə körpəniz mikroblara qarşı müdafiəsiz qala bilər.;;;
Su gələrsə dərhal xəstəxanaya müraciət edin; zaman keçdikcə infeksiya riski artır, ona görə də həkim vəziyyəti qiymətləndirib lazımi tədbiri görəcək.$q$),
(233, 'pregnancy_daily_content', 'c04052f3-92f1-4783-8ceb-a4f9489af352', 'baby_development', 'text', $q$Hamiləliyinizdə 30 həftəlik müddəti geridə qoydunuz. Körpənizin bədənində sürətli bir sümükləşmə prosesi nəticəsində skelet sistemi olduqca inkişaf etmiş bir hala gəlmişdir. Kəllə sümükləri isə hələ bu sümükləşmə prosesinə daxil olmamışdır. Bu vəziyyət körpənizin doğum kanalından rahat bir şəkildə keçə bilməsini təmin edir.;;;
Əmgək, körpənizin kəllə sümükləri sümükləşməmişdən əvvəl sümüklərin birləşmə yerlərində olan qığırdağın adıdır. Kəllə nahiyəsində 6 ədəd əmgək bulunur və doğuma yaxın müddət ərzində bu əmgəklərin 5-i bağlanmış olur. Körpəniz dünyaya gəldikdən sonra isə yalnız başın ön tərəfində yerləşən əmgək qalır. Körpənizin başındakı əmgək nahiyəsi birləşdirici toxumadan ibarətdir. Bu quruluş sümüklərin üst-üstə düşməsi ilə kəlləyə elastiklik qazandıraraq başın doğum kanalına girə bilməsini, beləliklə doğuşun reallaşmasını təmin edir. Doğuşdan sonra da beynin böyüməsi kəllənin böyüməsi ilə mümkün olur. Kəllənin bu elastik quruluşu sayəsində körpənizin beyin böyüməsinin təxminən 75%-i həyatının ilk 2 ilində baş verir.$q$, $q$Hamiləliyinizdə 30 həftəlik müddəti geridə qoydunuz. Körpənizin bədənində sürətli bir sümükləşmə prosesi nəticəsində skelet sistemi olduqca inkişaf etmiş bir hala gəlmişdir. Kəllə sümükləri isə hələ bu sümükləşmə prosesinə daxil olmamışdır. Bu vəziyyət körpənizin doğum kanalından rahat bir şəkildə keçə bilməsini təmin edir.;;;
Əmgək, körpənizin kəllə sümükləri sümükləşməmişdən əvvəl sümüklərin birləşmə yerlərində olan birləşdirici toxuma qişasının adıdır. Kəllə nahiyəsində 6 ədəd əmgək olur. Doğuş zamanı kəllədə əsasən iki əmgək açıq olur: arxa əmgək ilk 1-2 ayda, ön əmgək isə 12-18 ayda bağlanır. Körpənizin başındakı əmgək nahiyəsi birləşdirici toxumadan ibarətdir. Bu quruluş sümüklərin üst-üstə düşməsi ilə kəlləyə elastiklik qazandıraraq başın doğum kanalına girə bilməsini, beləliklə doğuşun reallaşmasını təmin edir. Doğuşdan sonra da beynin böyüməsi kəllənin böyüməsi ilə mümkün olur. Kəllənin bu elastik quruluşu sayəsində körpənizin beyin böyüməsinin təxminən 75%-i həyatının ilk 2 ilində baş verir.$q$),
(234, 'pregnancy_daily_content', '676af173-b90a-4c64-a591-ff651fa5a3ea', 'body_changes', 'text', $q$Hamiləlik dövründə xurma istehlakının bir çox faydası var. Xurma zülal, kalium, maqnezium, manqan, dəmir, mis və B1, B2, B3, A1, C vitaminləri ilə olduqca zəngin bir meyvədir. Tərkibində lif dərəcəsinin yüksək olması sayəsində toxluq hissi yaradır və həzm sistemini nizamlamaqda çox uğurludur. Xurma müxtəlif antioksidantlar ehtiva edir və faydalı bir təbii karbohidrat anbarıdır. Həmçinin tox tutur, qan şəkərini tənzimləyir və beləliklə, hamiləlik dövründə çəki nəzarətində faydalı olur. Tərkibindəki fol turşusu sayəsində hamiləlik dövrü boyunca körpənizin sağlam inkişafına töhfə verir. Xurmanın tərkibində oksitosin adlı maddə mövcuddur. Oksitosin uşaqlıq boynunun kənar müdaxilələrə ehtiyac qalmadan asanlıqla açılmasına kömək edir. Buna görə də xurmanın normal doğuşu asanlaşdıran ən mühüm qidalardan biri olduğu düşünülür.;;;
Bu mövzuda hələ ki qəti bir araşdırma olmasa da, tərkibindəki oksitosin səbəbindən uşaqlıq boynunu vaxtından əvvəl aça bilmə ehtimalına görə hamiləlik dövründə həddindən artıq miqdarda xurma yeməkdən çəkinmək lazımdır.$q$, $q$Hamiləlik dövründə xurma istehlakının bir çox faydası var. Xurma zülal, kalium, maqnezium, manqan, dəmir, mis və B1, B2, B3, A1, C vitaminləri ilə olduqca zəngin bir meyvədir. Tərkibində lif dərəcəsinin yüksək olması sayəsində toxluq hissi yaradır və həzm sistemini nizamlamaqda çox uğurludur. Xurma müxtəlif antioksidantlar ehtiva edir və faydalı bir təbii karbohidrat anbarıdır. Həmçinin tox tutur, qan şəkərini tənzimləyir və beləliklə, hamiləlik dövründə çəki nəzarətində faydalı olur. Tərkibindəki fol turşusu sayəsində hamiləlik dövrü boyunca körpənizin sağlam inkişafına töhfə verir. Bəzi tədqiqatlara görə xurma uşaqlıq boynunun yetişməsinə müsbət təsir göstərə bilər, lakin bu hələ qəti sübut olunmayıb.;;;
Xurma kalorili və şəkərli olduğu üçün hamiləlik dövründə onu həddindən artıq miqdarda yeməkdən çəkinmək lazımdır.$q$),
(235, 'pregnancy_daily_content', '805cdfb6-2608-4845-b4aa-f6272786a6f0', 'baby_development', 'text', $q$Körpənizin başında, saçlı dəri hissəsində doğum qabarığı adlanan bir şişkinlik yarana bilər. Buna formalaşma prosesi deyilir. Molding körpənizin doğuş gedişatı zamanı başının formasında və müəyyən dərəcədə həcmində müvəqqəti dəyişiklik olması vəziyyətidir. Doğuş anında körpənizin baş hissəsinin doğum kanalından keçə bilməsi üçün kanalın forma və həcminə uyğunlaşaraq biçimlənməsi lazımdır. Körpənizin başı doğum kanalından keçərkən başını önə əymə, daxilə döndərmə, arxaya atma və xaricə çevirmə kimi hərəkətlər edir. Bu proses əsnasında körpənizin kəlləsindəki sümüklər, bu sümüklərin arasında olan elastik qığırdaq toxuması sayəsində bir-birinə yaxınlaşır və bir-birinin üzərinə minir. Doğum kanalında keçən bu müddətdə yumşaq toxumaların sürətlə forma alması nəticəsində baş nahiyəsində bəzi müvəqqəti əyriliklər görünə bilər. Yenidoğulmuş körpələrin kəllə sümüyündəki forma pozğunluqlarının yaranma səbəblərindən bəziləri körpənin ana bətnindəki duruş pozisiyasından, doğuşun uzun və çətin olmasından, körpənin küvezdə qalmasından və ya boyun əzələlərindəki qısalıqlardan qaynaqlana bilər.$q$, $q$Körpənizin başında, saçlı dəri hissəsində doğum qabarığı adlanan bir şişkinlik yarana bilər. Bundan əlavə, kəllə sümüklərinin doğuş zamanı müvəqqəti forma dəyişməsinə "kəllənin formalaşması" (molding) deyilir. Bu, körpənizin doğuş gedişatı zamanı başının formasında və müəyyən dərəcədə həcmində müvəqqəti dəyişiklik olması vəziyyətidir. Doğuş anında körpənizin baş hissəsinin doğum kanalından keçə bilməsi üçün kanalın forma və həcminə uyğunlaşaraq biçimlənməsi lazımdır. Körpənizin başı doğum kanalından keçərkən başını önə əymə, daxilə döndərmə, arxaya atma və xaricə çevirmə kimi hərəkətlər edir. Bu proses əsnasında körpənizin kəlləsindəki sümüklər, bu sümüklərin arasında olan elastik qığırdaq toxuması sayəsində bir-birinə yaxınlaşır və bir-birinin üzərinə minir. Doğum kanalında keçən bu müddətdə yumşaq toxumaların sürətlə forma alması nəticəsində baş nahiyəsində bəzi müvəqqəti əyriliklər görünə bilər. Yenidoğulmuş körpələrin kəllə sümüyündəki forma pozğunluqlarının yaranma səbəblərindən bəziləri körpənin ana bətnindəki duruş pozisiyasından, doğuşun uzun və çətin olmasından, körpənin küvezdə qalmasından və ya boyun əzələlərindəki qısalıqlardan qaynaqlana bilər.$q$),
(236, 'pregnancy_daily_content', 'fc626924-530b-4871-85a2-84474a5bcec0', 'baby_development', 'text', $q$3-cü trimester dövründə körpənizin beyni inkişafına sürətlə davam etsə də, başın böyümə sürəti bədənin digər hissələrinin böyümə sürətinə nisbətən daha yavaşdır. Körpənizin beyin formalaşması ana bətnində 3-cü həftədə başlayır. Sinir sistemi körpənin ana bətnindəki inkişaf müddəti boyunca ən erkən ortaya çıxan və doğuşdan sonra da inkişafı ən gec tamamlanan sistemdir. Bu həftədən etibarən neyronların formalaşması tamamlanır. Neyronlar geridə qalan 9 həftə ərzində növlərə ayrılmış və sayca dəfələrlə artmışdı. 32-ci həftədə beyindəki ən xarici təbəqənin, yəni korteksin alt hissələrinə köç etməyə başlayırlar. Məhz bu prosesdə beynin və sinir sisteminin ümumi ana xətləri tamamlanmış olur. Doğuş vaxtı gəldikdə isə beyin artıq demək olar ki, son halını almışdır və demək olar ki, dəyişmir.$q$, $q$3-cü trimester dövründə körpənizin beyni inkişafına sürətlə davam etsə də, başın böyümə sürəti bədənin digər hissələrinin böyümə sürətinə nisbətən daha yavaşdır. Körpənizin beyin formalaşması ana bətnində 3-cü həftədə başlayır. Sinir sistemi körpənin ana bətnindəki inkişaf müddəti boyunca ən erkən ortaya çıxan və doğuşdan sonra da inkişafı ən gec tamamlanan sistemdir. Bu həftədən etibarən neyronların formalaşması tamamlanır. Neyronlar geridə qalan 9 həftə ərzində növlərə ayrılmış və sayca dəfələrlə artmışdı. 32-ci həftədə beyindəki ən xarici təbəqənin, yəni korteksin alt hissələrinə köç etməyə başlayırlar. Məhz bu prosesdə beynin və sinir sisteminin ümumi ana xətləri tamamlanmış olur. Doğuş vaxtı beynin əsas strukturu formalaşmış olur, lakin beyin həyatın ilk illərində sürətlə böyüməyə və yeni əlaqələr qurmağa davam edir.$q$),
(237, 'pregnancy_daily_content', 'b016d6e4-baac-45d0-93bb-1a801a1ac462', 'baby_development', 'text', $q$Amnion mayesi körpənin daxilində olduğu steril, rəngsiz və qoruyucu bir mayedir. Qismən uşaqlıq daxilindəki "amnion hüceyrələri" tərəfindən yaradılsa da, əsas mənbəyini anadan alır. Bu maye uşaqlıq daxilində körpənizin rahat hərəkət etməsini təmin edərkən, eyni zamanda onu zərbələrdən, infeksiyalardan və temperatur dəyişikliklərindən qoruyur. Hamiləlik müddətində temperaturunu 37 dərəcədə sabit saxlayan amnion mayesi körpənizin qışda soyuqdan, yayda isə istidən təsirlənməsinin qarşısını alır. 2-ci trimester dövründə amnion mayesi körpənin çəkisinə paralel olaraq artım göstərir. 32-ci həftədə isə bu maye 1 litrə çatmış olur ki, bu da amnion mayesinin çatdığı ən yüksək miqdardır. Körpənin daha çox çəki almasını təmin etmək üçün amnion mayesi bu həftədən etibarən doğuma qədər təxminən 150-250 ml azalır və orta hesabla 750-800 ml səviyyəsində sabitləşir.$q$, $q$Amnion mayesi körpənin daxilində olduğu steril, rəngsiz və qoruyucu bir mayedir. Hamiləliyin ilk həftələrində əsasən ana bədənindən gələn maye hesabına yaranır, ikinci trimestrdən etibarən isə amnion mayesinin əsas mənbəyi körpənizin sidiyi və ağciyər mayesidir. Bu maye uşaqlıq daxilində körpənizin rahat hərəkət etməsini təmin edərkən, eyni zamanda onu zərbələrdən, infeksiyalardan və temperatur dəyişikliklərindən qoruyur. Hamiləlik müddətində temperaturunu 37 dərəcədə sabit saxlayan amnion mayesi körpənizin qışda soyuqdan, yayda isə istidən təsirlənməsinin qarşısını alır. 2-ci trimester dövründə amnion mayesi körpənin çəkisinə paralel olaraq artım göstərir. 32-ci həftədə isə bu maye 1 litrə çatmış olur ki, bu da amnion mayesinin çatdığı ən yüksək miqdardır. Körpənin daha çox çəki almasını təmin etmək üçün amnion mayesi bu həftədən etibarən doğuma qədər təxminən 150-250 ml azalır və orta hesabla 750-800 ml səviyyəsində sabitləşir.$q$),
(238, 'pregnancy_daily_content', '2bbb9ba5-0677-4713-8d4c-c7c237ab84f6', 'baby_development', 'text', $q$Körpəniz bu həftə etibarilə doğuş pozisiyasını almış ola bilər. Körpələr ümumiyyətlə 32-ci həftəyə daxil olduqdan sonra artıq doğuş üçün lazım olan pozisiyanı almağa başlayırlar. Bu müddət orta hesabla belə olsa da, 4 həftə əvvəl və ya hətta doğuş anında belə baş verə bilər. Körpənizin doğuş pozisiyasını alması; başının aşağıda olması, omba hissəsini diafraqmanızın altına yerləşdirməsi, ayaqlarını qarnına doğru bükməsi və əllərini çarpaz şəkildə sinəsinə qoyması ilə təmin olunur. Körpənizin aldığı bu normal doğuş pozisiyasına sefalik və ya başıaşağı pozisiya adı verilir. >:P Doğuşun fizioloji cəhətdən baş tuta bilməsi üçün başın müəyyən bir şəkildə çanaq sümüyü daxilində dayanması lazımdır. Doğuş pozisiyasında körpənin ilk gələn hissəsi başının arxa tərəfində yerləşən çıxıntıdır. Bu sayədə körpənin başı sümük çatına mümkün olan ən kiçik diametrlə daxil olur.$q$, $q$Körpəniz bu həftə etibarilə doğuş pozisiyasını almış ola bilər. Körpələr ümumiyyətlə 32-ci həftəyə daxil olduqdan sonra artıq doğuş üçün lazım olan pozisiyanı almağa başlayırlar. Bu müddət orta hesabla belə olsa da, 4 həftə əvvəl və ya hətta doğuş anında belə baş verə bilər. Körpənizin doğuş pozisiyasını alması; başının aşağıda olması, omba hissəsini diafraqmanızın altına yerləşdirməsi, ayaqlarını qarnına doğru bükməsi və əllərini çarpaz şəkildə sinəsinə qoyması ilə təmin olunur. Körpənizin aldığı bu normal doğuş pozisiyasına sefalik və ya başıaşağı pozisiya adı verilir. Doğuşun fizioloji cəhətdən baş tuta bilməsi üçün başın müəyyən bir şəkildə çanaq sümüyü daxilində dayanması lazımdır. Doğuş pozisiyasında körpənin ilk gələn hissəsi başının arxa tərəfində yerləşən çıxıntıdır. Bu sayədə körpənin başı sümük çatına mümkün olan ən kiçik diametrlə daxil olur.$q$),
(239, 'pregnancy_daily_content', 'adc2549c-64e5-4fcb-ab22-00fd00f59fac', 'body_changes', 'text', $q$Hamiləlik dövründə körpənizin sümük inkişafı səbəbindən D vitamininə olan ehtiyacınız təxminən 5 dəfə artır. Xüsusilə körpənin sümük inkişafının sürətləndiyi ikinci trimester dövründə bədəninizdən körpəyə keçən kalsium miqdarı çox yüksək olur. Bu səbəbdən bədəniniz artan D vitamini ehtiyacını qarşılamaq məqsədilə bağırsaqlarda bu vitaminin sorulmasını artırır. Eyni zamanda sümüklərinizdən qana D vitamini keçidi baş verir. Bu vəziyyət hamiləlik dövrü ərzində sümüklərinizin həssaslaşmasına səbəb ola bilər.;;;
Bütün hamiləlik boyu qadınlar 5% nisbətində sümük kütləsi itkisi yaşayırlar. Bədəninizdə D vitamininin azalması nəticəsində hamiləlik şəkəri, preeklampsiya adlandırılan hamiləlik zəhərlənməsi və infeksiyalara yoluxma riskiniz arta bilər. D vitamini əlavəsi bu səbəbdən olduqca vacibdir. Takviyələrlə yanaşı, gün ərzində 15-20 dəqiqə günəş işığına məruz qalmağınız da fayda təmin edər.$q$, $q$D vitamini kalsiumun sorulması üçün vacibdir; hamiləlikdə gündəlik D vitamini əlavəsi (adətən 10 mkq/400 BV) tövsiyə oluna bilər, dozanı həkiminiz təyin edir. Xüsusilə körpənin sümük inkişafının sürətləndiyi ikinci trimester dövründə bədəninizdən körpəyə keçən kalsium miqdarı çox yüksək olur. Bu səbəbdən bədəniniz artan kalsium ehtiyacını qarşılamaq məqsədilə bağırsaqlarda kalsiumun sorulmasını artırır. Eyni zamanda sümüklərinizdən qana kalsium keçidi baş verir. Bu vəziyyət hamiləlik dövrü ərzində sümüklərinizin həssaslaşmasına səbəb ola bilər.;;;
Bütün hamiləlik boyu qadınlar 5% nisbətində sümük kütləsi itkisi yaşayırlar. Bədəninizdə D vitamininin azalması nəticəsində hamiləlik şəkəri, preeklampsiya adlandırılan hamiləlik zəhərlənməsi və infeksiyalara yoluxma riskiniz arta bilər. D vitamini əlavəsi bu səbəbdən olduqca vacibdir. Əlavələrlə yanaşı, gün ərzində 15-20 dəqiqə günəş işığına məruz qalmağınız da fayda təmin edər.$q$),
(240, 'pregnancy_daily_content', '97daa5bb-e709-4882-8a96-d104cbbdafc3', 'baby_development', 'text', $q$Körpənizin yoğun bağırsaqlarında, demək olar ki, bədən hüceyrələrinin sayı qədər həzmə kömək edəcək faydalı bakteriyalar toplanmış vəziyyətdədir.;;;
Yoğun bağırsaq həzm sisteminin son hissəsidir. Həzm olunmuş və sorulmuş qidaların qalıq hissələrini su və vitaminlərdən ayıraraq nəcisə çevirmək vəzifəsini yerinə yetirən bir orqandır. Yoğun bağırsağın ən mühüm vəzifələrindən biri də vitaminlərin sorulmasıdır. Bu sorulma yoğun bağırsaqda yaşayan bakteriyalar vasitəsilə baş verir. Yoğun bağırsaqda 700-dən çox bakteriya növü var və onların sayı milyonları ötür.$q$, $q$Körpənizin yoğun bağırsağı doğuşa hazırdır; faydalı bakteriyalar isə doğuş zamanı və ilk qidalanmalarla məskunlaşmağa başlayacaq.;;;
Yoğun bağırsaq həzm sisteminin son hissəsidir. Həzm olunmuş və sorulmuş qidaların qalıq hissələrini su və vitaminlərdən ayıraraq nəcisə çevirmək vəzifəsini yerinə yetirən bir orqandır. Yoğun bağırsağın ən mühüm vəzifələrindən biri də vitaminlərin sorulmasıdır. Bu sorulma yoğun bağırsaqda yaşayan bakteriyalar vasitəsilə baş verir. Yoğun bağırsaqda 700-dən çox bakteriya növü var və onların sayı milyonları ötür.$q$),
(241, 'pregnancy_daily_content', '5eeb8067-0b28-436d-9bac-19e1ef1b2e15', 'baby_development', 'text', $q$33-cü həftənin bitməsi etibarilə siz 7 ay 28 günlük hamiləsiniz. Körpəniz bu həftədən etibarən gündə ən az 30 qram çəki almağa başlayır. Bu çəki artımı sürətli şəkildə yağ hüceyrəsi istehsal etməsindən qaynaqlanır. Bu sayədə dərialtı yağ toxuması olduqca artan körpəniz artıq tam bir körpə görünüşü qazanmış vəziyyətdədir. Yağ səviyyəsi isə növbəti 2 həftə ərzində demək olar ki, doğuşdakı nisbətinə çatar. Bunun sayəsində dərisi olduqca hamar bir hal alar. Körpənizin dərisinin altında topladığı bu yağ hüceyrələri həm istiliyi qoruyan amil kimi çıxış edir, həm də enerji ehtiyatını təmin edir. Hamiləliyin sonuna yaxınlaşan bu həftələrdə körpənizin immunitet sistemi də güclənir. Bu güclənmə sizin bədəninizin formalaşdırdığı antitellərin plasenta və göbek kordonu vasitəsilə körpənizə keçməsi ilə baş verir. İnkişaf edən immunitet sistemi sayəsində körpəniz doğulduqda olduqca dözümlü olar və xarici dünyaya hazır olar.$q$, $q$34-cü həftənin bitməsi ilə siz təxminən 8 aylıq hamiləsiniz. Körpəniz bu həftədən etibarən gündə ən az 30 qram çəki almağa başlayır. Bu çəki artımı sürətli şəkildə yağ hüceyrəsi istehsal etməsindən qaynaqlanır. Bu sayədə dərialtı yağ toxuması olduqca artan körpəniz artıq tam bir körpə görünüşü qazanmış vəziyyətdədir. Yağ səviyyəsi isə növbəti 2 həftə ərzində demək olar ki, doğuşdakı nisbətinə çatar. Bunun sayəsində dərisi olduqca hamar bir hal alar. Körpənizin dərisinin altında topladığı bu yağ hüceyrələri həm istiliyi qoruyan amil kimi çıxış edir, həm də enerji ehtiyatını təmin edir. Hamiləliyin sonuna yaxınlaşan bu həftələrdə körpənizin immunitet sistemi də güclənir. Bu güclənmə sizin bədəninizin formalaşdırdığı antitellərin plasenta və göbək kordonu vasitəsilə körpənizə keçməsi ilə baş verir. İnkişaf edən immunitet sistemi sayəsində körpəniz doğulduqda olduqca dözümlü olar və xarici dünyaya hazır olar.$q$),
(242, 'pregnancy_daily_content', '8220cf1e-c217-46c8-aaef-257724e08389', 'baby_development', 'text', $q$Körpənizin bu mərhələdə hər kiloqramına düşən qan həcmi 80 millilitrdir və bədənində orta hesabla 250 qram qan mövcuddur. Qan hüceyrələri bədəndə sümük iliyində istehsal olunur. Sümük iliyi bəzi sümüklərin daxilində yerləşən süngərvari bir strukturdur. Sümük iliyində bəzi ixtisaslaşmış kök hüceyrələr tapılır. Bu hüceyrələr müxtəlif faktorlar vasitəsilə körpənizin bədəninin ehtiyaclarına uyğun olaraq qırmızı, ağ hüceyrələr və qan lövhəcikləri adlanan trombositlər istehsal edirlər. Körpənizin qan dövranı sistemində dövr edən qanın hemoqlobin miqdarı normaldan böyük fərqlər göstərir. Bu həftədən doğuşa qədər olan müddətdə qanındakı hemoqlobin miqdarı  q/dl civarındadır. Doğuşdan etibarən qısa bir müddət hemoqlobin miqdarında  q/dl qədər artım görülsə də, üçüncü ayına çatdıqda bu göstərici  q/dl civarına qədər azalır. Körpənizin doğulması ilə birlikdə sümük iliyində qırmızı qan hüceyrəsi istehsalında müvəqqəti fasilə yaranır. Bunun səbəbi bədəninin doğuşla birlikdə oksigen təzyiqi ilə qarşılaşmasıdır. Bu vəziyyət sümük iliyinin oksigen təzyiqinə uyğunlaşması ilə nizama düşsə də, yeni doğulmuş körpələr çox vaxt fizioloji anemia adlanan qanazlığı problemi yaşayırlar.$q$, $q$Körpənizin bu mərhələdə hər kiloqramına düşən qan həcmi 80 millilitrdir və bədənində orta hesabla 250 qram qan mövcuddur. Qan hüceyrələri bədəndə sümük iliyində istehsal olunur. Sümük iliyi bəzi sümüklərin daxilində yerləşən süngərvari bir strukturdur. Sümük iliyində bəzi ixtisaslaşmış kök hüceyrələr tapılır. Bu hüceyrələr müxtəlif faktorlar vasitəsilə körpənizin bədəninin ehtiyaclarına uyğun olaraq qırmızı, ağ hüceyrələr və qan lövhəcikləri adlanan trombositlər istehsal edirlər. Körpənizin qan dövranı sistemində dövr edən qanın hemoqlobin miqdarı normaldan böyük fərqlər göstərir. Bu həftədən doğuşa qədər olan müddətdə qanındakı hemoqlobin miqdarı təxminən 16-18 q/dl civarındadır. Doğuşdan sonra qısa bir müddət hemoqlobin miqdarında bir qədər artım görülsə də, üçüncü ayına çatdıqda bu göstərici təxminən 10-11 q/dl civarına qədər azalır. Körpənizin doğulması ilə birlikdə sümük iliyində qırmızı qan hüceyrəsi istehsalında müvəqqəti fasilə yaranır. Bunun səbəbi bədəninin doğuşla birlikdə oksigen təzyiqi ilə qarşılaşmasıdır. Bu vəziyyət sümük iliyinin oksigen təzyiqinə uyğunlaşması ilə nizama düşsə də, yeni doğulmuş körpələr çox vaxt fizioloji anemia adlanan qanazlığı problemi yaşayırlar.$q$),
(243, 'pregnancy_daily_content', '3e398e58-41a7-4c07-9c59-78972adc37be', 'body_changes', 'text', $q$Nəfəsiniz bir az açıla bilər. Körpə aşağı endiyi üçün ağciyərlər və mədə üzərindəki təzyiq azalır. Artıq daha rahat nəfəs ala və daha çox yemək yeyə bilərsiniz. Amma əvəzində qasıq nahiyəsində və sidik kisəsində təzyiq artır.;;;
Bununla yanaşı, nəfəsiniz bir az açıla bilər. Körpə aşağı endiyi üçün ağciyərlər və mədə üzərindəki təzyiq azalır. Artıq daha rahat nəfəs ala və daha çox yemək yeyə bilərsiniz. Amma əvəzində qasıq nahiyəsində və sidik kisəsində təzyiq artır.$q$, $q$Nəfəsiniz bir az açıla bilər. Körpə aşağı endiyi üçün ağciyərlər və mədə üzərindəki təzyiq azalır. Artıq daha rahat nəfəs ala və daha çox yemək yeyə bilərsiniz. Amma əvəzində qasıq nahiyəsində və sidik kisəsində təzyiq artır.$q$),
(244, 'pregnancy_daily_content', 'df4bd1af-d6a3-4228-b3e2-3e6d8392ce93', 'baby_development', 'text', $q$Körpənizin bağırsaqlarında mekonyum toplanmağa davam edir. Mekonyum, olduqca yapışqan qatılıqda, tünd yaşıl və ya qara rəngdə olan, körpənizin ilk nəcisinə verilən addır. %90-ı sudan ibarət olan bu maddənin tərkibində körpənizin dərisindən tökülən lanuqo tükləri, bağırsaq epitel hüceyrələri, selik və öd mayesi olur. Mekonyum tərkibindəki yüksək bilirubin səbəbilə yenidoğulmuş sarılığının ən mühüm səbəbidir. Doğuş anından etibarən ilk 48 saat ərzində mekonyumu anusdan xaric etməyən körpələrdə normaldan yüksək sarılıq göstəriciləri müşahidə olunur. Bilirubin bədənin normal olaraq qırmızı qan hüceyrələrini parçalaması prosesi zamanı ortaya çıxan sarı rəngli bir maddədir. Bu maddə qaraciyərdə olur və həzm zamanı bədəndən xaric edilir. Körpənizdə isə doğuş anına qədər anus qapalı qalır. Bu səbəbdən bilirubin maddəsi yoğun bağırsaqlarda mekonyumun tərkibində toplanır. Doğuşdan sonra müəyyən bir müddət ərzində bu mekonyum bədən tərəfindən atılmazsa, bağırsaqlar bilirubini soraraq qana geri qazandırır və qanda miqdarı olduqca artan bilirubin sarılığa səbəb olur.$q$, $q$Körpənizin bağırsaqlarında mekonyum toplanmağa davam edir. Mekonyum, olduqca yapışqan qatılıqda, tünd yaşıl və ya qara rəngdə olan, körpənizin ilk nəcisinə verilən addır. %90-ı sudan ibarət olan bu maddənin tərkibində körpənizin dərisindən tökülən lanuqo tükləri, bağırsaq epitel hüceyrələri, selik və öd mayesi olur. Mekonyumun gec xaric olunması tərkibindəki bilirubin səbəbilə yenidoğulmuş sarılığını artıra bilər. Doğuş anından etibarən ilk 48 saat ərzində mekonyumu anusdan xaric etməyən körpələrdə normaldan yüksək sarılıq göstəriciləri müşahidə olunur. Bilirubin bədənin normal olaraq qırmızı qan hüceyrələrini parçalaması prosesi zamanı ortaya çıxan sarı rəngli bir maddədir. Bu maddə qaraciyərdə olur və həzm zamanı bədəndən xaric edilir. Normalda körpə mekonyumu doğuşdan sonra xaric edir. Bu səbəbdən bilirubin maddəsi yoğun bağırsaqlarda mekonyumun tərkibində toplanır. Doğuşdan sonra müəyyən bir müddət ərzində bu mekonyum bədən tərəfindən atılmazsa, bağırsaqlar bilirubini soraraq qana geri qazandırır və qanda miqdarı olduqca artan bilirubin sarılığa səbəb olur.$q$),
(245, 'pregnancy_daily_content', 'e948b641-0b79-4f83-9869-a66d090c81f1', 'body_changes', 'text', $q$Hamiləlik dövrü boyu həm özünüz, həm də körpəniz üçün meyvə istehlak etməli olduğunuzu unutmayın. Bu meyvələrdən biri də kalsium, kalium, C vitamini, folik turşusu və B6 vitamini ilə zəngin olan banandır. Banan hamiləliyiniz ərzində olduqca vacib olan dəmir ehtiyacınızı qarşılamağa kömək edir. Həmçinin folik turşusu baxımından çox zəngindir. Folik turşusu körpənizin onurğa sütununun inkişafı və sinir sistemi üçün olduqca önəmlidir. Körpənizin sümükləşmə prosesində ehtiyac duyduğu kalsium da bananda kifayət qədər çoxdur. Bu səbəbdən xüsusilə körpənin sağlam sümük inkişafı üçün onu istehlak etməlisiniz. Banan, həmçinin B6 vitamini üçün yaxşı bir mənbədir. B6 vitamini sinir sisteminizdə neyromediator funksiyasını yerinə yetirir. Eyni zamanda bədəninizdəki qırmızı qan hüceyrələrinin yaranmasında təsirlidir. C vitamini ilə zəngin olan banan yaxşı bir antioksidantdır. Bu səbəbdən hüceyrələrinizdəki qocalmanı ləngidir və eyni zamanda immunitet sisteminizi gücləndirir. Bananın tərkibində bağırsaqlar üçün faydalı olan liflər var. Lakin həzm sisteminin yavaşlamasını da nəzərə alsaq, həddindən artıq istehlakı nəticəsində qəbizlik yarana bilər. Bu səbəbdən qidalanma proqramınıza gündə 2 ədəd kiçik banan əlavə etməniz kifayət edəcəkdir.$q$, $q$Hamiləlik dövrü boyu həm özünüz, həm də körpəniz üçün meyvə istehlak etməli olduğunuzu unutmayın. Bu meyvələrdən biri də kalium, C vitamini və B6 vitamini ilə zəngin olan banandır. Həmçinin müəyyən miqdarda folik turşusu ehtiva edir. Folik turşusu körpənizin onurğa sütununun inkişafı və sinir sistemi üçün olduqca önəmlidir. Banan kalium və B6 vitamini ilə zəngindir; kalsium üçün süd məhsullarına, dəmir üçün ət və paxlalılara üstünlük verin. Banan, həmçinin B6 vitamini üçün yaxşı bir mənbədir. B6 vitamini sinir sisteminizdə neyromediator funksiyasını yerinə yetirir. Eyni zamanda bədəninizdəki qırmızı qan hüceyrələrinin yaranmasında təsirlidir. C vitamini ilə zəngin olan banan yaxşı bir antioksidantdır. Bu səbəbdən hüceyrələrinizdəki qocalmanı ləngidir və eyni zamanda immunitet sisteminizi gücləndirir. Bananın tərkibində bağırsaqlar üçün faydalı olan liflər var. Lakin həzm sisteminin yavaşlamasını da nəzərə alsaq, həddindən artıq istehlakı nəticəsində qəbizlik yarana bilər. Bu səbəbdən qidalanma proqramınıza gündə 2 ədəd kiçik banan əlavə etməniz kifayət edəcəkdir.$q$),
(246, 'pregnancy_daily_content', 'cca07f51-052d-4eba-bb6f-e780658e5cc2', 'body_changes', 'text', $q$Böyük Mileston: Erkən Dönəm! Artıq doğuş hər an başlaya bilər və körpəniz "vaxtında doğulmuş" sayılır. Həkiminiz uşaqlıq boynunun vəziyyətini (açılış, yumşalma) yoxlaya bilər. Uşaqlıq boynu doğuşa hazırlıq üçün önə doğru gəlir və yumşalır.$q$, $q$Böyük mərhələ: Erkən vaxtında doğuş dövrü! Artıq doğuş hər an başlaya bilər və körpəniz "vaxtında doğulmuş" sayılır. Həkiminiz uşaqlıq boynunun vəziyyətini (açılış, yumşalma) yoxlaya bilər. Uşaqlıq boynu doğuşa hazırlıq üçün önə doğru gəlir və yumşalır.$q$),
(247, 'pregnancy_daily_content', 'f767f4b5-3cd7-4998-b9f7-8ee66f29236d', 'baby_development', 'text', $q$40 həftənin tamamlanmasına hələ vaxt olduğunu düşünə bilərsiniz, lakin unutmayın ki, hamiləliklərin təxminən 80%-i artıq 39-cu həftəyə qədər başa çatmış olur. Sağlam və normal hamiləliklərdə körpənin inkişafı tam hazır olduğu üçün doğuş 37-ci və 42-ci həftələr arasında hər an baş verə bilər. Körpəniz artıq tam yetkinləşib və ona qovuşmağınız an məsələsidir.;;;
İlk həftələrdə körpənin çəkisi cəmi 1-2 qram artdığı halda, son dövrlərdə yağ hüceyrələrinin istehsalı ilə bu sürət həftədə orta hesabla yarım kiloya qədər yüksəlir. Doğuşa bu qədər az qalmış körpənin sürətlə çəki alması onun xarici dünyaya uyğunlaşması və bədən istiliyini sərbəst şəkildə qoruya bilməsi üçün vacibdir. Bununla belə, hər körpənin çəki artımı sürətinin cinsiyyət, genetika və ətraf mühit amillərinə görə fərqli ola biləcəyini də nəzərə almaq lazımdır.$q$, $q$40 həftənin tamamlanmasına hələ vaxt olduğunu düşünə bilərsiniz, lakin unutmayın ki, doğuşların əksəriyyəti 37-42-ci həftələr arasında baş verir və təyin olunmuş gündə doğulanlar cəmi təxminən 5%-dir. Sağlam və normal hamiləliklərdə körpənin inkişafı tam hazır olduğu üçün doğuş 37-ci və 42-ci həftələr arasında hər an baş verə bilər. Körpəniz artıq tam yetkinləşib və ona qovuşmağınız an məsələsidir.;;;
İlk həftələrdə körpənin çəkisi cəmi 1-2 qram artdığı halda, son dövrlərdə yağ hüceyrələrinin istehsalı ilə bu sürət həftədə orta hesabla yarım kiloya qədər yüksəlir. Doğuşa bu qədər az qalmış körpənin sürətlə çəki alması onun xarici dünyaya uyğunlaşması və bədən istiliyini sərbəst şəkildə qoruya bilməsi üçün vacibdir. Bununla belə, hər körpənin çəki artımı sürətinin cinsiyyət, genetika və ətraf mühit amillərinə görə fərqli ola biləcəyini də nəzərə almaq lazımdır.$q$),
(248, 'pregnancy_daily_content', '37c59540-1af3-42e8-95c8-2c53b72f2a9f', 'body_changes', 'text', $q$🌿 Mən bir pırasa boydayam! Həkimlər deyir ki, 39-cu həftə doğuş üçün ən ideal vaxtdır. Beynim, ciyərlərim, qaraciyərim – hər şeyim tam hazırdır. Artıq bəhanəm yoxdur, sadəcə qapının açılmasını gözləyirəm!$q$, $q$Hamiləliyin bu son həftələrində körpə çanağa endikcə qasıq nahiyəsində təzyiq və tez-tez tualetə getmək ehtiyacı arta bilər. Braxton Hicks sancıları da daha tez-tez hiss oluna bilər. Müntəzəmləşən və güclənən sancılar, su gəlməsi, qanlı axıntı və ya körpənin hərəkətlərinin azalması halında dərhal həkiminizlə əlaqə saxlayın.$q$),
(249, 'pregnancy_daily_content', '89f0050d-f633-47d8-92b8-7c424334510d', 'baby_development', 'text', $q$Körpəniz bu həftə ilə birlikdə artıq uşaqlığınızdakı bütün həcmi tamamilə tutmuş vəziyyətdədir. Bunun nəticəsində hərəkətlərində azalma hiss etməniz olduqca normal qəbul edilən bir haldır. Sıxışmış bir mühitdə olan körpəniz uşaqlıq daxilində özünə maksimum sahə yaratmaq üçün ayaqlarını çarpaz şəkildə gövdəsinə doğru çəkir və qollarını sinəsində birləşdirir. Uşaqlıq daxilində hərəkət edə biləcəyi yer qalmadığı üçün ən kiçik tərpənişi belə bu mərhələdə canınızı ağrıda bilər. Körpəniz doğuşa hazırlaşdığı üçün başını doğum kanalına yerləşdirmişdir. Əgər bu sizin ilk hamiləliyiniz deyilsə, körpəniz başını hələ doğuş üçün lazım olan şəkildə yerləşdirməmiş ola bilər. Körpənizin doğum pozisiyası alması və doğum kanalına girməsi ilə uşaqlığın mədə və diafraqmanıza göstərdiyi təzyiq azalmışdır. Bu təzyiqin azalması ilə birlikdə mədə yanması və nəfəs alma problemləriniz xeyli yüngülləşmişdir. Lakin sidik kisəsi üzərində yaranan təzyiq heç vaxt olmadığı qədər artdığından tez-tez tualetə getmək ehtiyacı duya bilərsiniz.$q$, $q$Körpəniz bu həftə ilə birlikdə artıq uşaqlığınızdakı bütün həcmi tamamilə tutmuş vəziyyətdədir. Yer daraldığı üçün hərəkətlərin xarakteri dəyişə bilər, lakin onların sayı azalmamalıdır; azalma hiss etsəniz dərhal həkiminizlə əlaqə saxlayın. Sıxışmış bir mühitdə olan körpəniz uşaqlıq daxilində özünə maksimum sahə yaratmaq üçün ayaqlarını çarpaz şəkildə gövdəsinə doğru çəkir və qollarını sinəsində birləşdirir. Uşaqlıq daxilində hərəkət edə biləcəyi yer qalmadığı üçün ən kiçik tərpənişi belə bu mərhələdə canınızı ağrıda bilər. Körpəniz doğuşa hazırlaşdığı üçün başını doğum kanalına yerləşdirmişdir. Əgər bu sizin ilk hamiləliyiniz deyilsə, körpəniz başını hələ doğuş üçün lazım olan şəkildə yerləşdirməmiş ola bilər. Körpənizin doğum pozisiyası alması və doğum kanalına girməsi ilə uşaqlığın mədə və diafraqmanıza göstərdiyi təzyiq azalmışdır. Bu təzyiqin azalması ilə birlikdə mədə yanması və nəfəs alma problemləriniz xeyli yüngülləşmişdir. Lakin sidik kisəsi üzərində yaranan təzyiq heç vaxt olmadığı qədər artdığından tez-tez tualetə getmək ehtiyacı duya bilərsiniz.$q$),
(250, 'pregnancy_daily_content', '46262d69-53e1-4e37-8004-ee9b3e95fbbb', 'body_changes', 'text', $q$Doğuş sancıları bel və qasıq nahiyəsində hiss edilir və başlanğıcda aybaşı ağrılarına bənzəyir. Braxton Hicks adlanan yalançı sancılarla müqayisədə daha müntəzəmdir. Dincəldikdə şiddəti azalmır, irəliləyicidir, getdikcə tezliyi və gücü artaraq daha uzun çəkməyə başlayır.;;;
Xalq dilində "qarnın aşağı düşməsi" isə körpənizin çanağa yerləşdiyinin göstəricisidir. Xüsusilə ilk hamiləliyini yaşayan qadınlarda doğuşdan bir neçə həftə əvvəl bir rahatlama və yüngülləşmə hiss olunur. Körpənizin başı doğuş kanalına yerləşdikdə daha rahat nəfəs alırsınız və qabırğalarınızdakı təzyiqin azaldığını hiss edirsiniz.;;;
Körpənizin içində olduğu su kisəsinin açılması (suyun gəlməsi) halında sancıları gözləmədən həkiminizlə əlaqə saxlamalısınız. Bu vəziyyətdə körpəniz infeksiyalara qarşı müdafiəsiz qaldığı üçün nəzarət altında saxlanılmalısınız.;;;
Suyun gəlməsi artıq doğuşun başladığının dəqiq əlamətidir. Bu vəziyyəti fərq etməmək demək olar ki, qeyri-mümkündür. Bu, fasiləsiz və ya qısa aralıqlarla ayaqları isladacaq dərəcədə, nəzarət edilə bilməyən bol bir axıntıdır. Adətən bir neçə saat ərzində sancılar da başlayır.$q$, $q$Doğuş sancıları bel və qasıq nahiyəsində hiss edilir və başlanğıcda aybaşı ağrılarına bənzəyir. Braxton Hicks adlanan yalançı sancılarla müqayisədə daha müntəzəmdir. Dincəldikdə şiddəti azalmır, irəliləyicidir, getdikcə tezliyi və gücü artaraq daha uzun çəkməyə başlayır.;;;
Xalq dilində "qarnın aşağı düşməsi" isə körpənizin çanağa yerləşdiyinin göstəricisidir. Xüsusilə ilk hamiləliyini yaşayan qadınlarda doğuşdan bir neçə həftə əvvəl bir rahatlama və yüngülləşmə hiss olunur. Körpənizin başı doğuş kanalına yerləşdikdə daha rahat nəfəs alırsınız və qabırğalarınızdakı təzyiqin azaldığını hiss edirsiniz.;;;
Körpənizin içində olduğu su kisəsinin açılması (suyun gəlməsi) halında sancıları gözləmədən həkiminizlə əlaqə saxlamalısınız. Bu vəziyyətdə körpəniz infeksiyalara qarşı müdafiəsiz qaldığı üçün nəzarət altında saxlanılmalısınız.;;;
Suyun gəlməsi artıq doğuşun başladığının dəqiq əlamətidir. Su bol axın şəklində gələ bildiyi kimi, az-az sızma şəklində də ola bilər; hər iki halda həkiminizlə əlaqə saxlayın. Adətən bir neçə saat ərzində sancılar da başlayır.$q$),
(251, 'pregnancy_daily_content', '08e8895d-cc10-4825-8aac-fb6a2a6d3d95', 'body_changes', 'text', $q$Bu gün etibarilə 40 həftəlik hamiləlik müddətini tamamladınız. Vaxtınızın dolmasına baxmayaraq, doğuş hələ reallaşmayıbsa, narahat olmamalısınız. Aylarla gözləmisiniz və bəlkə də bir an əvvəl körpənizə qovuşmaq istəyirsiniz. Doğuşun niyə gecikdiyi ilə bağlı ağlınızda bəzi suallar ola bilər. 40 həftənin sonunda doğuşun baş verməməsi, yanlış hesablanmış son aybaşı tarixindən və ya gec mayalanmadan qaynaqlana bilər. Yaxud, vaxtınız düzgün hesablanmış olsa belə, heç bir səbəb olmadan doğuşunuz gecikə bilər. Təşvişə düşməməli və hələ 2 həftəlik vaxtınızın olduğunu unutmamalısınız. Sadəcə bu müddətdə yarana biləcək bəzi fəsadlara qarşı daha diqqətli olmalı, həkim müayinələrinizi tezləşdirməli və bəzi analizlərdən keçməlisiniz. Hamiləlik müddətinin dolması ilə körpəniz eyni sürətlə çəki almağa davam edəcəyi üçün təbii doğuş prosesi çətinləşə bilər. Ümumdünya Səhiyyə Təşkilatının (ÜST) məlumatlarına görə, 4500 qram olan körpələr təbii doğuş üçün hər hansı bir maneə yaratmır.$q$, $q$Bu gün etibarilə 40 həftəlik hamiləlik müddətini tamamladınız. Vaxtınızın dolmasına baxmayaraq, doğuş hələ reallaşmayıbsa, narahat olmamalısınız. Aylarla gözləmisiniz və bəlkə də bir an əvvəl körpənizə qovuşmaq istəyirsiniz. Doğuşun niyə gecikdiyi ilə bağlı ağlınızda bəzi suallar ola bilər. 40 həftənin sonunda doğuşun baş verməməsi, yanlış hesablanmış son aybaşı tarixindən və ya gec mayalanmadan qaynaqlana bilər. Yaxud, vaxtınız düzgün hesablanmış olsa belə, heç bir səbəb olmadan doğuşunuz gecikə bilər. Təşvişə düşməməli və hələ 2 həftəlik vaxtınızın olduğunu unutmamalısınız. Sadəcə bu müddətdə yarana biləcək bəzi fəsadlara qarşı daha diqqətli olmalı, həkim müayinələrinizi tezləşdirməli və bəzi analizlərdən keçməlisiniz. Hamiləlik müddətinin dolması ilə körpəniz eyni sürətlə çəki almağa davam edəcəyi üçün təbii doğuş prosesi çətinləşə bilər. Çox iri körpələrdə (4-4,5 kq-dan çox) doğuş fəsadlarının riski artır; doğuş üsulunu həkiminiz körpənin təxmini çəkisinə görə qiymətləndirəcək.$q$),
(252, 'pregnancy_daily_content', '7f952d08-70cf-40a7-af2e-4095f1619337', 'baby_development', 'text', $q$Hamiləlik dövrünün 38-ci həftəsinə qədər doğuşların təxminən %80-i baş tutmuş olur. Bu səbəbdən 42-ci həftəyə daxil olduğunuz bu günlərdə doğuş hələ reallaşmayıbsa, özünüzü olduqca gərgin hiss edə bilərsiniz. Yaxşı xəbər budur ki, gecikmiş hamiləlik dövrü adlandırılan bu mərhələdə 42-ci həftəyə qədər doğuş öz-özünə başlamazsa, həkiminizin məsləhəti ilə süni sancı və ya qeysəriyyə əməliyyatı vasitəsilə körpənizi qucağınıza ala bilərsiniz. Körpənizin hərəkətləri zaman-zaman çox ağrılı olsa da, əvvəlki həftələrlə müqayisədə hərəkət tezliyinin azaldığını hiss edə bilərsiniz. Körpəniz hər zamankından daha sıxılmış vəziyyətdədir və bu səbəbdən hərəkət edə biləcəyi geniş sahə qalmayıb. Gün ərzində onun hərəkətlərini saymalı və hərəkətlərin olması lazımdır olandan çox daha azaldığını hiss etdikdə həkiminizlə məsləhətləşməlisiniz. Amnion mayesinin bu həftələrdə xeyli azalması normal qəbul edilən bir haldır. Lakin bu maye körpənizin stressə girməsinə səbəb olacaq qədər azalarsa, həkiminiz 42-ci həftəni tamamlamadan doğuşu başladaraq müdaxilə edə bilər.$q$, $q$Doğuşların əksəriyyəti 37-42-ci həftələr arasında baş verir. Bu səbəbdən 42-ci həftəyə daxil olduğunuz bu günlərdə doğuş hələ reallaşmayıbsa, özünüzü olduqca gərgin hiss edə bilərsiniz. Yaxşı xəbər budur ki, gecikmiş hamiləlik dövrü adlandırılan bu mərhələdə 42-ci həftəyə qədər doğuş öz-özünə başlamazsa, həkiminizin məsləhəti ilə süni sancı və ya qeysəriyyə əməliyyatı vasitəsilə körpənizi qucağınıza ala bilərsiniz. Körpənizin hərəkətləri zaman-zaman ağrılı ola bilər; yer daraldığı üçün hərəkətlərin xarakteri dəyişə bilər, amma sayı azalmamalıdır. Körpəniz hər zamankından daha sıxılmış vəziyyətdədir və bu səbəbdən hərəkət edə biləcəyi geniş sahə qalmayıb. Gün ərzində onun hərəkətlərini izləyin; hərəkətlər azalarsa və ya dəyişərsə, gözləmədən dərhal həkiminizə və ya doğum evinə müraciət edin. Amnion mayesinin bu həftələrdə xeyli azalması normal qəbul edilən bir haldır. Lakin bu maye körpənizin stressə girməsinə səbəb olacaq qədər azalarsa, həkiminiz 42-ci həftəni tamamlamadan doğuşu başladaraq müdaxilə edə bilər.$q$),
(253, 'pregnancy_daily_content', 'acaaba70-7d7b-40eb-88be-941234cfb162', 'baby_development', 'text', $q$Körpənizin endokrin sistemi bədənin bütün fəaliyyətini təmin etmək və 9 aylıq qorunaqlı uşaqlıq mühitindən sonra xarici dünyaya uyğunlaşmaqda körpənizə kömək etmək üçün hazır vəziyyətdədir. Bu hormonlardan biri də karbohidrat mübadiləsində aktiv rol oynayan, bədəndə müəyyən dərəcədə stress yaradan kortizon hormonudur. Kortizon hormonu körpənizin böyüməüstü vəzisi tərəfindən sintezlənib qana qarışan steroid, yəni strukturunda yağ turşusu olan bir hormondur. Körpənizin bu hormonu istehsal etməsi gərginlik anında bədəninə kömək etməsini təmin edir. Körpənizin kortizol hormonu ilə yaratdığı stresslə qarşılaşan ürəyi, bədən əzələləri və beyni müəyyən dərəcədə güclənir. Bu sayədə körpəniz dünyaya gəldikdən sonra sağ qalmaq üçün daha az yardıma ehtiyac duyur.;;;
Xüsusilə doğuş anında ifraz olunan kortizon hormonu stressin tətiklədiyi digər bir hormon olan adrenalinin də ifraz olunmasını təmin edir. Adrenalin hormonu da körpənizdə enerji və hərəkəti ortaya çıxarır. Bu enerji körpənizin doğuş anında və xarici dünya ilə qarşılaşdığı ilk saatlarda yeni mühitinə uyğunlaşması üçün körpənizə hər cür yardımı göstərən bir amildir.$q$, $q$Körpənizin endokrin sistemi bədənin bütün fəaliyyətini təmin etmək və 9 aylıq qorunaqlı uşaqlıq mühitindən sonra xarici dünyaya uyğunlaşmaqda körpənizə kömək etmək üçün hazır vəziyyətdədir. Bu hormonlardan biri də karbohidrat mübadiləsində aktiv rol oynayan, bədəndə müəyyən dərəcədə stress yaradan kortizol hormonudur. Kortizol hormonu körpənizin böyrəküstü vəzisi tərəfindən sintezlənib qana qarışan steroid, yəni strukturunda yağ turşusu olan bir hormondur. Körpənizin bu hormonu istehsal etməsi gərginlik anında bədəninə kömək etməsini təmin edir. Körpənizin kortizol hormonu ilə yaratdığı stresslə qarşılaşan ürəyi, bədən əzələləri və beyni müəyyən dərəcədə güclənir. Bu sayədə körpəniz dünyaya gəldikdən sonra sağ qalmaq üçün daha az yardıma ehtiyac duyur.;;;
Xüsusilə doğuş anında ifraz olunan kortizol hormonu stressin tətiklədiyi digər bir hormon olan adrenalinin də ifraz olunmasını təmin edir. Adrenalin hormonu da körpənizdə enerji və hərəkəti ortaya çıxarır. Bu enerji körpənizin doğuş anında və xarici dünya ilə qarşılaşdığı ilk saatlarda yeni mühitinə uyğunlaşması üçün körpənizə hər cür yardımı göstərən bir amildir.$q$),
(254, 'pregnancy_daily_content', '67f8b3d3-cbfc-4995-af5b-fd9e49e105ef', 'body_changes', 'text', $q$42-ci həftənin tamamlanması ilə birlikdə doğuşunuz artıq baş tutmuş olmalıdır. 9 aylıq uzun və yorucu macəranın ardından körpənizə qovuşdunuz. 😊 Anacan ailəsi olaraq sizi və həyat yoldaşınızı təbrik edir, körpənizlə birlikdə uzun, sağlam və xoşbəxt bir ömür keçirməyinizi arzu edirik. Bu müddət ərzində bizə verdiyiniz dəstək üçün təşəkkürlər. Tətbiqimizin "Ana" modulunda görüşənədək!$q$, $q$42-ci həftə tamamlanır. Hələ doğmamısınızsa, həkiminizlə dərhal əlaqə saxlayın. Artıq körpənizə qovuşmusunuzsa, 9 aylıq uzun və yorucu macəranın ardından Anacan ailəsi olaraq sizi və həyat yoldaşınızı təbrik edir, körpənizlə birlikdə uzun, sağlam və xoşbəxt bir ömür keçirməyinizi arzu edirik. Bu müddət ərzində bizə verdiyiniz dəstək üçün təşəkkürlər. Doğuşdan sonra tətbiqdə "Analıq" rejiminə keçə bilərsiniz. Görüşənədək! 😊$q$),
(255, 'pregnancy_day_notifications', '1466cb19-fd27-4f75-a79c-d709e1623239', 'body', 'text', $q$Körpə artıq bətnində yerini tutur. Ölçüsü kiçik olsa da, ürəyi formalaşmağa başlayır.$q$, $q$Mayalanmış hüceyrə bölünərək uşaqlığa doğru yol alır. Bu günlərdə bədənində sakit, amma möhtəşəm bir proses gedir.$q$),
(256, 'pregnancy_day_notifications', 'ee028003-7c13-49d6-a074-6279f0809a0e', 'body', 'text', $q$Ürəyim vurmağa başladı! Bu balaca motorun səsini eşitmək üçün səbirsizlənirsən? Təqvimə ilk USM vaxtını qeyd et! 🖊️$q$, $q$Ürəyim formalaşır! Tezliklə döyünməyə başlayacaq. Bu balaca motorun səsini eşitmək üçün səbirsizlənirsən? Təqvimə ilk USM vaxtını qeyd et! 🖊️$q$),
(257, 'pregnancy_day_notifications', '55b6e494-7a56-4309-af7f-8fd6e4c2696c', 'body', 'text', $q$Sən eşitməsən də, o kiçik ürək artıq işə düşüb. Dəqiqədə 100-dən çox vurur!$q$, $q$Sən eşitməsən də, o kiçik ürək artıq formalaşır. Tezliklə ilk döyüntüləri başlayacaq!$q$),
(258, 'pregnancy_day_notifications', '75908864-8ad0-496c-8a26-f45ae3d7e742', 'body', 'text', $q$Körpənin Kalsium lazımdır! Qidalanma bölməsində süd məhsullarını yoxla. 🧀$q$, $q$Körpənə kalsium lazımdır! Qidalanma bölməsində süd məhsullarını yoxla. 🧀$q$),
(259, 'pregnancy_day_notifications', 'd77d400f-027c-4514-b287-ee1cd4aff422', 'title', 'text', $q$Qreypfrut qədər oldu! 🍊$q$, $q$Əncir boyda oldu! 🌱$q$),
(260, 'pregnancy_day_notifications', '4e185ebb-b0f4-4552-9a03-4a4c79c95d4f', 'body', 'text', $q$Körpə artıq sənin səsini və ürək döyüntünü aydın eşidir. Ona layla oxumağa başla, bu onu sakitləşdirir. 🎶$q$, $q$Körpənin qulaqları formalaşır; tezliklə səsini eşidəcək. İndidən ona danışmağa, layla oxumağa başla. 🎶$q$),
(261, 'pregnancy_day_notifications', '5b358e1c-fd56-41ad-b947-12dea0b15c36', 'body', 'text', $q$Qulaq sümükləri bərkiyir. Artıq səsinin tonunu, gülüşünü və ürək döyüntünü tanıyır.$q$, $q$Qulaq sümükləri formalaşır. Bir neçə həftədən sonra səsini eşitməyə başlayacaq.$q$),
(262, 'pregnancy_day_notifications', 'b4ebdd4a-9196-4b7e-a71f-fdfdc053ec32', 'body', 'text', $q$Çox hərəkət etmirəm? Qorxma. İndi mənə yuxu lazımdır. Böyük gün üçün enerji yığıram. Sən də dincəl! 🛌$q$, $q$Bəzən yatıram, böyük gün üçün enerji yığıram. Amma hərəkətlərim doğuşa qədər azalmamalıdır. Azalıbsa, gözləmə, dərhal həkiminə zəng et. 🛌$q$),
(263, 'pregnancy_day_notifications', '0e2e37ee-dd10-44ae-98a1-2379b737ce2b', 'body', 'text', $q$Yerim çox dardır, ona görə az tərpənirəm. Amma sən narahatsansa, Təpik Sayğacına daxil ol. Gəl birlikdə sayaq! 🦶$q$, $q$Yerim dardır, hərəkətlərim fərqli hiss oluna bilər, amma azalmamalıdır. Təpik Sayğacında birlikdə sayaq! Azaldığını hiss etsən, dərhal həkiminə zəng et. 🦶$q$),
(264, 'pregnancy_day_notifications', 'd154d2c7-ec75-47ac-ba69-4fbe92885614', 'body', 'text', $q$Doğuş yaxınlaşdıqca yuxuya getmək çətinləşə bilər. Bu, bədənin sizi körpə rejiminiə hazırlamasıdır.$q$, $q$Doğuş yaxınlaşdıqca yuxuya getmək çətinləşə bilər. Bu, bədənin səni körpə rejiminə hazırlamasıdır.$q$),
(265, 'pregnancy_day_notifications', '508da239-e1ff-41bc-b69e-7ac41310e57b', 'body', 'text', $q$Yerim yoxdur, Ana! Amma hərəkətlərimi hiss etməlisən. Şübhən varsa, şirin bir şey ye və Təpik Sayğacına gir.$q$, $q$Yerim yoxdur, Ana! Amma hərəkətlərimi hiss etməlisən. Hərəkətlərim azalıbsa, gözləmə: dərhal həkiminə və ya doğum evinə zəng et.$q$),
(266, 'weekly_tips', 'ca85a4a4-fad9-4c78-bbb5-39209ff9d8a1', 'content', 'text', $q$Təbrik edirik, son həftədəsiniz! Doğuş əlamətlərini izləyin və hazır olun.$q$, $q$Körpənizin beyni və sinir sistemi bu həftə çox sürətlə inkişaf edir. Fol turşusunu qəbul etməyə davam edin və ilk həkim müayinəsini planlaşdırın.$q$),
(267, 'weekly_tips', '4894235e-9682-404f-8851-ae713c8f879b', 'content', 'text', $q$Bu həftə embrion implantasiya olunur. Fol turşusu qəbuluna başlayın və həkiminizlə görüşün.$q$, $q$Bu həftə körpənizin ürəyi döyünməyə başlayır. Fol turşusunu qəbul etməyə davam edin və həkiminizlə görüşün.$q$),
(268, 'first_aid_steps', '23233e34-91c6-4a37-80bd-6d114859cf06', 'instruction_az', 'text', $q$Körpəni üzüstü çevirin, başı hələ də aşağıda olsun. İki barmağınızı döş sümüyünün aşağı yarısına qoyun (məmə xəttinin bir az aşağısı). 5 dəfə sürətlə basın - hər basma döşü 4 sm dərinliyə batırmalıdır. Hər basmadan sonra döşün tam qalxmasına imkan verin.$q$, $q$Körpəni arxası üstə (üzü yuxarı) çevirin, başı hələ də bir az aşağıda olsun. İki barmağınızı döş sümüyünün aşağı yarısına qoyun (məmə xəttinin bir az aşağısı). 5 dəfə sürətlə basın - hər basma döşü 4 sm dərinliyə batırmalıdır. Hər basmadan sonra döşün tam qalxmasına imkan verin.$q$),
(269, 'exercises', '4cc80a24-3b16-46a1-bc30-9e0d6283d28d', 'steps', 'json', $q$["1. Başlanğıc Vəziyyəti", "Ayaqlarınızı çiyin bərabərində (və ya bir az daha geniş) açın.", "Ayaq barmaqlarınız bir qədər yana baxa bilər (xüsusilə hamilələr üçün bu daha rahatdır).", "Belinizi dik tutun, çiyinlərinizi arxaya atın və irəli baxın.", "2. Hərəkətin İcrası", "Oturun: Çanağınızı geriyə doğru itələyərək yavaş-yavaş aşağı enin. Təsəvvür edin ki, arxanızda görünməz bir stul var və ona oturmağa çalışırsınız.", "Dizlərə diqqət: Dizləriniz ayaq barmaqlarınızın istiqamətində olmalıdır. Onların içəri doğru əyilməsinə (\"X\" forması almasına) icazə verməyin.", "Dərinlik: Budlarınız yerə paralel olana qədər enməyə çalışın. (Əgər hamiləsinizsə və ya dizinizdə problem varsa, tam paralel olmasa da olar, rahat hiss etdiyiniz yerə qədər enin).", "Qalxın: Dabanlarınızdan güc alaraq (pəncədən yox) başlanğıc vəziyyətinə qayıdın. Qalxarkən rass əzələlərini sıxın.", "3. Nəfəs Texnikası", "Enərkən: Burnunuzla dərindən nəfəs alın.", "Qalxarkən: Ağzınızla nəfəs verin."]$q$, $q$["1. Başlanğıc Vəziyyəti", "Ayaqlarınızı çiyin bərabərində (və ya bir az daha geniş) açın.", "Ayaq barmaqlarınız bir qədər yana baxa bilər (xüsusilə hamilələr üçün bu daha rahatdır).", "Belinizi dik tutun, çiyinlərinizi arxaya atın və irəli baxın.", "2. Hərəkətin İcrası", "Oturun: Çanağınızı geriyə doğru itələyərək yavaş-yavaş aşağı enin. Təsəvvür edin ki, arxanızda görünməz bir stul var və ona oturmağa çalışırsınız.", "Dizlərə diqqət: Dizləriniz ayaq barmaqlarınızın istiqamətində olmalıdır. Onların içəri doğru əyilməsinə (\"X\" forması almasına) icazə verməyin.", "Dərinlik: Budlarınız yerə paralel olana qədər enməyə çalışın. (Əgər hamiləsinizsə və ya dizinizdə problem varsa, tam paralel olmasa da olar, rahat hiss etdiyiniz yerə qədər enin).", "Qalxın: Dabanlarınızdan güc alaraq (pəncədən yox) başlanğıc vəziyyətinə qayıdın. Qalxarkən sağrı əzələlərinizi sıxın.", "3. Nəfəs Texnikası", "Enərkən: Burnunuzla dərindən nəfəs alın.", "Qalxarkən: Ağzınızla nəfəs verin."]$q$),
