(282, 'epds_questions', 'd51a6901-6595-4091-afb1-5ec4059046c2', 'options', 'json', $q$[{"text": "Yes, most of the time I haven't been able to cope at all", "value": 3, "text_ar": "نعم، في معظم الأوقات لم أكن قادرة على التأقلم إطلاقًا", "text_az": "Bəli, çox vaxt heç bacarmırdım", "text_de": "Ja, meistens kam ich überhaupt nicht zurecht", "text_kk": "Иә, көбінесе мүлде жеңе алмадым", "text_ru": "Да, большую часть времени совсем не удавалось справляться", "text_tr": "Evet, çoğu zaman hiç başa çıkamıyordum"}, {"text": "Yes, sometimes I haven't been coping as well as usual", "value": 2, "text_ar": "نعم، أحيانًا لم أكن قادرة على التأقلم كعادتي", "text_az": "Bəli, bəzən həmişəki kimi bacarırdım", "text_de": "Ja, manchmal kam ich nicht so gut zurecht wie sonst", "text_kk": "Иә, кейде әдеттегідей жеңе алдым", "text_ru": "Да, иногда удавалось справляться как обычно", "text_tr": "Evet, bazen her zamanki gibi başa çıkabiliyordum"}, {"text": "No, most of the time I have coped quite well", "value": 1, "text_ar": "لا، كنت قادرة على التأقلم جيدًا معظم الوقت", "text_az": "Xeyr, çox vaxt yaxşı bacarırdım", "text_de": "Nein, meistens kam ich recht gut zurecht", "text_kk": "Жоқ, көбінесе жақсы жеңе алдым", "text_ru": "Нет, большую часть времени удавалось справляться довольно хорошо", "text_tr": "Hayır, çoğu zaman iyi başa çıkabiliyordum"}, {"text": "No, I have been coping as well as ever", "value": 0, "text_ar": "لا، كنت قادرة على التأقلم كعادتي دائمًا", "text_az": "Xeyr, həmişəki kimi bacarırdım", "text_de": "Nein, ich kam so gut zurecht wie immer", "text_kk": "Жоқ, әдеттегідей жеңе алдым", "text_ru": "Нет, удавалось справляться как обычно", "text_tr": "Hayır, her zamanki gibi başa çıkabiliyordum"}]$q$, $q$[{"text": "Yes, most of the time I haven't been able to cope at all", "value": 3, "text_ar": "نعم، في معظم الأوقات لم أكن قادرة على التأقلم إطلاقًا", "text_az": "Bəli, çox vaxt heç bacarmırdım", "text_de": "Ja, meistens kam ich überhaupt nicht zurecht", "text_kk": "Иә, көбінесе мүлде жеңе алмадым", "text_ru": "Да, большую часть времени совсем не удавалось справляться", "text_tr": "Evet, çoğu zaman hiç başa çıkamıyordum"}, {"text": "Yes, sometimes I haven't been coping as well as usual", "value": 2, "text_ar": "نعم، أحيانًا لم أكن قادرة على التأقلم كعادتي", "text_az": "Bəli, bəzən həmişəki kimi bacara bilmirdim", "text_de": "Ja, manchmal kam ich nicht so gut zurecht wie sonst", "text_kk": "Иә, кейде әдеттегідей жеңе алмадым", "text_ru": "Да, иногда я справлялась хуже, чем обычно", "text_tr": "Evet, bazen her zamanki gibi başa çıkamıyordum"}, {"text": "No, most of the time I have coped quite well", "value": 1, "text_ar": "لا، كنت قادرة على التأقلم جيدًا معظم الوقت", "text_az": "Xeyr, çox vaxt yaxşı bacarırdım", "text_de": "Nein, meistens kam ich recht gut zurecht", "text_kk": "Жоқ, көбінесе жақсы жеңе алдым", "text_ru": "Нет, большую часть времени удавалось справляться довольно хорошо", "text_tr": "Hayır, çoğu zaman iyi başa çıkabiliyordum"}, {"text": "No, I have been coping as well as ever", "value": 0, "text_ar": "لا، كنت قادرة على التأقلم كعادتي دائمًا", "text_az": "Xeyr, həmişəki kimi bacarırdım", "text_de": "Nein, ich kam so gut zurecht wie immer", "text_kk": "Жоқ, әдеттегідей жеңе алдым", "text_ru": "Нет, удавалось справляться как обычно", "text_tr": "Hayır, her zamanki gibi başa çıkabiliyordum"}]$q$),
(283, 'mental_health_resources', 'd3081952-ac1a-414f-a6d1-55bbaff886f3', 'is_active', 'bool', $q$true$q$, $q$false$q$),
(284, 'scheduled_notifications', '2b45c134-f365-41b1-811c-19301641f72d', 'title', 'text', $q$Sabah Xoş Keçsin ☀️$q$, $q$Səhəriniz xoş keçsin ☀️$q$),
(285, 'safety_items', '7e0caddf-8e7a-4e66-9398-53595240fb6a', 'description_az', 'text', $q$Çox yüksək A vitamini (retinol) var. Ayda 1-2 dəfədən çox tövsiyə edilmir.$q$, $q$Çox yüksək A vitamini (retinol) var. Hamiləlikdə qaraciyər və qaraciyər məhsullarından tam çəkinin.$q$),
(286, 'first_aid_steps', '26f95e8e-9af5-42b7-bb39-91bb6ca22251', 'instruction_az', 'text', $q$Bədəni ehtiyatla yoxlayın: şişkinlik, qızartı, qanama, deformasiya. Başı, boyunu, qolları və ayaqları yavaşca hərəkət etdirin - ağrı reaksiyasını izləyin. Göz bəbəklərini yoxlayın - hər ikisi eyni ölçüdə olmalıdır. Sınıq şübhəsi varsa - həmin hissəni hərəkət etdirməyin!$q$, $q$Bədəni ehtiyatla yoxlayın: şişkinlik, qızartı, qanama, deformasiya. Baş, boyun və ya bel zədəsi şübhəsi varsa, uşağı tərpətməyin və 103-ə zəng edin. Qolları və ayaqları ancaq ağrı yoxdursa, yavaşca yoxlayın. Göz bəbəklərini yoxlayın: hər ikisi eyni ölçüdə olmalıdır. Sınıq şübhəsi varsa, həmin hissəni hərəkət etdirməyin!$q$),
(287, 'first_aid_steps', '44d2df65-ea71-42cd-bc75-c7d1dca8c151', 'instruction_az', 'text', $q$DƏRHAl 103 zəng edin - hətta uşaq nəfəs alsa belə. "Quru boğulma" riski var - ağciyərə keçən su saatlar sonra problem yarada bilər. Zəng edərkən CPR-ə başlayın - hər saniyə önəmlidir! Yanınızda başqa biri varsa - biri zəng etsin, biri CPR etsin.$q$, $q$DƏRHAL 103-ə zəng edin, hətta uşaq özünə gəlib nəfəs alsa belə: sudan çıxarılan uşağı həkim yoxlamalıdır, ağciyərə keçən su saatlar sonra problem yarada bilər. Uşaq nəfəs almırsa, zəng edərkən CPR-ə başlayın, hər saniyə önəmlidir! Yanınızda başqa biri varsa, biri zəng etsin, biri CPR etsin.$q$),
(288, 'first_aid_steps', 'cbd724e5-b458-4dfe-85fd-eafc99e6d58a', 'instruction_az', 'text', $q$Qoltuq altından və ya rektal termometrlə hərarəti ölçün. Rektal ölçmə ən dəqiqdir (xüsusilə 3 aydan kiçik körpələrdə). 38°C-dən yuxarı hərarət - yüksəkdir. 40°C-dən yuxarı - dərhal həkimə müraciət edin. Hərarəti və vaxtı qeyd edin.$q$, $q$Qoltuq altından və ya rektal termometrlə hərarəti ölçün. Rektal ölçmə ən dəqiqdir (xüsusilə 3 aydan kiçik körpələrdə). 38°C və yuxarı hərarət yüksəkdir. 3 aydan kiçik körpədə 38°C və yuxarı hərarət olarsa, dərhal həkimə müraciət edin. Hər yaşda 40°C-dən yuxarı hərarətdə dərhal həkimə müraciət edin. Hərarəti və vaxtı qeyd edin.$q$),
(289, 'faqs', '44ba92c4-4cce-4e6e-a953-36953f4c2894', 'answer', 'text', $q$Bəli! Anacan həm Azərbaycan, həm də İngilis dilindədir.$q$, $q$Bəli! Anacan 25 dildə mövcuddur, o cümlədən Azərbaycan, rus, türk və ingilis dillərində. Dili Ayarlar bölməsindən dəyişə bilərsiniz.$q$);
DO $$
DECLARE f record; dt text; cnt int; done int := 0;
BEGIN
  FOR f IN SELECT * FROM _fix ORDER BY n LOOP
    SELECT data_type INTO dt FROM information_schema.columns WHERE table_schema = 'public' AND table_name = f.tbl AND column_name = f.col;
    IF dt IS NULL THEN RAISE EXCEPTION 'CONTENT_FIX_NO_COLUMN %.%', f.tbl, f.col; END IF;
    IF dt = 'jsonb' OR dt = 'json' THEN
      EXECUTE format('UPDATE public.%I SET %I = $1::jsonb WHERE id = $2 AND %I::jsonb = $3::jsonb', f.tbl, f.col, f.col) USING f.new_v, f.rid, f.old_v;
    ELSIF dt = 'ARRAY' THEN
      EXECUTE format('UPDATE public.%I SET %I = ARRAY(SELECT jsonb_array_elements_text($1::jsonb)) WHERE id = $2 AND to_jsonb(%I) = $3::jsonb', f.tbl, f.col, f.col) USING f.new_v, f.rid, f.old_v;
    ELSIF dt = 'boolean' THEN
      EXECUTE format('UPDATE public.%I SET %I = $1::boolean WHERE id = $2 AND %I IS NOT DISTINCT FROM $3::boolean', f.tbl, f.col, f.col) USING f.new_v, f.rid, f.old_v;
    ELSE
      EXECUTE format('UPDATE public.%I SET %I = $1 WHERE id = $2 AND %I::text = $3', f.tbl, f.col, f.col) USING f.new_v, f.rid, f.old_v;
    END IF;
    GET DIAGNOSTICS cnt = ROW_COUNT;
    IF cnt <> 1 THEN RAISE EXCEPTION 'CONTENT_FIX_STALE row % (%.% id %)', f.n, f.tbl, f.col, f.rid; END IF;
    done := done + 1;
  END LOOP;
  RAISE NOTICE 'content fixes applied: %', done;
END $$;
COMMIT;